INSERT INTO public.errori ("id", "film_id", "minuto", "categoria", "descrizione", "approvato", "creato_il", "youtube_query", "conferme", "contestazioni", "inserito_da", "provenienza", "screenshot_url") VALUES
(1118, 206, '00:36:15', 'Errori di scena / Posizione', 'Nel recinto dello zoo di Capitol City, quando Coriolanus porta il cibo a Lucy Gray attraverso le sbarre, le macchie di polvere e sporco sulla manica della camicia bianca di Snow cambiano vistosamente forma e intensità tra il piano medio e il controcampo ravvicinato.', TRUE, '2026-10-25T21:45:45.199169', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(1119, 206, '00:54:30', 'Errori di scena / Posizione', 'Nel laboratorio della dottoressa Gaul, nel momento in cui Coriolanus lascia cadere il fazzoletto nella teca cilindrica, la posizione del tessuto sul fondo e la disposizione dei serpenti multicolori attorno ad esso cambiano notevolmente tra l''inquadratura a piombo dall''alto e il piano ravvicinato laterale.', TRUE, '2026-10-25T21:45:45.199169', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(1120, 206, '01:19:45', 'Errori di scena / Posizione', 'Nell''arena, durante l''arrivo del drone che recapita l''acqua a Lucy Gray, il tappo del contenitore metallico appare già svitato e appoggiato sulle macerie, ma nello stacco successivo la ragazza viene inquadrata mentre lo svita per la prima volta.', TRUE, '2026-10-25T21:45:45.199169', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(1121, 206, '01:51:10', 'Errori di scena / Posizione', 'Nel Distretto 12, durante il periodo di addestramento come Pacificatore, la ricrescita dei capelli rasati di Coriolanus è incongruente: nella camerata durante il dialogo serale con Sejanus i capelli appaiono nettamente più lunghi rispetto alla marcia all''aperto ambientata lo stesso giorno.', TRUE, '2026-10-25T21:45:45.199169', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(1122, 206, '02:07:35', 'Errori di scena / Posizione', 'Durante la scena dell''esecuzione all''Albero degli Impiccati, la posizione del nodo scorsoio sul collo del condannato cambia tra i tagli di montaggio: nel primo piano frontale è posizionato sotto la mandibola sinistra, mentre nel controcampo dal basso si trova quasi sulla nuca.', TRUE, '2026-10-25T21:45:45.199169', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(1123, 206, '02:24:50', 'Errori di scena / Posizione', 'Nel bosco vicino al lago, durante la caccia a Lucy Gray sotto la pioggia battente, la divisa militare di Coriolanus risulta completamente inzuppata d''acqua e scura in campo largo, ma nello stacco a mezza figura il tessuto mostra vistose zone asciutte sul petto e sulle spalle.', TRUE, '2026-10-25T21:45:45.199169', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(3580, 71, '00:04:30', 'Errori di scena / Posizione', 'Durante la scena in cui Luke viene attaccato dal Wampa sulla neve di Hoth, nell''inquadratura in primo piano in cui estrae la spada laser dalla neve, la ferita sul viso dell''attore Mark Hamill è visibile sulla guancia destra, mentre nei piani sequenza precedenti e successivi la ferita è sulla guancia sinistra (inversione dovuta al ribaltamento della pellicola o a controfigure).', TRUE, '2026-11-01T17:25:23.226675', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3581, 71, '00:45:12', 'Errori di scena / Posizione', 'Nel Millennium Falcon, mentre Ian Solo e la Principessa Leia discutono animatamente nei corridoi prima del bacio, la ciocca di capelli di Leia cambia costantemente posizione da un''inquadratura all''altra, passando da dietro l''orecchio a sopra la spalla senza che vi sia il tempo fisico per spostarli.', TRUE, '2026-11-01T17:25:23.226675', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3582, 71, '01:22:45', 'Troupe o microfoni visibili', '', TRUE, '2026-11-01T17:25:23.226675', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3583, 71, '01:58:10', 'Errori di scena / Posizione', 'Nella scena finale a bordo della fregata medica ribelle, quando Luke riceve la mano robotica, la posizione dei cavi e la disposizione degli strumenti medici sul carrello accanto al letto cambiano visibilmente tra le inquadrature larghe e i primi piani.', TRUE, '2026-11-01T17:25:23.226675', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3905, 204, '00:25:12', 'Errori di scena / Posizione', 'Durante una scena in cui Katniss parla nel Distretto 13, i suoi capelli cambiano visibilmente di posizione e di acconciatura tra un''inquadratura e l''altra, passando da ciocche sciolte sul viso a perfettamente ordinate dietro le spalle.', TRUE, '2026-11-02T10:11:20.461417', 'Hunger Games Mockingjay Part 1 hair continuity error Katniss', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3906, 204, '01:12:45', 'Errori di scena / Posizione', 'I documenti e i monitor sulla scrivania di Alma Coin cambiano disposizione in modo evidente tra le inquadrature larghe e i primi piani durante la riunione di strategia militare.', TRUE, '2026-11-02T10:11:20.461417', 'Hunger Games Mockingjay Part 1 President Coin scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4282, 339, '00:04:15', 'Anacronismi', 'Durante la sequenza iniziale della battaglia nel 1846, si possono notare alcuni edifici sullo sfondo che presentano caratteristiche architettoniche, come scale antincendio e dettagli strutturali, tipici di un''epoca successiva della storia di New York.', TRUE, '2026-11-02T14:51:13.207952', 'Gangs of New York opening battle historical inaccuracy', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4283, 339, '00:18:30', 'Errori storici o fattuali', 'Il film mostra i Draft Riots (rivolte della coscrizione) del 1863 come se fossero scoppiati immediatamente e direttamente per fermare la guerra, ma storicamente furono innescati specificamente dal primo sorteggio della lotteria della leva militare federale.', TRUE, '2026-11-02T14:51:13.207952', 'Gangs of New York draft riots historical context', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4284, 339, '01:12:40', 'Errori di scena / Posizione', 'Nella scena in cui Amsterdam e Bill il Genio parlano nel covo, la bottiglia di liquore sul tavolo cambia posizione e livello di riempimento tra un''inquadratura e l''altra senza che nessuno la tocchi.', TRUE, '2026-11-02T14:51:13.207952', 'Gangs of New York continuity bottle scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4285, 339, '01:45:20', 'Anacronismi', 'Vengono utilizzati alcuni termini gergali e modi di dire all''interno dei dialoghi che non erano storicamente in uso a New York durante gli anni ''40 e ''60 del XIX secolo, ma derivano da periodi successivi del Novecento.', TRUE, '2026-11-02T14:51:13.207952', 'Gangs of New York dialogue anachronisms', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(764, 144, '00:46:25', 'Continuità / Oggetti di scena', 'Durante il primo incontro tra Shosanna e il Maggiore Hellstrom nel ristorante, la posizione del piattino, la quantità di panna sullo strudel e la sigaretta nel posacenere cambiano tra le inquadrature frontali e quelle di controcampo.', TRUE, '2026-09-28T10:37:29.693506', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(4286, 339, '02:02:10', 'Errori di scena / Posizione', 'Durante il combattimento finale nei Five Points, la ferita e il sangue sul volto di Amsterdam cambiano visibilmente spessore, posizione e consistenza cromatica a seconda dei tagli di montaggio tra un primo piano e un campo largo.', TRUE, '2026-11-02T14:51:13.207952', 'Gangs of New York final battle continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(765, 144, '01:12:10', 'Continuità / Abbigliamento', 'Nella scena della taverna ''La Louisiane'', il nastro della decorazione militare sul petto del sergente Wilhelm cambia orientamento e inclinazione svariate volte durante la conversazione tesa al tavolo.', TRUE, '2026-09-28T10:37:29.693506', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(767, 144, '01:52:15', 'Continuità / Costumi e Trucco', 'L''ingessatura alla gamba di Bridget von Hammersmark (Diane Kruger) varia visibilmente in spessore e modellatura tra la scena della medicazione privata e l''arrivo nel foyer del cinema per la première.', TRUE, '2026-09-28T10:37:29.693506', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(3584, 72, '01:21:00', 'Errori di scena / Posizione', 'Quando Luke Skywalker viene catturato dagli Ewok e sollevato in aria legato a un tronco, la posizione delle corde e dei suoi polsi cambia visibilmente tra le diverse inquadrature ravvicinate e i campi lunghi.', TRUE, '2026-11-01T17:25:53.680183', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3585, 72, '00:44:00', 'Errori di scena / Posizione', 'Nella scena in cui Leila e Ian si trovano sulla luna boscosa di Endor prima della battaglia, i capelli di Carrie Fisher variano la loro disposizione e lunghezza tra le inquadrature frontali e quelle di spalle, a causa delle riprese effettuate in giorni differenti o con controfigure.', TRUE, '2026-11-01T17:25:53.680183', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3586, 72, '01:05:00', 'Errori di scena / Posizione', 'Durante la battaglia nello spazio sopra la seconda Morte Nera, la posizione dei danni subiti dal Millennium Falcon e la presenza o meno di segni di bruciatura sullo scafo esterno cambiano ripetutamente da un''inquadratura all''altra.', TRUE, '2026-11-01T17:25:53.680183', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3907, 205, '01:21:00', 'Errori di scena / Posizione', 'Durante la sequenza in cui Katniss si trova nei tunnel di Capitol City, i capelli della protagonista cambiano visibilmente posizione e lunghezza tra un''inquadratura e l''altra a causa dei diversi ciak e delle controfigure.', TRUE, '2026-11-02T10:12:14.950771', 'Hunger Games Mockingjay Part 2 Katniss sewers scene continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3908, 205, '00:45:00', 'Errori di scena / Posizione', 'Nella scena dell''attacco alla postazione dei difensori di Capitol City con la trappola della resina nera, la quantità di liquido e la sua disposizione sui vestiti dei personaggi variano drasticamente da un''inquadratura all''altra.', TRUE, '2026-11-02T10:12:14.950771', 'Hunger Games Mockingjay Part 2 black tar trap scene continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3909, 207, '00:15:30', 'Errori di scena / Posizione', 'Durante la scena nella Banca dei Cattivi, la posizione degli oggetti sulla scrivania del direttore cambia visibilmente tra un''inquadratura e l''altra mentre Gru parla.', TRUE, '2026-11-02T10:12:31.287802', 'Despicable Me Bank of Evil scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(766, 144, '01:24:35', 'Continuità / Posizione', 'Sempre durante il confronto nella taverna, il livello di scotch nel bicchiere impugnato da Archie Hicox (Michael Fassbender) oscilla tra quasi vuoto e parzialmente riempito tra stacchi di montaggio consecutivi senza che lui beva o verser da bere.', TRUE, '2026-09-28T10:37:29.693506', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(768, 144, '02:14:10', 'Continuità / Trucco', 'Nella cabina di proiezione, dopo che Shosanna spara a Frederick Zoller, la posizione del corpo di Zoller a terra e la disposizione delle macchie di sangue sulla sua uniforme cambiano nel momento in cui la donna si avvicina per voltarlo.', TRUE, '2026-09-28T10:37:29.693506', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(769, 144, '02:22:50', 'Continuità / Trucco e Posizione', 'Nella sequenza finale nel bosco, le rivoli di sangue che scendono dal taglio a forma di svastica sulla fronte di Hans Landa (Christoph Waltz) cambiano traiettoria e densità tra il primo piano dell''incisione e l''ultima inquadratura dall''alto.', TRUE, '2026-09-28T10:37:29.693506', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(763, 144, '00:31:10', 'Continuità / Trucco', 'La svastica incisa sulla fronte del soldato Butz da Aldo Raine mostra una forma, una profondità di taglio e una quantità di sangue nettamente differenti tra la scena dell''interrogatorio nel bosco e il successivo flashback nello studio di Hitler.', TRUE, '2026-09-28T10:37:29.693506', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(755, 143, '00:12:15', 'Incongruenza scientifica / Audio', 'Durante le scene con i delfini Cindy e Sandy, si sentono chiaramente i loro tipici versi mentre sono sott''acqua. Nella realtà, i delfini non producono quel tipo di vocalizzazioni udibili all''orecchio umano in quel modo sott''acqua senza rilasciare bolle d''aria.', TRUE, '2026-09-28T06:24:16.525723', NULL, 0, 0, 'lrscrm73@gmail.com', 'ia', NULL),
(757, 143, '00:52:10', 'Errori di scena / Oggetti', 'Durante la cattura del piccolo squalo bianco, si vede chiaramente che l''animale utilizzato in alcune inquadrature ravvicinate è un modello di gomma completamente rigido, privo di qualsiasi movimento naturale delle branchie o della bocca, che galleggia in modo innaturale.', TRUE, '2026-09-28T06:24:16.525723', NULL, 0, 0, 'lrscrm73@gmail.com', 'ia', NULL),
(758, 143, '01:18:25', 'Effetti speciali / Errori visivi', 'Nella famosa scena in cui lo squalo gigante nuota verso la vetrata della sala di controllo subacquea, l''animale è completamente immobile. Si tratta di un elemento bidimensionale che viene semplicemente ingrandito per simulare l''avvicinamento, rendendo l''effetto visivo estremamente piatto e privo di dinamismo.', TRUE, '2026-09-28T06:24:16.525723', NULL, 0, 0, 'lrscrm73@gmail.com', 'ia', NULL),
(759, 143, '01:22:15', 'Incongruenza fisica / Audio', 'Mentre lo squalo attacca la struttura subacquea, si sente un ruggito cupo e minaccioso provenire dal predatore. Gli squali non possiedono corde vocali né polmoni, rendendo biologicamente impossibile l''emissione di qualsiasi tipo di verso, specialmente sott''acqua.', TRUE, '2026-09-28T06:24:16.525723', NULL, 0, 0, 'lrscrm73@gmail.com', 'ia', NULL),
(760, 143, '01:26:45', 'Errori di montaggio / Continuità', 'Quando Philip FitzRoyce (Simon MacCorkindale) si trova all''interno della bocca dello squalo, la dimensione della bocca del predatore cambia drasticamente tra le inquadrature in primo piano (dove lo spazio interno appare enorme) e i campi medi (dove l''attore è visibilmente incastrato in un modello molto più stretto).', TRUE, '2026-09-28T06:24:16.525723', NULL, 0, 0, 'lrscrm73@gmail.com', 'ia', NULL),
(756, 143, '00:35:40', 'Errori di montaggio / Continuità', 'Quando Mike Brody (Dennis Quaid) emerge dall''acqua dopo un''immersione, i suoi capelli sono completamente bagnati e tirati all''indietro. Nell''inquadratura immediatamente successiva, mentre parla sulla banchina, i suoi capelli sono parzialmente asciutti e perfettamente pettinati.', TRUE, '2026-09-28T06:24:16.525723', NULL, 0, 0, 'lrscrm73@gmail.com', 'ia', NULL),
(84, 35, '01:12:05', 'Continuity', 'La cicatrice sul volto di Frodo provocata da Gollum cambia guancia e orientamento più volte durante le scene all''interno della torre di Cirith Ungol.', TRUE, '2026-09-13T15:13:22.290648', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(85, 35, '02:45:30', 'Crew & Equipment', 'Durante il combattimento contro Shelob, in un''inquadratura dal basso si scorgono i cavi di sicurezza di metallo collegati alla cintura dell''attore Sean Astin.', TRUE, '2026-09-13T15:13:22.392965', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(86, 36, '00:52:10', 'Continuity', 'Durante la sequenza del Gran Consiglio, il vestito del personaggio di Boromir cambia improvvisamente colore dal marrone scuro al blu polvere da un fotogramma all''altro.', TRUE, '2026-09-13T15:13:22.594544', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(87, 37, '00:15:30', 'Errori di scena / Posizione', 'Durante l''aggressione nella casa dello scrittore Frank Alexander, la striscia di nastro adesivo applicata sulla bocca della moglie cambia chiaramente posizione e inclinazione tra le inquadratura frontali e quelle di taglio.', TRUE, '2026-09-13T15:23:45.086249', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(657, 127, '01:56:50', 'Troupe o microfoni visibili', 'Mentre Frank e i suoi uomini raggiungono a cavallo la carrozza ferroviaria di Morton rimasta isolata tra le gole rocciose, sulla sabbia del terreno desertico in basso a destra sono perfettamente riconoscibili i solchi dei moderni pneumatici dei veicoli di produzione della troupe, non cancellati prima del ciak.', TRUE, '2026-09-19T18:08:29.015384', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(3587, 73, '01:54:00', 'Errori di scena / Posizione', 'Durante lo scontro finale con Darth Maul, la treccia da Padawan di Obi-Wan Kenobi si sposta dalla spalla destra alla sinistra a causa dell''inversione orizzontale dell''inquadratura (flipped shot) utilizzata in fase di montaggio.', TRUE, '2026-11-01T17:26:40.468564', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3588, 73, '00:32:00', 'Errori di scena / Posizione', 'Il dispositivo di comunicazione (comlink) utilizzato da Qui-Gon Jinn su Tatooine è stato realizzato riutilizzando ed è chiaramente identificabile come un rasoio femminile Gillette Sensor Excel rielaborato con piccoli dettagli decorativi.', TRUE, '2026-11-01T17:26:40.468564', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3589, 73, '00:18:00', 'Errori di scena / Posizione', 'Nella scena all''interno del sottomarino Bongo, quando Jar Jar Binks sviene per la paura, le sue orecchie create in CGI compenetrano e attraversano fisicamente lo schienale rigido del sedile.', TRUE, '2026-11-01T17:26:40.468564', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3590, 73, '02:00:00', 'Errori di scena / Posizione', 'Quando Obi-Wan taglia a metà la spada laser a doppia lama di Darth Maul, nella prima inquadratura successiva la metà dell''elsa rimasta nelle mani di Maul presenta un''estremità integra anziché mostrare i danni del taglio del plasma.', TRUE, '2026-11-01T17:26:40.468564', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3591, 73, '01:06:00', 'Errori di scena / Posizione', 'Subito dopo la vittoria nella gara di Podrace, la disposizione del fango sul viso di Anakin Skywalker e la posizione del mantello di Qui-Gon Jinn cambiano drasticamente ad ogni cambio di inquadratura.', TRUE, '2026-11-01T17:26:40.468564', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3592, 73, '00:06:00', 'Errori di scena / Posizione', 'All''inizio del film, quando Qui-Gon Jinn infila la spada laser nel portellone blindato per fonderlo, l''effetto grafico del metallo incandescente si estende e fonde prima che la lama entri effettivamente in contatto con la sezione centrale della porta.', TRUE, '2026-11-01T17:26:40.468564', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3910, 207, '00:42:15', 'Errori di scena / Posizione', 'Nel laboratorio di Gru, gli strumenti sul banco da lavoro cambiano posizione e numero tra le inquadrature larghe e i primi piani durante la costruzione del razzo.', TRUE, '2026-11-02T10:12:31.287802', 'Despicable Me lab scene mistakes', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4291, 341, '00:15:42', 'Errori di scena / Posizione', 'Durante la sequenza in cui John Anderton fugge nella metropolitana, il numero di passeggeri seduti vicino a lui cambia drasticamente tra un''inquadratura e l''altra, così come la posizione esatta delle riviste che sta leggendo per coprirsi il volto.', TRUE, '2026-11-02T14:51:22.25427', 'Minority Report metro scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(658, 127, '02:27:35', 'Errori di scena / Posizione', 'Nel celebre duello finale tra Armonica (Charles Bronson) e Frank (Henry Fonda), la direzione e la lunghezza delle ombre proiettate dai due contendenti sul terreno cambiano repentinamente tra i primissimi piani degli occhi e i campi lunghi d''insieme, tradendo il fatto che la scena è stata filmata nell''arco di diverse ore con il sole in posizioni assai differenti nel cielo.', TRUE, '2026-09-19T18:08:29.015384', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(4292, 341, '00:48:20', 'Errori di scena / Posizione', 'Nella scena in cui Anderton si sottopone all''intervento chirurgico clandestino agli occhi nel condominio fatiscente, le bende e la quantità di sangue sul suo viso variano visibilmente da un''inquadratura all''altra prima e dopo le medicazioni.', TRUE, '2026-11-02T14:51:22.25427', 'Minority Report eye surgery scene continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(771, 145, '00:15:12', 'Errore di troupe / Ombra visibile', 'Mentre Mr. Pink corre lungo il vicolo per sfuggire alla polizia subito dopo la rapina finita male, è chiaramente visibile l''ombra della telecamera e dell''operatore proiettata sul muro dell''edificio a sinistra.', TRUE, '2026-09-28T17:20:35.262633', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(772, 145, '00:22:30', 'Continuità / Trucco', 'La quantità e la forma della macchia di sangue sulla camicia bianca di Mr. Orange (Tim Roth) variano continuamente mentre giace sul pavimento del magazzino, passando da macchia fresca e fluida a chiazza più scura e quasi asciutta da un''inquadratura all''altra.', TRUE, '2026-09-28T17:20:35.262633', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(4293, 341, '01:12:15', 'Troupe o microfoni visibili', 'Nella scena dell''inseguimento con i jetpack in cui Anderton scende lungo la facciata verticale del palazzo, in un campo largo di profilo è possibile intravedere brevemente l''imbracatura e i cavi di sicurezza dello stuntman di Tom Cruise.', TRUE, '2026-11-02T14:51:22.25427', 'Minority Report jetpack scene wire visible', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4294, 341, '01:34:50', 'Errori di scena / Posizione', 'Quando Lamar Burgess (Max von Sydow) si trova nel suo ufficio e sposta alcuni oggetti sulla scrivania, la tazza e i documenti cambiano posizione e orientamento tra i diversi cambi di inquadratura (campo e controcampo).', TRUE, '2026-11-02T14:51:22.25427', 'Minority Report Max von Sydow office scene mistake', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4505, 27, '00:51:30', 'Anacronismi', 'In un''inquadratura larga delle campagne in cui si muovono le truppe romane, sullo sfondo in lontananza si intravede brevemente una linea elettrica o traliccio moderno non rimosso in post-produzione.', TRUE, '2026-11-02T15:32:15.20768', 'Spartacus e i 10 gladiatori mistake anachronism', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4506, 27, '01:08:45', 'Errori storici o fattuali', 'Le armature e i fregi degli ufficiali romani presentano decorazioni e elmi di foggia anacronistica rispetto al periodo storico della Repubblica romana in cui è ambientata la narrazione del film.', TRUE, '2026-11-02T15:32:15.20768', 'Spartacus e i 10 gladiatori historical error costume', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4536, 260, '00:15:20', 'Errori di scena / Posizione', 'Durante l''aggressione sulla corriera, Hutch viene colpito ripetutamente. I tagli e le ferite sul suo viso variano visibilmente di intensità e posizione tra un''inquadratura e l''altra.', TRUE, '2026-11-02T15:33:43.063606', 'Nobody bus fight scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4537, 260, '00:45:10', 'Errori di scena / Posizione', 'Nella sequenza in cui Hutch si prepara all''attacco nella sua casa, le armi e gli oggetti sul tavolo cambiano disposizione e numero a seconda dell''angolo di ripresa.', TRUE, '2026-11-02T15:33:43.063606', 'Nobody movie home preparation scene goofs', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4538, 260, '01:12:30', 'Errori di scena / Posizione', 'Durante la sparatoria finale nel magazzino, i fori di proiettile sui pilastri e sulle pareti scompaiono e riappaiono modificando la geometria della copertura tra i cambi di inquadratura.', TRUE, '2026-11-02T15:33:43.063606', 'Nobody warehouse shootout continuity mistake', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4539, 260, '00:15:30', 'Errori di scena / Posizione', 'Durante la scena in cui Hutch parla con il suo capo in ufficio, la tazza sulla scrivania cambia posizione e inclinazione tra un cambio di inquadratura e l''altro.', TRUE, '2026-11-02T15:33:43.063606', 'Nobody 2021 office scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4540, 260, '00:42:15', 'Errori di scena / Posizione', 'Nella sequenza dell''autobus, la bottiglia che Hutch usa come arma viene impugnata con mani diverse o mostra livelli di liquido differenti nei vari stacchi di montaggio.', TRUE, '2026-11-02T15:33:43.063606', 'Nobody 2021 bus fight goofs', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3593, 74, '01:21:00', 'Errori di scena / Posizione', 'Durante la sequenza nella fabbrica di droidi su Geonosis, la posizione della catena di montaggio e i pezzi che Padmé e Anakin affrontano cambiano visibilmente in modo incongruente tra un''inquadratura e l''altra.', TRUE, '2026-11-01T17:26:55.394478', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3594, 74, '02:00:00', 'Errori di scena / Posizione', 'Nella battaglia nell''arena su Geonosis, le catene che legano Anakin, Obi-Wan e Padmé ai pali scompaiono e riappaiono a seconda dell''inquadratura prima che riescano a liberarsi.', TRUE, '2026-11-01T17:26:55.394478', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3911, 209, '00:09:00', 'Anacronismi', 'Durante la scena del 1968 in cui i Minions si trovano a New York, si vede un modello di taxi Checker Marathon che presenta dettagli di produzione tipici dei primi anni ''80 e non del 1968.', TRUE, '2026-11-02T10:12:45.698167', 'Minions 2015 New York 1968 taxi error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3912, 209, '00:32:00', 'Errori storici o fattuali', 'Nel Regno Unito del 1968, le auto della polizia mostrate (le classiche ''panda cars'' della Metropolitan Police) indossano livree e combinazioni di colori che sono state introdotte solo diversi anni dopo.', TRUE, '2026-11-02T10:12:45.698167', 'Minions 2015 London police cars historical error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3913, 209, '00:45:00', 'Errori di scena / Posizione', 'Quando i Minions entrano nella Torre di Londra, la posizione dei gioielli della corona cambia visibilmente tra l''inquadratura larga e il primo piano ravvicinato su Bob.', TRUE, '2026-11-02T10:12:45.698167', 'Minions 2015 Crown Jewels scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4297, 346, '01:10:45', 'Troupe o microfoni visibili', 'In una delle sequenze in esterni sotto la pioggia battente, in un riflesso su una macchina della polizia è possibile intravedere brevemente l''ombra di un''attrezzatura di illuminazione e parte del braccio di un microfono.', TRUE, '2026-11-02T14:51:34.555378', 'Se7en movie crew reflection error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4298, 346, '01:25:30', 'Errori di scena / Posizione', 'Quando John Doe (Kevin Spacey) si consegna insanguinato alla stazione di polizia, la quantità e la disposizione del sangue sulla sua camicia variano sensibilmente tra l''ingresso e i primi piani successivi.', TRUE, '2026-11-02T14:51:34.555378', 'Se7en John Doe police station blood continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(773, 145, '00:26:40', 'Continuità / Posizione', 'Quando Mr. Blonde (Michael Madsen) tira fuori dal bagagliaio il poliziotto Marvin Nash, questi ha le mani ammanettate dietro la schiena. Durante alcune inquadrature successive del pestaggio, le mani ammanettate appaiono improvvisamente davanti al suo corpo per poi tornare dietro.', TRUE, '2026-09-28T17:20:35.262633', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(774, 145, '00:34:15', 'Continuità / Oggetti di scena', 'Quando Mr. Blonde rientra nel magazzino tenendo in mano un bicchiere di soda di un fast food, l''orientamento della cannuccia e il livello del coperchio cambiano posizione ad ogni stacco di montaggio.', TRUE, '2026-09-28T17:20:35.262633', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(775, 145, '01:14:05', 'Anacronismo / Oggetti di scena', 'Durante il flashback dell''addestramento sotto copertura di Mr. Orange, nella stanza è visibile un poster di una band e un pacchetto di sigarette con una grafica promozionale pubblicata solo anni dopo l''epoca in cui si svolge la storia.', TRUE, '2026-09-28T17:20:35.262633', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(776, 145, '01:32:18', 'Errore di montaggio / Effetti speciali', 'Durante lo stallo messicano finale, si vede la carica esplosiva di finto sangue (squib) sul petto di Eddie il Bello detonare prima che Mr. White riesca a ruotare la sua pistola e sparargli effettivamente.', TRUE, '2026-09-28T17:20:35.262633', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(777, 146, '00:07:40', 'Errore di continuità', 'Nella scena iniziale in cui Deckard mangia al banco nel quartiere cinese, la quantità di noodles nella sua ciotola e la posizione delle bacchette cambiano ripetutamente tra un''inquadratura e l''altra.', TRUE, '2026-09-29T14:16:41.047807', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(778, 146, '00:11:15', 'Incongruenza di sceneggiatura', 'Il capitano Bryant dice a Deckard che sei replicanti sono fuggiti e che uno è rimasto folgorato cercando di entrare alla Tyrell Corporation. Subito dopo, però, afferma che ci sono ancora quattro replicanti a piede libero, commettendo un evidente errore di calcolo matematico (6 - 1 dovrebbe fare 5).', TRUE, '2026-09-29T14:16:41.047807', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(779, 146, '00:18:25', 'Errore tecnico / Attrezzatura visibile', 'Durante il volo dello Spinner della polizia tra i grattacieli della Los Angeles futuristica, in alcune inquadrature controluce sono chiaramente visibili i sottili cavi di sospensione utilizzati per muovere il modellino del veicolo.', TRUE, '2026-09-29T14:16:41.047807', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(780, 146, '00:52:10', 'Errore di continuità / Trucco', 'Dopo il violento scontro con Leon, Deckard presenta una ferita sanguinante sul lato sinistro del volto. Quando sale in auto con Rachael, la ferita cambia forma, posizione e intensità del sangue tra i vari controcampi.', TRUE, '2026-09-29T14:16:41.047807', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(781, 146, '01:12:30', 'Controfigura visibile', 'Durante la fuga di Zhora, quando la replicante sfonda le vetrate dei negozi sotto gli spari di Deckard, è evidente che l''attrice Joanna Cassidy è stata sostituita da una controfigura (la stuntwoman Lee Pulford) che indossa una parrucca visibilmente diversa.', TRUE, '2026-09-29T14:16:41.047807', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(782, 146, '01:33:45', 'Controfigura visibile', 'Durante lo scontro nell''appartamento di J.F. Sebastian, quando Pris attacca Deckard compiendo delle capriole acrobatiche all''indietro, si nota chiaramente che l''acrobata è un ginnasta maschio con una parrucca bionda, con una corporatura molto diversa da quella di Daryl Hannah.', TRUE, '2026-09-29T14:16:41.047807', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(783, 146, '01:47:10', 'Incongruenza di montaggio / Illuminazione', 'Nel momento in cui Roy Batty muore e la colomba vola via dalle sue mani, l''inquadratura del cielo mostra uno sfondo diurno, azzurro e luminoso. Questo contrasta nettamente con l''ambientazione notturna, cupa e piovosa della scena immediatamente precedente e di quella successiva.', TRUE, '2026-09-29T14:16:41.047807', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(9, 2, '01:22:15', 'Crew & Equipment', 'Durante la rievocazione della battaglia di Zama nel Colosseo, una biga si ribalta contro la parete dell''arena e per diversi fotogrammi è chiaramente visibile una bombola di gas compresso nera installata nel retro del carro, usata per far rialzare o ribaltare il mezzo.', TRUE, '2026-09-13T14:42:52.166414', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(10, 2, '00:38:10', 'Anacronismo', 'Nelle scene in cui Massimo cammina attraverso i campi di grano o mentre si trova in Spagna, si possono notare sullo sfondo le linee di aratura simmetriche lasciate chiaramente da un moderno trattore.', TRUE, '2026-09-13T14:42:52.31543', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(11, 2, '01:05:40', 'Crew & Equipment', 'Durante un combattimento in arena, alla destra dello schermo è visibile per un istante un membro della troupe cinematografica che indossa jeans e una maglietta chiara tra la folla in costume.', TRUE, '2026-09-13T14:42:52.421124', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(12, 2, '00:26:00', 'Fattuale / Storico', 'Nel film l''imperatore Marco Aurelio viene soffocato a morte dal figlio Commodo. Nella realtà storica, Marco Aurelio morì per cause naturali (probabilmente peste o tumore) a Vindobona (l''odierna Vienna) nel 180 d.C.', TRUE, '2026-09-13T14:42:52.501079', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(3595, 75, '00:19:00', 'Errori di scena / Posizione', 'Durante il duello sul ponte della nave del Generale Grievous, la posizione e la presa delle spade laser di Anakin ed Ewan McGregor cambiano repentinamente tra un''inquadratura e l''altra.', TRUE, '2026-11-01T17:27:23.341847', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3596, 75, '01:09:00', 'Errori di scena / Posizione', 'Quando Yoda atterra sulla superficie di Kashyyyk, il suo bastone cambia mano e posizione mentre sale a bordo del veicolo aereo (Raddaugh).', TRUE, '2026-11-01T17:27:23.341847', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3597, 75, '01:40:00', 'Errori di scena / Posizione', 'Nel corso della battaglia su Mustafar, lo stato di usura e le bruciature sugli abiti di Anakin ed Obi-Wan variano visibilmente da un''inquadratura all''altra prima ancora che vengano dati alle fiamme dalla lava.', TRUE, '2026-11-01T17:27:23.341847', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3914, 216, '00:43:00', 'Errori di scena / Posizione', 'Durante la celebre scena della tempesta in cui il pianoforte scivola attraverso il salone delle feste (''Magic Waltz''), la posizione dello sgabello e l''orientamento del pianoforte cambiano in modo discontinuo tra le inquadrature ampie e i primi piani di Novecento e Max.', TRUE, '2026-11-02T10:13:48.117704', 'The Legend of 1900 magic waltz piano storm scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3915, 216, '01:42:00', 'Errori storici o fattuali', 'Nel momento culmine del duello musicale, Novecento accende una sigaretta appoggiandola sulle corde del pianoforte rese calde dalla sua frenetica esecuzione. In realtà, l''attrito dei martelletti sulle corde di un pianoforte non può produrre fisicamente il calore necessario (oltre 250 °C) per far prendere fuoco alla carta e al tabacco di una sigaretta.', TRUE, '2026-11-02T10:13:48.117704', 'The Legend of 1900 piano duel scene cigarette', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3916, 216, '01:32:00', 'Anacronismi', 'Durante la sfida pianistica, Jelly Roll Morton esegue la composizione ''The Crave''. Storicamente, Morton ha composto e registrato questo brano nel 1939, mentre la scena all''interno del racconto si svolge verso la fine degli anni ''20.', TRUE, '2026-11-02T10:13:48.117704', 'The Legend of 1900 Jelly Roll Morton The Crave', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(751, 142, '01:08:10', 'Effetti speciali / Cavi visibili', 'Nella drammatica scena in cui lo squalo attacca e rovescia l''elicottero di soccorso, in un fotogramma illuminato dal sole sono chiaramente visibili i cavi d''acciaio utilizzati dalla troupe per ribaltare la carcassa del velivolo in acqua.', TRUE, '2026-09-28T06:16:30.26034', NULL, 0, 0, 'lrscrm73@gmail.com', 'ia', NULL),
(752, 142, '01:21:05', 'Discontinuità meteorologica / Luce', 'Durante il lungo assedio alle barche a vela dei ragazzi, la copertura nuvolosa e la posizione del sole cambiano repentinamente: si passa da un cielo completamente cupo e nuvoloso a una luce solare diretta e nitida nel giro di pochi secondi di dialogo.', TRUE, '2026-09-28T06:16:30.26034', NULL, 0, 0, 'lrscrm73@gmail.com', 'ia', NULL),
(690, 65, '00:08:15', 'Errori storici o fattuali', 'La morte di Re Riccardo Cuor di Leone viene collocata temporalmente e visivamente in modo impreciso. Storicamente, Riccardo morì nel 1199 all''età di 41 anni a causa di una ferita infetta, mentre nel film viene rappresentato come un uomo molto più anziano e la dinamica del ferimento è romanzata per esigenze drammatiche.', TRUE, '2026-09-22T20:36:28.422194', NULL, 0, 0, 'mrtlsn07@gmail.com', 'ia', NULL),
(691, 65, '00:24:40', 'Errori di scena / Posizione', 'Quando Robin e Little John incontrano Marian per la prima volta nel convento, la posizione del velo da badessa di Marian (Audrey Hepburn) cambia tra i primi piani e i campi medi, rivelando più o meno capelli sulla fronte a seconda dell''inquadratura.', TRUE, '2026-09-22T20:36:28.422194', NULL, 0, 0, 'mrtlsn07@gmail.com', 'ia', NULL),
(692, 65, '00:42:10', 'Anacronismi', 'Nelle riprese esterne della foresta (effettuate principalmente nella regione della Navarra, in Spagna), si possono notare sullo sfondo specie di alberi e vegetazione non compatibili con la flora dell''Inghilterra medievale del XII secolo, oltre a leggeri segni di pneumatici moderni sul terreno battuto.', TRUE, '2026-09-22T20:36:28.422194', NULL, 0, 0, 'mrtlsn07@gmail.com', 'ia', NULL),
(744, 141, '01:21:15', 'Attrezzatura di scena visibile', 'Quando Quint spara il primo arpione e aggancia il barile giallo allo squalo, in un fotogramma in cui la pinna riaffiora è chiaramente visibile il cavo d''acciaio sottostato che traina la pinna meccanica.', TRUE, '2026-09-27T20:43:10.736812', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(784, 147, '00:14:25', 'Incongruenza / Liquidi', 'Nel pub di Walkabout Creek, durante la conversazione iniziale, il livello della birra nel bicchiere di Mick sale e scende inspiegabilmente tra i vari stacchi di montaggio senza che lui beva.', TRUE, '2026-09-29T14:45:36.15182', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(785, 147, '00:24:50', 'Errore di scena / Oggetti', 'Quando Mick mostra a Sue come affrontare il serpente, in un''inquadratura ravvicinata si nota chiaramente che il rettile utilizzato è un modello finto di gomma, rigido e privo di qualsiasi movimento naturale.', TRUE, '2026-09-29T14:45:36.15182', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(786, 147, '00:32:15', 'Incongruenza / Montaggio', 'Durante la scena dell''attacco del coccodrillo, quando Mick salva Sue, i capelli di lei sono completamente bagnati e inzuppati d''acqua. Nell''inquadratura immediatamente successiva, mentre camminano sulla riva, i suoi capelli sono quasi del tutto asciutti e in piega.', TRUE, '2026-09-29T14:45:36.15182', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(787, 147, '00:41:15', 'Incongruenza / Abbigliamento', 'Durante la traversata nel bush australiano, le macchie di sudore e polvere sulla camicia beige di Sue cambiano forma, dimensione e intensità da un''inquadratura all''altra, scomparendo quasi del tutto in alcuni momenti.', TRUE, '2026-09-29T14:45:36.15182', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL);
INSERT INTO public.errori ("id", "film_id", "minuto", "categoria", "descrizione", "approvato", "creato_il", "youtube_query", "conferme", "contestazioni", "inserito_da", "provenienza", "screenshot_url") VALUES
(788, 147, '00:52:10', 'Incongruenza / Oggetti', 'Nella camera d''albergo a New York, Mick si rade usando il suo enorme coltello Bowie. La disposizione e la quantità di schiuma da barba sulle sue guance cambiano vistosamente tra i primi piani e i piani medi.', TRUE, '2026-09-29T14:45:36.15182', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(789, 147, '01:12:40', 'Errore di scena / Attrezzatura', 'Mentre Mick cammina per le affollate strade di New York, nel riflesso della vetrina di un negozio sulla sinistra è chiaramente visibile per un istante la troupe cinematografica con una telecamera montata e un pannello riflettente.', TRUE, '2026-09-29T14:45:36.15182', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(790, 147, '01:18:05', 'Incongruenza / Posizione', 'Nella celebre scena del tentato borseggio (''Questo non è un coltello...''), la posizione dei tre malviventi rispetto a Mick e Sue cambia repentinamente tra i piani larghi e i primi piani ravvicinati.', TRUE, '2026-09-29T14:45:36.15182', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(792, 148, '00:27:15', 'Sincronizzazione audio/video', 'Mentre Aubrey e Maturin eseguono un duetto nella cabina del capitano, i movimenti dell''archetto e le diteggiature sulla tastiera del violino di Russell Crowe non combaciano con il fraseggio e le note che si ascoltano nella traccia audio.', TRUE, '2026-09-29T15:13:52.315198', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(3917, 216, '02:35:00', 'Errori storici o fattuali', 'Nel finale del film, il transatlantico Virginian viene fatto esplodere con la dinamite in mare aperto nel 1946 perché obsoleto. Nella realtà storica, la vera nave SS Virginian (rinominata Drottningholm nel 1920) sopravvisse alla Seconda Guerra Mondiale e fu regolarmente smantellata in un cantiere navale a Trieste nel 1955.', TRUE, '2026-11-02T10:13:48.117704', 'The Legend of 1900 ship explosion Virginian', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3598, 76, '00:14:20', 'Errori di scena / Posizione', 'Quando Rey mangia la sua porzione all''interno del camminatore AT-AT dismesso su Jakku, le macchie di sporco e polvere sul suo viso cambiano posizione e intensità da un''inquadratura all''altra.', TRUE, '2026-11-01T17:27:41.651973', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(791, 148, '00:13:40', 'Continuità', 'Durante il primo attacco a sorpresa dell''Acheron nella nebbia, Jack Aubrey viene ferito alla spalla e al collo da alcune schegge. Nelle inquadrature successive, la quantità di sangue che gli macchia la camicia e cola sulla clavicola varia vistosamente tra primi piani e campi medi, riducendosi per poi riapparire più estesa.', TRUE, '2026-09-29T15:13:52.315198', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(793, 148, '00:38:22', 'Continuità / Oggetti di scena', 'Durante la trapanazione cranica eseguita da Stephen Maturin sul marinaio ferito, l''orientamento della moneta d''argento da inserire e la disposizione dei ferri chirurgici sul vassoio cambiano posizione tra l''inquadratura di dettaglio e il piano medio successivo.', TRUE, '2026-09-29T15:13:52.315198', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(794, 148, '00:53:45', 'Continuità', 'Nel pieno della furiosa tempesta a Capo Horn, quando Aubrey è costretto ad abbattere le sartie dell''albero caduto per evitare che la Surprise affondi, i suoi capelli e gli abiti fradici cambiano disposizione a ogni stacco: in un''inquadratura ha ciocche incollate sulla fronte, nello stacco successivo sono raccolte e scostate dal viso.', TRUE, '2026-09-29T15:13:52.315198', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(795, 148, '01:14:10', 'Errori di scena / Anacronismi', 'Nell''equipaggiamento scientifico che Maturin utilizza per catalogare e conservare i campioni botanici e zoologici si notano flaconi e morsetti con filettature meccaniche e finiture metalliche prodotte a macchina, tipiche della produzione industriale del tardo Ottocento e non del 1805.', TRUE, '2026-09-29T15:13:52.315198', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(796, 148, '01:34:50', 'Continuità', 'Durante l''esplorazione a terra alle Isole Galápagos, mentre Maturin cerca il cormorano attero tra le rocce vulcaniche, l''ombra proiettata dal suo corpo e la luce solare sul paesaggio mutano drasticamente da un''inquadratura all''altra, indicando che i frammenti della stessa sequenza sono stati girati a diverse ore di distanza.', TRUE, '2026-09-29T15:13:52.315198', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(797, 148, '01:52:15', 'Continuità / Trucco e costumi', 'Nel culmine dell''arrembaggio finale contro l''Acheron, la giacca dell''uniforme di Aubrey subisce evidenti tagli e bruciature di polvere da sparo durante il combattimento corpo a corpo; tuttavia, pochi secondi dopo, quando avanza sottocoperta, il tessuto della manica risulta integro e nettamente più pulito.', TRUE, '2026-09-29T15:13:52.315198', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(798, 128, '00:12:45', 'Anacronismo', 'La motocicletta guidata da John Mallory (James Coburn) è un modello Triumph risalente alla fine degli anni ''20, mentre le vicende del film sono ambientate durante la Rivoluzione Messicana, precisamente nel 1913.', TRUE, '2026-09-29T16:26:57.287589', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(799, 128, '00:32:15', 'Errore di montaggio / Continuità', 'Nella scena in cui Juan e John parlano all''interno della taverna, la camicia di Juan appare vistosamente bagnata di sudore e sporca di polvere. Al cambio d''inquadratura, la camicia risulta improvvisamente molto più pulita e asciutta, per poi tornare bagnata nell''inquadratura successiva.', TRUE, '2026-09-29T16:26:57.287589', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(800, 128, '00:55:30', 'Errore di scena / Posizione', 'Quando John prepara i candelotti di dinamite sul tavolo per pianificare il colpo alla banca di Mesa Verde, la disposizione e il numero dei candelotti cambiano vistosamente tra il primo piano dettagliato e l''inquadratura più larga.', TRUE, '2026-09-29T16:26:57.287589', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(801, 128, '01:15:20', 'Anacronismo', 'Negli uffici governativi e all''interno della banca di Mesa Verde sono visibili alcune bandiere messicane che presentano lo stemma dell''aquila in una versione grafica che è stata adottata ufficialmente solo a partire dal 1968.', TRUE, '2026-09-29T16:26:57.287589', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(802, 128, '01:42:10', 'Anacronismo / Armi', 'Durante la celebre battaglia sul ponte, i soldati dell''esercito regolare messicano utilizzano una mitragliatrice pesante che è chiaramente una MG42 tedesca (o una sua variante ravvicinata), un''arma prodotta a partire dal 1942 e quindi inesistente nel 1913.', TRUE, '2026-09-29T16:26:57.287589', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(803, 128, '02:02:15', 'Errore tecnico / Elementi di produzione', 'Durante la spettacolare scena dello scontro e dell''esplosione del treno, nell''angolo sinistro dell''inquadratura in campo largo è possibile scorgere per una frazione di secondo la sagoma di una seconda cinepresa protetta da pannelli e un membro della troupe.', TRUE, '2026-09-29T16:26:57.287589', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(804, 128, '02:18:40', 'Errore di continuità / Trucco', 'Nelle drammatiche sequenze finali, dopo l''esplosione che ferisce mortalmente John, i tagli, le bruciature e le tracce di sangue sul suo volto cambiano posizione e intensità tra i diversi primi piani ravvicinati mentre dialoga con Juan.', TRUE, '2026-09-29T16:26:57.287589', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(3599, 76, '00:22:15', 'Troupe o microfoni visibili', 'Mentre Rey e Finn corrono nel deserto di Jakku sfuggendo all''attacco dei caccia TIE, sulla sabbia incontaminata davanti a loro sono chiaramente visibili le tracce delle ruote del veicolo della troupe e della telecamera.', TRUE, '2026-11-01T17:27:41.651973', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3600, 76, '00:23:40', 'Errori di scena / Posizione', 'Durante la fuga a piedi verso il Millennium Falcon, Finn afferra la mano di Rey. Quando la scena stacca sul primo piano e poi torna al campo largo, la presa delle loro mani cambia bruscamente e si stacca in modo incoerente con il movimento continuo della corsa.', TRUE, '2026-11-01T17:27:41.651973', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3601, 76, '00:54:10', 'Errori di scena / Posizione', 'Sul pianeta Takodana, quando Han Solo regala a Rey la pistola blaster verde, la posizione della mano di Han che tiene il calcio dell''arma cambia nettamente tra il campo lungo e il primo piano stretto.', TRUE, '2026-11-01T17:27:41.651973', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3602, 76, '01:14:30', 'Errori di scena / Posizione', 'Nella sala interrogatori della Base Starkiller, Kylo Ren si toglie l''elmo e lo appoggia su una vasca piena di cenere. Nelle inquadrature successive, la quantità di cenere sull''elmo e la sua inclinazione variano sensibilmente.', TRUE, '2026-11-01T17:27:41.651973', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3603, 76, '01:28:00', 'Errori di scena / Posizione', 'Quando Rey si libera dalla sedia di contenzione usando il trucco mentale della Forza su uno Stormtrooper, le cinghie che le bloccano le braccia risultano già visibilmente allentate prima ancora che lei inizi a manipolare la guardia.', TRUE, '2026-11-01T17:27:41.651973', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3604, 76, '01:52:40', 'Errori di scena / Posizione', 'Durante lo scontro finale con le spade laser nella foresta innevata, l''accumulo di neve sui capelli e sulle spalle di Kylo Ren e Rey cambia istantaneamente tra le inquadrature ravvicinate e i campi lunghi.', TRUE, '2026-11-01T17:27:41.651973', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3918, 216, '01:18:00', 'Errori di scena / Posizione', 'Quando Novecento spezza in più parti la matrice del disco appena inciso per la ragazza, i solchi di rottura ed il numero di frammenti visibili quando la rompe differiscono rispetto a quando Max raccoglie i pezzi nascosti nel pianoforte e li riassembla sul giradischi.', TRUE, '2026-11-02T10:13:48.117704', 'The Legend of 1900 record broken scene Novecento', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(15, 2, '00:41:20', 'Anacronismo', 'Nella scuola di gladiatori di Proximo in Nord Africa, le porte di alcune gabbie e stalle sono assicurate con lucchetti in metallo con serratura a chiave di concezione moderna.', TRUE, '2026-09-13T14:42:52.837227', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(805, 149, '00:04:15', 'Incongruenza visiva / Continuità', 'Durante la gara di autocross iniziale, le vetture dei protagonisti cambiano livello di sporco e fango sulla carrozzeria da un''inquadratura all''altra, passando da essere completamente ricoperte di fango a quasi pulite nel giro di pochi secondi.', TRUE, '2026-09-29T16:30:54.346567', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(806, 149, '00:18:30', 'Errore di montaggio / Continuità', 'Nella celebre scena della sfida a ''birra e salsicce'' nel locale, il numero di salsicce rimaste nei piatti di Kid e Ben oscilla in modo incoerente tra i primi piani e i campi larghi, aumentando e diminuendo senza che i personaggi le abbiano effettivamente consumate.', TRUE, '2026-09-29T16:30:54.346567', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(807, 149, '00:35:12', 'Controfigura evidente', 'Durante la rissa nella palestra, quando Terence Hill compie le spettacolari acrobazie sulle sbarre e sugli attrezzi ginnici, in diverse inquadrature dinamiche è chiaramente visibile il volto della controfigura acrobatica al posto di quello dell''attore.', TRUE, '2026-09-29T16:30:54.346567', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(808, 149, '00:52:45', 'Incongruenza / Equipaggiamento', 'Durante l''inseguimento in moto nel bosco, le motociclette utilizzate dagli scagnozzi cambiano tipo di pneumatici: in alcune scene di inseguimento montano gomme tassellate da fuoristrada, mentre nelle inquadrature di scivolata su asfalto presentano gomme lisce stradali.', TRUE, '2026-09-29T16:30:54.346567', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(809, 149, '01:02:10', 'Errore di scena / Oggettistica', 'Mentre il killer si prepara a sparare a Ben durante le prove del coro, il mirino telescopico del suo fucile di precisione appare montato al contrario in una delle inquadrature di dettaglio, per poi tornare orientato correttamente nell''inquadratura successiva.', TRUE, '2026-09-29T16:30:54.346567', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(810, 149, '01:18:15', 'Trucco / Effetti speciali', 'Nella rissa finale all''interno del locale pieno di palloncini, quando Bud Spencer colpisce uno scagnozzo facendolo volare contro una colonna, si nota chiaramente per una frazione di secondo il materasso di protezione scuro posizionato a terra per attutire la caduta dello stuntman.', TRUE, '2026-09-29T16:30:54.346567', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(811, 149, '01:26:40', 'Incongruenza / Continuità', 'Nel finale, quando una delle due nuove dune buggy rosse prende fuoco dopo la collisione, l''incendio divampa istantaneamente su tutta la vettura. Tuttavia, nell''inquadratura successiva, i danni da bruciatura sono visibili solo sul retro, lasciando la parte anteriore e la cappottina gialla inspiegabilmente intatte.', TRUE, '2026-09-29T16:30:54.346567', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(696, 64, '00:14:22', 'Anacronismi', 'Nelle scene girate nella foresta di Sherwood (in realtà Bidwell Park in California), si possono chiaramente notare sullo sfondo diversi alberi di eucalipto. Questa specie vegetale è originaria dell''Australia ed è stata introdotta nel continente americano solo nel XIX secolo, rendendo la sua presenza del tutto impossibile nell''Inghilterra del XII secolo.', TRUE, '2026-09-22T21:12:39.728883', NULL, 0, 0, 'mrtlsn07@gmail.com', 'ia', NULL),
(65, 26, '00:44:05', 'Continuity', 'La macchia di sangue e il taglio sulla spalla del gladiatore cambiano braccio tra un''inquadratura e la successiva.', TRUE, '2026-09-13T15:01:46.17144', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(745, 141, '01:39:50', 'Controfigure e incongruenze', 'Durante la sequenza dell''attacco alla gabbia subacquea, nelle riprese reali con lo squalo bianco (girate in Australia) si nota chiaramente che la persona nella gabbia è la controfigura rimpicciolita/manichino e non Richard Dreyfuss, oltre al fatto che lo squalo reale è nettamente più piccolo del modello animatronico usati nel film.', TRUE, '2026-09-27T20:43:10.736812', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(746, 141, '01:55:05', 'Effetti speciali visibili', 'Nel momento culminante in cui lo squalo balza sulla poppa dell''Orca affondandola parzialmente, sotto la pancia dell''animatronic ''Bruce'' è chiaramente visibile la piattaforma idraulica grigia utilizzata per sollevare la struttura.', TRUE, '2026-09-27T20:43:10.736812', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(3605, 77, '00:04:15', 'Errori di scena / Posizione', 'Quando Poe Dameron si trova all''interno del suo caccia X-wing prima di iniziare l''attacco alla Dreadnought, la posizione delle cinghie del suo casco e il modo in cui indossa i guanti cambiano ripetutamente tra le inquadrature in primo piano e quelle in campo medio.', TRUE, '2026-11-01T17:28:09.603308', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3606, 77, '00:32:00', 'Errori di scena / Posizione', 'Durante la sequenza in cui Rey brandisce la spada laser di Anakin/Luke su Ahch-To davanti a Luke, i capelli di Daisy Ridley cambiano continuamente posizione tra le riprese frontali e quelle di spalle, passando da dietro le orecchie a coprire il viso.', TRUE, '2026-11-01T17:28:09.603308', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3607, 77, '01:15:20', 'Errori di scena / Posizione', 'Nel combattimento nella Sala del Trono di Snoke, la guardia del corpo pretoriana che combatte contro Rey perde un''arma e la recupera nella ripresa successiva, oppure l''arma stessa sparisce e riappare a seconda dell''angolo di ripresa.', TRUE, '2026-11-01T17:28:09.603308', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3608, 77, '01:17:40', 'Troupe o microfoni visibili', 'Durante la caotica scena della lotta nella sala del trono di Snoke, in un fotogramma ravvicinato è possibile intravedere brevemente l''estremità di un''asta del microfono o un riflesso dell''attrezzatura di illuminazione sul pavimento lucido.', TRUE, '2026-11-01T17:28:09.603308', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3609, 77, '01:52:10', 'Errori di scena / Posizione', 'Durante la battaglia sul pianeta minerario Crait, i danni subiti dallo speeder di Finn cambiano visibilmente di gravità e posizione del fumo tra un''inquadratura e l''altra mentre si dirige verso il cannone del Primo Ordine.', TRUE, '2026-11-01T17:28:09.603308', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3610, 78, '01:23:00', 'Errori di scena / Posizione', 'Durante il duello tra Rey e Kylo Ren sui resti della Seconda Morte Nera, la posizione dei detriti e lo stato dell''acqua variano visibilmente tra un''inquadratura e l''altra a causa della complessa combinazione di set fisico e green screen.', TRUE, '2026-11-01T17:28:25.20183', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3919, 227, '00:15:00', 'Errori di scena / Posizione', 'Quando Kevin scende le scale con la spesa, le borse cambiano posizione e modo di essere tenute tra un''inquadratura e l''altra.', TRUE, '2026-11-02T10:14:39.590791', 'Home Alone grocery shopping scene error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3920, 227, '00:22:00', 'Errori di scena / Posizione', 'Mentre la mamma di Kevin cerca di telefonare a Chicago dall''aeroporto di Parigi, la cornetta del telefono cambia mano e orientamento rapidamente nei cambi di inquadratura.', TRUE, '2026-11-02T10:14:39.590791', 'Home Alone Kate phone booth paris error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3921, 227, '00:35:00', 'Errori di scena / Posizione', 'Quando Harry e Marv osservano la casa dei McCallister fuori dalla finestra, la quantità di neve sul davanzale e sul cappotto di Harry varia visibilmente tra i primi piani e i campi lunghi.', TRUE, '2026-11-02T10:14:39.590791', 'Home Alone wet bandits outside house continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3611, 79, '00:39:00', 'Troupe o microfoni visibili', 'Quando Luke e Obi-Wan entrano nella cantina di Mos Eisley, in una ripresa ad ampia inquadratura si può intravedere chiaramente per un istante l''ombra di un microfono a boom che si muove sulla parete di fondo.', TRUE, '2026-11-01T17:28:40.314496', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(812, 152, '00:32:15', 'Incongruenza fisica / Effetti speciali', 'Durante la scena del capovolgimento della nave, quando il salone principale si ribalta, si può notare un pianoforte a coda che scivola sul soffitto. In alcune inquadrature ravvicinate, il pianoforte si muove in una direzione, ma nel totale successivo si muove nella direzione opposta rispetto all''inclinazione della stanza.', TRUE, '2026-09-30T14:07:31.59787', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(813, 152, '00:48:10', 'Incongruenza di montaggio / Continuità', 'Mentre il gruppo guidato da Dylan attraversa il condotto dell''ascensore in fiamme, i capelli e i vestiti di Maggie (Jacinda Barrett) appaiono completamente bagnati e arruffati. Nell''inquadratura immediatamente successiva, i suoi capelli sono visibilmente asciutti e parzialmente pettinati, per poi tornare bagnati subito dopo.', TRUE, '2026-09-30T14:07:31.59787', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(814, 152, '01:02:45', 'Errori di scena / Oggetti', 'Durante l''attraversamento del condotto d''aria allagato, le torce elettriche utilizzate dai sopravvissuti continuano a funzionare perfettamente sott''acqua. Tuttavia, si tratta di normali torce non subacquee che avrebbero dovuto subire un cortocircuito immediato una volta immerse.', TRUE, '2026-09-30T14:07:31.59787', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(3612, 79, '01:21:00', 'Errori di scena / Posizione', 'Durante la sequenza nel compattatore di rifiuti della Morte Nera, la posizione dell''acqua e dei detriti intorno ai personaggi cambia visibilmente tra un''inquadratura e l''altra, così come i livelli di sporco sui costumi.', TRUE, '2026-11-01T17:28:40.314496', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(816, 152, '01:22:15', 'Errori di scena / Posizione', 'Quando Robert Ramsey (Kurt Russell) tenta di azionare la valvola di emergenza per invertire la rotazione delle eliche, lo si vede girare la manovella in senso orario. Nell''inquadratura successiva, da un''angolazione diversa, la sta girando chiaramente in senso antiorario.', TRUE, '2026-09-30T14:07:31.59787', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(817, 152, '01:28:40', 'Incongruenza di trucco', 'Nelle scene finali all''interno del compartimento delle eliche, le ferite e i tagli sul volto di Richard Nelson (Richard Dreyfuss) cambiano visibilmente di intensità e posizione: un profondo graffio sulla guancia destra scompare in un''inquadratura ravvicinata per poi riapparire più sfumato subito dopo.', TRUE, '2026-09-30T14:07:31.59787', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(818, 152, '01:31:10', 'Incongruenza fisica / Effetti speciali', 'Quando i sopravvissuti si lanciano in acqua per sfuggire all''esplosione finale della nave, l''enorme elica di prua smette improvvisamente di girare e poi riprende a ruotare a piena velocità tra due inquadrature consecutive, senza che nessuno abbia toccato i comandi in quel lasso di tempo.', TRUE, '2026-09-30T14:07:31.59787', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(838, 153, '01:08:40', 'Continuity / Dettagli', 'Quando Buzz è legato al razzo ''Big One'' con il nastro adesivo nero, il numero di giri del nastro attorno al suo torso e la larghezza dello stesso variano visibilmente tra i primi piani e i campi lunghi.', TRUE, '2026-09-30T18:32:59.256786', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(839, 153, '01:14:25', 'Errore di continuità / Props', 'Durante il rocambolesco inseguimento del camion del trasloco, l''antenna sul telecomando della macchina radiocomandata (RC) cambia lunghezza ed è piegata in alcune inquadrature, per poi apparire perfettamente dritta e svettante in altre.', TRUE, '2026-09-30T18:32:59.256786', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(267, 53, '00:15:40', 'Errori di scena / Posizione', 'Durante il flashback ambientato nel XVI secolo, la fodera della spada sulla schiena di Connor MacLeod passa dal lato destro al lato sinistro della spalla tra due inquadrature contigue.', TRUE, '2026-09-14T13:51:54.162455', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(720, 138, '00:22:45', 'Errori di scena / Posizione', 'Nella scena in cui Ordell e Louis conversano nel soggiorno di Melanie mentre guardano la TV, la posizione delle gambe di Melanie sul divano e l''altezza del liquido nel suo bicchiere cambiano visibilmente ad ogni cambio di inquadratura tra i campi e i controcampi.', TRUE, '2026-09-26T14:36:06.948712', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(721, 138, '00:36:10', 'Errori di scena / Posizione', 'Quando Max Cherry accoglie Jackie all''uscita dalla prigione e vanno al bar, la sigaretta che Max tiene in mano varia ripetutamente di lunghezza: in un piano sequenza appare quasi consumata, mentre al controcampo successivo torna ad essere significativamente più lunga.', TRUE, '2026-09-26T14:36:06.948712', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(3613, 79, '00:19:00', 'Errori di scena / Posizione', 'Quando i soldati imperiali (Sandtroopers) perquisiscono il landspeeder di Luke fuori da Mos Eisley, uno di loro si avvicina armato, ma nelle inquadrature successive la posizione del suo fucile cambia improvvisamente.', TRUE, '2026-11-01T17:28:40.314496', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3614, 79, '01:04:00', 'Errori di scena / Posizione', 'Quando Han Solo insegue gli stormtrooper nel blocco di detenzione della Morte Nera urlando ed entrando in una sala di controllo, in un''inquadratura successiva sparisce per un attimo la fondina della sua pistola.', TRUE, '2026-11-01T17:28:40.314496', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3618, 81, '00:00:00', 'Troupe o microfoni visibili', 'Durante la battaglia sulla chiatta di Jabba the Hutt, in alcune inquadrature è possibile intravedere brevemente l''ombra di un operatore di boom o dell''attrezzatura di ripresa proiettata sui personaggi o sulle pareti della chiatta.', TRUE, '2026-11-01T17:29:08.108255', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3619, 81, '00:00:00', 'Errori di scena / Posizione', 'Quando Luke Skywalker si trova nella cella di Jabba prima di cadere nel Rancor pit, le manette elettroniche ai suoi polsi cambiano posizione o appaiono allacciate in modo differente tra un cambio di inquadratura e l''altro.', TRUE, '2026-11-01T17:29:08.108255', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3620, 81, '00:00:00', 'Errori di scena / Posizione', 'Nel corso della sequenza nella foresta di Endor, i capelli di Leia variano leggermente nello styling e nel volume tra le riprese principali sul set e le riprese aggiuntive effettuate successivamente in studio.', TRUE, '2026-11-01T17:29:08.108255', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3922, 227, '00:48:00', 'Errori di scena / Posizione', 'Durante la scena in cui Kevin mangia la cena a base di maccheroni al formaggio, il tovagliolo che ha sulle ginocchia scompare e ricapare tra un taglio di montaggio e l''altro.', TRUE, '2026-11-02T10:14:39.590791', 'Home Alone Kevin macaroni dinner scene error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3923, 227, '01:05:00', 'Errori di scena / Posizione', 'Le decorazioni natalizie e le candele accese vicino alla porta d''ingresso cambiano disposizione sul tavolino mentre Marv e Harry si avvicinano all''entrata.', TRUE, '2026-11-02T10:14:39.590791', 'Home Alone entry hall decorations continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3932, 256, '00:00:00', 'Anacronismi', 'Durante il film, ambientato nel 1935, si vede l''uso della sedia elettrica con procedure e tecnologie che rispecchiano epoche diverse o presentano inesattezze rispetto all''effettivo sistema di esecuzione dello stato della Louisiana dell''epoca.', TRUE, '2026-11-02T10:14:57.257416', 'The Green Mile electric chair scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(819, 4, '00:08:00', 'Continuità', 'Quando Ace rientra nel suo appartamento con il cane appena salvato, sul tavolo si nota una scatola di cartone. L''aletta superiore della scatola cambia ripetutamente posizione, passando dall''essere aperta a completamente chiusa tra un''inquadratura e l''altra.', TRUE, '2026-09-30T14:13:27.336261', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(820, 4, '00:21:00', 'Continuità', 'Quando Ace trova la pietra arancione dell''anello dei Dolphins nel filtro della vasca di Snowflake, la gemma appare inizialmente piccola e di forma triangolare. Nelle inquadrature successive, quando la esamina da vicino, la pietra è visibilmente più grande e di forma rettangolare.', TRUE, '2026-09-30T14:13:27.336261', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(821, 4, '00:35:00', 'Continuità', 'Durante la scena a casa di Melissa, la porta a vetri scorrevole che conduce al balcone è chiaramente aperta in un''inquadratura a figura intera, ma risulta completamente chiusa nel controcampo successivo, senza che nessuno si sia avvicinato per toccarla.', TRUE, '2026-09-30T14:13:27.336261', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(822, 4, '00:44:00', 'Incongruenza storica', 'Nel filmato d''archivio del Super Bowl XVII (disputato nel 1983) che mostra il calcio fallito da Ray Finkle, i caschi e le divise dei Miami Dolphins presentano il logo e il design dei primi anni ''90, anacronistici rispetto all''epoca in cui si sarebbe svolto l''evento.', TRUE, '2026-09-30T14:13:27.336261', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(823, 4, '00:48:00', 'Incongruenza', 'Quando Ace visita la casa dei genitori di Ray Finkle e osserva le foto d''infanzia del giocatore, in una di esse il piccolo Ray indossa una t-shirt con un logo commerciale moderno che non esisteva negli anni ''60 o ''70, periodo in cui Finkle era bambino.', TRUE, '2026-09-30T14:13:27.336261', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(824, 4, '00:55:00', 'Continuità', 'Durante la telefonata nell''ufficio di Lois Einhorn, l''antenna del telefono cellulare della donna appare completamente sollevata in alcune inquadrature e totalmente abbassata in altre, alternandosi repentinamente durante il dialogo.', TRUE, '2026-09-30T14:13:27.336261', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(825, 4, '01:02:00', 'Elementi di scena visibili', 'Nella celebre sequenza in cui Ace scivola sul pavimento del manicomio di Shady Acres indossando il tutù rosa, durante l''inquadratura rallentata si possono chiaramente notare le ginocchiere protettive color carne sotto le sue calze chiare.', TRUE, '2026-09-30T14:13:27.336261', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(697, 64, '00:27:45', 'Errori di scena / Posizione', 'Durante il combattimento con i bastoni sul tronco sopra il torrente tra Robin Hood e Little John, Robin cade in acqua ed è completamente bagnato. Nella scena immediatamente successiva, quando risale sulla riva per parlare con gli uomini della foresta, i suoi abiti e la sua capigliatura appaiono visibilmente asciutti e perfettamente riordinati.', TRUE, '2026-09-22T21:12:39.728883', NULL, 0, 0, 'mrtlsn07@gmail.com', 'ia', NULL),
(698, 64, '00:43:10', 'Troupe o microfoni visibili', 'Durante l''imboscata nella foresta ai danni del convoglio del Principe Giovanni e di Lady Marian, in un''inquadratura dal basso di uno dei fuorilegge che si lancia da un ramo, è chiaramente visibile l''imbracatura di sicurezza con il cavo di sostegno che fuoriesce da sotto la casacca dell''attore.', TRUE, '2026-09-22T21:12:39.728883', NULL, 0, 0, 'mrtlsn07@gmail.com', 'ia', NULL),
(722, 138, '00:52:30', 'Troupe o microfoni visibili', 'Durante la tensione nell''appartamento di Jackie quando Ordell la sorprende al buio, al momento dell''accensione della lampada da tavolo è visibile per diversi secondi l''ombra proiettata dal microfono a giraffa (boom mic) sulla parte alta della parete a destra.', TRUE, '2026-09-26T14:36:06.948712', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(723, 138, '01:14:15', 'Anacronismi', 'L''opera è esplicitamente ambientata nel 1995 (come indicato sui documenti di viaggio e sulle carte d''identità dei personaggi). Tuttavia, nella sequenza del centro commerciale Del Amo, si scorge nel parcheggio una vettura il cui restyling del modello è stato commercializzato soltanto a partire dalla fine del 1996.', TRUE, '2026-09-26T14:36:06.948712', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(3615, 80, '01:28:00', 'Errori di scena / Posizione', 'Nel momento in cui Dart Fener taglia la mano a Luke Skywalker nella Carbon Chamber, la spada laser di Luke cambia posizione e orientamento tra un''inquadratura e l''altra.', TRUE, '2026-11-01T17:28:52.908976', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3616, 80, '01:05:00', 'Errori di scena / Posizione', 'Quando Ian Solo viene congelato nella carbonite, la posizione delle sue braccia e delle sue mani varia sensibilmente tra l''inquadratura ravvicinata e quella in campo largo.', TRUE, '2026-11-01T17:28:52.908976', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3617, 80, '00:44:00', 'Errori di scena / Posizione', 'All''interno del Millennium Falcon, durante la fuga dagli asteroidi, i tubi e i pannelli sullo sfondo cambiano disposizione tra le inquadrature interne dei vari personaggi.', TRUE, '2026-11-01T17:28:52.908976', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3924, 228, '00:00:00', 'Errori di scena / Posizione', 'Quando Kevin registra la lista dei regali all''inizio del film, la posizione delle sue mani sul registratore e il modo in cui tiene il microfono cambiano drasticamente tra un''inquadratura e l''altra.', TRUE, '2026-11-02T10:14:49.790822', 'Home Alone 2 voice recorder scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3925, 228, '00:00:00', 'Errori di scena / Posizione', 'All''aeroporto, quando Kevin scivola sul pavimento cerato e fa cadere i bagagli della gente, il numero e la disposizione delle valigie variano visibilmente tra il campo largo e i primi piani.', TRUE, '2026-11-02T10:14:49.790822', 'Home Alone 2 airport slide luggage continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3926, 228, '00:00:00', 'Errori di scena / Posizione', 'Quando Harry e Marv salgono sul taxi all''inizio del film a New York, la quantità di neve sui loro cappotti e cappelli scompare e riappare improvvisamente tra le diverse angolazioni della macchina.', TRUE, '2026-11-02T10:14:49.790822', 'Home Alone 2 Harry and Marv taxi snow continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3927, 228, '00:00:00', 'Errori di scena / Posizione', 'Nella scena in cui Kevin usa la carta di credito di suo padre per pagare la suite al Plaza Hotel, la tessera che mostra alla telecamera cambia posizione tra le dita in modo impossibile nel taglio di montaggio.', TRUE, '2026-11-02T10:14:49.790822', 'Home Alone 2 Kevin Plaza hotel credit card error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3928, 228, '00:00:00', 'Errori di scena / Posizione', 'Durante la sequenza delle trappole nella casa abbandonata, i mattoni lanciati da Kevin contro Marv colpiscono il volto del bandito lasciando segni di catrame o polvere che cambiano forma e posizione da un fotogramma all''altro.', TRUE, '2026-11-02T10:14:49.790822', 'Home Alone 2 Marv bricks face makeup continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3929, 228, '00:00:00', 'Troupe o microfoni visibili', 'In una delle inquadrature ampie mentre Kevin cammina per le strade di New York nei pressi del Rockefeller Center, si intravede brevemente l''ombra di un operatore di boom mic sul marciapiede.', TRUE, '2026-11-02T10:14:49.790822', 'Home Alone 2 microphone shadow visible scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3930, 228, '00:00:00', 'Errori di scena / Posizione', 'Quando i genitori di Kevin sono all''aeroporto a Miami, la borsa che la madre tiene in mano cambia spalla e posizione tra un cambio di inquadratura e l''altro durante la conversazione concitata.', TRUE, '2026-11-02T10:14:49.790822', 'Home Alone 2 Catherine O Hara airport bag continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3621, 91, '00:05:00', 'Anacronismi', 'La sequenza iniziale del film è ambientata nel 1959 durante la festa del decimo anniversario di matrimonio del protagonista. Tuttavia, tra le automobili parcheggiate all''esterno della villa figurano diversi modelli registrati e commercializzati soltanto nei primi anni ''60.', TRUE, '2026-11-01T17:29:39.294377', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(826, 157, '00:14:22', 'Errore di continuità', 'Durante la scena nella nuova cameretta, il pulsante del laser sul braccio di Buzz Lightyear cambia colore da verde a rosso tra un''inquadratura ravvicinata e una a mezzo busto.', TRUE, '2026-09-30T18:30:32.591797', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(827, 157, '00:32:15', 'Errore di rendering / Clipping', 'Quando Woody si nasconde frettolosamente dietro lo zaino sul pavimento, la sua mano destra attraversa visibilmente il tessuto dello zaino, rivelando un errore nel calcolo delle collisioni dei modelli 3D.', TRUE, '2026-09-30T18:30:32.591797', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(828, 157, '00:48:50', 'Errore di posizionamento', 'La scritta sotto lo stivale destro di Woody mostra brevemente il nome ''Bonnie'', ma nella scena successiva riappare il nome del nuovo bambino, coerentemente con la trama del film.', TRUE, '2026-09-30T18:30:32.591797', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(694, 65, '01:32:15', 'Errori di scena / Posizione', 'Durante il duello finale tra Robin Hood e lo Sceriffo di Nottingham, le ferite e le macchie di sangue sulla camicia bianca di Robin cambiano forma, intensità e posizione esatta tra un''inquadratura e l''altra durante i tagli di montaggio più rapidi.', TRUE, '2026-09-22T20:36:28.422194', NULL, 0, 0, 'mrtlsn07@gmail.com', 'ia', NULL),
(699, 64, '01:02:15', 'Errori storici o fattuali', 'Nella sequenza del torneo di tiro con l''arco, diversi cavalieri e guardie indossano elementi completi di armature a piastre di metallo. Storicamente, alla fine del XII secolo (sotto il regno di Riccardo Cuor di Leone), le truppe indossavano prevalentemente giachi di maglia di ferro (usberghi); le armature a piastre articolate si diffusero soltanto a partire dal XIV secolo.', TRUE, '2026-09-22T21:12:39.728883', NULL, 0, 0, 'mrtlsn07@gmail.com', 'ia', NULL),
(245, 51, '00:25:30', 'Errori di scena / Posizione', 'A bordo della nave Q-Ship di Ebony Maw, la pettinatura di Doctor Strange passa da visibilmente arruffata e disordinata a perfettamente composta nel giro di poche inquadrature ravvicinate.', TRUE, '2026-09-14T13:51:08.269075', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(829, 157, '01:05:12', 'Errore di illuminazione', 'Mentre i giocattoli attraversano il giardino di notte, l''ombra di Rex viene proiettata verso sinistra, mentre quelle di Buzz e Woody vanno verso destra, indicando una gestione errata delle sorgenti di luce virtuali.', TRUE, '2026-09-30T18:30:32.591797', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(830, 157, '01:22:05', 'Errore di animazione fisica', 'Quando Woody tira la sua cordicella per parlare, l''anello di plastica rimane teso all''esterno della schiena per tutta la durata della frase preregistrata, invece di riavvolgersi progressivamente.', TRUE, '2026-09-30T18:30:32.591797', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(831, 157, '01:35:40', 'Errore di continuità', 'Slinky si trova in fondo al gruppo vicino alla porta d''ingresso, ma nell''inquadratura immediatamente successiva appare in prima fila accanto a Buzz, senza che ci sia stato il tempo fisico per spostarsi.', TRUE, '2026-09-30T18:30:32.591797', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(832, 157, '01:42:18', 'Errore di scena', 'Il cappello di Woody cade a terra durante l''inseguimento finale e si sporca visibilmente di fango. Quando Buzz lo raccoglie pochi secondi dopo, il cappello è completamente pulito e lucido.', TRUE, '2026-09-30T18:30:32.591797', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL);
INSERT INTO public.errori ("id", "film_id", "minuto", "categoria", "descrizione", "approvato", "creato_il", "youtube_query", "conferme", "contestazioni", "inserito_da", "provenienza", "screenshot_url") VALUES
(724, 138, '01:42:10', 'Errori di scena / Posizione', 'Nella sequenza del camerino di Billingsley al Del Amo Fashion Center durante lo scambio della borsa, il sacchetto giallo con i soldi sporge dalla borsa della spesa in modo diverso tra l''inquadratura in soggettiva di Jackie e l''inquadratura frontale su Melanie.', TRUE, '2026-09-26T14:36:06.948712', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(3622, 91, '00:45:00', 'Errori di scena / Posizione', 'Nella basilica di San Miniato al Monte a Firenze, durante il primo incontro tra Michael e Sandra che lavora al restauro del dipinto, la posizione del pennello nelle mani della donna e le macchie di colore sul suo camice variano in modo incongruo tra i primi piani e i campi medi.', TRUE, '2026-11-01T17:29:39.294377', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(932, 185, '00:28:15', 'Continuità / Costumi', 'Durante la scena della pioggia battente in strada, il cappotto di Larry è completamente inzuppato d''acqua. Tuttavia, nell''inquadratura immediatamente successiva all''interno dell''ufficio, il cappotto appare solo leggermente umido sulle spalle.', TRUE, '2026-10-09T15:07:02.550997', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(3623, 91, '01:32:00', 'Errori di scena / Posizione', 'Nella sequenza finale all''aeroporto, quando Michael corre verso Sandra in campo lungo e controcampo al rallentatore, la posizione del colletto della camicia e della cravatta di Michael cambia visibilmente a ogni stacco di montaggio.', TRUE, '2026-11-01T17:29:39.294377', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3931, 228, '00:00:00', 'Errori di scena / Posizione', 'Durante la scena del furto al negozio di giocattoli ''Duncan''s Toy Chest'', la vetrina sfondata mostra frammenti di vetro che cambiano visibilmente disposizione sul marciapiede nelle riprese successive.', TRUE, '2026-11-02T10:14:49.790822', 'Home Alone 2 Duncans Toy Chest window glass continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3947, 178, '00:43:00', 'Errori di scena / Posizione', 'Quando King Kong strappa i vestiti di Ann Darrow sulla cima della montagna, nelle inquadrature successive i brandelli dei vestiti cambiano visibilmente dimensione e posizione tra un cambio di inquadratura e l''altro.', TRUE, '2026-11-02T10:17:02.237633', 'King Kong 1933 Ann Darrow dress rip continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3948, 178, '01:25:00', 'Errori di scena / Posizione', 'Durante la celebre sequenza della lotta sul grattacielo dell''Empire State Building, i biplani attaccano Kong. La posizione delle ferite e dei dettagli sui modellini e sulle riprese in stop-motion cambia in modo discontinuo tra un''inquadratura e la successiva.', TRUE, '2026-11-02T10:17:02.237633', 'King Kong 1933 Empire State Building biplanes continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3954, 182, '01:21:00', 'Errori di scena / Posizione', 'Durante la sequenza in cui Gandalf si consulta con Elrond, Saruman e Galadriel a Gran Burrone, la posizione del bastone di Gandalf poggiato accanto alla sua sedia varia in angolazione e distanza rispetto al pavimento tra le diverse inquadrature.', TRUE, '2026-11-02T10:17:31.133309', 'The Hobbit An Unexpected Journey Rivendell meeting scene mistake', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3955, 182, '02:25:00', 'Errori di scena / Posizione', 'Nel climax finale sulle montagne, quando Thorin viene ferito da Azog, la spada di Thorin cade a terra. Nelle inquadrature successive, la distanza tra il corpo di Thorin e la spada cambia drasticamente tra un cambio di inquadratura e l''altro.', TRUE, '2026-11-02T10:17:31.133309', 'The Hobbit An Unexpected Journey Thorin vs Azog ending scene goof', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3958, 190, '00:00:00', 'Errori di scena / Posizione', 'Durante una delle prime feste, i bicchieri e le bottiglie sui tavoli cambiano ripetutamente posizione e livello di riempimento tra un''inquadratura e l''altra, senza che nessuno li tocchi.', TRUE, '2026-11-02T10:18:16.193361', 'La Boum party scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3624, 92, '00:05:00', 'Errori di scena / Posizione', 'Durante la prima colazione di Gino alla trattoria, il livello del vino nel bicchiere e la posizione del pezzo di pane sul tavolo cambiano vistosamente tra le inquadrature ravvicinate e i piani medi.', TRUE, '2026-11-01T17:30:10.962923', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3625, 92, '00:48:00', 'Errori di scena / Posizione', 'Nella sequenza del concorso lirico ad Ancona, la disposizione del pubblico e dei giurati alle spalle di Bragana varia in modo non coerente tra i primi piani del cantante e le inquadrature d''insieme della sala.', TRUE, '2026-11-01T17:30:10.962923', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3626, 92, '01:12:00', 'Errori di scena / Posizione', 'Durante il dialogo sul treno tra Gino e lo Spagnolo, il paesaggio visibile dal finestrino e la direzione del fumo della locomotiva cambiano bruscamente tra un taglio e l''altro, suggerendo riprese effettuate in momenti diversi.', TRUE, '2026-11-01T17:30:10.962923', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3627, 92, '00:35:00', 'Troupe o microfoni visibili', 'In una ripresa in esterni lungo l''argine del Po, l''ombra della cinepresa e dell''operatore è chiaramente visibile sul terreno mentre la macchina da presa esegue un movimento a seguire i protagonisti.', TRUE, '2026-11-01T17:30:10.962923', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(833, 153, '00:09:15', 'Continuity / Errori di oggetti', 'Durante la riunione di emergenza sul tappeto di Andy, l''orologio Topolino appeso alla parete cambia l''ora mostrata dalle lancette in modo incoerente tra un campo e un controcampo, avanzando di circa 20 minuti per poi tornare indietro.', TRUE, '2026-09-30T18:32:59.256786', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(834, 153, '00:23:45', 'Continuity / Posizionamento', 'Nella scena in cui Woody spinge accidentalmente Buzz fuori dalla finestra, la posizione dei pennarelli, della lavagna e della lampada sulla scrivania di Andy cambia radicalmente tra l''inquadratura dall''alto e il primo piano.', TRUE, '2026-09-30T18:32:59.256786', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(835, 153, '00:32:10', 'Errore di continuità', 'Alla stazione di servizio Dinoco, durante la zuffa tra Woody e Buzz sotto il camion della Pizza Planet, la quantità di sporco sulle gomma posteriore del camion cambia drasticamente tra un stacco e l''altro.', TRUE, '2026-09-30T18:32:59.256786', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(836, 153, '00:48:30', 'Errore di scena / Posizione', 'Nella stanza di Sid, quando Woody viene intrappolato sotto la cassetta del latte, la pesante cassetta degli attrezzi appoggiata sopra di essa cambia orientamento e distanza dal bordo tra le diverse inquadrature.', TRUE, '2026-09-30T18:32:59.256786', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(837, 153, '00:55:12', 'Continuity / Oggetti', 'Dopo che Buzz tenta di volare e si stacca il braccio cadendo dalle scale nella casa di Sid, il braccio sinistro staccato si trova a distanze diverse dal corpo tra l''inquadratura dall''alto e quella in cui arriva la sorellina Hannah.', TRUE, '2026-09-30T18:32:59.256786', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(700, 64, '01:08:35', 'Errori di scena / Posizione', 'Quando Robin esegue il famoso tiro che spacca la freccia di Philip di Arras, nel primo piano del bersaglio la freccia originale viene spaccata esattamente a metà in modo simmetrico. Nel campo lungo successivo, la freccia appare invece spezzata in modo irregolare, con una scheggia pendente nettamente verso sinistra.', TRUE, '2026-09-22T21:12:39.728883', NULL, 0, 0, 'mrtlsn07@gmail.com', 'ia', NULL),
(733, 139, '01:38:50', 'Errori storici o fattuali', 'Quando Tangerine viene spinto fuori dal treno in corsa e rimane aggrappato al finestrino esterno mentre il treno viaggia a oltre 300 km/h, riesce a rompere il vetro e a rientrare. Fisicamente, a quella velocità, la pressione dell''aria e la resistenza aerodinamica renderebbero impossibile per un essere umano rimanere aggrappato alla carrozzeria liscia o muoversi con tale agilità senza essere spazzato via all''istante.', TRUE, '2026-09-26T15:22:11.065646', NULL, 0, 0, 'mrtrrt@libero.it', 'ia', NULL),
(743, 141, '00:48:30', 'Continuità', 'Nella famosa scena dell''attacco al piccolo Alex Kintner, le ombre sulla spiaggia e la posizione delle persone attorno a Brody variano drasticamente da un''inquadratura all''altra, rivelando che le riprese sono avvenute in momenti diversi della giornata.', TRUE, '2026-09-27T20:43:10.736812', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(3628, 92, '02:12:00', 'Errori di scena / Posizione', 'Nella sequenza finale dell''incidente automobilistico, l''entità dei danni sulla carrozzeria e la posizione dell''auto ribaltata non corrispondono alla dinamica dell''impatto mostrata nell''inquadratura immediatamente precedente.', TRUE, '2026-11-01T17:30:10.962923', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3933, 256, '00:00:00', 'Errori di scena / Posizione', 'Nella scena in cui John Coffrey tiene le mani di Paul Edgecomb per curargli l''infezione urinaria, la posizione delle sue mani e la presa cambiano leggermente tra un''inquadratura e l''altra durante i tagli di montaggio.', TRUE, '2026-11-02T10:14:57.257416', 'The Green Mile John Coffrey healing Paul', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3934, 256, '00:00:00', 'Errori storici o fattuali', 'Nel penitenziario di Cold Mountain viene fatto riferimento a procedure federali e statali miste che non rispecchiano fedelmente il sistema carcerario della Louisiana nel periodo della Grande Depressione.', TRUE, '2026-11-02T10:14:57.257416', 'The Green Mile historical accuracy', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3943, 176, '01:21:00', 'Anacronismi', 'Durante la sparatoria alla stazione ferroviaria di Union Station, si vede una carrozzina per bambini scendere le scale. Il modello specifico di passeggino mostrato nella scena (un modello moderno pieghevole) non esisteva nel 1930, periodo in cui è ambientato il film.', TRUE, '2026-11-02T10:16:54.946744', 'The Untouchables Union Station baby carriage scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3944, 176, '00:00:00', 'Errori storici o fattuali', 'Nel film, Frank Nitti viene ucciso da Eliot Ness lanciandolo dal tetto del tribunale durante il processo di Al Capone. Storicamente, Frank Nitti non morì in quel modo né in quel contesto: sopravvisse al processo a Capone e si suicidò nel 1943 a causa di problemi di salute.', TRUE, '2026-11-02T10:16:54.946744', 'The Untouchables Frank Nitti rooftop scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3945, 176, '00:35:00', 'Errori di scena / Posizione', 'Nella scena in cui Eliot Ness incontra per la prima volta Malone (Sean Connery) nella sua chiesa, la posizione del rosario e degli oggetti nelle mani di Malone cambia visibilmente tra un''inquadratura e l''altra durante il dialogo.', TRUE, '2026-11-02T10:16:54.946744', 'The Untouchables Kevin Costner Sean Connery church scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3946, 176, '01:45:00', 'Errori storici o fattuali', 'Nel climax del film, Al Capone viene giudicato e condannato specificamente per evasione fiscale e omicidio nell''aula del tribunale. Nella realtà, il processo a Capone riguardava esclusivamente l''evasione fiscale e non fu accusato o condannato per omicidio in quel procedimento.', TRUE, '2026-11-02T10:16:54.946744', 'The Untouchables courtroom trial scene Robert De Niro', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3949, 179, '00:00:00', 'Troupe o microfoni visibili', 'Durante le scene girate sulla spiaggia dell''isola, in alcune inquadrature è possibile intravedere brevemente l''ombra di un microfono a boom o attrezzatura della troupe sulla sabbia o sulle rocce.', TRUE, '2026-11-02T10:17:10.210041', 'King Kong 1976 crew visible microphone boom', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(840, 158, '00:03:45', 'Errore di continuità', 'Quando il padre di Bruce scende nel pozzo per salvarlo dopo la caduta, la corda di sicurezza cambia posizione sulle sue spalle e intorno al corpo tra un''inquadratura e l''altra.', TRUE, '2026-09-30T18:58:55.018001', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(841, 158, '00:14:10', 'Errore di continuità', 'Durante l''allenamento con le spade sul ghiaccio tra Bruce e Ducard, la quantità di neve accumulata sulle spalle e sul cappotto di Ducard varia vistosamente e repentinamente tra i tagli di montaggio.', TRUE, '2026-09-30T18:58:55.018001', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(842, 158, '00:26:30', 'Errore di continuità', 'Nella scena in cui Bruce affronta Carmine Falcone nel suo locale, il livello del liquore nel bicchiere di Falcone sale e scende inspiegabilmente tra un''inquadratura e l''altra, senza che lui ne beva.', TRUE, '2026-09-30T18:58:55.018001', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(843, 158, '01:02:15', 'Errore di continuità', 'Mentre Lucius Fox mostra a Bruce i prototipi della Wayne Enterprises, Bruce esamina il cappuccio di Batman tenendolo con la mano sinistra, ma nell''inquadratura successiva lo sta reggendo con la mano destra.', TRUE, '2026-09-30T18:58:55.018001', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(844, 158, '01:18:40', 'Errore di scena / Equipaggiamento', 'Quando Batman solleva uno dei criminali di Falcone attraverso il lucernario bagnato dalla pioggia, per un breve istante sono visibili i cavi di sicurezza neri utilizzati per sollevare l''attore.', TRUE, '2026-09-30T18:58:55.018001', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(845, 158, '01:35:10', 'Errore di continuità', 'Durante lo spettacolare inseguimento con la Batmobile (Tumbler), una delle auto della polizia che si scontra perde completamente il paraurti anteriore. Nella sequenza immediatamente successiva, lo stesso veicolo mostra il paraurti di nuovo intatto.', TRUE, '2026-09-30T18:58:55.018001', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(846, 158, '01:48:25', 'Errore di continuità', 'Quando Rachel si trova nella Batcaverna dopo essere stata intossicata dal gas dello Spauracchio, la disposizione dei suoi capelli bagnati sul viso cambia radicalmente tra i primi piani e le inquadrature più larghe.', TRUE, '2026-09-30T18:58:55.018001', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(747, 141, '02:01:40', 'Membri della troupe visibili', 'Mentre Brody si trova sull''albero della nave che affonda e tenta di sparare alla bombola nella bocca dello squalo, sullo sfondo tra le onde a sinistra della barca è visibile la prua di un''imbarcazione di supporto della troupe cinematografica.', TRUE, '2026-09-27T20:43:10.736812', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(933, 185, '00:42:10', 'Anacronismo / Scenografia', 'Nonostante il film sia ambientato negli anni ''90 dell''Ottocento (1890s), sullo sfondo della hall del teatro è visibile un interruttore della luce elettrica a parete con un design tipico degli anni ''40, periodo di produzione del film.', TRUE, '2026-10-09T15:07:02.550997', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(934, 185, '00:55:30', 'Errori di scena / Posizione', 'Durante la cena al ristorante tra Larry e Sylvia, la bottiglia di vino sul tavolo cambia orientamento tra un''inquadratura e l''altra: l''etichetta è prima rivolta verso la telecamera e poi ruotata di lato, senza che nessuno l''abbia toccata.', TRUE, '2026-10-09T15:07:02.550997', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(935, 185, '01:02:15', 'Errore di produzione / Ombre', 'Durante la concitata scena dell''inseguimento nei vicoli, l''ombra del microfono a giraffa (boom mic) è chiaramente visibile per un paio di secondi sulla parete di mattoni a sinistra dello schermo.', TRUE, '2026-10-09T15:07:02.550997', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(936, 185, '01:14:45', 'Continuità / Oggetti', 'Quando Larry conta i soldi vinti alle corse dei cavalli, la mazzetta di banconote cambia spessore e disposizione tra il dettaglio ravvicinato delle sue mani e l''inquadratura più ampia che mostra anche il suo volto.', TRUE, '2026-10-09T15:07:02.550997', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(937, 185, '00:18:50', 'Anacronismo / Costumi', 'In una scena di strada affollata, alcune comparse femminili sullo sfondo indossano scarpe con tacchi e acconciature che riflettono la moda degli anni ''40 anziché la rigorosa ricostruzione storica dell''epoca tardo-vittoriana.', TRUE, '2026-10-09T15:07:02.550997', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(976, 213, '01:03:50', 'Errori di scena / Danni', 'Quando il gigantesco capodoglio bianco sperona la Essex la prima volta, le tavole dello scafo vengono sfondate verso l''interno. Nella successiva scena sottocoperta, i frammenti di legno e le assi spezzate appaiono orientati diversamente e la falla presenta dimensioni notevolmente ridotte rispetto all''esterno.', TRUE, '2026-10-17T15:13:31.17943', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(977, 213, '01:19:20', 'Anacronismo / Trucco', 'Dopo settimane alla deriva in mare aperto con razionamento estremo e forte disidratazione, i denti di Owen Chase e del capitano Pollard rimangono perfettamente allineati, bianchi e senza alcun segno visibile di scorbuto o deterioramento gengivale tipico dell''epoca e della situazione.', TRUE, '2026-10-17T15:13:31.17943', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(3629, 93, '00:00:00', 'Errori di scena / Posizione', 'Durante le sequenze in cui il Dr. Riordan versa l''acido nella vasca, il livello del liquido all''interno del contenitore cambia in modo incoerente tra le inquadrature ravvicinate e i piani medi.', TRUE, '2026-11-01T17:30:47.992055', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3630, 93, '00:00:00', 'Errori di scena / Posizione', 'La crescita della barba di Bill durante il periodo di prigionia non segue una progressione temporale logica, apparendo più corta o più lunga in modo casuale tra scene cronologicamente successive.', TRUE, '2026-11-01T17:30:47.992055', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3631, 93, '00:00:00', 'Errori storici o fattuali', 'L''acido cloridrico utilizzato nel film non è in grado di dissolvere un corpo umano con la rapidità e la pulizia mostrate; inoltre, la reazione chimica produrrebbe fumi tossici che renderebbero l''ambiente del garage letale senza una ventilazione industriale.', TRUE, '2026-11-01T17:30:47.992055', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3632, 93, '00:00:00', 'Errori di scena / Posizione', 'In diverse inquadrature nel garage, la quantità di acido visibile nella damigiana (carboy) fluttua visibilmente, aumentando o diminuendo indipendentemente dal fatto che il dottore ne abbia appena prelevato una parte.', TRUE, '2026-11-01T17:30:47.992055', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3633, 93, '00:00:00', 'Troupe o microfoni visibili', 'In alcune scene d''interni nel garage abbandonato, si possono notare ombre anomale proiettate sulle pareti che non corrispondono ai movimenti degli attori, riconducibili alla troupe o alle attrezzature di ripresa.', TRUE, '2026-11-01T17:30:47.992055', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3634, 93, '00:00:00', 'Errori di scena / Posizione', 'La posizione del cane Monty cambia bruscamente tra i tagli di montaggio durante la scena in cui interagisce con il Dr. Riordan vicino alla zona della vasca.', TRUE, '2026-11-01T17:30:47.992055', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3635, 93, '00:00:00', 'Errori di scena / Posizione', 'La lunghezza della catena che tiene prigioniero Bill varia sensibilmente tra le diverse inquadrature, permettendogli in alcuni momenti di raggiungere punti della stanza che in precedenza sembravano fuori dalla sua portata.', TRUE, '2026-11-01T17:30:47.992055', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3636, 93, '00:00:00', 'Errori di scena / Posizione', 'Le macchie di sudore sul camice del Dr. Riordan appaiono e scompaiono o cambiano forma in modo non coerente durante lo svolgimento della stessa scena nel laboratorio.', TRUE, '2026-11-01T17:30:47.992055', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(847, 162, '00:02:45', 'Errore di continuità / Oggetti', 'Quando il riflettore con la scritta ''Sirius'' cade dal cielo sulla strada vicino a Truman, i frammenti di vetro e la posizione del faro sull''asfalto cambiano visibilmente tra l''inquadratura ravvicinata e quella successiva più ampia.', TRUE, '2026-09-30T19:53:41.113228', NULL, 0, 0, 'mrtlsn07@gmail.com', 'ia', NULL),
(848, 162, '00:32:15', 'Errore di continuità / Posizione', 'Mentre Truman è bloccato nel traffico e ascolta la frequenza radio della regia che descrive i suoi movimenti, le auto dietro di lui cambiano colore, modello e distanza istantaneamente tra le inquadrature interne all''abitacolo e quelle esterne.', TRUE, '2026-09-30T19:53:41.113228', NULL, 0, 0, 'mrtlsn07@gmail.com', 'ia', NULL),
(849, 162, '00:46:30', 'Errore di continuità', 'Nella scena dell''agenzia di viaggi, l''impiegata che accoglie Truman ha inizialmente una spilla dorata sul colletto sinistro della camicia. Nei controcampi successivi la spilla scompare, per poi riapparire alla fine della conversazione.', TRUE, '2026-09-30T19:53:41.113228', NULL, 0, 0, 'mrtlsn07@gmail.com', 'ia', NULL),
(850, 162, '01:12:40', 'Errore di continuità / Oggetti', 'Durante la tesa discussione in cucina, Meryl promuove il cacao ''Mococoa''. La posizione del barattolo e l''orientamento dell''etichetta verso la telecamera cambiano ripetutamente tra i vari stacchi di montaggio, nonostante lei lo tenga fermo con entrambe le mani.', TRUE, '2026-09-30T19:53:41.113228', NULL, 0, 0, 'mrtlsn07@gmail.com', 'ia', NULL),
(851, 162, '01:19:15', 'Errore di continuità', 'Sulla superstrada interrotta, Marlon offre a Truman una birra presa da una confezione da sei. Il livello della schiuma e il modo in cui Marlon tiene la lattina cambiano istantaneamente tra le inquadrature frontali e quelle riprese alle spalle dei personaggi.', TRUE, '2026-09-30T19:53:41.113228', NULL, 0, 0, 'mrtlsn07@gmail.com', 'ia', NULL),
(852, 162, '01:22:50', 'Errore di continuità / Posizione', 'Nel momento drammatico in cui Truman si ricongiunge con il padre creduto morto in mezzo alla nebbia artificiale, la posizione delle mani del padre sulle spalle e sulla schiena di Truman cambia bruscamente tra i primi piani e i campi medi.', TRUE, '2026-09-30T19:53:41.113228', NULL, 0, 0, 'mrtlsn07@gmail.com', 'ia', NULL),
(853, 162, '01:31:25', 'Errore di scena / Attrezzatura', 'Durante la tempesta nel mare artificiale, mentre Truman è sulla barca ''Santa Maria'', i suoi capelli e la sua camicia appaiono completamente fradici in un''inquadratura, ma visibilmente più asciutti e meno appiccicati al corpo nel taglio successivo, per poi tornare bagnati subito dopo.', TRUE, '2026-09-30T19:53:41.113228', NULL, 0, 0, 'mrtlsn07@gmail.com', 'ia', NULL),
(748, 142, '00:14:30', 'Discontinuità / Errore di montaggio', 'Durante la sequenza iniziale con i due subacquei che fotografano il relitto della Orca, la posizione della fotocamera subacquea e l''orientamento della lampada stroboscopica cambiano drasticamente tra il campo lungo e il primo piano.', TRUE, '2026-09-28T06:16:30.26034', NULL, 0, 0, 'lrscrm73@gmail.com', 'ia', NULL),
(978, 213, '01:31:05', 'Continuità', 'Sull''isola di Henderson, mentre Matthew Joy è disteso sulla sabbia visibilmente debilitato, la quantità di sabbia e il livello di ustioni sulla sua guancia destra cambiano tra il primo piano e la vista d''insieme.', TRUE, '2026-10-17T15:13:31.17943', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(979, 213, '01:44:40', 'Anacronismo / Oggetti di scena', 'In un''inquadratura ravvicinata del sartiame di una delle scialuppe di salvataggio alla deriva, è visibile una cima con trama a calza intrecciata moderna di materiale sintetico, anziché la tradizionale cima ritorta in fibra di canapa dell''inizio del XIX secolo.', TRUE, '2026-10-17T15:13:31.17943', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(980, 213, '01:53:10', 'Continuità', 'Nel confronto finale tra Chase e la balena bianca, il protagonista impugna l''arpione con le nocche sporche di sangue scuro incrostato; nell''inquadratura successiva, quando decide di non colpirla e abbassa il braccio, le sue mani sono bagnate ma completamente pulite dal sangue.', TRUE, '2026-10-17T15:13:31.17943', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(731, 139, '00:54:40', 'Errori di scena / Posizione', 'Durante la frenetica lotta nella carrozza ristoro tra Ladybug e Tangerine (Aaron Taylor-Johnson), Ladybug subisce un taglio sulla spalla e sul braccio. Nelle inquadrature immediatamente successive, la macchia di sangue sulla sua maglietta bianca cambia forma, dimensione e intensità di colore diverse volte senza una logica temporale.', TRUE, '2026-09-26T15:22:11.065646', NULL, 0, 0, 'mrtrrt@libero.it', 'ia', NULL),
(732, 139, '01:12:05', 'Errori di scena / Posizione', 'La valigetta d''argento contenente il riscatto subisce numerosi urti, graffi e ammaccature durante il film. In particolare, dopo lo scontro con Lemon, i vistosi graffi sulla superficie metallica della valigetta appaiono e scompaiono o cambiano lato a seconda dell''inquadratura speculare utilizzata nel montaggio.', TRUE, '2026-09-26T15:22:11.065646', NULL, 0, 0, 'mrtrrt@libero.it', 'ia', NULL),
(3637, 93, '00:00:00', 'Errori di scena / Posizione', 'L''illuminazione all''interno del garage non è coerente con le fonti di luce naturale mostrate; la luce cambia direzione e intensità tra un''inquadratura e l''altra senza che il tempo atmosferico o l''ora del giorno giustifichino il cambiamento.', TRUE, '2026-11-01T17:30:47.992055', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3935, 347, '01:21:00', 'Anacronismi', 'Durante una scena ambientata nel 1956, si vede sullo sfondo un distributore automatico che erodi lattine di alluminio con linguetta a strappo (pull-tab), tecnologia che non è stata introdotta sul mercato fino agli anni ''60.', TRUE, '2026-11-02T10:15:16.903414', 'A Beautiful Mind soda machine anachronism', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3936, 347, '00:45:00', 'Errori storici o fattuali', 'Nel film, John Nash viene invitato a tenere una conferenza al MIT e a fare ricerche durante la Guerra Fredda con accesso a una macchina di decrittazione avanzata. Nella realtà, il lavoro di Nash al MIT era incentrato sulla geometria differenziale e sulle equazioni alle derivate parziali, non sulla crittografia della NSA come mostrato nella finzione cinematografica.', TRUE, '2026-11-02T10:15:16.903414', 'A Beautiful Mind historical accuracy John Nash MIT', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3937, 347, '01:52:00', 'Errori di scena / Posizione', 'Nella scena in cui John Nash riceve la penna stilografica dai suoi colleghi alla Princeton University, il modo in cui tiene la penna e la posizione delle mani cambiano bruscamente tra un''inquadratura e l''altra (raccordi di montaggio non coincidenti).', TRUE, '2026-11-02T10:15:16.903414', 'A Beautiful Mind pen scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4299, 346, '01:50:15', 'Audio / Doppiaggio / Sync', 'Nella celebre scena finale nel deserto, durante il dialogo concitato tra Mills e Somerset, in alcune inquadrature larghe i movimenti delle labbra di Brad Pitt non coincidono perfettamente con l''audio della battuta a causa di un ridoppiaggio in post-produzione.', TRUE, '2026-11-02T14:51:34.555378', 'Se7en ending scene dialogue sync error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4304, 349, '00:00:00', 'Anacronismi', 'Durante le scene ambientate nel 1940-1941, si vedono veicoli e modelli di auto più recenti, oppure aeroplani giapponesi Zero rappresentati con livree o modifiche non storicamente accurate per quella fase esatta del conflitto.', TRUE, '2026-11-02T14:51:43.937168', 'Pearl Harbor historical inaccuracies planes cars', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4305, 349, '00:00:00', 'Errori storici o fattuali', 'La rappresentazione dell''attacco a Pearl Harbor mostra diverse inesattezze tattiche e cronologiche rispetto ai veri rapporti della US Navy, accentuate per scopi drammatici e spettacolari da Michael Bay.', TRUE, '2026-11-02T14:51:43.937168', 'Pearl Harbor attack historical mistakes factual errors', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(854, 165, '00:14:32', 'Discontinuità / Oggetti', 'Durante la conversazione tesa tra il personaggio di Tom Cruise e quello di Sandra Hüller al diner, la quantità di caffè nella tazza di Tom Cruise cambia improvvisamente tra un''inquadratura e l''altra: prima è quasi vuota, poi è piena a metà, senza che nessuno l''abbia riempita.', TRUE, '2026-10-03T07:41:01.605739', NULL, 0, 0, 'mrtrrt@libero.it', 'ia', NULL),
(855, 165, '00:38:15', 'Anacronismo / Oggetti di scena', 'Nello sfondo della scena ambientata nel deserto, quando Jesse Plemons scende dal pickup, è chiaramente visibile per qualche secondo uno smartphone moderno con schermo acceso nella tasca posteriore dei suoi jeans, nonostante la storia sia ambientata nei primi anni 2000.', TRUE, '2026-10-03T07:41:01.605739', NULL, 0, 0, 'mrtrrt@libero.it', 'ia', NULL),
(856, 165, '01:02:45', 'Riflessi / Equipaggiamento di produzione', 'Nel momento in cui John Goodman chiude con forza lo sportello della sua berlina nera, sul vetro del finestrino posteriore si nota chiaramente il riflesso del microfono a boom e di un fonico di cabina.', TRUE, '2026-10-03T07:41:01.605739', NULL, 0, 0, 'mrtrrt@libero.it', 'ia', NULL),
(857, 165, '01:24:10', 'Errori di costume / Continuità', 'Durante il complesso piano sequenza nella tempesta di sabbia, la giacca di pelle indossata da Tom Cruise presenta vistose macchie di fango sulla spalla sinistra. Nell''inquadratura immediatamente successiva, la giacca appare perfettamente pulita e asciutta.', TRUE, '2026-10-03T07:41:01.605739', NULL, 0, 0, 'mrtrrt@libero.it', 'ia', NULL),
(858, 165, '01:45:02', 'Discontinuità / Posizione degli attori', 'Mentre Riz Ahmed parla al telefono davanti alla mappa del cantiere, la sua mano destra tiene la cornetta all''orecchio. Al cambio di campo istantaneo, la cornetta passa alla mano sinistra, mentre la destra è improvvisamente appoggiata al tavolo.', TRUE, '2026-10-03T07:41:01.605739', NULL, 0, 0, 'mrtrrt@libero.it', 'ia', NULL),
(859, 165, '02:08:19', 'Errori di montaggio / Sincronizzazione audio', 'Durante il monologo drammatico di Sandra Hüller, si nota un evidente errore di labiale: le labbra dell''attrice continuano a muoversi per circa un secondo dopo che la battuta audio è già terminata.', TRUE, '2026-10-03T07:41:01.605739', NULL, 0, 0, 'mrtrrt@libero.it', 'ia', NULL),
(860, 165, '02:22:50', 'Effetti speciali / VFX', 'Nella scena del crollo del capannone, la cravatta di John Goodman vola verso sinistra spinta dallo spostamento d''aria, ma la polvere CGI generata attorno a lui si muove nella direzione opposta, rivelando una mancata coerenza nella simulazione fisica.', TRUE, '2026-10-03T07:41:01.605739', NULL, 0, 0, 'mrtrrt@libero.it', 'ia', NULL),
(39, 10, '00:15:20', 'Continuity', 'Durante l''inseguimento in auto a Shanghai, la posizione del vestito e della sciarpa di Willie cambia drasticamente tra i primi piani interni e le riprese esterne della vettura.', TRUE, '2026-09-13T14:53:50.74232', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(40, 10, '01:12:05', 'Crew & Equipment', 'Nella celebre sequenza dei carrelli della miniera, in diverse inquadrature ravvicinate ad alta velocità si notano chiaramente i modellini in miniatura e i pupazzi di stop-motion utilizzati per gli effetti speciali.', TRUE, '2026-09-13T14:53:50.84008', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(41, 11, '00:48:30', 'Fattuale / Storico', 'Durante il rogo dei libri a Berlino, la marcia militare suonata dalla banda è ''Königgrätzer Marsch'', ma gli ufficiali indossano uniformi della SS con dettagli ed elmetti introdotti solo diversi anni più tardi.', TRUE, '2026-09-13T14:53:51.250368', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(351, 68, '00:08:15', 'Anacronismi', 'La lettera di arruolamento che Robin riceve presenta una carta estremamente liscia, bianca e dai bordi perfettamente tagliati a macchina, tipica della produzione industriale moderna. Inoltre, i caratteri stampati sembrano realizzati con una pressa a caratteri mobili o addirittura con un font digitale moderno, secoli prima dell''invenzione della stampa di Gutenberg.', TRUE, '2026-09-15T18:05:31.609342', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(16, 3, '00:18:25', 'Continuity', 'L''icona dello stato della batteria sul display della videocamera passa da una sola tacca rossa a tre tacche verdi in diverse inquadrature nel corso della notte, senza che Hud abbia mai la possibilità di ricaricarla o sostituirla.', TRUE, '2026-09-13T14:43:24.454115', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(3638, 94, '00:12:45', 'Errori di scena / Posizione', 'Durante la scena del concerto, la posizione delle mani di Heike Makatsch sul pianoforte non corrisponde alla melodia udibile, rivelando una mancata sincronizzazione tra l''esecuzione e la traccia audio.', TRUE, '2026-11-01T17:37:03.782704', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(18, 3, '00:41:10', 'Continuity', 'Le macchie di sangue e la lacerazione sulla maglietta di Marlena cambiano forma, dimensione e posizione esatta tra il momento dell''attacco nel tunnel e l''arrivo al campo medico militare.', TRUE, '2026-09-13T14:43:24.589337', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(21, 4, '00:03:15', 'Continuity', 'Nella sequenza d''apertura in cui Ace impersona un corriere, i danni, i tagli e la posizione del nastro adesivo sulla scatola cambiano visibilmente tra un''inquadratura e l''altra mentre la maltratta lungo il corridoio e nell''ascensore.', TRUE, '2026-09-13T14:44:03.572178', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(3639, 94, '00:45:20', 'Troupe o microfoni visibili', 'In una ripresa in campo largo per le strade di Berlino, il riflesso di un membro della troupe con una macchina da presa è visibile brevemente su una vetrina di un negozio.', TRUE, '2026-11-01T17:37:03.782704', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3640, 94, '01:15:10', 'Errori di scena / Posizione', 'La posizione della sigaretta tra le dita di Daniel Craig cambia drasticamente tra un''inquadratura e la successiva durante il dialogo intenso nel caffè.', TRUE, '2026-11-01T17:37:03.782704', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3938, 166, '01:25:00', 'Troupe o microfoni visibili', 'Durante una delle intense sequenze all''interno dell''aula di tribunale, in un''inquadratura larga è possibile intravedere brevemente l''ombra di un microfono a boom riflettersi sulla parete di legno sullo sfondo.', TRUE, '2026-11-02T10:16:14.282063', 'A Time to Kill crew mic reflection courtroom scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3939, 166, '02:05:00', 'Errori di scena / Posizione', 'Nel corso della drammatica scena in cui Jake Brigance legge i documenti nel suo ufficio a tarda notte, la quantità di caffè nella tazza cambia visibilmente tra un''inquadratura e l''altra, passando da quasi piena a vuota senza che il personaggio abbia bevuto.', TRUE, '2026-11-02T10:16:14.282063', 'A Time to Kill continuity coffee cup office', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4306, 349, '00:00:00', 'Errori di scena / Posizione', 'In varie sequenze d''azione e nei duelli aerei, la posizione dei danni subiti dai velivoli (fori di proiettile, parti fumanti) cambia visivamente tra un''inquadratura e l''altra.', TRUE, '2026-11-02T14:51:43.937168', 'Pearl Harbor continuity plane damage mistake', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4307, 349, '00:00:00', 'Anacronismi', 'Durante le sequenze iniziali ambientate nell''infanzia dei protagonisti nel 1923, si vede un modello di trattore o camioncino che per caratteristiche costruttive appartiene a un''epoca successiva.', TRUE, '2026-11-02T14:51:43.937168', 'Pearl Harbor historical inaccuracies tractor', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4308, 349, '00:00:00', 'Errori storici o fattuali', 'Nelle scene dell''ospedale da campo e delle cure mediche dopo l''attacco, alcune procedure infermieristiche e medicinali mostrati (come determinati tipi di imballaggi o flebo) riflettono standard medici degli anni ''90 piuttosto che del 1941.', TRUE, '2026-11-02T14:51:43.937168', 'Pearl Harbor medical errors hospital scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3641, 97, '01:45:00', 'Anacronismi', 'Durante la celebre sequenza della corsa dei carri, sulla pista di sabbia dell''arena sono chiaramente visibili in diverse inquadrature i solchi lasciati dagli pneumatici della camera car utilizzata per le riprese in movimento.', TRUE, '2026-11-01T17:37:32.762473', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3642, 97, '00:00:00', 'Errori storici o fattuali', 'I legionari romani vengono mostrati mentre indossano l''armatura ''Lorica Segmentata'', un tipo di corazza che non era ancora diffuso né in uso in Giudea all''epoca degli avvenimenti (primo decennio del I secolo d.C.).', TRUE, '2026-11-01T17:37:32.762473', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(861, 166, '00:23:15', 'Anacronismo / Oggetti di scena', 'Durante la scena della sparatoria nel tribunale, Carl Lee spara diversi colpi con il fucile d''assalto M16. Nonostante spari a raffica continua, il selettore di fuoco dell''arma è visibilmente impostato su ''SEMI'' (semiautomatico) nei primi piani del fucile.', TRUE, '2026-10-03T07:51:46.524331', NULL, 0, 0, 'mrtrrt@libero.it', 'ia', NULL),
(862, 166, '00:48:10', 'Continuità / Abbigliamento', 'Quando Jake Brigance (Matthew McConaughey) parla con Ellen Roark (Sandra Bullock) nel suo studio, le ampie macchie di sudore sulla sua camicia azzurra cambiano continuamente forma e dimensione tra le inquadrature strette e quelle larghe.', TRUE, '2026-10-03T07:51:46.524331', NULL, 0, 0, 'mrtrrt@libero.it', 'ia', NULL),
(863, 166, '01:12:45', 'Continuità / Posizione', 'Durante la violenta manifestazione del Ku Klux Klan all''esterno del tribunale, la bandiera confederata tenuta da uno dei manifestanti in prima fila cambia mano e inclinazione tra due stacchi di camera consecutivi.', TRUE, '2026-10-03T07:51:46.524331', NULL, 0, 0, 'mrtrrt@libero.it', 'ia', NULL);
INSERT INTO public.errori ("id", "film_id", "minuto", "categoria", "descrizione", "approvato", "creato_il", "youtube_query", "conferme", "contestazioni", "inserito_da", "provenienza", "screenshot_url") VALUES
(3643, 97, '00:52:00', 'Errori storici o fattuali', 'Nelle scene ambientate sulla galera romana, i rematori sono rappresentati come schiavi incatenati ai banchi; storicamente la flotta romana impiegava uomini liberi o marinai stipendiati, mentre l''uso di schiavi incatenati è un mito storiografico successivo.', TRUE, '2026-11-01T17:37:32.762473', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(865, 166, '01:52:05', 'Continuità / Oggetti di scena', 'Durante l''attentato dinamitardo e l''incendio alla casa di Jake, il porticato appare completamente avvolto dalle fiamme in una ripresa esterna da lontano, ma nell''inquadratura immediatamente successiva dall''interno la struttura del portico risulta quasi intatta.', TRUE, '2026-10-03T07:51:46.524331', NULL, 0, 0, 'mrtrrt@libero.it', 'ia', NULL),
(866, 166, '02:14:30', 'Continuità / Trucco', 'Nella celebre arringa finale di Jake Brigance in tribunale, i ciocchi di capelli sulla sua fronte appaiono completamente inzuppati di sudore e appiccicati nella ripresa frontale, mentre nei controcampi laterali sono visibilmente più asciutti e riordinati.', TRUE, '2026-10-03T07:51:46.524331', NULL, 0, 0, 'mrtrrt@libero.it', 'ia', NULL),
(3644, 97, '01:48:00', 'Errori di scena / Posizione', 'Durante i vari cambi di inquadratura nella corsa dei carri, la posizione relativa dei carri di Ben-Hur e Messala e il numero di cavalli affiancati variano in modo incoerente tra un piano d''ascolto e il campo lungo successivo.', TRUE, '2026-11-01T17:37:32.762473', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(749, 142, '00:38:15', 'Equipaggiamento / Elementi di produzione visibili', 'Durante l''attacco alla sciatrice nautica, in un''inquadratura dall''alto dell''acqua è visibile per un secondo la piattaforma di supporto e la slitta idraulica usata per spingere lo squalo meccanico verso la superficie.', TRUE, '2026-09-28T06:16:30.26034', NULL, 0, 0, 'lrscrm73@gmail.com', 'ia', NULL),
(3940, 170, '01:15:00', 'Errori di scena / Posizione', 'Durante la conferenza stampa in cui viene discusso il piano per attaccare la nave madre aliena usando il caccia catturato, il bicchiere di vetro sulla scrivania del Presidente Whitmore cambia posizione, riempiendosi e svuotandosi alternativamente tra i vari campi e controcampi.', TRUE, '2026-11-02T10:16:40.269601', 'Independence Day conference room glass continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(23, 4, '00:45:30', 'Continuity', 'Durante la festa a casa di Ronald Camp, il livello del drink nel bicchiere di Ace e la posizione dei vari stuzzichini sul suo piatto continuano a cambiare da pieni a quasi vuoti ad ogni cambio di inquadratura.', TRUE, '2026-09-13T14:44:03.773975', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(24, 4, '01:02:15', 'Fattuale / Storico', 'Nella sequenza in cui Ace cade nella vasca dello squalo, l''animale emette dei versi acustici avvertibili sott''acqua. In realtà gli squali sono totalmente privi di organi vocali e non possono emettere alcun tipo di ruggito o suono.', TRUE, '2026-09-13T14:44:03.873502', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(3941, 170, '00:42:00', 'Errori di scena / Posizione', 'Quando il capitano Steven Hiller arriva alla base segreta dell''Area 51 trasportando il corpo dell''alieno, i militari aprono il container e lo bloccano. La posizione dei soldati e l''orientamento delle armi variano bruscamente da un''inquadratura all''altra senza che vi sia un movimento visibile dei personaggi.', TRUE, '2026-11-02T10:16:40.269601', 'Independence Day Hiller Area 51 alien body continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(986, 214, '02:14:05', 'Continuità / Trucco', 'Durante la drammatica corsa in auto verso l''ospedale sotto la neve, il flusso di sangue sulla fronte del Detective Loki altera la sua traiettoria e densità tra le varie riprese dall''interno dell''abitacolo.', TRUE, '2026-10-17T17:46:08.029438', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(987, 214, '02:22:40', 'Errori di scena / Posizione', 'Nella scena finale nel cortile dei Jones, la posizione del fischietto rosso sepolto vicino alla buca cambia leggermente orientamento rispetto alle foglie secche tra il primo piano e l''inquadratura più ampia.', TRUE, '2026-10-17T17:46:08.029438', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(3942, 170, '02:05:00', 'Errori di scena / Posizione', 'Nelle sequenze finali della battaglia aerea nel deserto, il caccia pilotato da Russell Casse mostra una quantità di missili agganciati sotto le ali che diminuisce e aumenta in modo incoerente durante le manovre di combattimento prima del lancio finale.', TRUE, '2026-11-02T10:16:40.269601', 'Independence Day Russell Casse missile count continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4309, 349, '00:00:00', 'Errori di scena / Posizione', 'Nella scena in cui Evelyn scrive una lettera, la posizione del calamaio e dei fogli di carta cambia visivamente tra un''inquadratura frontale e quella in primo piano dall''alto.', TRUE, '2026-11-02T14:51:43.937168', 'Pearl Harbor continuity error letter writing', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4507, 130, '00:15:20', 'Errori di scena / Posizione', 'Durante la scena in cui Burke Ryan cammina per le strade di Seattle, la borsa che porta a tracolla cambia spalla tra un cambio d''inquadratura e l''altro.', TRUE, '2026-11-02T15:32:36.152343', 'Love Happens 2009 Aaron Eckhart Seattle scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4508, 130, '00:42:15', 'Errori di scena / Posizione', 'Nella sequenza all''interno dell''aeroporto, il bagaglio a mano trasportato da Jennifer Aniston (Eloise) scompare momentaneamente tra un''inquadratura a campo largo e il primo piano successivo.', TRUE, '2026-11-02T15:32:36.152343', 'Love Happens Jennifer Aniston airport scene continuity goof', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4509, 130, '01:05:40', 'Audio / Doppiaggio / Sync', 'Nel momento culminante della discussione tra Burke e il suo manager Walter (Dan Fogler) nella hall dell''albergo, il movimento delle labbra di Dan Fogler non coincide perfettamente con l''audio delle battute pronunciate.', TRUE, '2026-11-02T15:32:36.152343', 'Love Happens Dan Fogler Aaron Eckhart hotel argument scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(868, 167, '00:14:32', 'Anacronismo / Oggetti', 'Durante la scena di allenamento nel palazzetto ambientata negli anni ''50, sullo sfondo è visibile per un secondo un cartellone pubblicitario contenente un codice QR parzialmente coperto da un telo.', TRUE, '2026-10-03T13:16:45.130492', NULL, 0, 0, 'mrtrrt@libero.it', 'ia', NULL),
(750, 142, '00:52:40', 'Discontinuità di costumi e oggetti', 'Quando Lo Sceriffo Brody esamina la carcassa dell''orca sulla spiaggia, la macchia di bagnato sulla sua camicia cambia forma e dimensione in modo incoerente tra i vari controcampi.', TRUE, '2026-09-28T06:16:30.26034', NULL, 0, 0, 'lrscrm73@gmail.com', 'ia', NULL),
(869, 167, '00:38:15', 'Errori di continuità', 'Quando il personaggio di Timothée Chalamet si prepara al servizio decisivo, nell''inquadratura frontale impugna la racchetta con la presa classica (shakehand), ma nel controcampo immediato la sta impugnando con la presa a penna (penholder).', TRUE, '2026-10-03T13:16:45.130492', NULL, 0, 0, 'mrtrrt@libero.it', 'ia', NULL),
(870, 167, '00:52:40', 'Attrezzatura visibile', 'Durante la concitata discussione nello spogliatoio tra i personaggi interpretati da Chalamet e Gwyneth Paltrow, nella parte superiore dell''inquadratura compare distintamente l''ombra del microfono a giraffa (boom mic).', TRUE, '2026-10-03T13:16:45.130492', NULL, 0, 0, 'mrtrrt@libero.it', 'ia', NULL),
(871, 167, '01:12:05', 'Errori di scena / Posizione', 'Nella scena del bar, il livello della bevanda nel bicchiere di Tyler, The Creator aumenta visibilmente tra due inquadrature staccate di pochi secondi, senza che nessuno gli versi altro liquido.', TRUE, '2026-10-03T13:16:45.130492', NULL, 0, 0, 'mrtrrt@libero.it', 'ia', NULL),
(872, 167, '01:35:50', 'Anacronismo / Costumi', 'Tra la folla degli spettatori al torneo finale, una comparso in terza fila indossa un paio di scarpe da ginnastica con suola moderna ed elementi riflettenti, del tutto inesistenti all''epoca della narrazione.', TRUE, '2026-10-03T13:16:45.130492', NULL, 0, 0, 'mrtrrt@libero.it', 'ia', NULL),
(873, 167, '01:48:12', 'Errori di continuità / Trucco e Parrucco', 'Nel pieno del match decisivo, il protagonista mostra la maglietta completamente bagnata di sudore e i capelli scompigliati. Nella ripresa ravvicinata subito successiva, i capelli sono di nuovo perfettamente pettinati e la maglia appare asciutta.', TRUE, '2026-10-03T13:16:45.130492', NULL, 0, 0, 'mrtrrt@libero.it', 'ia', NULL),
(874, 167, '02:04:18', 'Riflessi / Troupe', 'Mentre l''automobile d''epoca si allontana lungo la strada, nel paraurti cromato posteriore è chiaramente visibile il riflesso del cameraman con lo Steadicam e dell''operatore della ripresa.', TRUE, '2026-10-03T13:16:45.130492', NULL, 0, 0, 'mrtrrt@libero.it', 'ia', NULL),
(31, 6, '02:14:05', 'Anacronismo', 'Durante le riprese ambientate in Sicilia nel paesino di Savoca alla fine degli anni ''40, sullo sfondo sono chiaramente visibili diverse antenne televisive posizionate sui tetti delle case, tecnologia del tutto assente all''epoca nell''isola.', TRUE, '2026-09-13T14:48:18.035703', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(32, 7, '00:45:20', 'Crew & Equipment', 'Durante la sequenza della festa di San Gennaro a Little Italy nella parte dedicata al giovane Vito, nel riflesso del finestrino di un''auto d''epoca si nota nitidamente l''ombra di un operatore di ripresa con la macchina da presa.', TRUE, '2026-09-13T14:48:18.269067', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(33, 7, '02:32:15', 'Fattuale / Storico', 'Nelle scene ambientate a L''Avana durante la notte di Capodanno del 1958, compaiono tra il traffico della città alcune automobili americane prodotte soltanto nel 1959, mesi dopo gli avvenimenti narrati.', TRUE, '2026-09-13T14:48:18.341919', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(34, 8, '02:38:40', 'Continuity', 'Sulla scalinata del Teatro Massimo di Palermo, la macchia di sangue sulla camicia di Mary Corleone cambia forma, dimensione e posizione tra i primi piani e le inquadrature a figura intera.', TRUE, '2026-09-13T14:48:18.579126', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(35, 8, '01:12:05', 'Continuity', 'Durante la drammatica sparatoria in elicottero nella sala riunioni di Atlantic City, la giacca della giacca di Michael appare completamente sbottonata in un''inquadratura per poi risultare perfettamente abbottonata nel controcampo successivo.', TRUE, '2026-09-13T14:48:18.647442', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(42, 11, '01:15:22', 'Continuity', 'Durante la lunga lotta sopra il carro armato nel deserto, la quantità di polvere e fango sulla giacca e sul viso di Harrison Ford varia continuamente da un secondo all''altro.', TRUE, '2026-09-13T14:53:51.356777', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(43, 12, '00:22:15', 'Anacronismo', 'Quando Indy e Mutt arrivano in Perù, la musica di sottofondo è una versione del brano ''Bandstand Boogie'' incisa negli anni ''70, non compatibile con l''ambientazione del 1957.', TRUE, '2026-09-13T14:53:51.654872', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(44, 12, '00:54:10', 'Continuity', 'Nella scena del cimitero di Nazca, le ragnatele che si attaccano ai vestiti e ai capelli di Mutt scompaiono e riappaiono tra varie inquadrature ravvicinate.', TRUE, '2026-09-13T14:53:51.762687', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(45, 13, '00:18:40', 'Fattuale / Storico', 'Nella sequenza iniziale del 1944, il treno merci tedesco mostra marcature e codici di serie ferroviari entrati in uso formale solo nei primi anni ''50.', TRUE, '2026-09-13T14:53:52.073872', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(3645, 99, '00:04:30', 'Anacronismi', 'Nelle scene iniziali in cui Judah Ben-Hur e Messala gareggiano a cavallo, le cavalcature sono dotate di sella con staffe moderne. Le staffe non erano utilizzate nell''Impero Romano nel I secolo d.C., poiché furono introdotte in Europa soltanto molti secoli dopo.', TRUE, '2026-11-01T17:38:04.901938', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3646, 99, '00:48:15', 'Errori storici o fattuali', 'Durante la sequenza della battaglia navale, i rematori della galera romana vengono mostrati come schiavi incatenati costretti a remare al ritmo di un tamburo. Storicamente, la marina romana impiegava uomini liberi o salariati e non schiavi incatenati, per garantire l''efficienza bellica dell''equipaggio.', TRUE, '2026-11-01T17:38:04.901938', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3647, 99, '01:29:40', 'Errori di scena / Posizione', 'All''inizio della corsa dei carri nell''arena, sulla sabbia del tracciato sono chiaramente visibili i solchi e i segni degli pneumatici lasciati dai veicoli della troupe (camera car) usati per le riprese e la preparazione della pista.', TRUE, '2026-11-01T17:38:04.901938', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3648, 99, '01:33:15', 'Troupe o microfoni visibili', 'Durante un''inquadratura dal basso dei carri in corsa nell''arena, sulla polvere sollevata sul lato sinistro dello schermo è visibile l''ombra prolungata del braccio meccanico della gru della telecamera.', TRUE, '2026-11-01T17:38:04.901938', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3649, 99, '01:36:50', 'Errori di scena / Posizione', 'Negli ultimi giri della corsa dei carri, il livello di polvere, sangue e ferite sul volto e sull''armatura di Messala varia vistosamente e in modo incoerente tra inquadrature ravvicinate e campi lunghi consecutivi.', TRUE, '2026-11-01T17:38:04.901938', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3950, 179, '00:00:00', 'Errori di scena / Posizione', 'Nella sequenza in cui King Kong tiene Jessica Lange in mano, la posizione dei capelli dell''attrice e le pieghe della sua veste bagnata cambiano notevolmente tra un''inquadratura ravvicinata e il campo largo con il pupazzo o la mano meccanica.', TRUE, '2026-11-02T10:17:10.210041', 'King Kong 1976 continuity Jessica Lange hair', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3951, 179, '00:00:00', 'Anacronismi', 'Il film è ambientato nel 1976 (anno di uscita e contemporaneità della narrazione), ma alcune apparecchiature radio e strumentazioni petrolifere utilizzate dalla spedizione mostrano dettagli tecnici o modelli leggermente successivi o non coerenti con il periodo esatto.', TRUE, '2026-11-02T10:17:10.210041', 'King Kong 1976 anachronism equipment', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(875, 168, '00:04:30', 'Errore di continuità', 'Durante la scena in cui Anton Chigurh strangola il vice sceriffo con le manette, la scia di sangue sul pavimento e i segni neri lasciati dalle scarpe della vittima cambiano posizione e intensità tra le diverse inquadrature ravvicinate e quelle larghe.', TRUE, '2026-10-03T13:23:56.237925', NULL, 0, 0, 'mrtrrt@libero.it', 'ia', NULL),
(876, 168, '00:12:40', 'Errore di continuità / Posizione', 'Quando Llewelyn Moss si avvicina al camioncino nel deserto e trova l''uomo messicano ferito, la mano dell''uomo sul volante cambia posizione tra l''inquadratura dall''esterno e quella dall''interno dell''abitacolo.', TRUE, '2026-10-03T13:23:56.237925', NULL, 0, 0, 'mrtrrt@libero.it', 'ia', NULL),
(877, 168, '00:22:15', 'Anacronismo', 'Sebbene il film sia ambientato nel 1980, in diverse scene di sfondo si possono notare automobili e camioncini prodotti alla fine degli anni ''90 o nei primi anni 2000, come un modello di Ford F-150 chiaramente visibile sullo sfondo di una strada.', TRUE, '2026-10-03T13:23:56.237925', NULL, 0, 0, 'mrtrrt@libero.it', 'ia', NULL),
(878, 168, '00:38:10', 'Errore di scena / Oggetti', 'Nella stanza del motel, quando Moss svita la grata della presa d''aria per nascondere la valigetta con i soldi, le viti che ha rimosso e appoggiato sul pavimento cambiano disposizione e distanza tra loro nei tagli di montaggio successivi.', TRUE, '2026-10-03T13:23:56.237925', NULL, 0, 0, 'mrtrrt@libero.it', 'ia', NULL),
(879, 168, '00:48:15', 'Errore di continuità', 'Nella casa di Moss, quando Chigurh si siede sul divano e beve dal bicchiere di latte, il livello del liquido all''interno del bicchiere sale e scende inspiegabilmente tra i cambi di inquadratura prima che lui finisca di bere.', TRUE, '2026-10-03T13:23:56.237925', NULL, 0, 0, 'mrtrrt@libero.it', 'ia', NULL),
(880, 168, '00:55:30', 'Anacronismo', 'Quando Moss utilizza una cabina telefonica pubblica per effettuare una chiamata, il telefono a gettoni mostra un adesivo con un logo moderno della compagnia telefonica e un design del vano di restituzione delle monete che non esistevano ancora nel 1980.', TRUE, '2026-10-03T13:23:56.237925', NULL, 0, 0, 'mrtrrt@libero.it', 'ia', NULL),
(881, 168, '01:12:05', 'Errore di continuità', 'Durante lo scontro a fuoco nel motel, quando Moss viene ferito e scappa in strada, la quantità di sangue sulla sua camicia e la forma della macchia ematica cambiano visibilmente da un''inquadratura all''altra mentre corre.', TRUE, '2026-10-03T13:23:56.237925', NULL, 0, 0, 'mrtrrt@libero.it', 'ia', NULL),
(701, 64, '01:21:40', 'Errori storici o fattuali', 'I tabelloni utilizzati come bersagli durante la gara di tiro con l''arco presentano i classici anelli colorati concentrici (bianco, nero, blu, rosso, oro). Questo tipo di bersaglio regolamentare è stato introdotto e codificato solo nell''era moderna (XVIII-XIX secolo), mentre nel Medioevo si utilizzavano bersagli di paglia grezza, rocchetti o pioli di legno.', TRUE, '2026-09-22T21:12:39.728883', NULL, 0, 0, 'mrtlsn07@gmail.com', 'ia', NULL),
(46, 13, '01:05:12', 'Continuity', 'Durante l''inseguimento a Tangeri a bordo dei tuk-tuk, lo specchietto retrovisore del veicolo guidato da Indy risulta spezzato dopo un urto, ma torna integro nel campo lungo successivo.', TRUE, '2026-09-13T14:53:52.184805', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(59, 20, '01:15:22', 'Crew & Equipment', 'Nella parte superiore dello schermo entra brevemente nell''inquadratura il microfono a spugna dell''operatore audio.', TRUE, '2026-09-13T15:01:44.369792', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(1005, 234, '00:46:25', 'Errori storici o fattuali', 'In una delle sequenze notturne ambientate negli anni ''60 nei vicoli di Soho, vicino al bordo del marciapiede è chiaramente visibile la pavimentazione tattile a rilievo per non vedenti (blister paving), un''infrastruttura urbana standardizzata e introdotta nel Regno Unito solo a partire dagli anni ''90.', TRUE, '2026-10-24T15:28:27.637727', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(3650, 101, '00:01:00', 'Anacronismi', 'Nelle sequenze dei titoli di testa vengono mostrate le celebri mummie di Guanajuato (Messico). Tuttavia, la vicenda del film è ambientata nel 1838, mentre molte di quelle mummie risalgono a persone decedute durante l''epidemia di colera del 1865 o negli anni successivi.', TRUE, '2026-11-01T17:38:27.046716', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(1014, 234, '00:14:45', 'Errori di scena / Posizione', 'Nel primo incontro tra Eloise e la signora Collins nella sua stanza in affitto, la tazza di tè sul tavolino cambia orientamento tra le inquadrature: prima il manico è rivolto chiaramente verso destra rispetto allo spettatore, poi, nel controcampo ravvicinato, è girato esattamente verso sinistra senza che nessuno l''abbia toccato.', TRUE, '2026-10-24T15:35:51.422226', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(1015, 234, '00:36:20', 'Troupe o microfoni visibili', 'Nei camerini del locale quando Sandie si siede davanti alla specchiera a tre ante, muovendosi verso destra: per una frazione di secondo, nell''angolo in alto a sinistra dello specchio laterale, è chiaramente visibile la parte terminale dell''asta di un microfono boom della troupe che viene ritirata in fretta verso l''alto.', TRUE, '2026-10-24T15:35:51.422226', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(3651, 101, '00:26:30', 'Errori di scena / Posizione', 'Durante la cena nel castello, quando Jonathan Harker si taglia il dito affettando il pane, la posizione e la quantità di sangue sulla sua mano cambiano visibilmente tra l''inquadratura ravvicinata e il controcampo.', TRUE, '2026-11-01T17:38:27.046716', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3652, 101, '00:27:15', 'Errori di scena / Posizione', 'Sullo sfondo della sala da pranzo del castello di Dracula è presente un orologio d''epoca che rintocca e fa muovere il pendolo, ma le lancette sul quadrante rimangono ferme sulla stessa ora per tutta la scena.', TRUE, '2026-11-01T17:38:27.046716', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3653, 101, '00:58:10', 'Anacronismi', 'In diverse inquadrature esterne girate a Delft (usata per rappresentare Wismar), sullo sfondo dei tetti degli edifici storici si possono intravedere antenne televisive e serramenti moderni non d''epoca.', TRUE, '2026-11-01T17:38:27.046716', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3654, 101, '01:16:00', 'Errori di scena / Posizione', 'Nelle scene dell''invasione dei topi a Wismar, la produzione utilizzò migliaia di ratti da laboratorio bianchi dipinti artificialmente di grigio. In varie inquadrature a terra sono chiaramente visibili macchie bianche sul pelo dei topi dovute alla vernice che si staccava o che gli animali leccavano via.', TRUE, '2026-11-01T17:38:27.046716', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3952, 180, '01:15:00', 'Anacronismi', 'Durante le riprese a bordo della Venture, Jack Driscoll usa una macchina da scrivere che mostra font e spaziatura tipici di modelli successivi o presenta dettagli non coerenti con il 1933.', TRUE, '2026-11-02T10:17:17.629346', 'King Kong 2005 typewriter scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3953, 180, '02:10:00', 'Errori storici o fattuali', 'A New York, durante il numero di vaudeville al teatro dove viene esposto Kong, le automobili e i taxi che sfrecciano per strada includono alcuni modelli usciti dalle fabbriche automobilistiche negli anni immediatamente successivi al 1933.', TRUE, '2026-11-02T10:17:17.629346', 'King Kong 2005 New York 1933 cars street scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4314, 355, '00:04:30', 'Errori di scena / Posizione', 'Durante la scena iniziale del treno, la posizione dei passeggeri e dei giornali nelle mani delle comparse cambia visivamente tra un''inquadratura e l''altra prima dell''incidente.', TRUE, '2026-11-02T14:52:12.167086', 'Unbreakable train scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5517, 270, '00:12:45', 'Errori di scena / Posizione', 'Durante la scena del bar nel 1959, il bicchiere tenuto in mano da Al cambia posizione e livello di liquido tra un campo e un controcampo con Giacomo Poretti.', TRUE, '2026-11-02T17:20:11.82664', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(3655, 113, '00:12:45', 'Errori di scena / Posizione', 'Quando Hamilton sta parlando con Michael, la posizione della tazza di caffè sul tavolo cambia tra le inquadrature, passando da essere vicina al bordo a essere più centrata.', TRUE, '2026-11-01T17:49:39.611681', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(882, 169, '00:06:15', 'Anacronismo / Equipaggiamento', 'Durante l''addestramento a Parris Island (ambientato nel 1967), le reclute impugnano fucili M16A2. Questa specifica variante dell''M16 è stata adottata dal corpo dei Marines solo a partire dal 1982.', TRUE, '2026-10-03T13:27:46.941474', NULL, 0, 0, 'mrtrrt@libero.it', 'ia', NULL),
(883, 169, '00:28:40', 'Continuità / Oggetti di scena', 'Durante la scena del ''panno di sapone'' in cui la squadra punisce Pyle di notte, la disposizione delle coperte sul suo letto e la posizione delle calze cambiano visibilmente tra i campi lunghi e i primi piani.', TRUE, '2026-10-03T13:27:46.941474', NULL, 0, 0, 'mrtrrt@libero.it', 'ia', NULL),
(884, 169, '00:43:10', 'Continuità / Effetti speciali', 'Nella scena nei bagni della camerata, quando Pyle spara al Sergente Maggiore Hartman, lo schizzo di sangue e il pattern sulla parete bianca alle sue spalle cambiano forma e densità tra l''istante dell''impatto e la sequenza in cui cade all''indietro.', TRUE, '2026-10-03T13:27:46.941474', NULL, 0, 0, 'mrtrrt@libero.it', 'ia', NULL),
(885, 169, '00:52:30', 'Continuità / Vestiario', 'La celebre scritta ''Born to Kill'' presente sull''elmetto del soldato Joker cambia inclinazione, spessore del tratto e dimensione del font tra la scena iniziale della redazione di Stars and Stripes e le successive scene di pattugliamento.', TRUE, '2026-10-03T13:27:46.941474', NULL, 0, 0, 'mrtrrt@libero.it', 'ia', NULL),
(886, 169, '01:14:20', 'Errore di ambientazione', 'Nelle scene ambientate nella città di Huế (girate nella Bexton Gasworks vicino a Londra), in varie inquadrature sullo sfondo si scorgono elementi architettonici tipicamente industriali britannici e il fogliame delle palme fìnte importate mostra i sostegni di plastica alla base.', TRUE, '2026-10-03T13:27:46.941474', NULL, 0, 0, 'mrtrrt@libero.it', 'ia', NULL),
(3656, 113, '00:48:20', 'Errori di scena / Posizione', 'Durante la scena in cui Jensen viene trovata all''interno delle pareti della stazione, la posizione dei cavi e dei detriti attorno a lei cambia visibilmente tra i tagli di montaggio.', TRUE, '2026-11-01T17:49:39.611681', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(888, 169, '01:46:10', 'Errore di troupe', 'Durante l''avanzamento finale della squadra verso il rifugio del cecchino tra le macerie in fiamme, nell''angolo inferiore sinistro dello schermo è visibile per un secondo l''ombra di un operatore di ripresa con la cinepresa a mano.', TRUE, '2026-10-03T13:27:46.941474', NULL, 0, 0, 'mrtrrt@libero.it', 'ia', NULL),
(1016, 234, '00:46:10', 'Anacronismi', 'Durante una delle passeggiate di Sandie e Jack a Soho, tra le auto parcheggiate lungo la strada si nota una vettura con targa britannica che reca il suffisso alfabetico finale ''E''. Questo sistema di datazione per la lettera ''E'' entrò in vigore solo all''inizio del 1967, mentre gli eventi di quella parte della trama si svolgono nel 1965.', TRUE, '2026-10-24T15:35:51.422226', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(1017, 234, '01:03:15', 'Errori di scena / Posizione', 'Nella biblioteca universitaria, mentre Eloise consulta con crescente angoscia il lettore di microfilm per trovare notizie storiche di cronaca nera, il fotogramma del quotidiano proiettato sullo schermo salta di posizione tra il piano medio e il primissimo piano: un titolo di colonna che prima era al centro dell''area visiva risulta completamente fuori quadro nel taglio successivo.', TRUE, '2026-10-24T15:35:51.422226', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(1018, 234, '01:13:50', 'Errori di scena / Posizione', 'Subito dopo essersi fatta tingere i capelli di biondo, quando Eloise esce dal salone e scende i gradini sul marciapiede, l''acconciatura cambia sensibilmente: nell''inquadratura dall''interno del negozio la frangia è ordinata e perfettamente liscia sulla fronte, mentre nell''inquadratura esterna controluce è visibilmente divisa in due ciocche laterali più mosse e disordinate.', TRUE, '2026-10-24T15:35:51.422226', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(1019, 234, '01:28:40', 'Errori storici o fattuali', 'Durante il flashback drammatico nella camera con gli avventori del club, Jack posa sul comò alcune banconote di cartamoneta per il pagamento: le banconote mostrate appartengono alla serie ''D'' della Bank of England, emessa a partire dal 1970 con l''introduzione della decimalizzazione, del tutto anacronistica rispetto al sistema monetario britannico pre-decimale (fatto di sterline, scellini e pence) dell''epoca.', TRUE, '2026-10-24T15:35:51.422226', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(94, 37, '02:08:40', 'Errori di scena / Posizione', 'Nel finale in ospedale, quando il Ministro nutre Alex con l''imboccatura di cibo, la quantità presente sul cucchiaio e la posizione del vassoio rispetto alle lenzuola cambiano ad ogni stacco di camera.', TRUE, '2026-09-13T15:23:45.522883', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(165, 44, '00:04:15', 'Troupe o microfoni visibili', 'Durante l''agguato iniziale a Strangways ad opera dei tre finti ciechi, sulla parete dell''edificio a sinistra proiettata nitidamente si scorge l''ombra del braccio di un tecnico della troupe che sostiene la giraffa del microfono.', TRUE, '2026-09-14T13:48:35.31824', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(166, 44, '00:15:22', 'Errori di scena / Posizione', 'Quando Bond entra nell''ufficio del Governatore della Giamaica, appoggia il suo cappello Trilby sul tavolo con la falda rivolta verso l''alto; nelle inquadrature successive dal campo controcampo, il cappello risulta ruotato di 180 gradi e posizionato diversamente.', TRUE, '2026-09-14T13:48:35.398186', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(3657, 113, '01:05:15', 'Errori di scena / Posizione', 'Il sangue sul volto di Hamilton appare e scompare o cambia intensità in diverse inquadrature ravvicinate durante la sequenza di riparazione del giroscopio.', TRUE, '2026-11-01T17:49:39.611681', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3658, 113, '01:18:30', 'Errori di scena / Posizione', 'La posizione del braccio di Mundy, dopo l''incidente con il muro, cambia angolazione in modo incoerente tra l''inquadratura larga e quella stretta.', TRUE, '2026-11-01T17:49:39.611681', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3662, 120, '00:15:20', 'Errori di scena / Posizione', 'Durante la scena in cui Peter è in volo sull''aereo e sta parlando con Happy Hogan, il telefono che tiene in mano cambia posizione e orientamento tra un''inquadratura e l''altra.', TRUE, '2026-11-01T17:49:53.330994', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3663, 120, '00:42:10', 'Errori di scena / Posizione', 'A Venezia, quando il mostro d''acqua attacca, i tavolini e le sedie di un bar all''aperto vengono distrutti ma riappaiono intatti o in posizioni diverse nelle riprese successive da angolazioni differenti.', TRUE, '2026-11-01T17:49:53.330994', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3664, 120, '01:10:45', 'Errori di scena / Posizione', 'Nei laboratori segreti, quando Quentin Beck mostra le proiezioni olografiche, lo stato dei cavi e dei piccoli droni sul tavolo varia visibilmente nei cambi di inquadratura tra i vari attori.', TRUE, '2026-11-01T17:49:53.330994', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3956, 183, '01:21:00', 'Errori di scena / Posizione', 'Durante la fuga dei nani nei barili lungo il fiume, la posizione dei barili e la presenza dei personaggi cambiano visibilmente tra un''inquadratura e l''altra, passando da rapide tumultuose a zone d''acqua più calme senza soluzione di continuità logica.', TRUE, '2026-11-02T10:17:38.327219', 'The Hobbit The Desolation of Smaug barrel escape scene mistake', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(889, 164, '00:43:15', 'Errore di continuità', 'Dopo aver salvato Gabriel e aver massacrato i soldati inglesi con il tomahawk, Benjamin Martin è coperto di sangue. Nelle inquadrature successive, mentre abbraccia i figli, la disposizione e la quantità di sangue sul suo viso e sulla camicia cambiano vistosamente tra un taglio e l''altro.', TRUE, '2026-10-03T15:01:57.581376', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(890, 164, '00:41:10', 'Anacronismo / Equipaggiamento', 'Durante l''imboscata nella foresta, quando Benjamin Martin spara con la sua pistola a pietra focaia in primo piano, non si vede alcuna fiammata o fumo provenire dallo scodellino della focaia, rivelando che si tratta di un''arma di scena non caricata realmente.', TRUE, '2026-10-03T15:01:57.581376', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(891, 164, '01:12:30', 'Errore di continuità', 'Durante la scena in cui il Generale Cornwallis discute con i suoi ufficiali, la parrucca di Cornwallis cambia leggermente posizione e livello di ordine tra i primi piani e i campi medi.', TRUE, '2026-10-03T15:01:57.581376', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(892, 164, '01:50:25', 'Anacronismo / Oggetti di scena', 'In un''inquadratura panoramica in cui le truppe britanniche marciano lungo un sentiero di campagna, sono chiaramente visibili sul terreno fangoso i solchi degli pneumatici lasciati dai moderni camion della produzione cinematografica.', TRUE, '2026-10-03T15:01:57.581376', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(893, 164, '02:15:40', 'Errore di continuità / Bandiera', 'Durante la battaglia finale, la bandiera americana portata dai coloni mostra la disposizione delle stelle a cerchio (stile Betsy Ross). Tuttavia, in un''inquadratura ravvicinata molto rapida, la disposizione delle stelle cambia temporaneamente in una griglia più moderna.', TRUE, '2026-10-03T15:01:57.581376', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(894, 164, '02:22:15', 'Errore di continuità', 'Nel duello finale tra Benjamin Martin e il Colonnello Tavington, la giacca verde di quest''ultimo appare coperta di fango e polvere. Nei successivi primi piani ravvicinati, il colletto e la spalla della giacca sono improvvisamente molto più puliti.', TRUE, '2026-10-03T15:01:57.581376', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(895, 164, '00:35:20', 'Anacronismo / Trucco', 'Nonostante l''ambientazione sia il tardo XVIII secolo, molti dei personaggi principali e delle comparse (inclusi i bambini di Martin) mostrano una dentatura perfettamente bianca, dritta e curata con moderni standard odontoiatrici, del tutto improbabile per l''epoca.', TRUE, '2026-10-03T15:01:57.581376', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(702, 64, '01:34:50', 'Errori di scena / Posizione', 'Durante lo scontro finale all''interno del castello tra Robin Hood e Sir Guy di Gisborne, l''ombra dei due duellanti proiettata sulle colonne di pietra cambia repentinamente direzione e angolazione tra un piano sequenza e l''altro, tradendo un differente posizionamento dei proiettori di luce durante i diversi take del montaggio.', TRUE, '2026-09-22T21:12:39.728883', NULL, 0, 0, 'mrtlsn07@gmail.com', 'ia', NULL),
(3659, 119, '00:08:00', 'Errori di scena / Posizione', 'Quando Peter Parker è seduto in classe a scuola e sta guardando un video di se stesso su YouTube sul suo computer portatile, la posizione delle sue mani e la schermata del video cambiano visivamente tra le inquadrature ravvicinate e quelle larghe.', TRUE, '2026-11-01T17:49:46.853571', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3660, 119, '00:24:00', 'Errori di scena / Posizione', 'Durante la sequenza del bancomat, quando i criminali indossano le maschere dei Vendicatori, la posizione delle armi e il modo in cui tengono gli oggetti variano notevolmente tra un taglio di montaggio e l''altro.', TRUE, '2026-11-01T17:49:46.853571', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3661, 119, '00:45:00', 'Errori di scena / Posizione', 'Nella scena in cui Peter si trova nella sua stanza e chiude la porta o sposta oggetti sulla scrivania, gli oggetti di arredamento e i libri cambiano posizione spontaneamente tra le diverse inquadrature dei dialoghi.', TRUE, '2026-11-01T17:49:46.853571', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3957, 183, '02:05:00', 'Errori di scena / Posizione', 'Nel corso del confronto tra Bilbo e Smaug all''interno della Montagna Solitaria, la quantità di monete d''oro accumulate attorno a Bilbo varia in modo incoerente tra i campi lunghi e i primi piani.', TRUE, '2026-11-02T10:17:38.327219', 'The Hobbit The Desolation of Smaug Bilbo and Smaug gold pile error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4315, 355, '00:15:20', 'Errori di scena / Posizione', 'Nel suo studio d''arte, Elijah Price (Samuel L. Jackson) sposta una stampa rara tra le mani, ma nell''inquadratura successiva la stampa si trova perfettamente dritta sul tavolo senza che vi sia il tempo materiale per riporla.', TRUE, '2026-11-02T14:52:12.167086', 'Unbreakable Samuel L Jackson art gallery scene error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4316, 355, '00:42:10', 'Errori di scena / Posizione', 'Nello stadio in cui David Dunn lavora come addetto alla sicurezza, i bicchieri e gli oggetti sul bancone del metal detector cambiano disposizione e numero a seconda dell''angolo di ripresa.', TRUE, '2026-11-02T14:52:12.167086', 'Unbreakable stadium security scene continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4317, 355, '01:05:45', 'Errori di scena / Posizione', 'Quando David solleva i pesi insieme a suo figlio Joseph, il bilanciere mostra dischi di peso differenti o posizionati diversamente nei cambi d''inquadratura tra i primi piani e i campi medi.', TRUE, '2026-11-02T14:52:12.167086', 'Unbreakable weightlifting scene continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4360, 145, '00:08:15', 'Errori di scena / Posizione', 'Durante la sequenza iniziale al diner, il mucchio di pancake nel piatto di Mr. Orange cambia disposizione e quantitativo tra un cambio di inquadratura e l''altro mentre parla con gli altri membri della banda.', TRUE, '2026-11-02T14:53:30.515876', 'Reservoir Dogs diner scene continuity error pancakes', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4361, 145, '00:32:40', 'Errori di scena / Posizione', 'Nel magazzino, quando Mr. White spara per la prima volta contro il soffitto o gli oggetti per calmare gli animi, la pistola che impugna (una SIG Sauer P220) mostra in alcune inquadrature ravvicinate il cane disarmato o posizioni diverse del carrello.', TRUE, '2026-11-02T14:53:30.515876', 'Reservoir Dogs gun continuity mistakes Harvey Keitel', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL);
INSERT INTO public.errori ("id", "film_id", "minuto", "categoria", "descrizione", "approvato", "creato_il", "youtube_query", "conferme", "contestazioni", "inserito_da", "provenienza", "screenshot_url") VALUES
(4362, 145, '00:45:12', 'Troupe o microfoni visibili', 'Durante il dialogo teso tra Mr. White e Mr. Pink nel magazzino, in un''inquadratura di spalle si nota brevemente l''ombra di un microfono a boom oscillare sulla parete di mattoni sullo sfondo.', TRUE, '2026-11-02T14:53:30.515876', 'Reservoir Dogs boom mic shadow visible', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4363, 145, '01:05:20', 'Errori di scena / Posizione', 'Quando Mr. Blonde versa la benzina addosso al poliziotto legato sulla sedia, il livello del liquido nella tanica rossa varia in modo incoerente tra i vari stacchi di montaggio.', TRUE, '2026-11-02T14:53:30.515876', 'Reservoir Dogs Michael Madsen cop torture continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4364, 145, '01:22:10', 'Errori di scena / Posizione', 'Nella scena in cui Mr. Orange è steso sanguinante sul pavimento del magazzino e confida a Mr. White di essere un poliziotto sotto copertura, la posizione delle sue mani e delle macchie di sudore sulla giacca cambiano ripetutamente da un''inquadratura all''altra.', TRUE, '2026-11-02T14:53:30.515876', 'Reservoir Dogs Tim Roth confession scene continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4510, 181, '00:15:20', 'Errori di scena / Posizione', 'Durante la canzone dei goblin nelle Montagne Nebbiose, la posizione del cappuccio di Gandalf scompare e riappare improvvisamente tra un cambio d''inquadratura e l''altro.', TRUE, '2026-11-02T15:32:51.590097', 'The Hobbit 1977 animated movie continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3665, 121, '01:22:00', 'Errori di scena / Posizione', 'Durante la conversazione nell''appartamento di Happy Hogan, la posizione dei documenti e delle scatole sul tavolo cambia visibilmente tra un''inquadratura e l''altra senza che alcun personaggio li tocchi.', TRUE, '2026-11-01T17:49:59.168653', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3666, 121, '02:05:00', 'Errori di scena / Posizione', 'Nella scena della battaglia finale sulla Statua della Libertà, la quantità di neve e detriti sui ponteggi varia in modo incoerente tra le riprese grandangolari e i primi piani dei personaggi.', TRUE, '2026-11-01T17:49:59.168653', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(897, 57, '00:16:30', 'Incongruenza fisica / Continuità', 'Dopo che Jack Sparrow si tuffa in mare per salvare Elizabeth che sta annegando, i suoi capelli e i suoi vestiti appaiono completamente bagnati. Tuttavia, pochi istanti dopo, quando viene catturato dalle guardie sulla banchina, i suoi capelli sono quasi completamente asciutti e perfettamente acconciati.', TRUE, '2026-10-03T17:19:16.19067', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(898, 57, '00:11:45', 'Continuità', 'Durante il duello nella fucina tra Jack Sparrow e Will Turner, le macchie di fuliggine e sporco sul viso di Will cambiano forma, intensità e posizione tra un''inquadratura e l''altra.', TRUE, '2026-10-03T17:19:16.19067', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(899, 57, '01:22:10', 'Continuità', 'Durante la scena del sacrificio sull''Isla de Muerta, Barbossa taglia la mano di Elizabeth per bagnare il medaglione d''oro. Nelle inquadrature successive, la quantità di sangue sulla mano di Elizabeth e sul medaglione varia vistosamente, scomparendo quasi del tutto in alcuni tagli.', TRUE, '2026-10-03T17:19:16.19067', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(900, 57, '02:04:30', 'Errori di scena / Posizione', 'Quando Barbossa viene colpito e muore, lascia cadere la mela che teneva in mano. Nelle inquadrature dall''alto la mela si trova a pochi centimetri dalla sua mano destra, mentre nelle inquadrature successive più ravvicinate la mela è posizionata molto più lontano.', TRUE, '2026-10-03T17:19:16.19067', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(901, 57, '00:09:15', 'Anacronismo / Oggetti di scena', 'Sulla bandana di Jack Sparrow, in alcune inquadrature ravvicinate all''inizio del film quando arriva al porto di Port Royal, è visibile una piccola etichetta bianca con il logo del marchio moderno ''Adidas'', parzialmente coperta ma non del tutto rimossa dal reparto costumi.', TRUE, '2026-10-03T17:19:16.19067', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(902, 57, '00:48:20', 'Incongruenza di montaggio', 'Durante l''attacco della Black Pearl a Port Royal, un cannone della fortezza viene colpito ed esplode volando via. Nel fotogramma immediatamente successivo, lo stesso cannone è di nuovo integro nella sua posizione originale prima di sparire definitivamente nella scena seguente.', TRUE, '2026-10-03T17:19:16.19067', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(167, 44, '00:24:10', 'Errori storici o fattuali', 'Bond corregge il cameriere sul Dom Pérignon del 1953 affermando che sarebbe un errore berlo a una temperatura superiore a 4 gradi Celsius, tuttavia servirlo a quella temperatura anestetizzerebbe le papille gustative rovinando lo Champagne.', TRUE, '2026-09-14T13:48:35.503417', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(168, 44, '00:33:05', 'Errori di scena / Posizione', 'Nel corso dell''inseguimento automobilistico con la limousine del finto autista, i vetri della vettura di Bond variano continuamente da completamente trasparenti e puliti a visibilmente impolverati e scuri a seconda se la ripresa sia dal vivo o con schermo di retroproiezione.', TRUE, '2026-09-14T13:48:35.611151', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(169, 44, '00:41:18', 'Troupe o microfoni visibili', 'Nella tensione della stanza d''albergo in cui la tarantola striscia sul corpo di Bond, nel momento in cui 007 la colpisce con la scarpa vicino al letto si vede chiaramente il cavo della telecamera d''angolo riflesse sulla superficie lucida del comodino.', TRUE, '2026-09-14T13:48:35.70451', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(170, 44, '00:52:40', 'Errori di scena / Posizione', 'Durante l''interrogatorio e la successiva eliminazione del Professor Dent, l''arma impugnata da James Bond passa alternativamente da una Walther PPK con silenziatore a una Browning 1910 a seconda dei cambi di angolazione dell''inquadratura.', TRUE, '2026-09-14T13:48:35.796741', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(171, 44, '01:05:12', 'Anacronismi', 'Mentre Bond ed Felix Leiter consultano le mappe e le rotte verso Crab Key, si nota sullo sfondo un calendario con la tabella dei giorni settimanali che presenta incoerenze rispetto al reale calendario del 1962.', TRUE, '2026-09-14T13:48:35.839461', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(172, 44, '01:14:30', 'Errori di scena / Posizione', 'Quando Honey Ryder emerge dall''oceano cantando con le conchiglie in mano, l''allineamento della cinghia del suo coltello e il posizionamento delle conchiglie nella sacca cambiano drasticamente fra il primo piano e la panoramica.', TRUE, '2026-09-14T13:48:35.926872', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(173, 44, '01:22:15', 'Errori storici o fattuali', 'Il ''carro armato drago'' utilizzato dagli uomini del Dr. No viene descritto come un veicolo cingolato corazzato, ma al momento dello scontro si notano chiaramente le ruote in gomma di un telaio modificato da jeep da cui spuntano i finti cingoli staccati dal terreno.', TRUE, '2026-09-14T13:48:36.03921', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(3670, 124, '01:22:00', 'Errori di scena / Posizione', 'Durante la battaglia finale sotto la pioggia tra Neo e l''Agente Smith, in alcune inquadrature ravvicinate i capelli bagnati di Keanu Reeves cambiano posizione e asciugatura in modo incoerente rispetto all''inquadratura precedente.', TRUE, '2026-11-01T17:50:11.241078', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3671, 124, '00:45:00', 'Errori di scena / Posizione', 'Nella scena in cui Niobe pilota la Logos attraverso i tubi stretti, i danni visibili sulla plancia e sui monitor della nave cambiano da un''inquadratura all''altra.', TRUE, '2026-11-01T17:50:11.241078', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3672, 130, '00:12:45', 'Errori di scena / Posizione', 'Durante la scena del seminario, la posizione della bottiglia d''acqua sul tavolo davanti a Burke cambia tra le inquadrature, passando da essere vicina al bordo a essere spostata verso il centro.', TRUE, '2026-11-01T17:50:23.211891', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3673, 130, '00:45:20', 'Errori di scena / Posizione', 'Nella scena in cui Eloise sta sistemando i fiori nel suo negozio, la disposizione dei mazzi di fiori sul bancone cambia visibilmente tra un taglio di montaggio e l''altro.', TRUE, '2026-11-01T17:50:23.211891', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3674, 130, '01:15:10', 'Errori di scena / Posizione', 'Durante la conversazione tra Burke e il suocero in hotel, il bicchiere di bevanda tenuto in mano da Burke cambia livello di riempimento in modo incoerente tra le inquadrature alternate.', TRUE, '2026-11-01T17:50:23.211891', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3679, 135, '01:25:00', 'Errori di scena / Posizione', 'Durante la rissa finale in strada tra Rocky e Tommy Gunn, la pioggia battente crea evidenti problemi di continuità: i capelli e i vestiti dei due lottatori passano dall''essere completamente inzuppati a quasi asciutti o umidi a seconda dell''inquadratura.', TRUE, '2026-11-01T17:50:35.032872', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3680, 135, '00:15:00', 'Anacronismi', 'Nel corso dei flashback e delle sequenze ambientate nel passato o legate ai ricordi della gioventù di Rocky, alcuni dettagli di arredamento e abbigliamento non corrispondono correttamente al periodo storico di riferimento.', TRUE, '2026-11-01T17:50:35.032872', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(903, 58, '00:03:45', 'Continuità', 'Durante la scena iniziale sotto la pioggia torrenziale in cui Elizabeth viene arrestata da Cutler Beckett, le ciocche di capelli sul viso della donna cambiano continuamente disposizione e livello di bagnato tra i primi piani e i controcampi.', TRUE, '2026-10-03T17:23:47.864222', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(904, 58, '00:33:10', 'Continuità', 'Sull''isola dei Pelegosto, mentre Jack Sparrow cerca di scappare legato al lungo palo di bambù, la quantità e la disposizione dei frutti infilzati alle estremità del palo cambiano vistosamente tra le inquadrature larghe e i piani ravvicinati.', TRUE, '2026-10-03T17:23:47.864222', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(905, 58, '00:39:40', 'Errori di scena / Attrezzatura', 'Quando Will Turner e la ciurma fanno oscillare le gabbie sferiche di ossa per scalare il dirupo, in un''inquadratura dal basso è visibile un cavo di sicurezza in acciaio moderno che sostiene la gabbia oltre alle corde sceniche.', TRUE, '2026-10-03T17:23:47.864222', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(906, 58, '01:04:20', 'Continuità', 'Durante la partita a dadi bugiardi tra Will Turner e Davy Jones a bordo dell''Olandese Volante, la configurazione e la posizione dei dadi sul tavolo cambiano tra il momento in cui la tazza viene sollevata e il cambio di angolazione successivo.', TRUE, '2026-10-03T17:23:47.864222', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(907, 58, '01:54:30', 'Continuità', 'Nel celebre duello sulla ruota del mulino a Isla Cruces, Jack Sparrow si ritrova all''interno della ruota: la sua spada passa istantaneamente dall''essere impugnata a essere infilata nel fodero e poi di nuovo in mano tra stacchi consecutivi, senza che lui compia il gesto di rinfoderarla o estrarla.', TRUE, '2026-10-03T17:23:47.864222', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(908, 58, '01:59:15', 'Oggetti di scena', 'Sulla spiaggia di Isla Cruces, durante la contesa per la chiave del forziere fantasma, la chiave stessa cambia visibilmente dimensione e proporzioni nei dettagli dell''impugnatura tra le sequenze con gli stuntman e le inquadrature a fuoco stretto sui protagonisti.', TRUE, '2026-10-03T17:23:47.864222', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(909, 58, '02:11:05', 'Continuità', 'Durante il primo grande assalto del Kraken alla Perla Nera, un enorme tentacolo spazza via e frantuma completamente la ringhiera del ponte superiore; nell''inquadratura panoramica successiva, la stessa ringhiera è nuovamente intatta prima di essere distrutta un''altra volta.', TRUE, '2026-10-03T17:23:47.864222', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(725, 138, '01:54:05', 'Errori di scena / Posizione', 'Nel parcheggio sotterraneo e poi esterno dove Louis e Melanie cercano il furgone, le macchine parcheggiate intorno alla loro vettura cambiano modello e colore tra l''inquadratura larga e il totale registrato dalla prospettiva opposta.', TRUE, '2026-09-26T14:36:06.948712', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(726, 138, '02:20:40', 'Errori storici o fattuali', 'Nella resa dei conti finale all''interno dell''ufficio di Max Cherry, la posizione del cane della pistola impugnata da Ordell varia inquadratura dopo inquadratura, passando dall''essere armato (arretrato) all''essere a riposo (abbassato), senza che l''attore compia alcun movimento di riarmo.', TRUE, '2026-09-26T14:36:06.948712', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(174, 44, '01:35:40', 'Errori di scena / Posizione', 'Nella scena della decontaminazione radioattiva, Honey e Bond vengono lavati abbondantemente sotto docce ad alta pressione; nell''inquadratura immediatamente successiva dentro gli alloggi i capelli di Honey sono perfettamente asciutti e acconciati.', TRUE, '2026-09-14T13:48:36.11158', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(3667, 123, '00:35:12', 'Errori di scena / Posizione', 'Durante il combattimento nel salone di Merovingio, i segni dei colpi e i danni subiti dalle pareti e dai pilastri cambiano posizione o scompaiono tra un''inquadratura e l''altra.', TRUE, '2026-11-01T17:50:05.477118', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(177, 45, '00:12:45', 'Anacronismi', 'Mentre Goldfinger gioca a carte a piscina barando via auricolare, l''orologio da polso indossato dal magnate mostra le 11:15 in un primo piano, ma segna le 12:20 nel fotogramma successivo ambientato pochi secondi dopo.', TRUE, '2026-09-14T13:48:36.51498', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(3668, 123, '01:15:40', 'Errori di scena / Posizione', 'Nella scena dell''inseguimento autostradale, la Ducati 996 guidata da Trinity subisce danni evidenti alla carenatura in alcune inquadrature, che spariscono completamente in quelle successive.', TRUE, '2026-11-01T17:50:05.477118', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3669, 123, '01:22:15', 'Errori di scena / Posizione', 'Sempre durante l''inseguimento sull''autostrada, la quantità di traffico e la posizione esatta dei veicoli circostanti cambiano drasticamente e repentinamente tra le riprese aeree e quelle ad altezza d''uomo.', TRUE, '2026-11-01T17:50:05.477118', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3675, 134, '00:08:15', 'Errori di scena / Posizione', 'Durante la conferenza stampa prima del match di beneficenza con Thunderlips (Hulk Hogan), gli oggetti sul tavolo e la posizione del microfono cambiano in modo evidente tra un''inquadratura e l''altra.', TRUE, '2026-11-01T17:50:29.233149', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3676, 134, '00:22:40', 'Errori di scena / Posizione', 'Nel tragitto verso la palestra prima del match contro Clubber Lang, la disposizione dei vestiti e degli accessori indossati da Rocky varia repentinamente nei cambi di inquadratura.', TRUE, '2026-11-01T17:50:29.233149', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3677, 134, '00:45:10', 'Errori di scena / Posizione', 'Durante la sequenza dell''allenamento a Los Angeles con Apollo Creed sulla spiaggia, i segni della sabbia sul corpo di Rocky e la sua pettinatura bagnata variano da un primo piano a un campo largo.', TRUE, '2026-11-01T17:50:29.233149', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3678, 134, '01:12:00', 'Errori di scena / Posizione', 'Nel corso del secondo incontro tra Rocky e Clubber Lang, i tagli e le ferite sul volto di Rocky cambiano dimensione e posizione tra le riprese dei round e gli angoli del ring.', TRUE, '2026-11-01T17:50:29.233149', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3681, 150, '00:00:00', 'Troupe o microfoni visibili', 'Durante alcune delle sequenze nel deserto di Arrakis, in campi larghi particolarmente polverosi, la luce riflessa della troupe o occasionali ombre di attrezzature da presa sono visibili sulle rocce o sulla sabbia.', TRUE, '2026-11-01T17:50:42.443845', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3682, 150, '00:00:00', 'Errori di scena / Posizione', 'Nella scena in cui Paul Atreides si allena con Gurney Halleck, la posizione del sudore sugli abiti e sul viso dei personaggi varia leggermente tra i campi e i controcampi durante il dialogo.', TRUE, '2026-11-01T17:50:42.443845', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3687, 155, '00:08:00', 'Errori di scena / Posizione', 'Nel filmato amatoriale della cassetta VHS del passato di Andy, la videocamera mostra date e dettagli che cambiano rispetto alla tecnologia effettivamente disponibile e coerente con la cronologia dei film precedenti.', TRUE, '2026-11-01T17:50:56.825297', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3688, 155, '00:35:00', 'Errori di scena / Posizione', 'Quando i giocattoli vengono tirati fuori dal contenitore nell''aula dei bruchi al Sunnyside, la posizione di Buzz Lightyear cambia visibilmente tra un''inquadratura e l''altra rispetto agli altri giocattoli intorno a lui.', TRUE, '2026-11-01T17:50:56.825297', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3689, 155, '01:05:00', 'Errori di scena / Posizione', 'Durante la scena della discarica, il nastro trasportatore muove gli oggetti a velocità incoerenti, e in alcune inquadrature la distanza tra la fossa degli incineratori e la posizione dei giocattoli varia in modo non logico.', TRUE, '2026-11-01T17:50:56.825297', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(910, 174, '00:04:12', 'Continuità', 'Durante la sequenza iniziale dell''inondazione del Tevere, la quantità di fango e detriti sui volti e sui corpi di Romolo e Remo varia vistosamente tra i primi piani e le inquadrature a figura intera.', TRUE, '2026-10-05T17:18:54.999891', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(911, 174, '00:19:45', 'Trucco e costumi', 'Durante la prigionia nel campo dei Sabini, una profonda ferita da taglio sul costato di Romolo appare fresca e sanguinante in un''inquadratura, per poi risultare quasi completamente rimarginata e opaca nello stacco successivo.', TRUE, '2026-10-05T17:18:54.999891', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(912, 174, '00:36:20', 'Anacronismo / Dettagli di scena', 'In un primo piano ravvicinato di uno dei guerrieri della tribù durante il confronto nel bosco, si intravede chiaramente un''otturazione moderna in amalgama scura su uno dei molari inferiori.', TRUE, '2026-10-05T17:18:54.999891', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(913, 174, '00:51:30', 'Continuità', 'Il fuoco sacro trasportato dalla vestale Tefnie presenta una fiamma alta e fumosa nel campo lungo, ma al controcampo ravvicinato la brace è quasi del tutto spenta e produce pochissimo fumo.', TRUE, '2026-10-05T17:18:54.999891', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(914, 174, '01:08:14', 'Errori di scena / Posizione', 'Nel corso della marcia nella palude, Remo impugna la lancia nella mano destra; a seguito di un cambio di prospettiva immediato, l''arma si trova saldamente nella mano sinistra senza alcun movimento intermedio.', TRUE, '2026-10-05T17:18:54.999891', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(915, 174, '01:24:50', 'Attrezzatura tecnica visibile', 'Durante la fuga tra la fitta vegetazione e le radici, per una frazione di secondo nell''angolo inferiore sinistro dell''inquadratura si scorge un cavo nero di sicurezza o alimentazione parzialmente interrato sotto il fogliame.', TRUE, '2026-10-05T17:18:54.999891', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(916, 174, '01:43:05', 'Continuità', 'Durante lo scontro finale e drammatico tra Romolo e Remo, il sangue che copre il petto di Remo cambia disegno e consistenza: prima forma tre rivoli distinti, poi, senza che nessuno lo tocchi, si presenta come un''unica grande chiazza uniforme.', TRUE, '2026-10-05T17:18:54.999891', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(3683, 154, '00:04:15', 'Errori di scena / Posizione', 'Nel cortile di Andy, quando Rex guarda attraverso la lente d''ingrandimento, la posizione della lente cambia bruscamente tra un''inquadratura e l''altra rispetto al suo muso.', TRUE, '2026-11-01T17:50:50.218935', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(1020, 231, '00:14:35', 'Errori di scena / Posizione', 'Quando Finn parla con la sorella mentre gioca ai videogiochi, la posizione del controller nelle sue mani cambia drasticamente tra un campo e un controcampo: prima lo tiene con entrambe le mani sollevate, poi improvvisamente è appoggiato sulle gambe.', TRUE, '2026-10-24T15:36:29.469711', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(179, 45, '00:35:50', 'Anacronismi', 'L''Aston Martin DB5 fornita da Q possiede uno schermo radar con tracciamento digitale a mappe sovrapposte all''interno dell''abitacolo, una tecnologia di tracciamento GPS miniaturizzata che non esisteva assolutamente nel 1964.', TRUE, '2026-09-14T13:48:36.722352', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(180, 45, '00:48:12', 'Errori di scena / Posizione', 'Durante l''inseguimento sulle strade di montagna svizzere, la ruota tagliente dell''Aston Martin squarcia la fiancata e le gomme della Ford Mustang di Tilly Masterson, ma nelle inquadrature successive il danno varia di forma e la carrozzeria appare meno danneggiata.', TRUE, '2026-09-14T13:48:36.761098', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(3684, 154, '00:15:30', 'Errori di scena / Posizione', 'Nell''appartamento di Al, quando Woody viene esaminato dal restauratore di giocattoli, gli strumenti sul tavolo cambiano posizione e quantità da un''inquadratura ravvicinata a quella generale.', TRUE, '2026-11-01T17:50:50.218935', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(182, 45, '01:12:20', 'Troupe o microfoni visibili', 'Durante il riassunto del piano Grand Slam ai gangster riuniti attorno al plastico meccanico, nella parte superiore dell''inquadratura spunta chiaramente un microfono a giraffa per la registrazione dell''audio.', TRUE, '2026-09-14T13:48:36.928893', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(183, 45, '01:24:55', 'Errori storici o fattuali', 'Goldfinger spiega che la bomba sporca utilizzerà Cobalto 60 per rendere l''oro di Fort Knox radioattivo per 57 anni. Dal punto di vista della fisica nucleare, l''isotopo Cobalto-60 ha un''emivita di circa 5,27 anni, il che rende il calcolo scientificamente errato.', TRUE, '2026-09-14T13:48:36.96564', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(184, 45, '01:36:10', 'Errori di scena / Posizione', 'All''interno del caveau di Fort Knox, il timer della bomba atomica mostra i numeri scorrere a una velocità non costante: alcuni secondi durano molto più a lungo di un secondo reale per far coincidere la battuta finale dell''agente 007.', TRUE, '2026-09-14T13:48:37.037919', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(3685, 154, '00:32:00', 'Errori di scena / Posizione', 'Nel negozio di giocattoli ''Al''s Toy Barn'', quando Buzz Lightyear incontra l''altro Buzz sullo scatole, la plastica di chiusura della confezione scompare e riappare in alcune inquadrature.', TRUE, '2026-11-01T17:50:50.218935', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(186, 45, '01:50:15', 'Troupe o microfoni visibili', 'Nella sequenza finale a bordo del jet dove si rompe il finestrino e Goldfinger viene risucchiato fuori, nei fotogrammi in cui il corpo attraversa l''oblò si intravedono i cavi di sicurezza d''acciaio che tirano lo stuntman verso l''esterno.', TRUE, '2026-09-14T13:48:37.234357', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(3686, 154, '01:05:20', 'Errori di scena / Posizione', 'Durante la scena all''aeroporto, all''interno del sistema di smistamento bagagli, la posizione dei vari contenitori e valigie non è coerente con il movimento continuo del nastro trasportatore.', TRUE, '2026-11-01T17:50:50.218935', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3690, 156, '00:00:00', 'Errori di scena / Posizione', 'Durante il flashback iniziale sotto la pioggia, la posizione dei giocattoli e il livello dell''acqua nelle pozzanghere cambiano in modo incoerente tra le inquadrature ampie e i primi piani.', TRUE, '2026-11-01T17:51:03.648408', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3691, 156, '00:00:00', 'Anacronismi', 'Gli eventi del flashback risalgono a nove anni prima, ma alcuni modelli di auto e oggetti sullo sfondo presentano dettagli stilistici non coerenti con la linea temporale stabilita.', TRUE, '2026-11-01T17:51:03.648408', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3697, 160, '00:08:00', 'Errori di scena / Posizione', 'Durante la sequenza iniziale del dirottamento dell''aereo della CIA, l''agente incappucciato viene fatto salire a bordo con una cravatta. Quando la telecamera cambia inquadratura mentre l''aereo viene agganciato, la cravatta spare e riappare a seconda delle riprese.', TRUE, '2026-11-01T17:51:16.691807', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3698, 160, '00:35:00', 'Errori di scena / Posizione', 'Nella scena in cui Bruce Wayne riceve la visita di Selina Kyle a casa sua, la posizione dei bicchieri e degli oggetti sul tavolo cambia leggermente tra un''inquadratura e l''altra mentre parlano.', TRUE, '2026-11-01T17:51:16.691807', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3699, 160, '01:15:00', 'Errori di scena / Posizione', 'Durante il combattimento tra Batman e Bane nelle fogne, la maschera e i tubi di Bane subiscono variazioni di posizione e lievi differenze estetiche nei dettagli ravvicinati rispetto ai campi larghi.', TRUE, '2026-11-01T17:51:16.691807', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3700, 160, '01:45:00', 'Errori di scena / Posizione', 'Quando i poliziotti di Gotham escono dalle fogne dopo mesi di isolamento, le loro uniformi e la loro barba sono sorprendentemente pulite e curate, nonostante le condizioni estreme in cui avrebbero dovuto vivere.', TRUE, '2026-11-01T17:51:16.691807', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3692, 159, '00:08:30', 'Errori di scena / Posizione', 'Durante la riunione dei boss mafiosi con il Joker, la cicca di sigaretta e il modo in cui il Joker tiene la matassa cambiano leggermente posizione tra le inquadrature dei primi piani e i campi larghi.', TRUE, '2026-11-01T17:51:10.094996', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3693, 159, '00:25:00', 'Errori di scena / Posizione', 'Quando il commissario Loeb e il sindaco parlano nell''ufficio, i fascicoli sulla scrivania cambiano posizione e disposizione sul tavolo a seconda dell''angolazione della telecamera.', TRUE, '2026-11-01T17:51:10.094996', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(918, 180, '00:45:12', 'Incongruenza / Continuità', 'Durante la prima esplorazione di Skull Island, l''abito di Ann Darrow si sporca vistosamente di fango. Nelle inquadrature successive, prima che abbia la possibilità di lavarsi, il vestito appare improvvisamente molto più pulito e le macchie rimaste cambiano posizione.', TRUE, '2026-10-06T19:44:34.973473', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(919, 180, '01:12:30', 'Errore di montaggio / CGI', 'Durante la scena della fuga dei brontosauri, la posizione dei personaggi umani rispetto alle zampe dei dinosauri giganti cambia bruscamente tra un taglio e l''altro. In un''inquadratura Jack Driscoll è sul punto di essere calpestato, ma nel taglio successivo si trova a diversi metri di distanza in totale sicurezza.', TRUE, '2026-10-06T19:44:34.973473', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(920, 180, '01:45:22', 'Errore di scena / Trucco', 'Durante lo scontro tra Kong e i tre V-Rex, Ann Darrow viene sballottata all''interno di una fitta vegetazione e nel fango. Nonostante i violenti scossoni, la sua acconciatura bionda rimane perfettamente ordinata e il trucco sul viso non presenta alcuna sbavatura tra un''inquadratura e l''altra.', TRUE, '2026-10-06T19:44:34.973473', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(921, 180, '02:10:45', 'Incongruenza fisica / Proporzioni', 'Quando Kong viene catturato e trasportato sulla nave Venture, le dimensioni della stiva che lo ospita per il viaggio verso New York appaiono geometricamente impossibili e sproporzionate rispetto alle reali dimensioni esterne dello scafo della nave mostrate in precedenza.', TRUE, '2026-10-06T19:44:34.973473', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(922, 180, '02:40:10', 'Errore di continuità', 'Nella scena in cui Kong e Ann scivolano sul laghetto ghiacciato a Central Park, lo spessore del ghiaccio e la quantità di neve fresca accumulata sui bordi cambiano drasticamente tra le riprese grandangolari (in CGI) e i primi piani degli attori ricostruiti in studio.', TRUE, '2026-10-06T19:44:34.973473', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(923, 180, '02:52:30', 'Anacronismo storico', 'Durante l''attacco finale sull''Empire State Building, i biplani militari Curtiss F8C-5 Helldiver presentano alcune insegne e dettagli della cabina di pilotaggio che non corrispondono storicamente ai modelli in uso nel 1933, anno in cui è ambientata la pellicola.', TRUE, '2026-10-06T19:44:34.973473', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(727, 139, '00:12:35', 'Errori storici o fattuali', 'Il treno Shinkansen mostrato nel film (che viaggia da Tokyo a Kyoto) presenta interni con scompartimenti privati spaziosi e una carrozza bar/lounge lussuosa. Nella realtà, i treni della linea Tokaido Shinkansen (N700S) non dispongono di scompartimenti privati di questo tipo né di carrozze bar così ampie, ma solo di file standard di sedili e carrelli mobili per il servizio ristoro.', TRUE, '2026-09-26T15:22:11.065646', NULL, 0, 0, 'mrtrrt@libero.it', 'ia', NULL),
(187, 46, '00:00:35', 'Errori di scena / Posizione', 'Durante la drammatica scena iniziale dell''esplosione dell''auto di Ace Rothstein, la vettura usata per lo stunt presenta una carrozzeria nettamente differente dal modello guidato da Robert De Niro pochi secondi prima, ed è chiaramente visibile un manichino al posto dell''attore.', TRUE, '2026-09-14T13:49:13.568485', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(188, 46, '00:15:20', 'Errori di scena / Posizione', 'Nel primo incontro tra Ace e Ginger al tavolo da gioco, la disposizione e il colore delle fiches cambiano visibilmente tra il campo e il controcampo senza che nessuno le abbia toccate.', TRUE, '2026-09-14T13:49:13.646551', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(189, 46, '00:28:45', 'Troupe o microfoni visibili', 'Durante un dialogo all''esterno sotto il sole di Las Vegas tra Ace e Nikki, sugli occhiali da sole a specchio di De Niro si riflettono chiaramente il cameraman e un pannello riflettente della troupe.', TRUE, '2026-09-14T13:49:13.694516', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(190, 46, '00:42:10', 'Anacronismi', 'Nella sequenza ambientata nei primi anni ''70, sullo sfondo del parcheggio del casinò si nota un modello di autovettura equipaggiato con una terza luce di arresto posteriore, caratteristica obbligatoria negli USA solo a partire dal 1986.', TRUE, '2026-09-14T13:49:13.81385', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(3694, 159, '00:42:00', 'Errori di scena / Posizione', 'Durante la scena dell''interrogatorio tra Batman e il Joker, i lividi sul volto di Batman e la posizione delle manette subiscono piccole variazioni incoerenti nei cambi di inquadratura.', TRUE, '2026-11-01T17:51:10.094996', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3695, 159, '01:12:00', 'Errori di scena / Posizione', 'Nella sequenza dell''attentato al funerale del giudice Surrillo, i fori di proiettile sul parabrezza dell''auto cambiano numero e disposizione tra un''inquadratura e l''altra.', TRUE, '2026-11-01T17:51:10.094996', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3696, 159, '01:28:00', 'Errori di scena / Posizione', 'Quando Gordon e i suoi agenti fanno irruzione nel covo dove Harvey Dent è tenuto in ostaggio, le corde che legano Dent cambiano tensione e modo in cui sono annodate prima e dopo l''esplosione.', TRUE, '2026-11-01T17:51:10.094996', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3959, 191, '00:05:00', 'Errori di scena / Posizione', 'Nella scena iniziale alla stazione ferroviaria, l''orologio pubblico visibile sullo sfondo mostra orari diversi e incoerenti tra le inquadrature ravvicinate di Vic e i campi medi della folla.', TRUE, '2026-11-02T10:18:49.792123', 'Il tempo delle mele 2 stazione orologio errore', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3960, 191, '00:12:00', 'Errori di scena / Posizione', 'Mentre Vic discute con i genitori in cucina, il livello del succo d''arancia all''interno del suo bicchiere varia sensibilmente tra un''inquadratura e l''altra, aumentando e diminuendo senza che lei beva.', TRUE, '2026-11-02T10:18:49.792123', 'La Boum 2 kitchen scene juice continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3961, 191, '00:45:00', 'Errori di scena / Posizione', 'Durante il concerto dei Cook da Books, l''asta del microfono del cantante cambia altezza e inclinazione tra i primi piani e le inquadrature larghe del palco.', TRUE, '2026-11-02T10:18:49.792123', 'La Boum 2 Cook da Books concert goof', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3962, 191, '00:08:00', 'Errori di scena / Posizione', 'Nel primo incontro tra Vic e Philippe sul treno, la posizione dei capelli di Vic (alcune ciocche che cadono sulla spalla sinistra) cambia ripetutamente tra i vari stacchi di montaggio della conversazione.', TRUE, '2026-11-02T10:18:49.792123', 'La Boum 2 Vic Philippe train meeting hair', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3963, 191, '00:30:00', 'Troupe o microfoni visibili', 'In una sequenza in cui i protagonisti si muovono in auto per le strade di Parigi, è possibile scorgere il riflesso delle luci di produzione e di un operatore sui finestrini laterali della vettura durante una curva.', TRUE, '2026-11-02T10:18:49.792123', 'La Boum 2 car reflection crew', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3701, 160, '02:25:00', 'Errori di scena / Posizione', 'Nella scena della morte di Talia al Ghul, la posizione della sua testa e il modo in cui i suoi occhi si chiudono variano leggermente tra il primo piano e il campo medio successivo.', TRUE, '2026-11-01T17:51:16.691807', NULL, 0, 0, 'IA (Archivio)', 'ia', NULL),
(3964, 191, '01:10:00', 'Errori di scena / Posizione', 'Durante la scena in cui vengono controllati i documenti per il viaggio, i passaporti e i biglietti appoggiati sul tavolo cambiano orientamento e distanza tra loro tra un''inquadratura dall''alto e una frontale.', TRUE, '2026-11-02T10:18:49.792123', 'La Boum 2 passport table continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3965, 191, '00:55:00', 'Errori di scena / Posizione', 'Durante la corsa in moto, lo sfondo che scorre dietro Philippe e Vic mostra edifici che non corrispondono alla direzione di marcia e alle curve effettuate dal manubrio, evidenziando l''uso di uno schermo per la retroproiezione.', TRUE, '2026-11-02T10:18:49.792123', 'La Boum 2 motorcycle scene background', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3966, 191, '00:06:00', 'Errori di scena / Posizione', 'Alla stazione, la disposizione delle persone e dei bagagli sulla banchina alle spalle di Vic cambia drasticamente nel passaggio da un''inquadratura stretta a un campo lungo, con alcune comparse che spariscono e riappaiono.', TRUE, '2026-11-02T10:18:49.792123', 'La Boum 2 station crowd continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4318, 356, '00:15:30', 'Errori di scena / Posizione', 'Quando Leonard si trova nella sua stanza d''albergo e scrive sul retro di una polaroid, la posizione della penna e l''inclinazione della fotografia cambiano in modo evidente tra un''inquadratura e l''altra nel montaggio sequenziale.', TRUE, '2026-11-02T14:52:16.530823', 'Memento polaroid scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4319, 356, '00:42:15', 'Errori di scena / Posizione', 'Nel corso della conversazione alcolica nel bar tra Leonard e Natalie, il bicchiere di Natalie si riempie e si svuota parzialmente tra i cambi d''inquadratura senza che nessuno tocchi la bottiglia.', TRUE, '2026-11-02T14:52:16.530823', 'Memento bar scene Natalie drink continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL);
INSERT INTO public.errori ("id", "film_id", "minuto", "categoria", "descrizione", "approvato", "creato_il", "youtube_query", "conferme", "contestazioni", "inserito_da", "provenienza", "screenshot_url") VALUES
(4320, 356, '01:05:40', 'Troupe o microfoni visibili', 'Durante la sequenza in macchina in cui Leonard guida, in un breve riflesso sul finestrino laterale è possibile intravedere brevemente la sagoma di un operatore della troupe con una telecamera.', TRUE, '2026-11-02T14:52:16.530823', 'Memento crew reflection car scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(924, 182, '00:28:15', 'Errore di continuità', 'Durante la caotica cena a Casa Baggins, la disposizione del cibo sul tavolo, in particolare i formaggi, le fette di carne e le pagnotte di pane, cambia ripetutamente posizione e quantità tra le inquadrature strette sui nani e quelle larghe della stanza.', TRUE, '2026-10-09T15:05:48.403226', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(925, 182, '00:38:40', 'Errore di continuità / Oggetti', 'Quando Bilbo corre fuori da Casa Baggins con il contratto firmato, tiene il foglio arrotolato saldamente nella mano destra. Nell''inquadratura immediatamente successiva, mentre corre lungo il sentiero della Contea, il contratto si trova improvvisamente nella mano sinistra.', TRUE, '2026-10-09T15:05:48.403226', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(926, 182, '01:12:10', 'Errore di continuità', 'Nella scena in cui i troll catturano Bilbo, la spada Pungolo (ancora non rinominata) è chiaramente infilata nella cintura dei suoi pantaloni. Nello stacco successivo la spada scompare del tutto, per poi riapparire misteriosamente quando i troll lo sollevano in aria.', TRUE, '2026-10-09T15:05:48.403226', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(927, 182, '01:35:25', 'Errore di continuità / Posizione', 'Durante l''inseguimento dei mannari (Warg) con la slitta di Radagast, la disposizione e il numero dei conigli di Rhosgobel che trainano la slitta variano vistosamente tra le inquadrature ravvicinate dal vivo e quelle digitali a lungo raggio.', TRUE, '2026-10-09T15:05:48.403226', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(928, 182, '02:02:15', 'Errore di continuità', 'Nella scena degli indovinelli nell''oscurità tra Bilbo e Gollum, l''Anello cade dalla tasca di quest''ultimo. La posizione dell''Anello sul terreno sabbioso cambia nettamente tra il primo piano dettagliato e l''inquadratura successiva in cui Bilbo si china a raccoglierlo.', TRUE, '2026-10-09T15:05:48.403226', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(929, 182, '02:25:30', 'Errore di continuità / Oggetti', 'Durante la rocambolesca fuga dalle caverne dei Goblin, la spada di Thorin, Orcrist, appare completamente coperta di sporco e sangue nero di goblin in un''inquadratura, ma nel taglio successivo, senza che sia stata pulita, brilla perfettamente lucida.', TRUE, '2026-10-09T15:05:48.403226', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(930, 182, '02:38:10', 'Errore di continuità / Trucco', 'Quando Thorin affronta Azog sulla collina alla fine del film, i graffi e le ferite di sangue sul viso di Thorin cambiano forma, intensità e posizione tra i vari primi piani ravvicinati durante il drammatico scontro.', TRUE, '2026-10-09T15:05:48.403226', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(4321, 356, '01:28:10', 'Errori di scena / Posizione', 'Le ferite sul volto di Leonard e i graffi cambiano leggermente di intensità e posizione in alcune sequenze a causa delle riprese non lineari e del make-up non perfettamente uniformato tra i vari giorni di shooting.', TRUE, '2026-11-02T14:52:16.530823', 'Memento Guy Pearce makeup continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4330, 361, '00:15:24', 'Errori di scena / Posizione', 'Quando i ragazzi si fermano alla stazione di servizio e il proprietario dice loro che non c''è benzina, la tanica sul retro del furgone cambia leggermente posizione e orientamento tra un''inquadratura e l''altra.', TRUE, '2026-11-02T14:52:35.327769', 'The Texas Chain Saw Massacre gas station scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4331, 361, '00:32:10', 'Troupe o microfoni visibili', 'Durante la scena in cui Kirk entra nella casa di Leatherface, in un breve controcampo controluce è possibile intravedere brevemente l''ombra del microfono boom proiettata sulla parete.', TRUE, '2026-11-02T14:52:35.327769', 'The Texas Chain Saw Massacre boom mic shadow error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4332, 361, '00:45:15', 'Errori di scena / Posizione', 'Quando Pam viene catturata e appesa al gancio da macellaio, la posizione delle sue mani e il modo in cui la corda o il gancio la sostengono cambiano visibilmente tra i primi piani e i campi medi.', TRUE, '2026-11-02T14:52:35.327769', 'The Texas Chain Saw Massacre Pam meat hook scene continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4333, 361, '01:02:40', 'Errori di scena / Posizione', 'Nella sequenza della cena in famiglia, la quantità di cibo e la posizione degli utensili sul tavolo variano notevolmente tra un taglio di montaggio e l''altro, specialmente vicino al piatto di Franklin.', TRUE, '2026-11-02T14:52:35.327769', 'The Texas Chain Saw Massacre dinner scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4334, 361, '01:14:05', 'Troupe o microfoni visibili', 'Durante l''inseguimento di Sally nel bosco di notte, in un''inquadratura grandangolare si intravede per un istante un riflettore della troupe tra gli alberi sulla sinistra.', TRUE, '2026-11-02T14:52:35.327769', 'The Texas Chain Saw Massacre crew lights visible forest scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4511, 181, '00:42:10', 'Errori di scena / Posizione', 'Quando Bilbo estrae la spada Pungolo (Sting) per la prima volta contro i ragni nel Bosco Atro, la lama passa dall''essere completamente dritta a leggermente curva nell''inquadratura ravvicinata successiva.', TRUE, '2026-11-02T15:32:51.590097', 'The Hobbit 1977 mistakes spiders', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3703, 2, '00:09:42', 'Anacronismi', 'Durante la sequenza in Germania, Massimo cavalca un cavallo di razza Lipizzana, una razza equina sviluppata secoli dopo rispetto all''epoca romana.', TRUE, '2026-11-02T08:50:52.146222', 'Gladiator movie horses Lipizzaner anachronism', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(938, 189, '00:08:15', 'Incongruenza / Capelli', 'Durante il viaggio in auto verso New York, i capelli di Sally cambiano continuamente aspetto tra un''inquadratura e l''altra: in alcune scene sono visibilmente spettinati dal vento, mentre in quelle immediatamente successive sono perfettamente in ordine.', TRUE, '2026-10-09T15:27:00.329313', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(939, 189, '00:28:40', 'Incongruenza / Oggetti di scena', 'Nella scena in cui Harry e Sally camminano per Central Park in autunno, la sciarpa di Harry cambia il modo in cui è annodata intorno al collo diverse volte tra i cambi di inquadratura.', TRUE, '2026-10-09T15:27:00.329313', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(3704, 2, '00:32:15', 'Errori di scena / Posizione', 'Quando Massimo viene marchiato sulla spalla con le lettere ''SPQR'' a fuoco, la posizione e l''orientamento del marchio cambiano leggermente nelle inquadrature successive prima di guarire.', TRUE, '2026-11-02T08:50:52.146222', 'Gladiator movie Russell Crowe SPQR brand scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(941, 189, '00:45:30', 'Incongruenza / Cibo e Bevande', 'Nella celebre scena del finto orgasmo al ristorante ''Katz''s Delicatessen'', il panino di Sally cambia posizione sul piatto e la quantità di cibo rimasta varia inspiegabilmente tra i primi piani e i campi medi.', TRUE, '2026-10-09T15:27:00.329313', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(942, 189, '00:52:15', 'Incongruenza / Bicchieri', 'Durante la scena del doppio appuntamento a quattro, il livello del vino bianco nel bicchiere di Marie sale e scende ripetutamente senza che lei ne beva effettivamente.', TRUE, '2026-10-09T15:27:00.329313', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(943, 189, '01:02:10', 'Incongruenza / Recitazione', 'Nella scena del museo dove Harry parla con l''accento strano (''pepper'' monologue), l''espressione di Sally passa istantaneamente da un sorriso divertito a una faccia seria e annoiata tra due inquadrature consecutive, senza transizione temporale.', TRUE, '2026-10-09T15:27:00.329313', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(944, 189, '01:12:10', 'Incongruenza / Posizione', 'Durante la discussione sul tavolino a forma di ruota di carro tra Jess e Marie, la scatola di cartone sullo sfondo cambia posizione e orientamento tra un taglio e l''altro della telecamera.', TRUE, '2026-10-09T15:27:00.329313', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(945, 189, '01:29:05', 'Incongruenza / Abbigliamento', 'Alla festa di Capodanno finale, quando Harry corre per dichiararsi a Sally, il colletto della sua camicia e la sua cravatta cambiano posizione (prima slacciata e storta, poi sistemata) tra le inquadrature ravvicinate e quelle più larghe.', TRUE, '2026-10-09T15:27:00.329313', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(191, 46, '00:55:00', 'Errori di scena / Posizione', 'Quando il baro viene punito nel retrobottega spezzandogli la mano con un martello, la posizione del braccio dell''uomo sul tavolo cambia tra le inquadrature ravvicinate e quelle ad angolo largo.', TRUE, '2026-09-14T13:49:13.905088', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(192, 46, '01:08:15', 'Errori storici o fattuali', 'Vengono descritte dettagliatamente le procedure di controllo delle licenze di gioco da parte della Gaming Control Board del Nevada, ma le tempistiche e la burocrazia mostrate differiscono sensibilmente dalla reale legislazione dell''epoca.', TRUE, '2026-09-14T13:49:14.008969', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(194, 46, '01:39:12', 'Troupe o microfoni visibili', 'Nella parte superiore dello schermo, durante la riunione segreta tra i boss mafiosi nel retrobottega, è visibile per un paio di secondi il microfono a giraffa (boom mic) che cala dall''alto.', TRUE, '2026-09-14T13:49:14.145845', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(195, 46, '01:52:30', 'Errori di scena / Posizione', 'Durante il litigio domestico tra Sam e Ginger, l''acconciatura della donna appare prima scompigliata, poi perfettamente ordinata e infine di nuovo spettinata nel giro di pochissimi secondi.', TRUE, '2026-09-14T13:49:14.209226', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(196, 46, '02:05:15', 'Anacronismi', 'Durante una ripresa panoramica della Strip di Las Vegas che dovrebbe svolgersi a metà anni ''70, sullo sfondo si nota l''insegna di un hotel con un logo moderno adottato dalla catena soltanto a metà degli anni ''90.', TRUE, '2026-09-14T13:49:14.312099', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(198, 46, '02:38:20', 'Errori di scena / Posizione', 'Durante il drammatico incontro nel deserto tra Nikki e i suoi scagnozzi, l''altezza delle ombre proiettate sui personaggi varia drasticamente tra un piano d''ascolto e l''altro, rivelando che le riprese si sono svolte in diverse ore della giornata.', TRUE, '2026-09-14T13:49:14.450997', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(199, 47, '00:08:15', 'Errori di scena / Posizione', 'Durante lo spettacolare inseguimento a piedi nel cantiere in Madagascar, la quantità di fango e macchie di polvere sulla camicia e sui pantaloni di Bond aumenta e diminuisce in modo incoerente da un''inquadratura all''altra.', TRUE, '2026-09-14T13:49:14.614325', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(3705, 2, '01:15:30', 'Anacronismi', 'I gladiatori utilizzano elmi e protezioni corporali che appartengono a periodi storici differenti e lontani tra loro di diversi secoli rispetto all''era di Marco Aurelio e Commodo.', TRUE, '2026-11-02T08:50:52.146222', 'Gladiator movie historical armor errors mistakes', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3706, 2, '01:44:20', 'Troupe o microfoni visibili', 'In una delle ampie inquadrature panoramiche del Colosseo affollato, per un breve fotogramma si intravede una moderna gru per cinepresa dietro le strutture superiori.', TRUE, '2026-11-02T08:50:52.146222', 'Gladiator crew camera crane visible Colosseum scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3707, 2, '02:18:10', 'Errori di scena / Posizione', 'Prima del duello finale, il pugnale nascosto che Commodo tiene nella tunica scompare e riappare tra un cambio di inquadratura e l''altro.', TRUE, '2026-11-02T08:50:52.146222', 'Gladiator final duel Commodus dagger continuity mistake', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3967, 195, '00:15:30', 'Errori di scena / Posizione', 'Durante l''inseguimento iniziale con il Nightrider, la strumentazione della macchina della polizia cambia visibilmente tra le inquadrature in primo piano e quelle larghe.', TRUE, '2026-11-02T10:19:07.655108', 'Mad Max 1979 opening chase dashboard error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3968, 195, '00:32:00', 'Errori di scena / Posizione', 'Quando la banda di Toecutter vandalizza la moto di Cundalini e saccheggia il negozio, la posizione delle bottiglie sul bancone varia da un''inquadratura all''altra senza che nessuno le tocchi.', TRUE, '2026-11-02T10:19:07.655108', 'Mad Max 1979 store scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4322, 359, '00:15:22', 'Anacronismi', 'Durante le scene ambientate nel 1799, in diverse inquadrature ravvicinate dei cavalli e delle carrozze si possono notare finiture e bardature metalliche realizzate con tecniche di fusione industriale decisamente troppo moderne per l''epoca.', TRUE, '2026-11-02T14:52:25.667207', 'Sleepy Hollow 1999 historical inaccuracies goofs', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4323, 359, '00:42:10', 'Errori di scena / Posizione', 'Nella scena in cui Ichabod Crane esamina il corpo nel fienile, la posizione della lanterna a olio cambia vistosamente tra un cambio di inquadratura e l''altro, passando da terra al tavolo di legno senza che nessuno la sposti.', TRUE, '2026-11-02T14:52:25.667207', 'Sleepy Hollow 1999 continuity error lantern', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(946, 194, '00:11:45', 'Incongruenza / Continuità', 'Durante il primo processo (il caso Gettys), la posizione delle mani di Kevin Lomax mentre tiene i fogli delle prove cambia repentinamente tra le inquadrature strette e quelle larghe, passando dall''essere tenuti con una sola mano a due mani sollevate.', TRUE, '2026-10-09T16:31:26.565729', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(947, 194, '00:42:10', 'Incongruenza / Continuità', 'Sulla terrazza dell''edificio di Milton, il forte vento spettina visibilmente i capelli di Kevin, mentre i capelli di Milton (Al Pacino) rimangono quasi immobili o si muovono in direzioni opposte a seconda dell''inquadratura, rivelando l''uso di barriere antivento posizionate solo per uno degli attori.', TRUE, '2026-10-09T16:31:26.565729', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(948, 194, '01:15:35', 'Incongruenza / Continuità', 'Quando Mary Ann (Charlize Theron) mostra a Kevin il suo nuovo taglio di capelli corto, la lunghezza e la simmetria delle ciocche cambiano visibilmente tra i primi piani e le inquadrature medie, segno che la parrucca o il taglio sono stati ritoccati tra i vari ciak.', TRUE, '2026-10-09T16:31:26.565729', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(949, 194, '01:38:22', 'Errore fattuale / Logistica', 'Nella scena della metropolitana di New York, il treno su cui sale Kevin mostra un numero di carrozza esterno che non corrisponde alla linea effettiva che sta percorrendo. Inoltre, gli interni cambiano modello di carrozza (da sedili arancioni a sedili blu/grigi) tra il momento dell''imbarco e il viaggio.', TRUE, '2026-10-09T16:31:26.565729', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(950, 194, '01:52:10', 'Attrezzatura visibile', 'Nelle pareti di marmo nero lucido e altamente riflettente dell''attico di Milton, mentre Kevin cammina lungo il corridoio principale, è possibile scorgere per un breve istante il riflesso di un operatore della troupe con una telecamera montata su steadicam.', TRUE, '2026-10-09T16:31:26.565729', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(951, 194, '02:08:40', 'Sincronizzazione audio/video', 'Durante il celebre monologo finale di John Milton nell''ufficio, in un paio di inquadrature di profilo il movimento delle sue labbra non coincide con le parole pronunciate nella traccia audio originale, indicando che è stata utilizzata una ripresa alternativa (alternate take) sovrapposta al montaggio sonoro definitivo.', TRUE, '2026-10-09T16:31:26.565729', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(952, 194, '02:14:15', 'Incongruenza / Oggetti', 'Durante lo scontro finale, quando l''ufficio inizia a subire mutamenti e fiamme, la disposizione dei fogli, dei libri e dei bicchieri sulla scrivania di Milton cambia drasticamente da un''inquadratura all''altra senza che nessuno li tocchi, svelando il reset della scena tra i diversi ciak degli effetti speciali.', TRUE, '2026-10-09T16:31:26.565729', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(728, 139, '00:18:15', 'Errori di scena / Posizione', 'Nelle scene in cui Prince (Joey King) manipola il giovane Kimura, tiene in mano un libro. La posizione delle sue dita tra le pagine e il punto esatto in cui il libro è aperto cambiano repentinamente tra un''inquadratura frontale e quella da sopra la spalla, rivelando che le riprese sono state effettuate in momenti diversi.', TRUE, '2026-09-26T15:22:11.065646', NULL, 0, 0, 'mrtrrt@libero.it', 'ia', NULL),
(729, 139, '00:22:10', 'Errori storici o fattuali', 'Nella scena in cui Ladybug sperimenta le funzioni del water tecnologico giapponese, il getto d''acqua continua a spruzzare verso l''alto con forza anche dopo che lui si è alzato. Nella realtà, i sanitari Washlet giapponesi sono dotati di sensori di pressione sul sedile che interrompono istantaneamente l''erogazione dell''acqua non appena l''utente si alza, per evitare allagamenti.', TRUE, '2026-09-26T15:22:11.065646', NULL, 0, 0, 'mrtrrt@libero.it', 'ia', NULL),
(200, 47, '00:22:40', 'Troupe o microfoni visibili', 'Nella sequenza dell''inseguimento all''aeroporto di Miami, nel riflesso dei vetri delle porte scorrevoli del terminal è chiaramente visibile il carrello della macchina da presa insieme al cameraman.', TRUE, '2026-09-14T13:49:14.710388', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(3708, 3, '00:12:00', 'Errori di scena / Posizione', 'Durante la festa di addio all''inizio del film, la bottiglia di birra che Rob sta bevendo cambia magicamente posizione e livello di liquido tra un''inquadratura e l''altra mentre parla con Beth nella cucina.', TRUE, '2026-11-02T08:51:01.103063', 'Cloverfield party scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3709, 3, '00:35:00', 'Errori di scena / Posizione', 'Mentre il gruppo attraversa le strade di Manhattan coperte di polvere e detriti, le scarpe e i vestiti dei protagonisti subiscono variazioni di pulizia e sporco notevoli tra un cambio di inquadratura e l''altro.', TRUE, '2026-11-02T08:51:01.103063', 'Cloverfield street scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3969, 197, '00:00:00', 'Troupe o microfoni visibili', 'Durante le scene nel deserto e all''interno della Thunderdome, in alcune inquadrature ampie si possono intravedere brevemente le ombre della troupe o dell''attrezzatura di ripresa sulla sabbia e sui veicoli.', TRUE, '2026-11-02T10:19:14.523901', 'Mad Max Beyond Thunderdome crew shadow visible', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3970, 197, '00:00:00', 'Errori di scena / Posizione', 'Durante il combattimento nella Thunderdome tra Max e Blaster, la posizione dell''elmo e dei finimenti di Blaster cambia leggermente tra un''inquadratura e l''altra prima che gli venga tolto.', TRUE, '2026-11-02T10:19:14.523901', 'Mad Max Beyond Thunderdome Blaster helmet continuity goof', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4324, 359, '01:12:45', 'Troupe o microfoni visibili', 'Durante la fuga nella foresta oscura, in un breve controcampo in cui il cavaliere senza testa insegue Ichabod, si intravede per un istante il riflesso di un riflettore della troupe su una delle lenti della macchina presa.', TRUE, '2026-11-02T14:52:25.667207', 'Sleepy Hollow movie crew equipment visible reflection', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4325, 359, '01:25:30', 'Errori di scena / Posizione', 'Nel climax finale sul ponte coperto, le ferite e le macchie di sangue sul cappotto di Johnny Depp variano di intensità e posizione da un''inquadratura all''altra durante le sequenze d''azione.', TRUE, '2026-11-02T14:52:25.667207', 'Sleepy Hollow 1999 Johnny Depp blood continuity goof', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4365, 204, '00:45:12', 'Errori di scena / Posizione', 'Quando Katniss visita l''ospedale nel Distretto 8, un ferito sulla barella cambia posizione della coperta e delle mani tra un''inquadratura e quella immediatamente successiva.', TRUE, '2026-11-02T14:53:35.6838', 'Hunger Games Mockingjay Part 1 District 8 hospital scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4366, 204, '01:12:30', 'Troupe o microfoni visibili', 'Durante una sequenza concitata nei tunnel del Distretto 13, per un breve fotogramma è possibile intravedere l''ombra di un microfono boom sulla parete di roccia.', TRUE, '2026-11-02T14:53:35.6838', 'Hunger Games Mockingjay Part 1 boom mic visible crew error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4367, 204, '00:22:15', 'Errori di scena / Posizione', 'Il bicchiere d''acqua tenuto da Plutarch Heavensbee durante una conversazione con la Presidente Coin appare pieno a metà e poi completamente pieno a seconda che l''inquadratura sia stretta o larga.', TRUE, '2026-11-02T14:53:35.6838', 'Hunger Games Mockingjay Part 1 Plutarch glass continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4512, 181, '00:25:12', 'Errori di scena / Posizione', 'Quando Thorin e la compagnia arrivano a casa di Bilbo (Bag End), i cappelli dei nani appesi all''ingresso cambiano disposizione e numero tra un''inquadratura grandangolare e i primi piani successivi.', TRUE, '2026-11-02T15:32:51.590097', 'The Hobbit 1977 dwarves at bag end animation error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(953, 199, '00:18:45', 'Continuità / Trucco e costumi', 'Durante la cattura della giovane Furiosa da parte degli scagnozzi di Dementus, le striature di fango e terra sul volto della bambina cambiano forma e densità tra i primi piani e le inquadrature a mezzo busto.', TRUE, '2026-10-09T18:21:32.14648', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(954, 199, '00:42:10', 'Continuità / Oggetti di scena', 'L''orsacchiotto di pezza legato all''armatura di Dementus durante i negoziati alla Cittadella cambia orientamento: in un''inquadratura pende verso il lato sinistro con le zampe piegate, mentre al controcampo successivo è perfettamente dritto e le cinghie di fissaggio sono allacciate diversamente.', TRUE, '2026-10-09T18:21:32.14648', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(955, 199, '01:12:35', 'Continuità / Danni ai veicoli', 'Nel corso dell''attacco aereo dei Mortiflyer guidati dall''Octoboss contro la War Rig, uno dei lati della cisterna viene squarciato e perforato da arpioni; nelle inquadrature dal basso subito seguenti, lo stesso pannello metallico appare liscio e privo di fori.', TRUE, '2026-10-09T18:21:32.14648', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(956, 199, '01:29:50', 'Continuità / Armi e oggetti', 'Durante lo scontro a Bullet Farm con Praetorian Jack e Furiosa, il conteggio dei colpi sparati dal fucile non corrisponde al numero di bossoli espulsi: in un cambio di angolazione, una camera di scoppio precedentemente vuota riappare carica senza che il personaggio abbia effettuato il ricaricamento.', TRUE, '2026-10-09T18:21:32.14648', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(957, 199, '01:54:12', 'Continuità / Trucco e protesi', 'Nel momento in cui Furiosa fugge dopo aver perso l''avambraccio, la fasciatura emostatica e l''estensione del moncherino mostrano discrepanze anatomiche evidenti tra il campo lungo in cui si trascina nella sabbia e il primo piano successivo.', TRUE, '2026-10-09T18:21:32.14648', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(958, 199, '02:08:40', 'Continuità / Costumi', 'Durante l''inseguimento finale nella desolazione, il mantello di Dementus passa dall''essere pesantemente strappato, sporco e ingrigito dalla polvere a una tonalità notevolmente più pulita e accesa nelle inquadrature ravvicinate subito dopo lo schianto della sua vettura.', TRUE, '2026-10-09T18:21:32.14648', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(959, 199, '02:18:25', 'Errori di scena / Posizione', 'Nel faccia a faccia culminante tra Furiosa e Dementus, la pistola lasciata cadere nella sabbia si sposta di oltre un metro rispetto ai piedi di Dementus tra l''inquadratura dall''alto e il controcampo a livello del suolo, senza che nessuno dei due l''abbia calciata.', TRUE, '2026-10-09T18:21:32.14648', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(13, 2, '02:24:10', 'Continuity', 'Durante il duello finale tra Massimo e Commodo nel Colosseo, la posizione delle ferite da taglio e la quantità di sangue sulle spalle e sulla corazza di Massimo cambiano visibilmente tra le varie inquadrature.', TRUE, '2026-09-13T14:42:52.620774', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(1021, 231, '00:28:10', 'Troupe o microfoni visibili', 'Durante la scena in cui i tre ladri osservano la casa dall''interno del furgone, nel riflesso del vetro del finestrino laterale è chiaramente visibile la sagoma di un operatore della troupe con la videocamera.', TRUE, '2026-10-24T15:36:29.469711', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(201, 47, '00:37:10', 'Errori storici o fattuali', 'Il treno ad alta velocità su cui viaggiano Bond e Vesper mostra la livrea e il logo delle ferrovie nazionali ceche (ČD), poiché la scena è stata girata nella Repubblica Ceca; tuttavia in Montenegro non esiste alcuna linea ferroviaria ad alta velocità di quel tipo.', TRUE, '2026-09-14T13:49:14.742954', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(202, 47, '00:51:25', 'Errori di scena / Posizione', 'Al tavolo da poker del Casino Royale, la disposizione e la quantità di fiches impilate davanti a Le Chiffre cambiano nettamente tra i primi piani del personaggio e le inquadrature a figura intera.', TRUE, '2026-09-14T13:49:14.834055', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(203, 47, '01:05:00', 'Errori storici o fattuali', 'Durante la mano finale di Texas Hold''em, la gestione dell''ordine delle puntate e la risposta del croupier al momento dell''all-in violano diverse regole ufficiali dei tornei internazionali di poker professionistico.', TRUE, '2026-09-14T13:49:14.924411', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(204, 47, '01:18:30', 'Errori di scena / Posizione', 'Quando Bond viene avvelenato e corre verso la sua Aston Martin per somministrarsi l''antidoto, le macchie di sudore sul suo vestito appaiono vistosamente estese, poi quasi del tutto scomparse quando entra nell''abitacolo.', TRUE, '2026-09-14T13:49:15.019238', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(205, 47, '01:32:15', 'Anacronismi', 'Lo smartphone utilizzato da James Bond mostra un software con funzionalità di tracciamento satellitare e grafica ad alta risoluzione non ancora disponibili sul mercato all''epoca dell''uscita del film nel 2006.', TRUE, '2026-09-14T13:49:15.121363', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(206, 47, '01:45:50', 'Troupe o microfoni visibili', 'Nel momento in cui l''Aston Martin DBS si ribalta a gran velocità, si può chiaramente scorgere sotto la scocca dell''auto il cannone pneumatico a pistone adibito a far cappottare il veicolo per lo stunt.', TRUE, '2026-09-14T13:49:15.157981', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(3711, 4, '00:00:00', 'Errori di scena / Posizione', 'Quando Ace Ventura entra in ascensore con il cane nel pacco postale all''inizio del film, il guinzaglio del cane scompare e riappare tra un''inquadratura e l''altra.', TRUE, '2026-11-02T09:28:37.833601', 'Ace Ventura Pet Detective elevator scene dog leash goof', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3712, 4, '00:00:00', 'Errori di scena / Posizione', 'Durante la scena in cui Ace guida la sua auto con la testa fuori dal finestrino, la posizione delle mani sul volante e la direzione del traffico sullo sfondo cambiano visibilmente tra le inquadrature interne ed esterne.', TRUE, '2026-11-02T09:28:37.833601', 'Ace Ventura driving scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3713, 4, '00:00:00', 'Errori di scena / Posizione', 'Nell''ufficio di Melissa Robinson, quando Ace rovescia accidentalmente degli oggetti sulla scrivania, la disposizione di carta e cancelleria varia nei successivi cambi di inquadratura.', TRUE, '2026-11-02T09:28:37.833601', 'Ace Ventura office desk continuity goof', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3714, 4, '00:00:00', 'Errori di scena / Posizione', 'Durante il colloquio nel manicomio di Shady Acres, il distintivo che Ace mostra alla guardia cambia posizione nella tasca della giacca tra un primo piano e un campo medio.', TRUE, '2026-11-02T09:28:37.833601', 'Ace Ventura Shady Acres badge goof', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3715, 4, '00:00:00', 'Errori di scena / Posizione', 'Quando Ace entra nella stanza dei trofei a casa di Ronald Camp, la giacca che indossa appare inzuppata d''acqua in un''inquadratura e quasi asciutta in quella successiva.', TRUE, '2026-11-02T09:28:37.833601', 'Ace Ventura Ronald Camp party wet jacket goof', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3971, 224, '00:00:00', 'Anacronismi', 'Durante i titoli di testa e in alcune scene, si possono notare elementi scenografici o armature che presentano dettagli stilistici non accurati per il periodo storico della Terza Guerra Servita nel I secolo a.C., riflettendo invece la moda cinematografica peplum degli anni ''60.', TRUE, '2026-11-02T10:19:26.321338', 'Spartacus 1960 opening credits historical inaccuracy', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4326, 360, '00:03:15', 'Errori di scena / Posizione', 'Durante la scena iniziale in casa di Malcolm Crowe, i documenti sulla scrivania cambiano posizione e orientamento tra un''inquadratura e l''altra mentre lui e la moglie parlano prima dell''intrusione di Vincent.', TRUE, '2026-11-02T14:52:30.462398', 'The Sixth Sense opening scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(960, 200, '00:35:15', 'Incongruenza / Continuità', 'Le chiazze di sudore sulla camicia blu di Sonny (Al Pacino) cambiano continuamente di forma e dimensione tra un''inquadratura e l''altra durante le trattative all''esterno della banca, scomparendo quasi del tutto in alcune scene per poi riapparire più estese subito dopo.', TRUE, '2026-10-09T21:20:04.937473', NULL, 0, 0, 'mrrtgrg11@gmail.com', 'ia', NULL),
(961, 200, '00:42:10', 'Incongruenza / Trucco e Parrucco', 'I capelli di Sonny appaiono completamente bagnati di sudore e scompigliati in un''inquadratura ravvicinata, ma nel controcampo immediatamente successivo sono visibilmente più asciutti e ordinati.', TRUE, '2026-10-09T21:20:04.937473', NULL, 0, 0, 'mrrtgrg11@gmail.com', 'ia', NULL),
(962, 200, '00:48:15', 'Apparecchiature visibili', 'Durante la celebre scena in cui Sonny arringa la folla gridando ''Attica! Attica!'', nel riflesso dei vetri della banca e di un''auto parcheggiata è possibile scorgere per un breve istante la sagoma di un operatore con la cinepresa e un pannello riflettente per le luci.', TRUE, '2026-10-09T21:20:04.937473', NULL, 0, 0, 'mrrtgrg11@gmail.com', 'ia', NULL),
(963, 200, '00:55:30', 'Errore di continuità / Oggetti', 'L''orologio da parete all''interno della banca mostra orari incoerenti rispetto allo scorrere reale del tempo della narrazione. In alcune sequenze l''orario salta avanti e indietro di oltre dieci minuti tra inquadrature consecutive dello stesso dialogo.', TRUE, '2026-10-09T21:20:04.937473', NULL, 0, 0, 'mrrtgrg11@gmail.com', 'ia', NULL),
(964, 200, '01:12:05', 'Incongruenza / Oggetti di scena', 'Alcune auto della polizia di New York posizionate fuori dalla banca cambiano misteriosamente il numero identificativo sulla carrozzeria o presentano diversi modelli di lampeggianti sul tetto tra le riprese dall''alto e quelle a livello della strada.', TRUE, '2026-10-09T21:20:04.937473', NULL, 0, 0, 'mrrtgrg11@gmail.com', 'ia', NULL),
(965, 200, '01:22:40', 'Errore di scena / Posizione', 'Nella scena in cui vengono consegnate le pizze per gli ostaggi, il modo in cui Sonny afferra e tiene i cartoni cambia istantaneamente tra i tagli di montaggio: prima li sostiene con entrambe le mani dal basso, poi improvvisamente ne tiene uno sotto il braccio sinistro.', TRUE, '2026-10-09T21:20:04.937473', NULL, 0, 0, 'mrrtgrg11@gmail.com', 'ia', NULL),
(966, 200, '01:35:10', 'Errore di scena / Posizione', 'Sal (John Cazale) tiene il suo fucile puntato in direzioni diverse tra i primi piani e i campi medi. In un''inquadratura l''arma è appoggiata sulla sua gamba, ma nel taglio successivo è immediatamente puntata verso gli ostaggi, senza che lui abbia compiuto il movimento.', TRUE, '2026-10-09T21:20:04.937473', NULL, 0, 0, 'mrrtgrg11@gmail.com', 'ia', NULL),
(730, 139, '00:31:15', 'Errori di scena / Posizione', 'Durante lo scontro letale tra Ladybug (Brad Pitt) e il Lupo (Bad Bunny), il coltello di quest''ultimo si conficca profondamente nella valigetta metallica. Nei cambi di inquadratura successivi, l''inclinazione del coltello e la profondità della lama penetrata nella valigetta variano visibilmente tra i piani ravvicinati e i campi medi.', TRUE, '2026-09-26T15:22:11.065646', NULL, 0, 0, 'mrtrrt@libero.it', 'ia', NULL),
(207, 47, '01:58:10', 'Errori di scena / Posizione', 'Durante la convulsa sequenza nel palazzo affondante a Venezia, il nodo della cravatta di Bond cambia forma e grado di allentamento mentre tenta di salvare Vesper intrappolata nell''ascensore.', TRUE, '2026-09-14T13:49:15.228363', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(208, 47, '02:10:45', 'Errori di scena / Posizione', 'I tagli e le macchie di sangue sul viso di James Bond nella scena finale sulla spiaggia variano di posizione, forma ed intensità tra una ripresa ravvicinata e l''altra.', TRUE, '2026-09-14T13:49:15.263887', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(209, 47, '02:22:30', 'Errori storici o fattuali', 'La velocità di affondamento dell''intero palazzo veneziano dovuta alla rottura dei palloni di galleggiamento è idrodinamicamente e strutturalmente impossibile per un edificio storico in pietra e muratura.', TRUE, '2026-09-14T13:49:15.334908', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(210, 48, '00:18:22', 'Errori di scena / Posizione', 'Durante la camminata iniziale di Futaki nel fango, le macchie di fango sui suoi pantaloni e sugli stivali cambiano visibilmente disposizione e densità tra il campo lungo e il campo medio successivo.', TRUE, '2026-09-14T13:49:44.414725', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(211, 48, '00:45:10', 'Troupe o microfoni visibili', 'Durante la lunga carrellata che segue il dottore all''esterno, nell''angolo superiore destro dell''inquadratura è brevemente visibile l''estremità dell''asta del microfono d''ambiente mentre si abbassa per pochi secondi.', TRUE, '2026-09-14T13:49:44.510998', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(3716, 6, '01:22:00', 'Errori di scena / Posizione', 'Nella scena in cui Michael Corleone spara a Sollozzo e McCluskey nel ristorante, il piatto di vitello davanti a Michael scompare e riappare tra un''inquadratura e l''altra.', TRUE, '2026-11-02T09:29:41.678344', 'The Godfather restaurant scene mistake plate', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3717, 6, '00:30:00', 'Errori di scena / Posizione', 'Quando Jack Woltz si sveglia nel suo letto con la testa del cavallo recisa, le lenzuola cambiano posizione e colore delle macchie di sangue in modo evidente tra il primo piano e il campo medio.', TRUE, '2026-11-02T09:29:41.678344', 'The Godfather horse head scene goof', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3718, 6, '01:05:00', 'Errori di scena / Posizione', 'Durante la riunione delle Famiglie mafiose, il bicchiere di carta e i documenti sul tavolo di Barzini cambiano disposizione da un''inquadratura all''altra.', TRUE, '2026-11-02T09:29:41.678344', 'The Godfather meeting of the five families mistake', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3972, 236, '01:29:00', 'Errori di scena / Posizione', 'Nella sequenza all''aeroporto di Baltimora, quando Cole viene colpito e cade a terra morente, la posizione del suo corpo e delle braccia cambia in modo evidente tra l''inquadratura larga e i primi piani successivi.', TRUE, '2026-11-02T10:20:04.201279', '12 Monkeys airport scene ending death', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4327, 360, '00:22:40', 'Errori di scena / Posizione', 'Nella scena in cui Cole è in cucina con la madre, la posizione dei biscotti e del cartone del latte sul tavolo varia visibilmente tra i cambi di inquadratura frontale e di profilo.', TRUE, '2026-11-02T14:52:30.462398', 'The Sixth Sense Toni Collette kitchen scene goof', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4328, 360, '00:45:10', 'Errori di scena / Posizione', 'Durante la festa di compleanno in cui Cole viene chiuso nella tenda, gli oggetti sparsi sul pavimento vicino all''ingresso cambiano disposizione da un taglio di montaggio all''altro.', TRUE, '2026-11-02T14:52:30.462398', 'The Sixth Sense birthday party tent scene error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4329, 360, '01:12:00', 'Errori di scena / Posizione', 'Nella sequenza in cui Cole e Malcolm parlano sulle panchine vicino alla chiesa, il colletto della giacca di Malcolm risulta sollevato in un''inquadratura e perfettamente sistemato in quella successiva senza che ci sia stato tempo per aggiustarlo.', TRUE, '2026-11-02T14:52:30.462398', 'The Sixth Sense bench scene continuity Bruce Willis', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL);
INSERT INTO public.errori ("id", "film_id", "minuto", "categoria", "descrizione", "approvato", "creato_il", "youtube_query", "conferme", "contestazioni", "inserito_da", "provenienza", "screenshot_url") VALUES
(4476, 292, '00:15:20', 'Anacronismi', 'Durante una scena in cui Jojo corre per le strade della città, si intravede sullo sfondo un dettaglio architettonico o un elemento di arredo urbano moderno o posteriore all''epoca della Seconda Guerra Mondiale.', TRUE, '2026-11-02T14:56:28.521258', 'Jojo Rabbit historical inaccuracy background', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(967, 202, '00:16:45', 'Continuità / Acconciatura', 'Durante la scena della Mietitura nel Distretto 12, quando Katniss si offre volontaria al posto della sorella Prim, la sua treccia cambia posizione più volte tra la spalla sinistra, la spalla destra e la schiena a seconda dell''inquadratura.', TRUE, '2026-10-11T16:28:20.885381', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(968, 202, '00:43:10', 'Continuità / Posizione', 'Durante la sfilata dei Tributi sulle bighe a Capitol City, la mano di Peeta attorno alla vita di Katniss cambia posizione tra i campi lunghi e i primi piani, passando dal fianco alla schiena.', TRUE, '2026-10-11T16:28:20.885381', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(969, 202, '00:49:25', 'Errori di scena / Oggetti', 'Quando Katniss scaglia la freccia contro la mela nella bocca del maiale davanti ai Favoriti, il punto d''impatto e l''inclinazione della freccia nella mela cambiano tra il momento dell''impatto e la vista d''insieme.', TRUE, '2026-10-11T16:28:20.885381', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(970, 202, '01:18:15', 'Continuità / Trucco', 'Dopo che Katniss viene punta dalle Aghi Killer (Tracker Jackers), le pustole e il gonfiore da veleno sul suo collo e sul viso cambiano dimensione e disposizione tra un''inquadratura e l''altra.', TRUE, '2026-10-11T16:28:20.885381', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(971, 202, '01:26:40', 'Continuità / Oggetti di scena', 'Nella scena della morte di Rue, Katniss circonda il corpo della bambina con dei fiori. La quantità, la tipologia e la disposizione esatta dei fiori cambiano tra il primo piano e la visuale dall''alto.', TRUE, '2026-10-11T16:28:20.885381', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(972, 202, '01:33:50', 'Continuità / Trucco', 'Quando Katniss ritrova Peeta mimetizzato sulle rive del fiume, il fango e la pittura mimetica sulla guancia e sulla fronte di Peeta cambiano forma e densità prima ancora che Katniss glieli pulisca.', TRUE, '2026-10-11T16:28:20.885381', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(973, 202, '02:08:10', 'Continuità / Oggetti di scena', 'Nel momento culminante in cui Katniss e Peeta minacciano di ingerire le bacche velenose (Morsoserrato), la quantità e la disposizione delle bacche nel palmo della mano di Katniss variano tra il campo stretto e il controcampo.', TRUE, '2026-10-11T16:28:20.885381', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(212, 48, '01:12:05', 'Errori di scena / Posizione', 'Nella scena in cui il dottore prende appunti al tavolo, il livello del liquido nella bottiglia di pálinka sale di un paio di centimetri tra due inquadrature contigue, senza che nessuno ne abbia versata altra.', TRUE, '2026-09-14T13:49:44.610825', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(213, 48, '01:58:40', 'Anacronismi', 'Sullo sfondo della desolata campagna durante il cammino della piccola Estike, si intravede un traliccio dell''alta tensione moderno con cavi e componenti non compatibili con il periodo di ambientazione rurale della fine dell''era comunista.', TRUE, '2026-09-14T13:49:44.645639', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(214, 48, '02:30:15', 'Errori di scena / Posizione', 'Durante la tragica sequenza della bambina con il gatto, la posizione delle zampe del felino rispetto alla ciotola sul pavimento varia in modo incoerente nel passaggio tra l''inquadratura dall''alto e quella ad altezza occhi.', TRUE, '2026-09-14T13:49:44.721355', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(215, 48, '03:15:00', 'Troupe o microfoni visibili', 'Durante la scorta del camion sotto la pioggia battente, sulla superficie bagnata del finestrino laterale si riflettono nitidamente la sagoma della macchina da presa su carrello e le luci di schiarita della troupe.', TRUE, '2026-09-14T13:49:44.755576', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(3719, 7, '01:22:00', 'Errori di scena / Posizione', 'Durante la drammatica scena in cui Michael Corleone affronta Fredo a L''Avana durante i festeggiamenti di Capodanno, la posizione delle mani e la tazza che Fredo tiene cambiano visivamente tra un''inquadratura e l''altra senza che ci sia il tempo fisico per compiere il movimento.', TRUE, '2026-11-02T09:31:04.937964', 'The Godfather Part II Fredo Cuba new years eve scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(217, 48, '04:20:30', 'Errori storici o fattuali', 'Su un foglio di registro mostrato dall''ufficiale governativo è visibile un timbro burocratico della Repubblica d''Ungheria introdotto ufficialmente soltanto dopo il 1992, incoerente con l''epoca di svolgimento del racconto.', TRUE, '2026-09-14T13:49:44.925678', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(218, 48, '04:55:18', 'Errori di scena / Posizione', 'Mentre Irimiás arringa la folla all''aperto, l''intensità della pioggia passa repentinamente da un rovescio battente a una debole pioggerellina nel giro di un singolo stacco di montaggio.', TRUE, '2026-09-14T13:49:45.022081', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(219, 48, '05:30:45', 'Troupe o microfoni visibili', 'In un lungo piano sequenza a seguire sulle spalle di Petrina mentre cammina controvento nel campo, l''ombra del cameraman e della rig di supporto si proietta chiaramente sulla parte inferiore del suo cappotto.', TRUE, '2026-09-14T13:49:45.065195', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(220, 48, '06:10:12', 'Errori di scena / Posizione', 'Quando i contadini preparano i propri bagagli per la partenza, le cinghie in cuoio di una valigia risultano affibbiate nell''inquadratura generale ma completamente slacciate nel dettaglio successivo.', TRUE, '2026-09-14T13:49:45.12985', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(221, 48, '06:45:00', 'Anacronismi', 'Lungo il ciglio della strada sterrata si nota a terra un tappo di plastica a vite per bottiglie PET di tipo moderno, oggetto del tutto irreperibile nelle campagne ungheresi dell''epoca raffigurata.', TRUE, '2026-09-14T13:49:45.225467', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(3720, 7, '02:40:00', 'Errori di scena / Posizione', 'Nella sequenza del colloquio al Senato, il bicchiere d''acqua davanti a uno dei senatori cambia livello di riempimento e posizione sul tavolo tra le inquadrature in campo largo e i primi piani.', TRUE, '2026-11-02T09:31:04.937964', 'The Godfather Part II Senate hearing scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3973, 238, '01:21:00', 'Errori di scena / Posizione', 'Durante la visita medica iniziale a Regan, la posizione della crocetta sul collo della bambina e dei vari strumenti medici sul vassoio cambiano ripetutamente tra un''inquadratura e l''altra senza che nessuno li abbia toccati.', TRUE, '2026-11-02T10:20:12.190902', 'The Exorcist medical examination scene goofs', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3974, 238, '00:45:00', 'Errori di scena / Posizione', 'Nella scena in cui Chris MacNeil riceve una telefonata nella sua camera da letto, la posizione del ricevitore del telefono e dei fogli sulla scrivania varia visibilmente tra i campi e i controcampi.', TRUE, '2026-11-02T10:20:12.190902', 'The Exorcist phone call scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3975, 238, '01:50:00', 'Errori di scena / Posizione', 'Nella sequenza finale nella stanza da letto, la disposizione dei libri, delle candele e degli oggetti sacri sul comodino si modifica in modo incongruente tra un cambio di inquadratura e l''altro.', TRUE, '2026-11-02T10:20:12.190902', 'The Exorcist bedroom climax continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4335, 304, '00:15:20', 'Anacronismi', 'Durante le scene ambientate negli anni ''20, la musica suonata o menzionata a volte include brani o registrazioni che appartengono a un periodo successivo o presentano arrangiamenti anacronistici rispetto all''epoca esatta in cui si svolge la sequenza notturna.', TRUE, '2026-11-02T14:52:47.783338', 'Midnight in Paris music anachronism years', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4513, 181, '00:54:30', 'Errori di scena / Posizione', 'Durante la fuga dalle caverne dei goblin, la spada di Gandalf, Glamdring, mostra variazioni nella lunghezza della lama e nella forma dell''elsa rispetto alle scene precedenti.', TRUE, '2026-11-02T15:32:51.590097', 'The Hobbit 1977 Gandalf sword continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3721, 8, '01:25:00', 'Errori di scena / Posizione', 'Durante la riunione degli azionisti della Immobiliare in Vaticano, i bicchieri e i documenti sui tavoli cambiano disposizione e livello di riempimento tra un''inquadratura e l''altra.', TRUE, '2026-11-02T09:31:51.85655', 'Godfather Part III Vatican meeting scene mistake', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3722, 8, '02:30:00', 'Errori di scena / Posizione', 'Nella sequenza finale al Teatro Massimo, il bicchiere di cannoli e aranciata consumato da Connie Corleone cambia mano e livello di liquido tra i campi lunghi e i primi piani.', TRUE, '2026-11-02T09:31:51.85655', 'Godfather 3 Teatro Massimo ending scene errors', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
