(4007, 281, '00:28:00', 'Errori di scena / Posizione', 'Mentre Marty viene impiccato dalla banda di Buford Tannen, le sue mani sono inizialmente legate dietro la schiena. Tuttavia, in un''inquadratura ravvicinata, Marty viene visto afferrare la corda intorno al collo con le mani davanti a sé per cercare di respirare.', TRUE, '2026-11-02T10:25:45.218496', 'Back to the Future 3 Marty hanging scene goof', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4008, 281, '01:40:00', 'Troupe o microfoni visibili', 'Durante la sequenza del salvataggio di Clara sul treno in corsa, quando Doc utilizza l''hoverboard per raggiungerla, sono chiaramente visibili i cavi di sicurezza che sostengono Christopher Lloyd e Mary Steenburgen.', TRUE, '2026-11-02T10:25:45.218496', 'Back to the Future 3 hoverboard wires visible', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4009, 281, '00:09:00', 'Errori di scena / Posizione', 'La lettera che Doc scrive dal 1885 presenta differenze nella grafia e nella disposizione del testo tra il momento in cui Marty la legge nel 1955 e le inquadrature ravvicinate mostrate in precedenza o successivamente.', TRUE, '2026-11-02T10:25:45.218496', 'Back to the Future 3 Doc''s letter consistency', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4010, 281, '01:42:00', 'Errori di scena / Posizione', 'Durante la spinta finale del treno, il tachimetro della DeLorean mostra una velocità prossima alle 80 miglia orarie, ma le riprese esterne del treno mostrano chiaramente che la locomotiva si muove a una velocità molto più ridotta, probabilmente non superiore ai 30-40 mph.', TRUE, '2026-11-02T10:25:45.218496', 'Back to the Future 3 train speed discrepancy', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4011, 281, '00:18:00', 'Errori di scena / Posizione', 'Nella scena al drive-in del 1955, mentre Marty si prepara per il viaggio nel tempo, la lunghezza e la direzione delle ombre cambiano drasticamente tra le inquadrature, rivelando che la scena è stata girata nell''arco di diverse ore nonostante nel film duri pochi minuti.', TRUE, '2026-11-02T10:25:45.218496', 'Back to the Future 3 drive-in shadows goof', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4012, 281, '01:47:00', 'Troupe o microfoni visibili', 'Nell''istante esatto in cui il treno moderno travolge la DeLorean sui binari nel 1985, è possibile scorgere una cinepresa protetta da una copertura sul lato sinistro dell''inquadratura, posizionata per filmare l''impatto da un''altra angolazione.', TRUE, '2026-11-02T10:25:45.218496', 'Back to the Future 3 train hits delorean camera visible', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4013, 281, '01:38:00', 'Errori di scena / Posizione', 'Durante la sequenza sul treno, la bandana che Doc porta al collo cambia continuamente posizione: in alcune inquadrature è legata stretta, in altre è sciolta e in altre ancora scompare del tutto per poi riapparire.', TRUE, '2026-11-02T10:25:45.218496', 'Back to the Future 3 Doc bandana continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4014, 281, '01:52:00', 'Errori di scena / Posizione', 'Quando il treno del tempo decolla alla fine del film, le iconiche scie di fuoco appaiono sospese nell''aria prima ancora che le ruote del treno passino effettivamente in quel punto specifico della traiettoria.', TRUE, '2026-11-02T10:25:45.218496', 'Back to the Future 3 flying train fire trails', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL);
INSERT INTO public.errori ("id", "film_id", "minuto", "categoria", "descrizione", "approvato", "creato_il", "youtube_query", "conferme", "contestazioni", "inserito_da", "provenienza", "screenshot_url") VALUES
(4015, 281, '01:35:00', 'Errori storici o fattuali', 'In diverse inquadrature della linea ferroviaria nel 1885, specialmente durante l''inseguimento del treno, sono visibili sotto i binari di scena le rotaie moderne in acciaio pesante e le traversine in cemento della linea ferroviaria reale su cui stavano girando.', TRUE, '2026-11-02T10:25:45.218496', 'Back to the Future 3 modern train tracks visible', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4383, 280, '01:14:50', 'Anacronismi', 'Nel 1955, durante il ballo ''Enchantment Under the Sea'', la musica eseguita dalla band sul palco e gli strumenti utilizzati presentano alcuni dettagli di amplificazione e modelli di chitarre leggermente posticipati rispetto all''effettivo anno 1955.', TRUE, '2026-11-02T14:53:46.907492', 'Back to the Future Part II 1955 dance band instruments anachronism', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4399, 285, '00:00:00', 'Anacronismi', 'Durante la scena in cui Johnny Hooker cammina per le strade di Chicago, si vede sullo sfondo un parchimetro moderno che non era ancora stato inventato o installato nel periodo in cui è ambientato il film (1936).', TRUE, '2026-11-02T14:54:18.178611', 'The Sting 1973 goofs parking meter', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4400, 285, '00:00:00', 'Errori di scena / Posizione', 'Nella sequenza della partita a poker nel treno privato di Lonnegan, il bicchiere davanti a un giocatore minore cambia ripetutamente livello di riempimento tra un''inquadratura e l''altra.', TRUE, '2026-11-02T14:54:18.178611', 'The Sting train poker scene goofs', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4401, 285, '00:00:00', 'Troupe o microfoni visibili', 'In alcune riprese grandangolari delle strade di Chicago, si possono intravvedere brevemente le ombre di alcuni membri della troupe cinematografica sull''asfalto o sui muri degli edifici.', TRUE, '2026-11-02T14:54:18.178611', 'The Sting crew shadow visible', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4402, 285, '00:00:00', 'Anacronismi', 'I rotoli di carta igienica visibili nei bagni di servizio durante alcune scene secondarie presentano goffrature e confezioni tipiche della produzione industriale degli anni ''60/''70 anziché del 1936.', TRUE, '2026-11-02T14:54:18.178611', 'The Sting 1973 anachronism prop', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4471, 266, '00:15:40', 'Errori di scena / Posizione', 'Durante la chiamata sulla piattaforma Zoom all''inizio del film, la posizione della tazza e degli oggetti sulla scrivania di Benoit Blanc cambia leggermente tra un cambio di inquadratura e l''altro.', TRUE, '2026-11-02T14:56:23.309658', 'Glass Onion Knives Out Zoom call scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4472, 266, '00:28:15', 'Errori di scena / Posizione', 'Quando il gruppo arriva al molo per prendere la barca per l''isola privata, le borse e i bagagli dei personaggi cambiano disposizione e posizione esatta tra i primi piani e i campi larghi.', TRUE, '2026-11-02T14:56:23.309658', 'Glass Onion dock scene luggage continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4473, 266, '00:45:20', 'Anacronismi', 'Il film è ambientato nel maggio del 2020 (durante la pandemia di COVID-19), ma diversi dispositivi tecnologici e oggetti di scena mostrati nel corso della pellicola presentano interfacce o modelli usciti sul mercato in anni successivi.', TRUE, '2026-11-02T14:56:23.309658', 'Glass Onion 2020 timeline tech anachronism', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5522, 276, '00:12:45', 'Errori di scena / Posizione', 'Durante la riunione in presidenza, i fascicoli sulla scrivania cambiano disposizione e inclinazione tra un''inquadratura in campo medio e il primo piano ravvicinato del Preside.', TRUE, '2026-11-02T17:20:34.537184', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(67, 28, '00:37:45', 'Fattuale / Storico', 'Vengono citati decreti ed editti storici attribuiti a Caracalla che in realtà vennero promulgati diversi decenni più tardi.', TRUE, '2026-09-13T15:01:46.792075', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(3752, 35, '02:30:00', 'Errori di scena / Posizione', 'Durante la scena in cui Aragorn si fa avanti ai Cancelli Neri per distrarre Sauron, i suoi capelli cambiano visibilmente lunghezza e posizione tra un''inquadratura e l''altra a causa delle riprese aggiuntive effettuate anni dopo rispetto alla produzione principale.', TRUE, '2026-11-02T09:48:56.990854', 'The Lord of the Rings Return of the King Aragorn Black Gate hair continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3753, 35, '00:45:00', 'Errori di scena / Posizione', 'Quando Pipino ruba il Palantír da sotto il mantello di Gandalf addormentato, la posizione del bastone del mago e la sua distanza dal corpo variano sensibilmente nelle diverse inquadrature dei dettagli.', TRUE, '2026-11-02T09:48:56.990854', 'The Lord of the Rings Return of the King Pippin takes Palantir continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4016, 282, '01:53:00', 'Anacronismi', 'Il poster di Raquel Welch nel film ''Un milione di anni fa'' è visibile sulla parete della cella di Andy nel 1966. Tuttavia, il film è uscito nelle sale solo alla fine del 1966 nel Regno Unito e nel 1967 negli Stati Uniti, rendendo quasi impossibile che Andy ne possedesse già una versione commerciale di quelle dimensioni.', TRUE, '2026-11-02T10:26:58.438424', 'Shawshank Redemption Raquel Welch poster goof', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4017, 282, '01:56:00', 'Errori di scena / Posizione', 'Quando il direttore Norton lancia un sasso contro il poster di Raquel Welch per scoprire il tunnel, il buco che si crea inizialmente è piccolo e dai bordi frastagliati. Nell''inquadratura successiva, quando il direttore si avvicina e infila la mano, il buco è diventato molto più grande, perfettamente circolare e con i bordi netti.', TRUE, '2026-11-02T10:26:58.438424', 'Shawshank Redemption rock through poster scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4018, 282, '01:04:00', 'Anacronismi', 'La registrazione de ''Le nozze di Figaro'' (Sull''aria) che Andy trasmette tramite gli altoparlanti della prigione è quella diretta da Karl Böhm con la Deutsche Oper Berlin. Questa specifica incisione è stata realizzata nel 1968, ma la scena è ambientata a metà degli anni ''50.', TRUE, '2026-11-02T10:26:58.438424', 'Shawshank Redemption Mozart scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4019, 282, '00:36:00', 'Anacronismi', 'Le lattine di birra ''Black Label'' che i detenuti bevono sul tetto nel 1949 presentano un design del logo e della linguetta che è stato introdotto dalla Carling solo negli anni ''60.', TRUE, '2026-11-02T10:26:58.438424', 'Shawshank Redemption roof beer scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4020, 282, '02:03:00', 'Errori di scena / Posizione', 'Quando il direttore apre la Bibbia di Andy e trova l''incavo per il martelletto, lo scavo inizia dal libro dell''Esodo. Tuttavia, confrontando le dimensioni del martelletto mostrate all''inizio del film, l''oggetto è troppo lungo per essere contenuto interamente all''interno delle pagine tagliate mostrate nell''inquadratura finale.', TRUE, '2026-11-02T10:26:58.438424', 'Shawshank Redemption rock hammer bible', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4021, 282, '00:18:00', 'Errori di scena / Posizione', 'La foto segnaletica di Red da giovane nel suo fascicolo per la libertà vigilata è in realtà una foto di Alfonso Freeman, il figlio di Morgan Freeman. Sebbene sia un tocco realistico, la qualità della carta fotografica e lo stile del ritratto sono chiaramente moderni e non coerenti con una foto segnaletica degli anni ''20 o ''30.', TRUE, '2026-11-02T10:26:58.438424', 'Shawshank Redemption Red young photo', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4022, 282, '01:15:00', 'Anacronismi', 'Le manette utilizzate dalle guardie per scortare Andy in isolamento sono modelli moderni della Smith & Wesson con chiusura a doppia serratura, un design che non era ancora in uso o disponibile durante il periodo storico rappresentato (anni ''50).', TRUE, '2026-11-02T10:26:58.438424', 'Shawshank Redemption handcuffs goof', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4023, 282, '01:55:00', 'Anacronismi', 'Quando viene scoperta la fuga di Andy, la sirena d''allarme del penitenziario emette un suono elettronico ad alta frequenza. Nel 1966, le sirene carcerarie erano dispositivi meccanici che producevano un suono più cupo e con una variazione di tono (pitch) legata alla rotazione del motore.', TRUE, '2026-11-02T10:26:58.438424', 'Shawshank Redemption prison siren', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4024, 282, '01:51:00', 'Errori di scena / Posizione', 'Andy lucida le scarpe del direttore Norton (modello Derby con lacci aperti) e le mette nella scatola. Tuttavia, quando lo vediamo entrare in banca il giorno successivo dopo la fuga, indossa un paio di scarpe modello Oxford (lacci chiusi), diverse da quelle prelevate dall''ufficio del direttore.', TRUE, '2026-11-02T10:26:58.438424', 'Shawshank Redemption Andy bank shoes', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4025, 282, '00:05:00', 'Anacronismi', 'Nelle scene iniziali del 1946, le guardie che ispezionano le celle utilizzano torce elettriche in alluminio anodizzato con impugnatura zigrinata. Questo design è tipico delle torce Maglite, che sono state introdotte sul mercato solo a partire dal 1979.', TRUE, '2026-11-02T10:26:58.438424', 'Shawshank Redemption flashlight goof', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4384, 282, '00:00:00', 'Errori di scena / Posizione', 'Durante la scena in cui Andy siede in macchina fuori dalla casa della moglie con una pistola in mano, il fumo della sigaretta e la posizione delle sue mani cambiano in modo evidente tra le inquadrature in primo piano e quelle dall''esterno.', TRUE, '2026-11-02T14:53:59.175751', 'The Shawshank Redemption car scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4385, 282, '00:00:00', 'Anacronismi', 'Nel corso dei primi anni di detenzione di Andy (fine anni ''40), si intravedono in alcune inquadrature panoramiche della prigione dei veicoli o dettagli stradali che presentano specifiche caratteristiche estetiche riconducibili ad anni successivi.', TRUE, '2026-11-02T14:53:59.175751', 'The Shawshank Redemption car anachronism', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4386, 282, '00:00:00', 'Errori di scena / Posizione', 'Quando i detenuti lavorano alla pavimentazione della strada nel 1949, la quantità di catrame e la posizione degli strumenti di lavoro cambiano repentinamente tra un cambio di inquadratura e l''altro senza che i prigionieri si siano mossi.', TRUE, '2026-11-02T14:53:59.175751', 'The Shawshank Redemption tar road scene continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4387, 282, '00:00:00', 'Errori storici o fattuali', 'Il sistema di schedatura e le cartelle cliniche/penali utilizzate dal direttore e dal personale amministrativo della prigione di Shawshank presentano formati di timbri e moduli tipografici standardizzati introdotti negli uffici statali solo decenni più tardi.', TRUE, '2026-11-02T14:53:59.175751', 'The Shawshank Redemption prison records error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4388, 282, '00:00:00', 'Errori di scena / Posizione', 'Nella scena in cui Tommy viene ucciso nel cortile, la posizione del suo corpo rispetto alle linee di demarcazione del terreno e ai bossoli cambia leggermente tra l''inquadratura iniziale della caduta e i successivi primi piani.', TRUE, '2026-11-02T14:53:59.175751', 'The Shawshank Redemption Tommy death scene error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3754, 45, '00:00:00', 'Errori di scena / Posizione', 'Durante la sequenza iniziale a Miami, quando James Bond si trova nella camera d''albergo prima di scoprire Jill Masterson dipinta d''oro, la bottiglia di champagne sul secchiello del ghiaccio cambia posizione e livello di liquido tra le diverse inquadrature.', TRUE, '2026-11-02T09:51:26.771189', 'Goldfinger Miami hotel champagne scene error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3755, 45, '00:00:00', 'Errori di scena / Posizione', 'Quando l''Aston Martin DB5 viene colpita dai proiettori di luce durante l''inseguimento notturno alla fonderia di Goldfinger in Svizzera, i danni sulla carrozzeria e sui vetri dell''auto variano visibilmente da un''inquadratura all''altra.', TRUE, '2026-11-02T09:51:26.771189', 'Goldfinger Aston Martin chase bullet holes continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3756, 45, '00:00:00', 'Errori di scena / Posizione', 'Nel corso della partita a golf tra James Bond e Auric Goldfinger, la pallina da golf che viene mossa o ritrovata cambia posizione in modo innaturale rispetto al punto in cui era finita nel colpo precedente.', TRUE, '2026-11-02T09:51:26.771189', 'Goldfinger golf game ball position error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3757, 47, '01:22:00', 'Troupe o microfoni visibili', 'Durante la sequenza del torneo di poker al Casino Royale, in un''inquadratura ravvicinata su uno dei giocatori, è possibile intravedere brevemente il riflesso di un operatore della troupe con l''attrezzatura audio su una delle superfici lucide del tavolo.', TRUE, '2026-11-02T09:51:42.18347', 'Casino Royale crew visible reflection poker table', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4026, 283, '01:21:00', 'Errori di scena / Posizione', 'Durante la gita in barca organizzata da McMurphy, la posizione dei pazienti e degli oggetti a bordo cambia visibilmente tra un''inquadratura e l''altra, tradendo i tagli di montaggio e le riprese effettuate in momenti diversi.', TRUE, '2026-11-02T10:27:05.531925', 'One Flew Over the Cuckoo''s Nest boat scene goof', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4394, 283, '00:42:15', 'Errori di scena / Posizione', 'Durante la terapia di gruppo, i fogli e gli appunti tenuti in mano da alcuni pazienti cambiano posizione e orientamento tra i primi piani e i campi medi, evidenziando le ripetizioni delle riprese.', TRUE, '2026-11-02T14:54:04.233172', 'One Flew Over the Cuckoo''s Nest group therapy continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4395, 283, '01:50:10', 'Errori di scena / Posizione', 'Dopo la rivolta nella sala comune, i segni di disordine e la posizione dei mobili rovesciati variano sensibilmente quando la telecamera passa dai dettagli ai campi larghi durante l''arrivo delle guardie.', TRUE, '2026-11-02T14:54:04.233172', 'One Flew Over the Cuckoo''s Nest ward mess continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4427, 119, '00:15:20', 'Errori di scena / Posizione', 'Quando Peter cammina per i corridoi della scuola parlando con Ned, lo zaino che indossa cambia posizione o la spalla su cui poggia la tracolla si inverte tra un''inquadratura e l''altra.', TRUE, '2026-11-02T14:55:13.468287', 'Spider-Man Homecoming hallway continuity error backpack', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4428, 119, '00:42:10', 'Errori di scena / Posizione', 'Nel laboratorio di Tony Stark o durante la conversazione in auto, le mani di Peter o gli oggetti che tiene cambiano orientamento rapidamente da un''angolazione all''altra senza che ci sia il tempo fisico per farlo.', TRUE, '2026-11-02T14:55:13.468287', 'Spider-Man Homecoming car scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4429, 119, '01:05:40', 'Troupe o microfoni visibili', 'Durante la sequenza d''azione sul camion in movimento, in un riflesso sullo specchietto o sulla carrozzeria metallica è possibile intravedere brevemente l''ombra di un''attrezzatura della troupe o di un operatore di camera.', TRUE, '2026-11-02T14:55:13.468287', 'Spider-Man Homecoming crew visible reflection truck scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4430, 119, '01:22:15', 'Errori di scena / Posizione', 'Nella scena in cui Peter è intrappolato nel magazzino e cerca di sollevare le macerie, la quantità di polvere e detriti sul suo costume varia visivamente tra un primo piano e un campo largo.', TRUE, '2026-11-02T14:55:13.468287', 'Spider-Man Homecoming warehouse scene rubble continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4446, 139, '01:42:00', 'Troupe o microfoni visibili', 'Durante il combattimento finale sul treno deragliato in mezzo alla città, in un''inquadratura grandangolare che mostra Brad Pitt mentre schiva un colpo, è possibile intravedere brevemente per un fotogramma l''imbracatura di sicurezza e i cavi di sostegno dello stuntman sotto i vestiti.', TRUE, '2026-11-02T14:55:38.303746', 'Bullet Train stunt wire visible mistake', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4447, 139, '00:35:10', 'Errori di scena / Posizione', 'Nella scena in cui Lemon parla delle regole del ''Thomas the Tank Engine'' a Ladybug, la bottiglietta d''acqua sul tavolino cambia inclinazione e livello del liquido tra un''inquadratura e l''altra, senza che nessuno l''abbia toccata.', TRUE, '2026-11-02T14:55:38.303746', 'Bullet Train Lemon train continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4448, 139, '01:15:20', 'Errori storici o fattuali', 'Quando il treno si avvicina alla stazione finale e si scontra violentemente, la velocità indicata sui monitor di bordo e la dinamica dell''impatto ignorano i moderni sistemi automatici di frenata d''emergenza (Urgent Train Stop) di cui sono dotati i treni Shinkansen giapponesi.', TRUE, '2026-11-02T14:55:38.303746', 'Bullet Train Shinkansen brakes realistic error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4449, 139, '00:15:20', 'Errori storici o fattuali', 'Durante il viaggio dello Shinkansen, il treno attraversa paesaggi montuosi e urbani a velocità vertiginosa, ma i finestrini e la prospettiva esterna mostrano spesso una campagna e gallerie che non corrispondono alla reale conformazione della linea ferroviaria Tokaido tra Tokyo e Kyoto.', TRUE, '2026-11-02T14:55:38.303746', 'Bullet Train geography route error Shinkansen', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4450, 139, '01:22:45', 'Errori di scena / Posizione', 'Quando Ladybug combatte contro i vari sicari nella carrozza, le bottiglie e i bicchieri posizionati sui tavolini cambiano disposizione, scomparendo e riapparendo tra un''inquadratura e l''altra durante i tagli di montaggio.', TRUE, '2026-11-02T14:55:38.303746', 'Bullet Train continuity props fight scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4515, 210, '00:15:20', 'Errori di scena / Posizione', 'Quando Gru si trova nella cucina della villa di Dru, i bicchieri sul bancone cambiano posizione e quantità tra un''inquadratura e l''altra mentre i due parlano.', TRUE, '2026-11-02T15:33:08.123109', 'Despicable Me 3 Gru meets Dru kitchen scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4516, 210, '00:32:45', 'Errori di scena / Posizione', 'Durante la fuga di Balthazar Bratt, gli strumenti musicali e i gadget tecnologici che distrugge sulla strada variano per disposizione e modello da un''inquadratura larga a quella ravvicinata.', TRUE, '2026-11-02T15:33:08.123109', 'Despicable Me 3 Balthazar Bratt attack scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4517, 210, '00:48:10', 'Errori di scena / Posizione', 'Nella base dei Minions in prigione, il numero di oggetti sulla mensola della cella in cui si trovano diminuisce e aumenta improvvisamente durante la rivolta.', TRUE, '2026-11-02T15:33:08.123109', 'Despicable Me 3 Minions in prison scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3758, 50, '00:00:00', 'Errori di scena / Posizione', 'Durante la scena del party nella Torre degli Avengers, la bottiglia di Asgardian Liquor posata sul tavolo cambia costantemente posizione e inclinazione tra le inquadrature dei vari attori che vi si avvicinano.', TRUE, '2026-11-02T09:52:02.943191', 'Avengers Age of Ultron party scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3759, 50, '00:00:00', 'Errori di scena / Posizione', 'Nella sequenza in cui Bruce Banner si trasforma in Hulk per la prima volta nella città asiatica, i suoi occhiali cadono a terra frantumandosi, ma nelle inquadrature successive li indossa nuovamente intatti.', TRUE, '2026-11-02T09:52:02.943191', 'Avengers Age of Ultron Hulk glasses continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4027, 284, '00:26:00', 'Anacronismi', 'Nella celebre scena in cui Butch porta Etta Place in bicicletta, la cerniera zip sul retro dell''abito di Etta è chiaramente visibile. Le cerniere lampo non venivano utilizzate negli abiti femminili all''epoca in cui è ambientato il film (1899).', TRUE, '2026-11-02T10:28:06.080537', 'Butch Cassidy bicycle scene Raindrops Keep Fallin on My Head', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4028, 284, '01:05:00', 'Troupe o microfoni visibili', 'Durante la lunga sequenza dell''inseguimento a cavallo da parte del gruppo di guardie («Who are those guys?»), in diverse inquadrature panoramiche del terreno brullo sono visibili sul terreno le chiare impronte degli pneumatici dei mezzi della troupe cinematografica.', TRUE, '2026-11-02T10:28:06.080537', 'Butch Cassidy who are those guys chase scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4029, 284, '01:18:15', 'Errori di scena / Posizione', 'Nella scena del salto dal precipizio nel fiume, quando i due si lanciano dalla roccia si nota chiaramente la differenza di corporatura e acconciatura tra gli attori principali (Paul Newman e Robert Redford) e le due controfigure che effettuano realmente il tuffo.', TRUE, '2026-11-02T10:28:06.080537', 'Butch Cassidy cliff jump scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4030, 284, '00:46:20', 'Errori di scena / Posizione', 'Dopo l''enorme esplosione del vagone blindato della Union Pacific, le banconote volano ovunque. Tra un''inquadratura e l''altra la quantità e la disposizione dei detriti e del denaro a terra attorno al vagone distrutto cambiano radicalmente.', TRUE, '2026-11-02T10:28:06.080537', 'Butch Cassidy train explosion scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4031, 284, '00:27:30', 'Troupe o microfoni visibili', 'Mentre Butch compie acrobazie in bicicletta vicino alla staccionata per divertire Etta, in un''inquadratura angolata verso il basso si proietta chiaramente sul terreno l''ombra della telecamera e del suo operatore.', TRUE, '2026-11-02T10:28:06.080537', 'Butch Cassidy bicycle stunts scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4032, 284, '01:35:10', 'Errori storici o fattuali', 'Nelle scene ambientate in Bolivia (in realtà girate in Messico), le guardie e le forze dell''ordine indossano divise storicamente errate per la Bolivia del 1908 e gli comparse locali parlano con un marcato accento spagnolo-messicano anziché andino/boliviano.', TRUE, '2026-11-02T10:28:06.080537', 'Butch Cassidy Bolivia scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4397, 284, '00:00:00', 'Errori di scena / Posizione', 'Durante le sequenze delle rapine ai treni, la posizione delle borse di denaro e delle cariche di dinamite usate per far saltare le porte dei vagoni cambia visibilmente tra i campi lunghi e i primi piani ravvicinati dei tagli di montaggio.', TRUE, '2026-11-02T14:54:14.075991', 'Butch Cassidy train robbery continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4398, 284, '00:00:00', 'Errori storici o fattuali', 'La celebre sequenza finale in cui i due fuorilegge vengono circondati dall''esercito boliviano a San Vicente si discosta storicamente dai reali eventi della sparatoria e dalle modalità dell''accerchiamento documentate nella biografia dei veri Butch Cassidy e Sundance Kid.', TRUE, '2026-11-02T14:54:14.075991', 'Butch Cassidy and the Sundance Kid historical inaccuracy San Vicente', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4423, 78, '00:15:30', 'Errori di scena / Posizione', 'Durante la sequenza del inseguimento sui landspeeder sul pianeta Pasaana, il fucile a tracolla indossato da Finn cambia spalla e posizione tra un''inquadratura e l''altra mentre saltano da un veicolo all''altro.', TRUE, '2026-11-02T14:54:57.498429', 'Star Wars Rise of Skywalker Pasaana speeder chase scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4424, 78, '00:42:10', 'Errori di scena / Posizione', 'Quando Poe, Finn e Rey si trovano nella cella delle prigioni del Destroyer stellare, il medaglione che Poe tiene in mano scompare e riappare tra i cambi di inquadratura dei dialoghi.', TRUE, '2026-11-02T14:54:57.498429', 'Star Wars Rise of Skywalker star destroyer jail scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4425, 78, '01:12:45', 'Errori di scena / Posizione', 'Nel quartier generale della Resistenza, la ferita sul volto di Leia o di altri personaggi mostra variazioni di intensità del trucco e della posizione del sangue secco tra una scena e quella immediatamente successiva.', TRUE, '2026-11-02T14:54:57.498429', 'Star Wars Rise of Skywalker resistance base scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4426, 78, '01:35:20', 'Errori di scena / Posizione', 'Sul pianeta Exegol, durante la battaglia finale, il mantello di Kylo Ren appare bagnato, sporco o perfettamente asciutto a seconda che l''inquadratura sia larga o ravvicinata.', TRUE, '2026-11-02T14:54:57.498429', 'Star Wars Rise of Skywalker Kylo Ren Exegol battle', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4441, 133, '00:15:20', 'Anacronismi', 'Quando Rick Dalton beve alcolici nel suo camerino, sullo sfondo appare un manifesto promozionale con caratteri tipografici e loghi di un formato grafico che non esisteva nel 1969.', TRUE, '2026-11-02T14:55:33.384322', 'Once Upon a Time in Hollywood poster anachronism', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4442, 133, '00:42:10', 'Errori di scena / Posizione', 'Durante la conversazione al ristorante tra Rick Dalton e Marvin Schwarz, i tovaglioli e i bicchieri sul tavolo cambiano disposizione e livello di riempimento tra i campi e i controcampi.', TRUE, '2026-11-02T14:55:33.384322', 'Once Upon a Time in Hollywood restaurant scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4443, 133, '01:10:45', 'Troupe o microfoni visibili', 'In una ripresa laterale sul set della serie TV ''Lancer'', si intravede brevemente l''ombra di un microfono a giraffa (boom mic) proiettata sulla parete del ranch in alto a destra.', TRUE, '2026-11-02T14:55:33.384322', 'Once Upon a Time in Hollywood boom mic shadow visible', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4444, 133, '01:33:15', 'Anacronismi', 'Nella sequenza in cui Sharon Tate cammina per le strade di Los Angeles, si nota una vettura moderna o un dettaglio di arredo urbano successivo al 1969 non rimosso dalla scenografia.', TRUE, '2026-11-02T14:55:33.384322', 'Once Upon a Time in Hollywood street scene car anachronism', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4445, 133, '02:05:30', 'Errori di scena / Posizione', 'Durante l''aggressione nella casa di Rick Dalton, il posizionamento delle armi bianche e degli oggetti contundenti sul pavimento cambia tra un''inquadratura e l''altra prima dell''intervento del lanciafiamme.', TRUE, '2026-11-02T14:55:33.384322', 'Once Upon a Time in Hollywood fight scene continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(272, 53, '01:14:50', 'Errori di scena / Posizione', 'Nel corso dello scontro decisivo, le ferite da taglio e i rivoli di sangue sul volto di Duncan MacLeod cambiano forma, densità e posizione a seconda che l''inquadratura sia frontale o di profilo.', TRUE, '2026-09-14T13:51:54.493929', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(3760, 51, '00:15:30', 'Errori di scena / Posizione', 'Durante la sequenza a New York in cui Bruce Banner cerca di trasformarsi in Hulk davanti a Doctor Strange e Wong, la posizione dei suoi occhiali da vista e il modo in cui li tiene in mano variano repentinamente tra un''inquadratura e l''altra.', TRUE, '2026-11-02T09:52:11.816229', 'Avengers Infinity War Bruce Banner transforms mistake', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3761, 51, '00:45:00', 'Errori di scena / Posizione', 'Nel quartier generale degli Avengers, quando James Rhodes interrompe l''ologramma del Segretario Ross, la tazza di caffè che tiene in mano scompare e riappare tra i cambi d''inquadratura.', TRUE, '2026-11-02T09:52:11.816229', 'Avengers Infinity War Rhodey hologram coffee cup goof', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3762, 51, '01:10:00', 'Errori di scena / Posizione', 'Sul pianeta Vormir, quando Thanos e Gamora arrivano in cima alla montagna, la posizione del mantello e delle cinghie sulla spalla di Thanos cambia in modo evidente tra le riprese frontali e quelle di profilo.', TRUE, '2026-11-02T09:52:11.816229', 'Avengers Infinity War Vormir Thanos Gamora continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4033, 285, '00:05:20', 'Anacronismi', 'Durante le scene iniziali ambientate nel 1936, è possibile scorgere un camion parcheggiato in strada che appartiene a un modello prodotto solo a partire dalla fine degli anni ''40.', TRUE, '2026-11-02T10:29:10.237982', 'The Sting 1973 opening scene truck anachronism', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4034, 285, '00:10:45', 'Anacronismi', 'In diverse scene ambientate sulla metropolitana sopraelevata di Chicago, si vedono chiaramente vagoni della serie 2200, che sono stati messi in servizio solo nel 1969.', TRUE, '2026-11-02T10:29:10.237982', 'The Sting 1973 Chicago L train anachronism', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4035, 285, '00:38:15', 'Anacronismi', 'Il logo della Western Union visibile nell''ufficio e sui telegrammi è quello introdotto dalla compagnia negli anni ''50, non quello storicamente accurato per il 1936.', TRUE, '2026-11-02T10:29:10.237982', 'The Sting 1973 Western Union logo', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4036, 285, '00:48:30', 'Errori di scena / Posizione', 'Durante la partita a poker sul treno, la posizione delle carte di Lonnegan e l''altezza del suo drink cambiano drasticamente tra un''inquadratura e l''altra senza che lui li tocchi.', TRUE, '2026-11-02T10:29:10.237982', 'The Sting poker scene continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4037, 285, '01:12:00', 'Errori storici o fattuali', 'Viene menzionato un club chiamato ''Blue Note''. Sebbene esistessero molti club con nomi simili, il celebre Blue Note di Chicago a cui il film sembra alludere aprì solo nel 1947.', TRUE, '2026-11-02T10:29:10.237982', 'The Sting 1973 Blue Note reference', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4038, 285, '01:58:20', 'Errori di scena / Posizione', 'Nella scena finale della sparatoria, la macchia di sangue finto sul petto di Hooker (Robert Redford) cambia forma e dimensione tra l''inquadratura larga e il primo piano.', TRUE, '2026-11-02T10:29:10.237982', 'The Sting 1973 ending blood goof', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4039, 285, '00:22:10', 'Anacronismi', 'Nello skyline di Chicago visibile in alcune riprese esterne, si possono notare edifici moderni costruiti tra la fine degli anni ''60 e l''inizio degli anni ''70.', TRUE, '2026-11-02T10:29:10.237982', 'The Sting 1973 Chicago skyline anachronism', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4040, 285, '00:56:40', 'Errori di scena / Posizione', 'Quando Gondorff è nella casa della giostra e parla con Hooker, il livello del liquore nella bottiglia che tiene in mano sale e scende tra i vari stacchi di montaggio.', TRUE, '2026-11-02T10:29:10.237982', 'The Sting 1973 Gondorff bottle continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4041, 285, '01:25:15', 'Anacronismi', 'Sui cartelli della stazione ferroviaria e in alcuni uffici viene utilizzato il carattere tipografico Helvetica, che è stato creato solo nel 1957.', TRUE, '2026-11-02T10:29:10.237982', 'The Sting 1973 Helvetica font anachronism', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4042, 285, '00:03:45', 'Errori di scena / Posizione', 'Durante l''inseguimento iniziale a piedi, i capelli di Hooker passano dall''essere spettinati a perfettamente pettinati e di nuovo spettinati tra un taglio e l''altro.', TRUE, '2026-11-02T10:29:10.237982', 'The Sting 1973 Hooker chase hair continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4403, 357, '00:00:00', 'Troupe o microfoni visibili', 'In alcune scene ravvicinate girate sul ponte dell''imbarcazione durante i momenti più agitati, si possono intravedere brevemente i riflessi dell''attrezzatura di illuminazione e talvolta la sagoma di un operatore di ripresa nei vetri o sulle superfici bagnate della barca.', TRUE, '2026-11-02T14:54:26.421359', 'The Perfect Storm crew reflection error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4404, 357, '00:00:00', 'Errori storici o fattuali', 'Durante le sequenze in cui l''elicottero della Guardia Costiera è in volo, la rappresentazione delle procedure di rifornimento in volo e l''autonomia stimata dei velivoli HH-3F Pelican non rispecchiano fedelmente le reali specifiche tecniche e operative utilizzate durante il salvataggio del 1991.', TRUE, '2026-11-02T14:54:26.421359', 'The Perfect Storm helicopter rescue historical inaccuracies', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4405, 357, '00:00:00', 'Errori di scena / Posizione', 'Quando l''equipaggio discute sottocoperta, la posizione delle tazze da caffè e dei vari strumenti di navigazione sui tavoli cambia visibilmente da un''inquadratura all''altra senza che nessuno li abbia toccati.', TRUE, '2026-11-02T14:54:26.421359', 'The Perfect Storm continuity error cups', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4406, 357, '00:00:00', 'Anacronismi', 'In alcune inquadrature di sfondo nel porto e nelle strade di Gloucester, compaiono cartelli stradali, segnaletica orizzontale e modelli di contenitori per rifiuti che riflettono standard e normative di sicurezza stradale e urbana introdotti decenni dopo il 1991.', TRUE, '2026-11-02T14:54:26.421359', 'The Perfect Storm anachronisms street signs', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4407, 51, '00:12:45', 'Errori di scena / Posizione', 'Durante la sequenza nel parco a New York, quando Tony Stark parla con Pepper Potts prima dell''arrivo della Q-Ship, il colletto della camicia di Tony cambia altezza e posizione della piega tra un''inquadratura e l''altra.', TRUE, '2026-11-02T14:54:35.159093', 'Avengers Infinity War Tony and Pepper park scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
