(3798, 82, '00:00:00', 'Errori di scena / Posizione', 'Nel prologo del film, durante la simulazione di salvataggio nel centro di addestramento dell''MI6, l''abbigliamento e la posizione delle ferite fittizie di James Bond variano visibilmente tra un''inquadratura e l''altra prima dell''intervento di M.', TRUE, '2026-11-02T09:56:41.400512', 'Never Say Again opening training scene goof', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4082, 357, '00:00:00', 'Anacronismi', 'Durante le scene ambientate nel 1991, si possono notare alcuni modelli di automobili, camion e attrezzature portuali che sono stati prodotti in anni successivi rispetto all''ambientazione temporale del film.', TRUE, '2026-11-02T12:05:03.537242', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(4083, 357, '00:00:00', 'Errori storici o fattuali', 'Nel film viene mostrato l''elicottero della Guardia Costiera rischiare lo schianto e l''ammaraggio forzato a causa della totale mancanza di carburante; nella realtà storica dell''operazione di salvataggio dell''Andrea Gail, l''elicottero completò il rifornimento in volo prima di esaurire completamente il combustibile.', TRUE, '2026-11-02T12:05:03.537242', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(4477, 292, '00:42:10', 'Errori di scena / Posizione', 'Mentre Jojo parla con Adolf nella stanza, la tazza da tè sul tavolino cambia posizione e livello di liquido tra un''inquadratura in primo piano e il campo medio successivo.', TRUE, '2026-11-02T14:56:28.521258', 'Jojo Rabbit continuity cup scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4478, 292, '01:05:45', 'Errori storici o fattuali', 'I distintivi e le uniformi indossate da alcuni membri della Gestapo presentano imprecisioni storiche minori rispetto ai veri gradi e decorazioni della Germania nazista del 1945.', TRUE, '2026-11-02T14:56:28.521258', 'Jojo Rabbit Gestapo uniforms historical error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4479, 292, '00:15:20', 'Anacronismi', 'Durante una panoramica dei veicoli militari nel campo della Gioventù Hitleriana, si intravede brevemente un componente meccanico o un tipo di pneumatico su un camion leggero che corrisponde a standard produttivi del dopoguerra, anacronistico rispetto al 1945.', TRUE, '2026-11-02T14:56:28.521258', 'Jojo Rabbit historical vehicle error scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4480, 292, '00:42:10', 'Errori di scena / Posizione', 'Nella cucina della casa di Jojo, mentre Rosie prepara da mangiare e parla con il figlio, i barattoli di conserve posizionati sulla mensola sullo sfondo cambiano disposizione e numero tra un''inquadratura ravvicinata e il controcampo.', TRUE, '2026-11-02T14:56:28.521258', 'Jojo Rabbit kitchen scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4481, 292, '01:05:45', 'Errori storici o fattuali', 'Nel momento in cui la Gestapo effettua il controllo dei documenti nella casa, l''uso e l''emissione di alcuni moduli cartacei mostrati sullo schermo presentano formati tipografici e intestazioni burocratiche non conformi ai veri modelli amministrativi del Terzo Reich nel 1945.', TRUE, '2026-11-02T14:56:28.521258', 'Jojo Rabbit Gestapo scene historical accuracy', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4482, 292, '01:22:30', 'Errori di scena / Posizione', 'Durante i combattimenti per le strade della città tra le forze difensive e gli Alleati, cumuli di detriti e macerie variano visibilmente di volume e posizione da un''angolazione all''altra durante la stessa sequenza d''azione.', TRUE, '2026-11-02T14:56:28.521258', 'Jojo Rabbit battle scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4541, 260, '01:12:40', 'Troupe o microfoni visibili', 'Durante la sparatoria nella fabbrica, in un''inquadratura grandangolare riflessa su una superficie lucida di metallo è possibile intravedere brevemente l''ombra di un operatore di camera.', TRUE, '2026-11-02T15:33:43.063606', 'Nobody 2021 crew reflection error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4542, 271, '00:15:20', 'Errori di scena / Posizione', 'Durante la sequenza in auto, la posizione degli oggetti sul cruscotto cambia visibilmente tra un''inquadratura in primo piano e il campo largo successivo.', TRUE, '2026-11-02T15:33:58.674399', 'Cosi e la vita Aldo Giovanni e Giacomo auto errore continuità', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4543, 271, '00:42:10', 'Errori di scena / Posizione', 'Nei campi e controcampi della discussione all''aperto sui monti dell''Abruzzo, i capelli di Giacomo (Giacomo Poretti) cambiano continuamente di pettinatura a causa del vento e dei ciak differenti.', TRUE, '2026-11-02T15:33:58.674399', 'Cosi e la vita errore montaggio scena montagna', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4544, 271, '01:05:40', 'Errori di scena / Posizione', 'Il bicchiere tenuto in mano da Antonio Catania in una scena di dialogo passa da quasi pieno a vuoto e viceversa tra i tagli di montaggio senza che il personaggio abbia bevuto.', TRUE, '2026-11-02T15:33:58.674399', 'Cosi e la vita errore bicchiere continuità', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4545, 271, '00:25:40', 'Errori di scena / Posizione', 'Durante la fuga in macchina, la camicia di Aldo (Aldo Baglio) mostra una macchia di sudore o un segno che varia vistosamente di forma e dimensione tra l''inquadratura dall''esterno e il primo piano all''interno dell''abitacolo.', TRUE, '2026-11-02T15:33:58.674399', 'Cosi e la vita Aldo macchina errore continuita', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4546, 271, '00:42:15', 'Troupe o microfoni visibili', 'In una delle sequenze girate in esterni di giorno tra i sentieri montani, si intravede chiaramente per un breve fotogramma l''ombra dell''asta del microfono boom proiettata sulla roccia alle spalle di Giacomo.', TRUE, '2026-11-02T15:33:58.674399', 'Cosi e la vita errore microfono ombra', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4547, 271, '01:05:30', 'Errori di scena / Posizione', 'Nella scena in cui i protagonisti mangiano nei pressi della tenda, la quantità di cibo presente nel piatto di Giovanni (Giovanni Storti) diminuisce e aumenta improvvisamente da un''inquadratura all''altra senza che lui tocchi le posate.', TRUE, '2026-11-02T15:33:58.674399', 'Cosi e la vita errore piatto cibo', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4573, 325, '00:15:30', 'Errori di scena / Posizione', 'Durante la scena in cui Sondra Pransky e Sid Waterman parlano nel parco, i bicchieri di carta che tengono in mano cambiano livello di riempimento e posizione tra un''inquadratura e l''altra.', TRUE, '2026-11-02T15:34:42.819126', 'Scoop 2006 continuity error park scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4574, 325, '00:42:15', 'Anacronismi', 'Nel film, ambientato nei primi anni 2000 a Londra, si possono notare alcuni modelli di automobili e autobus a due piani con livree e loghi pubblicitari che appartengono a un periodo successivo all''uscita della pellicola.', TRUE, '2026-11-02T15:34:42.819126', 'Scoop Woody Allen car anachronism', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4575, 325, '01:05:40', 'Errori storici o fattuali', 'Le procedure investigative e legali mostrate in merito al presunto ''Tarot Card Killer'' presentano notevoli inesattezze rispetto al vero sistema giudiziario britannico e alla giurisdizione della polizia metropolitana di Londra.', TRUE, '2026-11-02T15:34:42.819126', 'Scoop movie factual errors police', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4576, 325, '01:22:10', 'Errori di scena / Posizione', 'Nella sequenza finale nella residenza di Peter Lyman, il tovagliolo sul tavolo accanto a Sondra appare prima spiegato e nell''inquadratura successiva perfettamente piegato a triangolo, senza che nessuno lo abbia toccato.', TRUE, '2026-11-02T15:34:42.819126', 'Scoop Hugh Jackman Scarlett Johansson dinner scene continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3799, 87, '01:05:00', 'Errori di scena / Posizione', 'Durante la sparatoria nella giungla, la quantità di fango e sangue sul volto e sul corpo di Sylvester Stallone varia drasticamente e inspiegabilmente da un''inquadratura all''altra.', TRUE, '2026-11-02T09:57:16.700215', 'Rambo 2 mud continuity error scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4084, 357, '00:08:00', 'Anacronismi', 'All''interno del bar Crow''s Nest, un cliente indossa una maglietta con il logo ''Life is Good''. Il marchio è stato creato e commercializzato a partire dal 1994, tre anni dopo gli eventi reali del 1991 narrati nel film.', TRUE, '2026-11-02T12:08:12.382929', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(4085, 357, '00:22:00', 'Errori di scena / Posizione', 'Mentre la Andrea Gail sta lasciando il porto di Gloucester, l''illuminazione e le ombre sulla barca cambiano drasticamente tra le inquadrature ravvicinate e quelle ampie, passando da una luce solare diretta a un cielo pesantemente nuvoloso in pochi istanti.', TRUE, '2026-11-02T12:08:12.382929', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(4086, 357, '01:25:00', 'Errori di scena / Posizione', 'Durante la tempesta, dopo che le finestre della cabina di pilotaggio vengono distrutte dalla forza dell''acqua, in alcune inquadrature successive i vetri appaiono inspiegabilmente intatti o i telai risultano privi di danni evidenti.', TRUE, '2026-11-02T12:08:12.382929', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(4087, 357, '00:00:00', 'Errori storici o fattuali', 'La struttura fisica della Andrea Gail nel film differisce dalla realtà: la vera imbarcazione non possedeva la coffa (crow''s nest) alta e la configurazione del ponte mostrata. La nave usata per il film, la Lady Grace, fu modificata con sovrastrutture fittizie per esigenze sceniche.', TRUE, '2026-11-02T12:08:12.382929', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(4088, 357, '00:10:00', 'Anacronismi', 'In diverse scene nel bar e sulla barca sono visibili bottiglie di birra Samuel Adams che presentano un design dell''etichetta e del logo introdotto dal birrificio solo alla fine degli anni ''90, non coerente con l''ambientazione del 1991.', TRUE, '2026-11-02T12:08:12.382929', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(4484, 360, '00:03:00', 'Errori di scena / Posizione', 'Durante la scena del bagno all''inizio del film, quando Malcolm Crowe si rende conto di essere stato ferito da Vincent Gray, la quantità di sangue sulla camicia e l''estensione della chiazza variano leggermente tra le diverse inquadrature ravvicinate e a campo largo.', TRUE, '2026-11-02T15:04:26.497464', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(4485, 360, '00:15:00', 'Errori di scena / Posizione', 'Nella scena in cui Cole è a scuola e disegna, le matite e i fogli sul suo banco cambiano disposizione e numero tra un''inquadratura e l''altra mentre l''insegnante si avvicina.', TRUE, '2026-11-02T15:04:26.497464', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(4486, 360, '00:45:00', 'Troupe o microfoni visibili', 'In una sequenza all''interno dell''appartamento di Cole, riflettersi brevemente sul vetro di una finestra o su una superficie lucida si intravede l''ombra dell''asta del microfono boom.', TRUE, '2026-11-02T15:04:26.497464', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(4487, 360, '01:05:00', 'Errori di scena / Posizione', 'Durante la scena del pranzo funebre della bambina avvelenata dalla matrigna, i piatti e i bicchieri sul tavolo della cucina cambiano posizione in modo evidente durante i cambi di angolazione tra i vari personaggi.', TRUE, '2026-11-02T15:04:26.497464', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(4548, 272, '00:00:00', 'Errori di scena / Posizione', 'Durante le sequenze in cui i tre protagonisti provano lo spettacolo teatrale del Cyrano, la posizione degli oggetti di scena sul tavolo cambia visibilmente tra un''inquadratura e l''altra, in particolare tazze e copioni.', TRUE, '2026-11-02T15:34:01.959704', 'Chiedimi se sono felice errori continuità', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4549, 272, '00:00:00', 'Errori di scena / Posizione', 'Nella scena in cui Giovanni lavora come statua vivente ai Grandi Magazzini, i passanti sullo sfondo cambiano posizione in modo repentino tra i vari stacchi di montaggio, evidenziando la ripetizione dei ciak.', TRUE, '2026-11-02T15:34:01.959704', 'Chiedimi se sono felice scena grandi magazzini', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4577, 327, '00:15:22', 'Anacronismi', 'In una scena ambientata nel 1972, sullo sfondo si intravedono veicoli o modelli di automobili (come alcune berline europee) che presentano dettagli di design o targhe tipicamente successivi alla metà degli anni ''70.', TRUE, '2026-11-02T15:34:52.229453', 'Munich 2005 car anachronism scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4578, 327, '01:04:10', 'Errori di scena / Posizione', 'Durante un incontro in un bar tra Avner e i suoi contatti, la tazza da caffè e i bicchieri sul tavolo cambiano posizione e livello di riempimento tra un''inquadratura in primo piano e quella a campo medio.', TRUE, '2026-11-02T15:34:52.229453', 'Munich 2005 continuity coffee cup scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4579, 327, '02:12:45', 'Errori storici o fattuali', 'Le procedure e le attrezzature specifiche utilizzate dal Mossad e dalle agenzie di intelligence in alcune sequenze operative mostrano licenze cinematografiche rispetto ai veri protocolli segreti dell''epoca.', TRUE, '2026-11-02T15:34:52.229453', 'Munich 2005 historical accuracy Mossad', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4580, 327, '00:00:00', 'Anacronismi', 'In diverse sequenze ambientate nei primi anni ''70, compaiono modelli di automobili e furgoni europei (come alcuni modelli di Mercedes-Benz o berline francesi) dotati di indicatori di direzione laterali o dettagli della carrozzeria introdotti soltanto nella seconda metà del decennio.', TRUE, '2026-11-02T15:34:52.229453', 'Munich 2005 car anachronism goof', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4581, 327, '00:00:00', 'Errori storici o fattuali', 'Le armi da fuoco silenziate utilizzate dagli agenti in alcune missioni mostrano comportamenti balistici e livelli di rumorosità cinematograficamente alterati rispetto alle reali prestazioni dei silenziatori dell''epoca.', TRUE, '2026-11-02T15:34:52.229453', 'Munich 2005 gun silencer realism error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4582, 327, '00:00:00', 'Errori di scena / Posizione', 'Durante le sequenze negli appartamenti europei dove la squadra pianifica le operazioni, i documenti, le mappe e gli strumenti di scrittura sul tavolo cambiano visibilmente disposizione e orientamento tra un cambio d''inquadratura e l''altro.', TRUE, '2026-11-02T15:34:52.229453', 'Munich 2005 continuity table maps goof', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4583, 327, '00:00:00', 'Anacronismi', 'Alcuni dettagli di abbigliamento, come tagli di giubbotti invernali e calzature indossate da comparse nelle scene di strada a Londra e Parigi, presentano etichette o design di chiara ispirazione moderna o anni ''80 anziché del 1972.', TRUE, '2026-11-02T15:34:52.229453', 'Munich 2005 costume error background', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL);
INSERT INTO public.errori ("id", "film_id", "minuto", "categoria", "descrizione", "approvato", "creato_il", "youtube_query", "conferme", "contestazioni", "inserito_da", "provenienza", "screenshot_url") VALUES
(4594, 342, '00:15:20', 'Anacronismi', 'Durante le scene nel ghetto di Varsavia, si possono notare in alcune inquadrature sullo sfondo o ai lati della strada elementi di segnaletica stradale o pozzetti moderni che non appartengono al periodo della Seconda Guerra Mondiale.', TRUE, '2026-11-02T15:35:05.537986', 'The Pianist anachronisms street background', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4595, 342, '00:48:10', 'Errori di scena / Posizione', 'Nella scena in cui la famiglia Szpilman è in attesa alla stazione prima della deportazione, la posizione delle valigie e dei fagotti cambia visivamente tra un''inquadratura e l''altra e tra i campi e i controcampi.', TRUE, '2026-11-02T15:35:05.537986', 'The Pianist station deportation scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3803, 97, '00:01:00', 'Anacronismi', 'Nella sequenza d''apertura della Natività, la Stella di Betlemme è raffigurata come una stella a cinque punte perfetta (pentagramma), una convenzione artistica moderna che non corrisponde alle rappresentazioni astronomiche o storiche dell''epoca.', TRUE, '2026-11-02T09:58:59.584799', 'Ben-Hur 1925 Star of Bethlehem scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3804, 97, '00:15:00', 'Errori storici o fattuali', 'Sulla facciata e all''interno della casa di Hur è visibile il Magen David (Stella di Davide) utilizzato come simbolo araldico della famiglia. Storicamente, l''uso dell''esagramma come simbolo identificativo dell''ebraismo o di casate nobiliari giudaiche non era ancora diffuso nel I secolo d.C.', TRUE, '2026-11-02T09:58:59.584799', 'Ben-Hur 1925 House of Hur Star of David', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3805, 97, '00:42:00', 'Troupe o microfoni visibili', 'Durante la marcia dei prigionieri verso le galere nel deserto, in un''inquadratura dal basso verso l''alto, l''ombra della cinepresa e dell''operatore è chiaramente proiettata sulla sabbia mentre i figuranti passano accanto all''obiettivo.', TRUE, '2026-11-02T09:58:59.584799', 'Ben-Hur 1925 desert march camera shadow', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3806, 97, '00:48:00', 'Errori di scena / Posizione', 'Nelle scene all''interno della galera, il trucco che simula sporcizia e sudore sui corpi dei rematori, incluso Ben-Hur, cambia drasticamente tra i primi piani e i campi medi, apparendo e scomparendo in modo incoerente tra i tagli di montaggio.', TRUE, '2026-11-02T09:58:59.584799', 'Ben-Hur 1925 galley slave makeup continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3807, 97, '00:55:00', 'Troupe o microfoni visibili', 'Durante la battaglia navale contro i pirati, in diverse inquadrature dei modellini delle navi che si scontrano, sono visibili i sottili cavi d''acciaio utilizzati dai tecnici degli effetti speciali per trainare e far collidere le imbarcazioni.', TRUE, '2026-11-02T09:58:59.584799', 'Ben-Hur 1925 sea battle miniatures wires', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3808, 97, '01:05:00', 'Anacronismi', 'In diverse scene a Gerusalemme e nell''arena, i calzari di alcuni legionari romani mostrano chiaramente suole e tacchi in gomma moderna, tipici della produzione calzaturiera degli anni ''20, invece delle classiche ''caligae'' interamente in cuoio.', TRUE, '2026-11-02T09:58:59.584799', 'Ben-Hur 1925 Roman soldiers modern shoes', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3809, 97, '01:10:00', 'Anacronismi', 'Nelle inquadrature panoramiche della folla che assiste alla corsa dei carri nel Circus Maximus, diversi spettatori nelle prime file indossano orologi da polso, un accessorio ovviamente inesistente nell''antica Roma.', TRUE, '2026-11-02T09:58:59.584799', 'Ben-Hur 1925 chariot race crowd wristwatches', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3810, 97, '01:15:00', 'Errori di scena / Posizione', 'Durante uno degli incidenti nella corsa dei carri, le ''metae'' (le colonne di pietra alle estremità della spina) oscillano visibilmente all''impatto, rivelando di essere scenografie leggere realizzate in legno e gesso anziché solida pietra.', TRUE, '2026-11-02T09:58:59.584799', 'Ben-Hur 1925 chariot race crash pillars', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3811, 97, '01:18:00', 'Errori di scena / Posizione', 'Dopo un violento scontro tra carri, uno degli aurighi che dovrebbe essere morto o privo di sensi al suolo viene visto sollevare chiaramente la testa per controllare l''arrivo degli altri carri prima di riadagiarsi a terra.', TRUE, '2026-11-02T09:58:59.584799', 'Ben-Hur 1925 chariot race moving dead extra', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3812, 97, '01:20:00', 'Troupe o microfoni visibili', 'Nelle inquadrature più ampie dell''arena (girate a Culver City), sullo sfondo oltre le mura del set, sono brevemente visibili le sagome di edifici moderni della Los Angeles degli anni ''20 che svettano all''orizzonte.', TRUE, '2026-11-02T09:58:59.584799', 'Ben-Hur 1925 Circus Maximus set background', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4089, 20, '00:00:00', 'Errori di scena / Posizione', 'Durante una delle scene di combattimento nei sotterranei, la bottiglia di acqua sul tavolo in secondo piano cambia posizione e livello di liquido tra un''inquadratura e l''altra.', TRUE, '2026-11-02T14:45:04.891543', 'Gladiator 1992 James Marshall fight scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4090, 20, '00:00:00', 'Troupe o microfoni visibili', 'In un''inquadratura grandangolare della palestra di quartiere, sul bordo inferiore dello schermo si intravede per un istante l''ombra di un braccio del microfono boom.', TRUE, '2026-11-02T14:45:04.891543', 'Gladiator 1992 crew visible boom mic', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
