(4166, 307, '00:42:10', 'Errori di scena / Posizione', 'Nella scena in cui Teddy Daniels (Leonardo DiCaprio) fuma una sigaretta sotto la pioggia battente durante l''uragano, la lunghezza della cenere e la quantità di consumo della sigaretta variano drasticamente da un''inquadratura all''altra.', TRUE, '2026-11-02T14:48:52.082557', 'Shutter Island cigarette continuity rain scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4167, 307, '01:12:45', 'Anacronismi', 'Nel film, ambientato nel 1954, alcuni dei veicoli militari e della polizia mostrano dettagli o componenti di modelli successivi non ancora esistenti in quell''anno specifico.', TRUE, '2026-11-02T14:48:52.082557', 'Shutter Island historical car anachronism', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4168, 307, '01:28:15', 'Errori di scena / Posizione', 'Durante la colluttazione nella grotta tra Teddy e la presunta vera Rachel Solando, i capelli bagnati del protagonista cambiano completamente stile e posizione sul viso tra un cambio di inquadratura e il successivo.', TRUE, '2026-11-02T14:48:52.082557', 'Shutter Island cave scene hair continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4169, 307, '01:55:00', 'Troupe o microfoni visibili', 'In una delle sequenze finali girate sul faro, riflettendosi brevemente su una superficie metallica lucida dello strumento di illuminazione, è possibile intravedere per un istante l''ombra dell''operatore di camera.', TRUE, '2026-11-02T14:48:52.082557', 'Shutter Island crew reflection lighthouse scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4268, 336, '01:25:00', 'Errori di scena / Posizione', 'Durante una delle scene di tensione in cui Sean Devine (Kevin Bacon) parla con i sospettati, la posizione della tazza di caffè che tiene in mano cambia visibilmente tra un''inquadratura e l''altra, passando dall''essere stretta tra entrambe le mani a essere tenuta per il manico.', TRUE, '2026-11-02T14:50:58.387425', 'Mystic River Kevin Bacon coffee continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4269, 336, '00:42:00', 'Errori di scena / Posizione', 'Nella scena in cui Jimmy (Sean Penn) riceve la tragica notizia al minimarket, i prodotti sugli scaffali alle sue spalle cambiano disposizione e posizione tra l''inquadratura larga e i primi piani successivi.', TRUE, '2026-11-02T14:50:58.387425', 'Mystic River Sean Penn store scene continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4270, 336, '01:50:00', 'Errori di scena / Posizione', 'Durante la sequenza della festa e del successivo confronto notturno, le condizioni meteorologiche e l''intensità della pioggia variano in modo evidente tra le riprese esterne ampie e i dettagli ravvicinati dei personaggi.', TRUE, '2026-11-02T14:50:58.387425', 'Mystic River rain continuity error scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4271, 336, '00:00:00', 'Troupe o microfoni visibili', 'In alcune inquadrature ampie delle strade di Boston durante le riprese in esterna, è possibile intravedere brevemente l''ombra di un microfono boom sul marciapiede o sulle fiancate delle auto in sosta.', TRUE, '2026-11-02T14:50:58.387425', 'Mystic River boom mic visible', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4272, 336, '00:00:00', 'Anacronismi', 'Sebbene il film sia ambientato nei primi anni 2000 (circa 2002-2003), in alcune scene di traffico sullo sfondo si possono intravedere modelli di automobili e furgoni immatricolati in anni leggermente successivi all''ambientazione narrativa.', TRUE, '2026-11-02T14:50:58.387425', 'Mystic River car model anachronism', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3820, 110, '02:40:00', 'Errori storici o fattuali', 'Durante l''esecuzione finale di William Wallace, la regina Isabella (Sophie Marceau) visita il re Edoardo I sul letto di morte. Storicamente, Edoardo I morì nel 1307, mentre l''esecuzione di Wallace avvenne nel 1305, rendendo temporalmente impossibile questo incontro.', TRUE, '2026-11-02T10:00:49.783901', 'Braveheart Isabella and Edward death scene historical error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3821, 110, '01:25:00', 'Anacronismi', 'Nel film, Robert the Bruce viene mostrato come un indeciso che tradisce Wallace a Stirling e vive un conflitto interiore per tutta la durata della pellicola. Storicamente, Robert the Bruce non partecipò alla battaglia di Stirling Bridge dalla parte degli inglesi e fu un sostenitore costante della causa indipendentista.', TRUE, '2026-11-02T10:00:49.783901', 'Braveheart Robert the Bruce historical inaccuracies', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4107, 130, '00:00:00', 'Errori di scena / Posizione', 'Durante una delle scene di conversazione all''aperto a Seattle, le condizioni di luce del sole cambiano drasticamente tra un''inquadratura e la controinquadratura, passando da una luce solare diretta a un cielo nuvoloso, indicando che le riprese sono avvenute in momenti diversi della giornata.', TRUE, '2026-11-02T14:45:56.594145', 'Love Happens 2009 continuity error lighting scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4130, 286, '00:15:30', 'Errori di scena / Posizione', 'Quando Marion Crane guida la sua auto durante la fuga con il denaro, il tergicristallo cambia posizione e stato (acceso o spento) tra un''inquadratura e l''altra, nonostante le condizioni meteorologiche variano bruscamente.', TRUE, '2026-11-02T14:47:47.201012', 'Psycho Marion driving continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4131, 286, '00:20:10', 'Errori di scena / Posizione', 'La quantità di denaro (i 40.000 dollari nella busta) cambia visibilmente di spessore e posizione sul sedile della macchina e poi nella borsa di Marion tra le varie inquadrature.', TRUE, '2026-11-02T14:47:47.201012', 'Psycho money envelope continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4132, 286, '00:48:00', 'Errori di scena / Posizione', 'Nella famosa scena della doccia, la posizione dell''acqua sul corpo di Janet Leigh e i tagli alternati mostrano variazioni nella bagnatura dei capelli e della pelle tra un''inquadratura e l''altra.', TRUE, '2026-11-02T14:47:47.201012', 'Psycho shower scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4133, 286, '00:52:15', 'Errori di scena / Posizione', 'Quando Norman Bates pulisce il bagno dopo l''omicidio nella doccia, il sangue sul pavimento e gli strumenti usati cambiano disposizione mentre si sposta da un''inquadratura ravvicinata a una panoramica.', TRUE, '2026-11-02T14:47:47.201012', 'Norman cleans bathroom psycho error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4134, 286, '01:05:40', 'Errori di scena / Posizione', 'Il giornale che Arbogast sta leggendo mentre si reca al motel mostra pieghe e posizioni differenti delle mani dell''attore nei cambi di inquadratura tra primo piano e campo medio.', TRUE, '2026-11-02T14:47:47.201012', 'Psycho Arbogast newspaper continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4135, 286, '01:12:00', 'Troupe o microfoni visibili', 'Durante la colluttazione sulle scale in cui il detective Arbogast viene aggredito, in un fotogramma ravvicinato è possibile intravedere brevemente l''ombra del microfono boom sulla parete.', TRUE, '2026-11-02T14:47:47.201012', 'Psycho boom mic shadow staircase', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4136, 286, '01:25:30', 'Errori di scena / Posizione', 'Quando Lila Crane entra nella casa dei Bates e accende le luci, l''interruttore a muro cambia tipo e posizione rispetto al dettaglio mostrato nei secondi successivi.', TRUE, '2026-11-02T14:47:47.201012', 'Psycho Lila in house switch continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4144, 296, '00:08:15', 'Errori di scena / Posizione', 'Quando Holland March cade attraverso il tetto di vetro della casa di Mrs. Glen, la disposizione dei frammenti di vetro sul pavimento cambia drasticamente tra l''inquadratura dall''alto e quella dal basso mentre Ryan Gosling grida.', TRUE, '2026-11-02T14:48:04.500145', 'The Nice Guys Ryan Gosling glass roof fall scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4145, 296, '00:24:40', 'Troupe o microfoni visibili', 'Durante la sequenza in macchina in cui Jackson Healy guida e Holland March è sul sedile del passeggero, in un riflesso sul finestrino laterale è brevemente visibile l''ombra di un operatore della troupe con una cinepresa.', TRUE, '2026-11-02T14:48:04.500145', 'The Nice Guys car scene reflection boom mic', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4146, 296, '00:42:10', 'Anacronismi', 'Ambientato nel 1977, in una scena di strada si intravede sullo sfondo un cartellone pubblicitario con un font tipografico e un logo di una catena commerciale che non esisteva in quella forma negli anni ''70.', TRUE, '2026-11-02T14:48:04.500145', 'The Nice Guys 1977 background anachronism', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4147, 296, '01:15:30', 'Errori di scena / Posizione', 'Nel corso della sparatoria nel bagno turco/hotel, la quantità di sangue sul volto e sulla camicia di Jackson Healy varia visibilmente da un''inquadratura all''altra prima ancora che si asciughi o venga pulita.', TRUE, '2026-11-02T14:48:04.500145', 'The Nice Guys Russell Crowe bathroom fight continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
