(4295, 346, '00:15:20', 'Errori di scena / Posizione', 'Durante la scena nell''appartamento della prima vittima (la gola tagliata), la posizione degli oggetti sulla tavola e dei fascicoli spostati dai detective cambia visibilmente tra un''inquadratura e l''altra nei cambi di campo.', TRUE, '2026-11-02T14:51:34.555378', 'Seven 1995 continuity error apartment', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4296, 346, '00:42:10', 'Errori di scena / Posizione', 'Nel corso della discussione tra Somerset e Mills nel bar, i bicchieri e i tovaglioli sul tavolo si muovono e cambiano disposizione da un''inquadratura all''altra senza che i personaggi li tocchino.', TRUE, '2026-11-02T14:51:34.555378', 'Se7en diner scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3822, 111, '02:27:00', 'Errori di scena / Posizione', 'Quando il capitano Smith si trova nella plancia di comando mentre l''acqua rompe i vetri, la sua barba e i suoi capelli sono completamente bagnati in un''inquadratura, ma appaiono visibilmente più asciutti o pettinati diversamente nell''angolazione successiva.', TRUE, '2026-11-02T10:00:57.820468', 'Titanic captain smith bridge flooding scene error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3823, 111, '01:15:00', 'Errori storici o fattuali', 'Durante la festa in terza classe, quando Jack e Rose ballano scatenati, si vede chiaramente sul ponte una cassa di birra con bottiglie dotate di tappo a corona metallico (crown cap), invenzione brevettata e diffusa solo anni dopo il 1912.', TRUE, '2026-11-02T10:00:57.820468', 'Titanic third class party beer bottles error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3824, 111, '01:45:00', 'Errori di scena / Posizione', 'Nella scena in cui l''acqua inonda la Grand Staircase (scalinata principale), si nota chiaramente che i manichini usati per le controfigure o gli stuntmen indossano giubbotti di salvataggio moderni rivestiti di stoffa diversa rispetto a quelli d''epoca.', TRUE, '2026-11-02T10:00:57.820468', 'Titanic grand staircase flooding stunt double error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3825, 111, '02:10:00', 'Errori di scena / Posizione', 'Quando Jack e Rose sono intrappolati nel cancello chiuso della terza classe, la chiave che Rose usa per sbloccare il lucchetto cambia posizione e persino tipo di chiave tra i primi piani e i campi medi.', TRUE, '2026-11-02T10:00:57.820468', 'Titanic locking gate key mistake scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4108, 197, '00:15:30', 'Errori di scena / Posizione', 'Durante l''arrivo di Max a Bartertown, quando viene fatto scendere dal veicolo, la posizione delle corde e delle catene che lo legano cambia visibilmente tra un cambio di inquadratura e l''altro.', TRUE, '2026-11-02T14:46:26.163396', 'Mad Max Beyond Thunderdome Bartertown arrival scene continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
