(3838, 116, '00:00:00', 'Errori di scena / Posizione', 'Nel corso del film, ambientato in un futuro non specificato ma fortemente tecnologico, compaiono alcune incongruenze nei dispositivi indossabili e negli schermi dei computer di Theodore, dove le interfacce utente fluttuano leggermente o cambiano disposizione grafica tra un''inquadratura e l''altra durante le scene di editing delle lettere.', TRUE, '2026-11-02T10:02:19.099294', 'Her movie continuity errors tech', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4141, 295, '00:12:45', 'Anacronismi', 'Nel film, ambientato nel 2017 durante il Día de los Muertos, la foto di Ernesto de la Cruz incorniciata viene mostrata in diverse sequenze. Tuttavia, la chitarra a forma di teschio che Ernesto suona è un modello ispirato chiaramente alle chitarre reali prodotte da brand moderni molto tempo dopo l''epoca in cui Ernesto sarebbe morto (presumibilmente negli anni ''30 o ''40).', TRUE, '2026-11-02T14:47:58.77139', 'Coco Ernesto de la Cruz guitar mistake', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4142, 295, '00:35:20', 'Errori di scena / Posizione', 'Quando Miguel entra nel dipartimento per il controllo dei passaporti nella Terra dei Morti, i documenti sulla scrivania dell''impiegato cambiano disposizione tra un''inquadratura e l''altra, e i timbri appaiono e scompaiono dalle mani del personaggio.', TRUE, '2026-11-02T14:47:58.77139', 'Coco Land of the Dead desk continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4143, 295, '01:02:10', 'Errori storici o fattuali', 'Le tradizioni legate al Día de los Muertos mostrate nel film combinano elementi di diverse regioni del Messico (come Michoacán e Oaxaca) in modo anomalo rispetto a come viene realmente celebrato a Santa Cecilia, località immaginaria ma ispirata ai villaggi rurali tradizionali.', TRUE, '2026-11-02T14:47:58.77139', 'Coco movie cultural inaccuracies Day of the Dead', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4221, 322, '00:08:45', 'Anacronismi', 'Durante le scene ambientate alla fine del XIX secolo, in alcune inquadrature esterne di Londra si possono intravedere segnali stradali moderni e griglie di scolo dell''asfalto che non esistevano all''epoca.', TRUE, '2026-11-02T14:50:01.778873', 'The Prestige modern details anachronism', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4222, 322, '00:34:20', 'Errori di scena / Posizione', 'Nel corso della discussione nel backstage tra Borden e Angier, i bicchieri sul tavolo cambiano posizione e livello di riempimento tra un''inquadratura e l''altra.', TRUE, '2026-11-02T14:50:01.778873', 'The Prestige continuity error glasses', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4223, 322, '01:12:10', 'Troupe o microfoni visibili', 'Durante una delle esibizioni sul palco, in un''inquadratura grandangolare si intraprende brevemente l''ombra di un microfono boom nella parte superiore dello schermo.', TRUE, '2026-11-02T14:50:01.778873', 'The Prestige boom mic visible crew', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4224, 322, '01:45:30', 'Errori storici o fattuali', 'Viene mostrato l''uso di lampadine e apparecchiature elettriche basate su corrente alternata con standard e potenze che anticipano di diversi anni le effettive realizzazioni tecnologiche dell''epoca di Nikola Tesla rappresentata nel film.', TRUE, '2026-11-02T14:50:01.778873', 'The Prestige Tesla electricity historical inaccuracy', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4493, 301, '00:00:00', 'Errori storici o fattuali', 'Durante le scene subacquee in cui Robert Redford tenta di rattoppare lo scafo dello yacht con la fibra di vetro e la resina epossidica, le procedure tecniche mostrate e la rapidità con cui la resina farebbe presa e polimerizzerebbe sott''acqua in quelle condizioni di temperatura sono altamente idealizzate e cinematiche rispetto alla realtà nautica.', TRUE, '2026-11-02T15:13:34.587172', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(4494, 301, '00:00:00', 'Errori di scena / Posizione', 'Nel corso della tempesta e delle successive sequenze di navigazione alla deriva, la quantità di acqua all''interno della cabina varia notevolmente e in modo incoerente tra un''inquadratura e l''altra, passando da pozzanghere sul pavimento a livelli molto più alti per poi ridursi inspiegabilmente senza che vi sia un''evidente azione di svuotamento.', TRUE, '2026-11-02T15:13:34.587172', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(4495, 301, '00:00:00', 'Errori storici o fattuali', 'Durante la sequenza in cui il protagonista usa il sestante per determinare la propria posizione in mare, l''uso dello strumento e i calcoli mostrati presentano imprecisioni tecniche e procedurali rispetto alla vera navigazione astronomica d''altura.', TRUE, '2026-11-02T15:13:34.587172', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(4554, 298, '00:15:20', 'Troupe o microfoni visibili', 'Durante la brutale sequenza dell''attacco dell''orso grizzly, in alcune inquadrature ravvicinate riflesse negli occhi o sul pelo bagnato dell''animale (in parte generato in CGI ma girato con controfigure e stunt), è possibile intravedere brevemente l''attrezzatura della troupe o l''ombra di un operatore.', TRUE, '2026-11-02T15:34:20.649241', 'The Revenant bear attack scene behind the scenes crew visible', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4555, 298, '00:45:10', 'Errori di scena / Posizione', 'Quando Hugh Glass (Leonardo DiCaprio) viene abbandonato nella fossa e coperto parzialmente di terra da Fitzgerald, la posizione delle foglie e dei detriti sul suo volto cambia visibilmente tra un cambio di inquadratura e l''altro.', TRUE, '2026-11-02T15:34:20.649241', 'The Revenant Glass left in grave continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4556, 298, '01:10:30', 'Anacronismi', 'Nel film vengono utilizzate alcune tipologie di armi da fuoco e polvere da sparo con caratteristiche e borre che presentano anacronismi rispetto alle precise tecniche di ricarica ad avancarica in uso nel 1823 tra i trapper del Missouri.', TRUE, '2026-11-02T15:34:20.649241', 'The Revenant historical and gun accuracy errors', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4557, 298, '01:35:40', 'Errori storici o fattuali', 'La geografia dei viaggi di Glass attraverso il Montana e il Dakota del Sud mostra sovrapposizioni e transizioni paesaggistiche estreme girate in realtà tra il Canada e la Patagonia, alterando la coerenza delle distanze e dei climi reali dell''epoca.', TRUE, '2026-11-02T15:34:20.649241', 'The Revenant geographic accuracy and filming locations', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4558, 298, '02:02:15', 'Errori di scena / Posizione', 'Nel duello finale tra Glass e Fitzgerald nella neve, le ferite e le quantità di sangue sui volti dei due personaggi variano sensibilmente da un piano sequenza all''altro, nonostante non sia trascorso tempo diegetico sufficiente per tali variazioni.', TRUE, '2026-11-02T15:34:20.649241', 'The Revenant final fight scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4563, 310, '00:45:12', 'Errori di scena / Posizione', 'Durante la sequenza in cui i figli di Jake e Neytiri esplorano la foresta e interagiscono con i Metkayina, la posizione delle armi e delle sacche di equipaggiamento cambia visibilmente tra un''inquadratura e l''altra nei cambi di prospettiva.', TRUE, '2026-11-02T15:34:31.526151', 'Avatar The Way of Water continuity error weapons', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL);
INSERT INTO public.errori ("id", "film_id", "minuto", "categoria", "descrizione", "approvato", "creato_il", "youtube_query", "conferme", "contestazioni", "inserito_da", "provenienza", "screenshot_url") VALUES
(4564, 310, '01:12:30', 'Errori di scena / Posizione', 'Nella scena subacquea in cui Kiri comunica con la fauna marina, i capelli e le decorazioni bioluminescenti variano la loro disposizione e luminosità in modo incoerente durante i tagli di montaggio ravvicinati.', TRUE, '2026-11-02T15:34:31.526151', 'Avatar The Way of Water Kiri underwater continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(718, 118, '12', 'Errori di scena / Posizione', 'boooh', TRUE, '2026-09-26T09:29:00.982833', NULL, 0, 0, 'mrtrrt67@gmail.com', 'utente', NULL),
(3839, 119, '00:00:00', 'Errori di scena / Posizione', 'Nel flashback iniziale del 2012 dopo la battaglia di New York, Adrian Toomes indossa una giacca che cambia leggermente la posizione del bavero e delle cerniere tra le inquadrature ravvicinate e i campi larghi mentre discute con i suoi soci.', TRUE, '2026-11-02T10:02:53.738927', 'Spider-Man Homecoming opening scene Toomes salvage', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3840, 119, '00:00:00', 'Anacronismi', 'Il cartello dell''otto anni dopo all''inizio del film crea un celebre errore temporale/fattuale rispetto alla linea temporale ufficiale del Marvel Cinematic Universe stabilita in precedenza.', TRUE, '2026-11-02T10:02:53.738927', 'Spider Man Homecoming 8 years later timeline error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3841, 119, '00:00:00', 'Errori di scena / Posizione', 'Durante la scena del traghetto di Staten Island, il cibo e i vestiti dei civili bagnati o danneggiati appaiono e scompaiono tra i vari cambi di inquadratura nel momento in cui la nave si spezza.', TRUE, '2026-11-02T10:02:53.738927', 'Spider-Man Homecoming ferry split scene continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3844, 121, '01:15:00', 'Errori di scena / Posizione', 'Durante la scena in cui Peter Parker si trova nel laboratorio del Sanctum Sanctorum, i pezzi di arredamento e gli artefatti mistici sullo sfondo cambiano posizione tra un cambio di inquadratura e l''altro.', TRUE, '2026-11-02T10:03:14.339758', 'Spider-Man No Way Home Sanctum Sanctorum scene mistake', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(242, 50, '02:02:15', 'Errori di scena / Posizione', 'Durante la battaglia finale attorno al nucleo di attivazione della città volante, la posizione delle macchie di polvere sul costume di Vedova Nera cambia continuamente tra un piano sequenza e l''altro.', TRUE, '2026-09-14T13:51:07.871547', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(243, 50, '02:14:00', 'Troupe o microfoni visibili', 'Mentre la massa terrestre sokoviana precipita verso la Terra, in una ripresa dal basso di un veicolo che si stacca dalla carreggiata si nota brevemente la struttura rigida di supporto del pistone pneumatico usato per ribaltare l''auto sul set.', TRUE, '2026-09-14T13:51:07.964362', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(1022, 231, '00:45:20', 'Errori di scena / Posizione', 'Nella scena all''esterno durante la neve, la quantità di fiocchi sulle spalle del cappotto di Finn cambia continuamente tra un''inquadratura e l''altra: prima ne è completamente ricoperto, nel campo successivo appare pulito e poi di nuovo imbiancato.', TRUE, '2026-10-24T15:36:29.469711', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(324, 60, '00:11:45', 'Errori storici o fattuali', 'Nelle scene ambientate a Londra compare ripetutamente la bandiera del Regno Unito (Union Jack) nella sua versione moderna, comprensiva della croce di San Patrizio (la diagonale rossa). Tuttavia, la pellicola è ambientata nel 1750 circa durante il regno di Giorgio II, mentre la croce di San Patrizio fu integrata nella bandiera solo con l''Atto di Unione del 1801.', TRUE, '2026-09-14T14:11:51.434478', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(197, 46, '02:21:00', 'Errori storici o fattuali', 'La moneta da un dollaro lanciata sul tavolo da gioco in una scena d''azzardo mostra il conio commemorativo Eisenhower Bicentennial, prodotto solo tra il 1975 e il 1976, mentre la scena è cronologicamente ambientata nel 1971.', TRUE, '2026-09-14T13:49:14.401863', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(244, 51, '00:11:05', 'Errori di scena / Posizione', 'Mentre Tony Stark fa jogging con Pepper Potts a Central Park, la felpa sportiva legata attorno alle sue spalle cambia annodamento e posizione della manica tra le riprese frontali e quelle da dietro.', TRUE, '2026-09-14T13:51:08.176184', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(246, 51, '00:41:12', 'Troupe o microfoni visibili', 'All''interno della navicella dei Guardiani della Galassia, mentre Groot gioca con il videogioco portatile, nella parte superiore dell''inquadratura sbalza leggermente dentro il campo visivo il microfono a spugna panoramico.', TRUE, '2026-09-14T13:51:08.384518', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(247, 51, '00:58:40', 'Errori storici o fattuali', 'Durante le fasi di riattivazione della stella di neutroni a Nidavellir, gli impatti delle macerie e la forgia metallica generano boati udibili ed echeggianti nello spazio aperto, violando la legge fisica dell''assenza di propagazione del suono nel vuoto.', TRUE, '2026-09-14T13:51:08.495736', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(248, 51, '01:12:18', 'Errori di scena / Posizione', 'Durante l''agguato a Edimburgo, la ferita da pugnalata sul petto di Visione proietta una scia di luce dorata che cambia angolazione e intensità a seconda dell''ampiezza dell''inquadratura.', TRUE, '2026-09-14T13:51:08.588232', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(249, 51, '01:30:45', 'Anacronismi', 'Quando Peter Parker cita il classico del cinema ''Aliens'' per sconfiggere Ebony Maw, pronuncia una frase citando la dicitura esatta di un adattamento televisivo americano arrivato nei canali via cavo anni dopo e non la versione cinematografica originale del 1986.', TRUE, '2026-09-14T13:51:08.683086', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(250, 51, '01:48:22', 'Errori di scena / Posizione', 'Durante il combattimento su Titan, i graffi e le incisioni presenti sul Guanto dell''Infinito indossato da Thanos scompaiono completamente nei primi piani dedicati al posizionamento delle singole gemme.', TRUE, '2026-09-14T13:51:08.784005', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(251, 51, '02:01:10', 'Errori di scena / Posizione', 'Mentre Doctor Strange duella con Thanos moltiplicando la sua immagine, il mantello della levitazione reale posizionato sulle sue spalle cambia la chiusura attorno al collo tra un''immagine e l''altra.', TRUE, '2026-09-14T13:51:08.826536', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(252, 51, '02:15:35', 'Errori di scena / Posizione', 'Nella battaglia del Wakanda, le macchie di fango sul viso e sulla barba di Capitan America variano visibilmente forma prima e subito dopo la carica iniziale contro l''esercito degli Outriders.', TRUE, '2026-09-14T13:51:08.898097', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(253, 51, '02:24:50', 'Errori di scena / Posizione', 'Thor colpisce Thanos al petto piantandogli la scure Stormbreaker. Quando Thanos usa la Gemma del Tempo e dello Spazio per ritirarsi, lo squarcio sulla sua armatura e sul petto cambia forma e posizione di qualche centimetro.', TRUE, '2026-09-14T13:51:08.999866', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(254, 52, '00:02:15', 'Errori di scena / Posizione', 'Durante la scena iniziale in cui Clint Barton insegna a sua figlia a usare l''arco, la quantità di frecce presenti all''interno della faretra cambia continuamente da tre a quattro tra una ripresa e l''altra.', TRUE, '2026-09-14T13:51:53.032537', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(255, 52, '00:19:40', 'Errori di scena / Posizione', 'Quando Thor decapita Thanos nella sua capanna sul pianeta giardino, la posizione del corpo di Thanos sul pavimento cambia bruscamente tra la visuale dall''alto e l''inquadratura frontale ravvicinata.', TRUE, '2026-09-14T13:51:53.154092', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(256, 52, '00:32:10', 'Troupe o microfoni visibili', 'Mentre Scott Lang mangia il suo taco fuori dal quartier generale degli Avengers, nel riflesso dei vetri dell''autovettura scura parcheggiata sullo sfondo è chiaramente visibile l''ombra della parabola di illuminazione del set.', TRUE, '2026-09-14T13:51:53.231196', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(257, 52, '00:45:12', 'Anacronismi', 'Nella sequenza ambientata nel 1970 all''interno della base militare di Camp Lehigh, sul muro di uno dei corridoi sotterranei si nota una moderna videocamera di sorveglianza digitale a circuito chiuso, del tutto inesistente in quell''epoca.', TRUE, '2026-09-14T13:51:53.327941', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(258, 52, '00:58:30', 'Errori storici o fattuali', 'Durante il viaggio nel passato a New York nel 2012, Bruce Banner cita la dinamica della traiettoria di caduta di un oggetto in assenza di gravità usando formule fisiche errate e invertendo i vettori di accelerazione.', TRUE, '2026-09-14T13:51:53.440314', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(259, 52, '01:12:05', 'Errori di scena / Posizione', 'Nella scena in cui Tony Stark parla con suo padre Howard Stark nel 1970, la lunghezza e la piega della cravatta di Tony cambiano visibilmente ad ogni cambio di inquadratura.', TRUE, '2026-09-14T13:51:53.533437', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(260, 52, '01:28:45', 'Errori di scena / Posizione', 'Sul pianeta Vormir, durante il combattimento tra Vedova Nera e Occhio di Falco per decidere chi debba sacrificarsi, i tagli e le macchie di sporco sul viso di Natasha cambiano forma e posizione.', TRUE, '2026-09-14T13:51:53.575178', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(261, 52, '01:41:20', 'Errori di scena / Posizione', 'Mentre i vendicatori indossano le tute bianche quantiche per prepararsi al viaggio nel tempo, i guanti di Ant-Man appaiono sfilati nella visuale panoramica ma sono regolarmente indossati nel primo piano successivo.', TRUE, '2026-09-14T13:51:53.646835', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(344, 62, '00:48:30', 'Errori storici o fattuali', 'Nel film, Jordan Belfort afferma che la rivista Forbes lo ha soprannominato ''Il lupo di Wall Street'' nell''articolo a lui dedicato. In realtà, il famoso articolo di Forbes del 1991 era intitolato ''Stealing from the Rich'' e lo descriveva come una sorta di Robin Hood al contrario; il soprannome ''Lupo'' è stato coniato dallo stesso Belfort solo anni dopo per la sua autobiografia.', TRUE, '2026-09-15T17:15:16.830593', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(345, 62, '01:14:15', 'Errori di scena / Posizione', 'Durante la festa nella villa negli Hamptons dove Jordan parla per la prima volta con Naomi, il livello del drink nel bicchiere di Jordan varia continuamente tra i vari stacchi di inquadratura, passando da quasi pieno a metà senza che lui ne beva un sorso.', TRUE, '2026-09-15T17:15:16.907955', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(175, 44, '01:44:00', 'Troupe o microfoni visibili', 'Durante il drammatico scontro finale al reattore nucleare, nell''angolo in alto a destra dello schermo entra brevemente in campo la parte superiore di un pannello di illuminazione da set.', TRUE, '2026-09-14T13:48:36.216421', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(347, 62, '02:07:45', 'Errori di scena / Posizione', 'Nella sequenza dell''effetto ritardato dei Quaalude Lemmon 714, mentre Jordan striscia sui gradini del club per raggiungere la sua Lamborghini, la cravatta cambia posizione tra un''inquadratura e l''altra: prima è completamente ribaltata dietro la spalla, poi pende sul davanti e infine torna sul lato.', TRUE, '2026-09-15T17:15:17.13477', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(348, 62, '02:22:15', 'Anacronismi', 'Durante la presentazione delle calzature di Steve Madden negli uffici della Stratton Oakmont (scena ambientata nel 1993), sullo sfondo compaiono modelli di scarpe con zeppa in gomma nera (come le celebri ciabatte ''Slinky'') che Steve Madden avrebbe disegnato e commercializzato solo a partire dal 1995/1996.', TRUE, '2026-09-15T17:15:17.206365', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(350, 62, '02:44:05', 'Errori storici o fattuali', 'Nella sequenza dell''affondamento dello yacht ''Naomi'' al largo della Sardegna, l''imbarcazione viene mostrata mentre si allaga rapidamente a causa di un guasto meccanico e del mare tempestoso. Nella realtà, il naufragio del 1996 fu causato dalla decisione diretta di Belfort di forzare il capitano a salpare con mare forza 8, provocando la rottura del portellone di poppa a causa delle onde giganti che travolsero l''imbarcazione.', TRUE, '2026-09-15T17:15:17.440341', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(262, 52, '02:04:15', 'Errori di scena / Posizione', 'Clamoroso errore di continuità nella battaglia finale: Ant-Man (in forma gigante) si vede sullo sfondo mentre sferra un pugno a un leviatano alieno, ma nello stesso istante è mostrato in versione normale dentro il furgone con Wasp per riattivare il tunnel quantico.', TRUE, '2026-09-14T13:51:53.736757', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(263, 52, '02:12:40', 'Errori di scena / Posizione', 'Dopo che Thanos spezza a metà lo scudo in vibranio di Captain America, in un''inquadratura successiva a largo campo durante la radunata degli eroi lo scudo appare per pochi frame miracolosamente integro sul braccio di Steve Rogers.', TRUE, '2026-09-14T13:51:53.776962', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(264, 52, '02:20:55', 'Errori di scena / Posizione', 'Nel momento in cui Tony Stark ruba le Gemme dell''Infinito a Thanos e le trasferisce sulla sua armatura, la Gemma della Mente e la Gemma dello Spazio si scambiano di posizione sulla mano prima dello schiocco finale.', TRUE, '2026-09-14T13:51:53.850679', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(265, 52, '02:32:10', 'Errori di scena / Posizione', 'Durante il funerale di Tony Stark, la posizione dei personaggi posizionati lungo il pontile del lago (in particolare Spider-Man e Captain Marvel) varia notevolmente tra la ripresa con il drone e i primi piani.', TRUE, '2026-09-14T13:51:53.948501', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(266, 53, '00:06:12', 'Troupe o microfoni visibili', 'Durante il combattimento iniziale all''interno del cimitero, nella parte superiore dello schermo è visibile per diversi secondi il microfono a spugna (boom mic) della troupe che segue i movimenti dei personaggi.', TRUE, '2026-09-14T13:51:54.088269', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(268, 53, '00:27:05', 'Anacronismi', 'Nelle riprese di un ricordo storico ambientato nel XVIII secolo nelle campagne scozzesi, sullo sfondo in alto a destra si nota chiaramente la scia di condensazione lasciata dal passaggio di un aereo di linea moderno.', TRUE, '2026-09-14T13:51:54.257261', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(269, 53, '00:39:20', 'Errori di scena / Posizione', 'Durante l''incontro al santuario, il livello di consumo delle candele poste sul tavolo centrale passa dall''essere quasi del tutto esaurito ad essere quasi nuovo nell''arco di un singolo cambio di campo.', TRUE, '2026-09-14T13:51:54.35121', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
