(296, 55, '01:11:00', 'Troupe o microfoni visibili', 'Quando Rocky corre sulla neve inseguito dall''auto degli agenti del KGB, sul cofano lucido dell''automobile scura si riflette nitidamente la struttura di metallo dell''auto-camera (camera car) che precede la scena.', TRUE, '2026-09-14T13:53:59.082726', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(297, 55, '01:18:45', 'Errori storici o fattuali', 'Prima dell''inizio dell''incontro a Mosca, la melodia eseguita per l''inno nazionale sovietico contiene un errore nell''arrangiamento orchestrale ufficiale dell''era di Mikhail Gorbaciov.', TRUE, '2026-09-14T13:53:59.190297', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL);
INSERT INTO public.errori ("id", "film_id", "minuto", "categoria", "descrizione", "approvato", "creato_il", "youtube_query", "conferme", "contestazioni", "inserito_da", "provenienza", "screenshot_url") VALUES
(298, 55, '01:25:30', 'Errori di scena / Posizione', 'Nel corso dei primi round del match, il grande taglio sul sopracciglio sinistro di Ivan Drago scompare misteriosamente nel round successivo per poi ricomparire più marcato nel round undici.', TRUE, '2026-09-14T13:53:59.287137', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(299, 55, '01:32:10', 'Troupe o microfoni visibili', 'Durante l''intervallo tra le riprese all''angolo di Rocky, nel riflesso del secchio d''acqua in metallo si distingue chiaramente la luce circolare di uno faretto di illuminazione della troupe.', TRUE, '2026-09-14T13:53:59.322252', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(300, 55, '01:39:50', 'Errori di scena / Posizione', 'Alla fine dell''incontro, quando Rocky pronuncia il suo celebre discorso al pubblico sovietico con la bandiera americana sulle spalle, i suoi guantoni e il volto passano dall''essere coperti di sangue e sudore all''essere quasi del tutto puliti.', TRUE, '2026-09-14T13:53:59.392445', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(301, 56, '00:04:15', 'Errori di scena / Posizione', 'Nelle primissime scene in cui Rocky viene trasportato in ambulanza subito dopo l''incontro del primo film, i tagli e i gonfiori sul suo volto cambiano forma, dimensione e quantità di sangue finto tra un primo piano e l''altro.', TRUE, '2026-09-14T13:54:32.874155', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(304, 56, '00:36:45', 'Errori di scena / Posizione', 'Nella scena romantica in cui Rocky chiede ad Adrian di sposarlo al parco sotto la neve, l''accumulo di fiocchi di neve sulle spalle dei loro cappotti scompare e ricompare drasticamente ad ogni cambio di angolazione della telecamera.', TRUE, '2026-09-14T13:54:33.075927', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(305, 56, '00:48:30', 'Anacronismi', 'Durante una passeggiata in quartiere, si nota sullo sfondo un''automobile parcheggiata che mostra sul parabrezza un bollino di ispezione e immatricolazione risalente al 1979, mentre la storia nella finzione cinematografica si svolge tra il 1976 e il 1977.', TRUE, '2026-09-14T13:54:33.176911', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(306, 56, '01:02:18', 'Errori di scena / Posizione', 'Quando Rocky lavora al macello insieme a Paulie, la posizione dei ganci da carne dietro di lui e le macchie di sangue sul suo grembiule bianco cambiano posizione tra un secondo e l''altro.', TRUE, '2026-09-14T13:54:33.218861', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(307, 56, '01:14:05', 'Troupe o microfoni visibili', 'All''interno della palestra di Mickey, mentre Rocky si allena al sacco da boxe e l''allenatore gli grida le istruzioni, sul vetro della finestra sullo sfondo si intravede il riflesso dell''operatore con la cinepresa.', TRUE, '2026-09-14T13:54:33.285153', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(308, 56, '01:25:50', 'Errori di scena / Posizione', 'Durante le scene in cui Adrian è in coma in ospedale in seguito al parto complicato, la cannula dell''ossigeno applicata al suo viso cambia posizione e i tubicini sono disposti in modo diverso da un''inquadratura all''altra.', TRUE, '2026-09-14T13:54:33.378086', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(309, 56, '01:38:12', 'Errori storici o fattuali', 'Nella celebre sequenza di allenamento in cui Rocky corre per Philadelphia seguito da una folla di bambini, il percorso seguito è geograficamente assurdo: salta da un quartiere all''altro della città percorrendo oltre 30 miglia in un''unica sessione di corsa continua.', TRUE, '2026-09-14T13:54:33.418329', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(4215, 320, '00:45:12', 'Errori di scena / Posizione', 'Nella scena in cui i prigionieri vengono legati e fatti marciare attraverso la foresta verso la città Maya, le corde e i nodi attorno ai polsi di alcuni figuranti cambiano visivamente posizione e tipo di legatura tra un cambio di inquadratura e l''altro.', TRUE, '2026-11-02T14:49:51.927251', 'Apocalypto continuity rope prisoners', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3853, 133, '01:25:00', 'Anacronismi', 'Quando Cliff Booth ripara l''antenna televisiva sul tetto della casa di Rick Dalton, indossa scarpe da ginnastica avvolte in stile vintage, ma in alcune inquadrature la suola mostra chiaramente il disegno moderno di un modello di scarpa da skate non esistente nel 1969.', TRUE, '2026-11-02T10:04:52.286087', 'Once Upon a Time in Hollywood Brad Pitt antenna roof scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3854, 133, '00:45:00', 'Errori di scena / Posizione', 'Nel bar in cui Cliff Booth ricorda il suo presunto scontro con Bruce Lee sul set di The Green Hornet, il bicchiere di birra davanti a Cliff cambia livello di riempimento e quantità di schiuma tra un''inquadratura e l''altra, nonostante non ne abbia bevuto.', TRUE, '2026-11-02T10:04:52.286087', 'Once Upon a Time in Hollywood Cliff stunt bar scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3855, 133, '01:50:00', 'Anacronismi', 'Nella scena in cui Sharon Tate fa acquisti e passeggia per Westwood, si intravedono veicoli parcheggiati sullo sfondo dotati di targhe californiane con la combinazione di colori e caratteri tipica degli anni ''80 anziché quelli gialli e neri del 1969.', TRUE, '2026-11-02T10:04:52.286087', 'Once Upon a Time in Hollywood Margot Robbie Westwood scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3856, 133, '02:15:00', 'Errori storici o fattuali', 'Durante il film viene citata la trasmissione radiofonica della stazione KHJ di Los Angeles con jingle e programmazione che non erano ancora in onda in quella specifica data dell''estate del 1969.', TRUE, '2026-11-02T10:04:52.286087', 'Once Upon a Time in Hollywood radio KHJ 1969', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3860, 137, '01:05:00', 'Errori di scena / Posizione', 'Durante la scena in cui Vincent e Sam si trovano al bar a Parigi, i bicchieri e i tovaglioli sui tavolini cambiano posizione e livello di riempimento tra un''inquadratura e l''altra nei campi e controcampi.', TRUE, '2026-11-02T10:05:21.073625', 'Ronin De Niro Reno cafe scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3861, 137, '00:42:00', 'Troupe o microfoni visibili', 'Nella sequenza girata tra i vicoli di Arles, riflettori e attrezzature della troupe cinematografica si riflettono chiaramente sulla carrozzeria lucida di un''auto parcheggiata mentre i personaggi camminano.', TRUE, '2026-11-02T10:05:21.073625', 'Ronin movie crew reflection visible', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(310, 56, '01:42:00', 'Errori di scena / Posizione', 'Arrivato in cima alla scalinata del Philadelphia Museum of Art, la felpa grigia di Rocky passa da essere totalmente inzuppata di sudore sul petto a quasi perfettamente asciutta nella ripresa aerea successiva.', TRUE, '2026-09-14T13:54:33.495886', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(311, 56, '01:51:30', 'Troupe o microfoni visibili', 'All''ingresso dei pugili nel palazzetto per l''incontro finale, durante la visuale dal basso dell''angolo di Apollo Creed, nella parte altissima dello schermo spunta per un attimo l''estremità del microfono della troupe audio.', TRUE, '2026-09-14T13:54:33.594051', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(312, 56, '01:58:40', 'Errori di scena / Posizione', 'Tra un round e l''altro del match finale, il profondo taglio sull''occhio destro di Rocky viene medicato e coperto di vaselina, ma nel fotogramma successivo all''inizio del round successivo il taglio appare posizionato più in alto verso il sopracciglio.', TRUE, '2026-09-14T13:54:33.686631', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(313, 56, '02:05:15', 'Errori storici o fattuali', 'Nel 15° round, quando sia Rocky che Apollo crollano a terra stremati, il conteggio dell''arbitro dura in realtà quasi 14 secondi effettivi al cronometro anziché i regolamentari 10 secondi previsti dal regolamento ufficiale del pugilato.', TRUE, '2026-09-14T13:54:33.729484', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(314, 56, '02:12:00', 'Errori di scena / Posizione', 'Durante il celebre discorso della vittoria in cui Rocky urla ''Yo Adrian, I did it!'', i lacci del guantone sinistro del pugile appaiono sciolti in una ripresa, per poi tornare perfettamente stretti e allacciati nella ripresa successiva.', TRUE, '2026-09-14T13:54:33.794325', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(315, 61, '00:08:15', 'Anacronismi', 'Durante la sequenza dell''inaugurazione della banca a Saint Martin, viene mostrato un caveau dotato di una moderna cassaforte con serratura a combinazione meccanica e ingranaggi complessi. Le casseforti con serrature a combinazione di questo tipo sono state inventate solo nella seconda metà del XIX secolo, mentre il film è ambientato intorno alla metà del XVIII secolo.', TRUE, '2026-09-14T14:11:22.133547', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(316, 61, '00:14:40', 'Errori storici o fattuali', 'Nella scena dell''inseguimento con la banca trainata dai cavalli, l''intero edificio in mattoni e pietra viene trascinato intatto per le vie della città. Dal punto di vista della fisica e dell''architettura dell''epoca, una struttura in muratura non armata si sarebbe sbriciolata istantaneamente appena strappata dalle sue fondamenta.', TRUE, '2026-09-14T14:11:22.254175', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(432, 90, '00:23:10', 'Errori di scena / Posizione', 'Quando Gabrielle guida verso il Messico per cercare suo padre, la sporcizia sul parabrezza della sua auto scompare e riappare tra i primi piani dall''interno del veicolo e le riprese esterne dall''alto.', TRUE, '2026-09-16T10:29:42.0926', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(319, 61, '00:48:50', 'Troupe o microfoni visibili', 'Durante l''attacco degli squali fantasma di Salazar, quando Jack e Henry cercano di raggiungere la riva sulla scialuppa, in un''inquadratura ravvicinata del movimento dei remi è visibile per un istante il cavo di sicurezza in acciaio agganciato alla parte inferiore dello scafo della barca per guidarne il movimento sul set.', TRUE, '2026-09-14T14:11:22.544946', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(320, 61, '01:02:15', 'Anacronismi', 'Carina Smyth fa riferimento a coordinate astronomiche legate al pianeta Urano per decifrare il diario. Tuttavia, il pianeta Urano è stato scoperto da William Herschel solo nel 1781, un periodo nettamente successivo rispetto all''epoca in cui sono ambientate le avventure del film.', TRUE, '2026-09-14T14:11:22.634471', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(321, 61, '01:18:40', 'Errori storici o fattuali', 'Sulle navi della Marina Reale britannica viene mostrata la bandiera Union Jack che include la croce rossa diagonale di San Patrizio (rappresentante l''Irlanda). Questa versione della bandiera fu adottata ufficialmente solo con l''Atto di Unione del 1801, mentre nel XVIII secolo la bandiera britannica non conteneva ancora la croce irlandese.', TRUE, '2026-09-14T14:11:22.743895', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(322, 61, '01:31:10', 'Errori di scena / Posizione', 'Quando Barbossa si trova a bordo per affrontare la minaccia di Salazar, la posizione della sua gamba di legno e delle relative cinghie varia tra le inquadrature: nei tagli frontali la cinghia di supporto sulla coscia appare allacciata sopra i pantaloni, mentre nei controcampi ripresi da dietro risulta posizionata sotto la giacca o diversamente ancorata.', TRUE, '2026-09-14T14:11:22.839615', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(323, 61, '02:01:05', 'Errori di scena / Posizione', 'Nella sequenza finale dell''ancora calata nella fenditura marina, la quantità di fango e macchie d''acqua sui vestiti di Henry e Carina cambia visibilmente tra le inquadrature successive, passando da abiti completamente inzuppati e sporchi a capi quasi puliti e asciutti durante i primi piani emotivi.', TRUE, '2026-09-14T14:11:22.876661', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(346, 62, '01:38:10', 'Errori di scena / Posizione', 'Nella scena a bordo del volo privato verso la Svizzera, quando il gruppo festeggia disordinatamente, le linee di sostanza bianca disposte sul tavolino di cristallo cambiano forma, lunghezza e numero ad ogni cambio di inquadratura della telecamera.', TRUE, '2026-09-15T17:15:17.006303', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(3857, 134, '00:04:15', 'Troupe o microfoni visibili', 'Durante le sequenze iniziali del montaggio che mostra il successo di Rocky e i suoi incontri per difendere il titolo, in alcune inquadrature ravvicinate del pubblico o del ring è possibile intravedere brevemente l''ombra di un microfono a boom sul plexiglas o sulla lizza.', TRUE, '2026-11-02T10:05:00.824272', 'Rocky III microphone boom shadow', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3858, 134, '01:25:30', 'Errori di scena / Posizione', 'Nel corso della seconda ripresa del match finale tra Rocky Balboa e Clubber Lang, la quantità di sudore e la disposizione dei capelli bagnati di Rocky variano drasticamente tra un taglio di montaggio e l''altro, passando da completamente inzuppati a quasi asciutti in pochi secondi.', TRUE, '2026-11-02T10:05:00.824272', 'Rocky III final fight continuity sweat', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4213, 319, '01:35:00', 'Troupe o microfoni visibili', 'Nella scena finale in cui la stazione di polizia viene distrutta, per un breve fotogramma in basso a destra è possibile intravedere la base di un cavo di sicurezza utilizzato per uno stunt.', TRUE, '2026-11-02T14:49:47.110239', 'Hot Fuzz stunt wire visible', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4242, 329, '00:15:20', 'Anacronismi', 'Durante le scene ambientate nei primi anni ''30 durante la Grande Depressione, si possono notare alcuni veicoli e modelli di camion che presentano dettagli di carrozzeria o componenti meccaniche posteriori al 1935.', TRUE, '2026-11-02T14:50:28.471347', 'Cinderella Man 2005 car error mistake', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4243, 329, '00:42:10', 'Errori di scena / Posizione', 'Nella sequenza della cucina in cui Jim Braddock parla con la moglie Mae, i piatti e le tazze sul tavolo cambiano posizione e livello di riempimento tra un''inquadratura e l''altra.', TRUE, '2026-11-02T14:50:28.471347', 'Cinderella Man movie mistake continuity kitchen', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4244, 329, '01:18:45', 'Errori storici o fattuali', 'Nel match sul ring, alcune tecniche di arbitraggio e le regole applicate rispecchiano più il pugilato moderno che gli standard rigorosi dei match dei pesi massimi degli anni ''30.', TRUE, '2026-11-02T14:50:28.471347', 'Cinderella Man boxing match historical accuracy', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(325, 60, '00:20:15', 'Anacronismi', 'Durante la rocambolesca fuga in carrozza di Jack Sparrow per le vie di Londra, sul muro di un edificio e lungo il selciato si intravedono elementi di conduttura in metallo e grate di scolo in ghisa tipiche della tarda epoca vittoriana (seconda metà dell''Ottocento), del tutto assenti a metà del Settecento.', TRUE, '2026-09-14T14:11:51.547637', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(326, 60, '00:37:40', 'Errori di scena / Posizione', 'Durante l''ammutinamento sulla Queen Anne''s Revenge, la sporcizia sul viso di Jack Sparrow e la disposizione delle sue treccine sul pettorale variano visibilmente da un''inquadratura all''altra nell''arco di pochi secondi di dialogo con Angelica.', TRUE, '2026-09-14T14:11:51.620239', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(327, 60, '00:41:20', 'Troupe o microfoni visibili', 'Quando Barbanera usa la spada magica per controllare le corde e la sartiame della nave contro i marinai ribelli, in un fotogramma in cui un marinaio viene sollevato a mezz''aria è chiaramente visibile il cavo di metallo dell''imbracatura di sicurezza utilizzato dallo stuntman.', TRUE, '2026-09-14T14:11:51.753514', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(328, 60, '00:54:10', 'Errori di scena / Posizione', 'Durante il drammatico attacco delle sirene a Whitecap Bay, Jack Sparrow finisce completamente immerso in acqua. Nella scena immediatamente successiva, quando si arrampica sulla torretta del faro per far esplodere la polvere da sparo, i suoi abiti e la giacca risultano visibilmente asciutti.', TRUE, '2026-09-14T14:11:51.836377', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(329, 60, '01:04:30', 'Errori di scena / Posizione', 'Quando la sirena Syrena viene trasportata nella cassa di vetro riempita d''acqua, il livello del liquido ed il modo in cui i suoi capelli bagnati le coprono le spalle e il volto cambiano vistosamente tra le inquadrature frontali e quelle laterali dei marinai che la trasportano.', TRUE, '2026-09-14T14:11:51.929835', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(330, 60, '01:16:45', 'Errori storici o fattuali', 'All''interno del vascello incagliato ''Santiago'', appartenuto all''esploratore Juan Ponce de León, si notano elementi d''arredo, armi da fuoco e carte geografiche risalenti alla fine del XVII o inizio XVIII secolo. Storicamente, Ponce de León è deceduto nel 1521, quindi la nave avrebbe dovuto contenere strumentazioni ed equipaggiamenti di inizio XVI secolo.', TRUE, '2026-09-14T14:11:52.026864', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(331, 60, '01:21:10', 'Errori di scena / Posizione', 'Nella cabina di Ponce de León, Jack Sparrow e Barbossa cercano i due calici d''argento. Prima che la nave cominci ad oscillare sul dirupo, la posizione dei calici sul letto cambia spontaneamente tra due stacchi di montaggio ravvicinati.', TRUE, '2026-09-14T14:11:52.062928', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(332, 60, '01:42:15', 'Troupe o microfoni visibili', 'Durante la marcia delle truppe spagnole verso il tempio della Fonte della Giovinezza, in una ripresa dal basso con movimento di macchina verso l''alto, nell''angolo inferiore sinistro dello schermo proiettato sulle rocce è brevemente visibile l''ombra della gru di ripresa (Jib/Jimmy Jib) e del paraluce della telecamera.', TRUE, '2026-09-14T14:11:52.136141', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(333, 60, '01:53:50', 'Errori di scena / Posizione', 'Nella sequenza finale presso la Fonte della Giovinezza, quando Angelica si ferisce la mano per raccogliere il veleno della spada, la macchia di sangue sul suo palmo e sul vestito cambia dimensione, forma e densità di colore nei vari primi piani mentre parla con Jack.', TRUE, '2026-09-14T14:11:52.228799', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(343, 62, '00:12:45', 'Anacronismi', 'Nelle scene ambientate nel 1987, durante le inquadrature esterne lungo le strade di Wall Street, si possono notare sullo sfondo alcuni modelli di automobili e taxi con linee aerodinamiche e targhe di stile della fine degli anni ''90 e primi anni 2000.', TRUE, '2026-09-15T17:15:16.732795', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(335, 59, '00:26:40', 'Errori di scena / Posizione', 'Durante la battaglia nello stabilimento balneare di Sao Feng, Elizabeth Swann impugna due spade. In un''inquadratura ravvicinata ne perde una che cade in acqua a sinistra, ma nel controcampo immediatamente successivo la si vede chiaramente mentre la impugna di nuovo senza aver avuto il tempo materiale per riprenderla.', TRUE, '2026-09-14T14:15:11.743441', 'Pirati dei Caraibi - Ai confini del mondo Durante la battaglia nello stabilimento balneare di Sao mistake error', 0, 0, 'IA (Sistema)', 'ia', NULL),
(336, 59, '00:43:15', 'Errori di scena / Posizione', 'Nel Cimitero di Davy Jones, quando Jack Sparrow si trova da solo sulla Perla Nera incagliata nel deserto e parla con le allucinazioni di sé stesso, la macchia di fuliggine sulla sua guancia sinistra cambia forma, dimensione e intensità tra le varie inquadrature ravvicinate e i campi medi.', TRUE, '2026-09-14T14:15:11.778757', 'Pirati dei Caraibi - Ai confini del mondo Nel Cimitero di Davy Jones quando Jack Sparrow mistake error', 0, 0, 'IA (Sistema)', 'ia', NULL),
(433, 90, '00:43:50', 'Errori di scena / Posizione', 'Dopo essere stato brutalmente pestato dagli uomini del cartello guidati dai fratelli Martinez, i tagli e le macchie di sangue sul viso di Rambo cambiano visibilmente forma e posizione tra l''inquadratura a terra e il momento in cui viene soccorso da Carmen.', TRUE, '2026-09-16T10:29:42.0926', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(3859, 135, '01:25:00', 'Errori di scena / Posizione', 'Durante la rissa di strada finale tra Rocky e Tommy Gunn, la posizione dei tagli e dei lividi sul volto di Sylvester Stallone cambia visibilmente da un''inquadratura all''altra, apparendo e scomparendo o cambiando lato tra i primi piani e i campi larghi.', TRUE, '2026-11-02T10:05:08.102384', 'Rocky V street fight Tommy Gunn scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(68, 29, '01:12:00', 'Continuity', 'Le pesanti catene ai polsi del protagonista appaiono spezzate dopo la lotta, ma nella scena immediatamente successiva tornano integre.', TRUE, '2026-09-13T15:01:47.103086', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(338, 59, '01:39:20', 'Troupe o microfoni visibili', 'Nella scena del parley sulla lingua di sabbia tra Lord Beckett, Davy Jones, Will, Elizabeth, Barbossa e Jack, sulla sabbia bianca a destra dello schermo è visibile per un istante l''ombra della gru della macchina da presa e di un pannello riflettente usati dalla troupe per illuminare gli attori.', TRUE, '2026-09-14T14:15:11.944556', 'Pirati dei Caraibi - Ai confini del mondo Nella scena del parley sulla lingua di sabbia mistake error', 0, 0, 'IA (Sistema)', 'ia', NULL),
(339, 59, '02:05:10', 'Errori di scena / Posizione', 'Durante la grande battaglia finale nel Maelstrom, mentre Barbossa celebra il matrimonio tra Will ed Elizabeth sotto una pioggia battente, i capelli di Elizabeth cambiano continuamente stato: nei campi lunghi sono completamente inzuppati e appiccicati al viso, mentre nei primi piani della promessa nuziale risultano solo leggermente umidi e ben acconciati.', TRUE, '2026-09-14T14:15:12.018362', 'Pirati dei Caraibi - Ai confini del mondo Durante la grande battaglia finale nel Maelstrom mentre mistake error', 0, 0, 'IA (Sistema)', 'ia', NULL),
(340, 59, '02:17:45', 'Troupe o microfoni visibili', 'Quando Jack Sparrow si lancia con una corda tra gli alberi della nave per recuperare lo scrigno di Davy Jones, sotto il suo giacchetto si nota chiaramente la tensione e la sagoma dell''imbracatura di sicurezza moderna e il cavo d''acciaio di supporto collegato alla schiena dell''attore.', TRUE, '2026-09-14T14:15:12.165398', 'Pirati dei Caraibi - Ai confini del mondo Quando Jack Sparrow si lancia con una corda mistake error', 0, 0, 'IA (Sistema)', 'ia', NULL),
(341, 59, '02:28:30', 'Errori di scena / Posizione', 'Nel climax della battaglia sul ponte dell''Olandese Volante, Jack tiene la chiave del cuore di Davy Jones nella mano sinistra prima di minacciare Jones. Nel stacco di montaggio immediato sul pugno di Jones, la chiave si trova improvvisamente nella mano destra di Jack.', TRUE, '2026-09-14T14:15:12.237948', 'Pirati dei Caraibi - Ai confini del mondo Nel climax della battaglia sul ponte dellOlandese Volante mistake error', 0, 0, 'IA (Sistema)', 'ia', NULL),
(353, 68, '00:15:30', 'Anacronismi', 'Durante gli scontri in Terra Santa, i soldati nemici e successivamente le guardie di Nottingham utilizzano balestre a ripetizione che funzionano come fucili d''assalto automatici, dotate di caricatori verticali e sistemi di ricarica rapida a pompa. Questo tipo di tecnologia bellica è totalmente anacronistica per l''epoca medievale.', TRUE, '2026-09-15T18:05:31.76036', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(354, 68, '00:38:45', 'Errori di scena / Posizione', 'Durante la sequenza di addestramento in cui Little John insegna a Robin a tirare rapidamente con l''arco, la posizione delle frecce scagliate sul bersaglio cambia repentinamente tra un''inquadratura e l''altra. In un fotogramma ravvicinato le frecce sono raggruppate al centro, mentre nel campo lungo successivo sono disposte in modo diverso e alcune sono sparite.', TRUE, '2026-09-15T18:05:31.809659', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(355, 68, '00:52:10', 'Errori storici o fattuali', 'Le miniere di carbone di Nottingham sono rappresentate come un immenso complesso industriale siderurgico della fine del XIX secolo, con passerelle metalliche sospese, carrelli su rotaie d''acciaio e fumi industriali. Nel XII secolo, l''estrazione del carbone era estremamente rudimentale e non esistevano strutture metalliche di tale portata ingegneristica.', TRUE, '2026-09-15T18:05:31.877319', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(356, 68, '01:10:15', 'Anacronismi', 'I costumi dei personaggi, in particolare le giacche di pelle trapuntate di Robin e gli abiti dello Sceriffo di Nottingham, presentano cuciture a macchina perfette, cerniere lampo nascoste e tagli di sartoria moderna stile streetwear contemporaneo. Anche i tessuti sintetici utilizzati per i cappucci e le fodere sono palesemente moderni.', TRUE, '2026-09-15T18:05:31.96689', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(357, 68, '01:28:30', 'Errori di scena / Posizione', 'Durante la rivolta finale nei pressi delle miniere, le ferite da taglio e le macchie di fuliggine sul volto di Robin Hood cambiano forma, intensità e posizione esatta tra i primi piani e le inquadrature più larghe, rivelando una scarsa continuità nel trucco di scena tra i vari ciak.', TRUE, '2026-09-15T18:05:32.064608', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(358, 68, '01:35:20', 'Anacronismi', 'Durante lo scontro finale tra i ribelli e le guardie dello Sceriffo, queste ultime si schierano utilizzando scudi antisommossa metallici e tattiche di contenimento della folla che replicano fedelmente quelle della polizia moderna. Gli scudi hanno persino feritoie visive e impugnature ergonomiche del tutto estranee al medioevo.', TRUE, '2026-09-15T18:05:32.106971', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(359, 69, '00:12:15', 'Errori di scena / Posizione', 'Durante l''assedio del castello di Chalus-Chabrol, Robin si prepara a tirare con l''arco. In un''inquadratura ravvicinata, le frecce nella sua faretra sono disposte in modo disordinato e con le piume rivolte verso l''alto. Nel taglio successivo, le frecce sono perfettamente allineate e orientate diversamente, per poi tornare disordinate subito dopo.', TRUE, '2026-09-15T18:19:14.513235', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(360, 69, '00:18:40', 'Errori storici o fattuali', 'Re Riccardo Cuor di Leone viene colpito al collo da un dardo di balestra scagliato da un cuoco francese e muore quasi istantaneamente sul campo di battaglia. Storicamente, Riccardo fu effettivamente ferito alla spalla/collo durante l''assedio di Châlus-Chabrol nel marzo 1199, ma morì ben undici giorni dopo a causa della gangrena sopraggiunta, non sul colpo.', TRUE, '2026-09-15T18:19:14.56688', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(361, 69, '00:42:10', 'Errori di scena / Posizione', 'Quando Robin e i suoi compagni arrivano a Londra via fiume per consegnare la corona reale, si vede un''inquadratura grandangolare del Tamigi con una forte corrente e barche che oscillano vistosamente. Nel primo piano immediatamente successivo, mentre attraccano, l''acqua è improvvisamente calmissima e piatta, priva di qualsiasi increspatura coerente con la scena precedente.', TRUE, '2026-09-15T18:19:14.653349', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(362, 69, '01:15:30', 'Anacronismi', 'Nelle scene ambientate a Nottingham e nelle campagne circostanti, si possono notare diversi strumenti agricoli, tra cui forconi a tre punte interamente in ferro e pale con bordi rinforzati con leghe metalliche moderne. Nel 1199, la maggior parte degli attrezzi agricoli dei contadini era rudimentale, realizzata quasi esclusivamente in legno sagomato a causa dell''altissimo costo del ferro.', TRUE, '2026-09-15T18:19:14.756378', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(363, 69, '01:38:25', 'Errori storici o fattuali', 'La trama si sviluppa fortemente attorno a una ''Carta delle Libertà'' scritta dal padre di Robin, che anticipa la Magna Carta, e che Re Giovanni promette di firmare per unire il paese contro i francesi. Storicamente, la Magna Carta fu redatta e imposta a Re Giovanni d''Inghilterra dai baroni ribelli solo nel 1215 a Runnymede, senza alcun legame con un''invasione francese sulle spiagge o con la figura di un arciere di nome Robin.', TRUE, '2026-09-15T18:19:14.859254', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(3862, 138, '00:01:15', 'Errori di scena / Posizione', 'Durante la sequenza dei titoli di testa, mentre Jackie Brown si sposta sul tappeto mobile dell''aeroporto, gli orologi a muro sullo sfondo mostrano orari incoerenti tra loro (passando ad esempio dalle 4:15 alle 4:10) nonostante lei proceda costantemente in avanti.', TRUE, '2026-11-02T10:06:24.467493', 'Jackie Brown opening credits clocks', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3863, 138, '00:10:20', 'Errori di scena / Posizione', 'Nella scena in cui Ordell convince Beaumont a entrare nel bagagliaio, il poggiatesta del sedile del passeggero della Chrysler scompare nelle inquadrature girate dal sedile posteriore, mentre è regolarmente presente in tutte le inquadrature frontali.', TRUE, '2026-11-02T10:06:24.467493', 'Jackie Brown Beaumont trunk scene headrest', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3864, 138, '00:13:45', 'Errori di scena / Posizione', 'Mentre Ordell parla con Beaumont chiuso nel bagagliaio, l''apertura del portellone varia drasticamente tra i tagli di montaggio: in alcune inquadrature è aperto solo di pochi centimetri, in altre è sollevato quasi completamente.', TRUE, '2026-11-02T10:06:24.467493', 'Jackie Brown Beaumont trunk lid', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3865, 138, '00:21:10', 'Errori di scena / Posizione', 'Durante l''arresto di Jackie all''aeroporto, la posizione delle mani dell''agente che la blocca cambia tra il piano medio e il primo piano: inizialmente la afferra per il braccio destro, ma nello stacco successivo la tiene per il sinistro mentre applica le manette.', TRUE, '2026-11-02T10:06:24.467493', 'Jackie Brown arrest scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3866, 138, '00:25:30', 'Errori di scena / Posizione', 'Durante il primo interrogatorio condotto da Ray Nicolette, il livello della bibita nel bicchiere di plastica con la cannuccia davanti a lui oscilla vistosamente, aumentando e diminuendo tra un''inquadratura e l''altra.', TRUE, '2026-11-02T10:06:24.467493', 'Jackie Brown Ray Nicolette interrogation', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(422, 85, '02:05:40', 'Errori di scena / Posizione', 'All''interno della stanza della memoria logica di HAL 9000, Dave Bowman procede alla disattivazione dei blocchi di memoria. L''utensile speciale utilizzato per svitare le schede trasparenti passa dalla mano destra alla mano sinistra tra due stacchi di montaggio consecutivi senza che l''astronauta lo abbia mai scambiato di mano.', TRUE, '2026-09-16T10:00:42.101711', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(3867, 138, '00:48:20', 'Errori di scena / Posizione', 'Nella scena al bar tra Jackie e Max Cherry, i capelli di Jackie cambiano posizione continuamente: in alcune inquadrature sono portati dietro l''orecchio destro, in altre ricadono liberamente in avanti coprendo parte del viso.', TRUE, '2026-11-02T10:06:24.467493', 'Jackie Brown bar scene Max Cherry', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(365, 69, '02:02:15', 'Anacronismi', 'Le truppe francesi tentano lo sbarco sulle coste inglesi utilizzando imbarcazioni a fondo piatto dotate di una rampa frontale apribile per facilitare la discesa dei soldati. Questo design è un evidente anacronismo, poiché ricalca fedelmente i moderni mezzi di sbarco (come i famosi Higgins Boats utilizzati nel D-Day della Seconda Guerra Mondiale). All''inizio del XIII secolo, gli sbarchi avvenivano tramite normali navi da trasporto o scialuppe, costringendo i soldati a scavalcare le paratie laterali.', TRUE, '2026-09-15T18:19:15.065278', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(366, 69, '02:08:40', 'Errori di scena / Posizione', 'Nello scontro finale in acqua tra Robin e Godfrey, la cotta di maglia e la tunica di Robin appaiono completamente inzuppate d''acqua, infangate e appesantite dal bagnasciuga. Pochi secondi dopo, quando Robin si rialza e osserva la ritirata dei francesi, la sua tunica è visibilmente asciutta nella parte superiore e priva delle vistose macchie di fango bagnato viste nell''inquadratura precedente.', TRUE, '2026-09-15T18:19:15.165888', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(367, 69, '01:58:12', 'Anacronismi', 'Durante la battaglia finale sulla spiaggia, i francesi sbarcano utilizzando imbarcazioni dotate di rampe anteriori ribaltabili. Questo design è un evidente anacronismo, poiché ricalca fedelmente i mezzi da sbarco (Higgins Boats) impiegati durante la seconda guerra mondiale, del tutto inesistenti nel XII secolo.', TRUE, '2026-09-15T18:23:51.652663', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(352, 68, '00:12:40', 'Errori storici o fattuali', 'La rappresentazione della Terza Crociata in Arabia è palesemente modellata sulla moderna guerra urbana in Medio Oriente. Gli edifici sembrano fatti di cemento armato moderno con tondini di ferro, e i soldati utilizzano tattiche di pattugliamento e copertura da cecchini tipiche delle forze speciali contemporanee, del tutto estranee alle strategie militari del XII secolo.', TRUE, '2026-09-15T18:05:31.682269', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(669, 133, '01:12:35', 'Anacronismi', 'Quando Sharon Tate si reca al cinema Bruin per vedere se stessa nel film ''The Wrecking Crew'', si possono notare sullo sfondo dei parchimetri stradali a tariffa oraria digitale e con scritte moderne, incompatibili con i modelli interamente meccanici in uso a Los Angeles nel 1969.', TRUE, '2026-09-19T19:47:51.941973', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(368, 69, '00:42:15', 'Anacronismi', 'Diversi soldati francesi e cavalieri inglesi indossano componenti di armatura a piastre e celate (come i bacinetti) tipiche del XIV e XV secolo. Nel 1199, epoca in cui è ambientato il film, l''equipaggiamento militare era quasi esclusivamente composto da usberghi in maglia di ferro (chainmail) e cervelliere o elmi con nasale.', TRUE, '2026-09-15T18:23:51.757054', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(369, 69, '00:11:04', 'Errori di scena / Posizione', 'Durante l''assedio del castello di Châlus-Chabrol, quando Robin si prepara a scoccare una freccia contro il cuoco francese sulle mura, la freccia è inizialmente posizionata sul lato sinistro dell''arco. Nel cambio d''inquadratura successivo, la freccia si trova sul lato destro dell''arco, per poi tornare a sinistra nel momento del tiro.', TRUE, '2026-09-15T18:23:51.853354', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(370, 69, '00:26:40', 'Troupe o microfoni visibili', 'Nella scena dell''imboscata nella foresta ai danni dei cavalieri che trasportano la corona del re, sul terreno fangoso ai lati del sentiero principale si possono chiaramente notare i solchi paralleli lasciati dagli pneumatici dei fuoristrada della troupe cinematografica, incompatibili con il passaggio di soli carri e cavalli dell''epoca.', TRUE, '2026-09-15T18:23:51.949333', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(371, 69, '02:02:10', 'Errori di scena / Posizione', 'Quando Marion cade in acqua durante lo scontro finale sulla spiaggia e viene soccorsa da Robin, i suoi capelli appaiono completamente bagnati, intrisi di fango e appiccicati al viso. Pochi secondi dopo, mentre osserva la ritirata dei francesi, i suoi capelli sono improvvisamente asciutti, puliti e vaporosi.', TRUE, '2026-09-15T18:23:52.050002', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(372, 69, '00:54:30', 'Errori di scena / Posizione', 'Quando Robin consegna la corona di Re Riccardo a Giovanna d''Inghilterra e alla Regina Madre, la tiene inizialmente con le punte rivolte verso il basso. Nell''inquadratura successiva in primo piano, la corona è improvvisamente ruotata di 180 gradi, con le gemme principali orientate diversamente rispetto alla presa precedente.', TRUE, '2026-09-15T18:23:52.152446', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(1069, 151, '00:24:15', 'Errori di scena / Posizione', 'Durante la camminata tra le dune, la posizione del cappuccio e del tubo del sistema filtrante della tuta distillante sul collo di Chani cambia sistemazione tra il campo largo e il primo piano successivo, spostandosi da sopra a sotto la spagna destra.', TRUE, '2026-10-24T21:20:30.061684', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(3868, 138, '01:12:15', 'Errori di scena / Posizione', 'Nell''ufficio di Max Cherry, durante il dialogo con Ordell sulla cauzione, la posizione degli oggetti sulla scrivania (in particolare il telefono e la spillatrice) cambia tra le inquadrature ravvicinate e quelle più larghe.', TRUE, '2026-11-02T10:06:24.467493', 'Jackie Brown Max Cherry office scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3869, 138, '01:32:40', 'Errori di scena / Posizione', 'Nella scena del bagno dell''aeroporto, quando Jackie trasferisce il denaro nella borsa di Sherwin-Williams, l''orientamento delle mazzette di banconote e la disposizione degli elastici che le tengono unite cambiano tra il dettaglio delle mani e l''inquadratura media.', TRUE, '2026-11-02T10:06:24.467493', 'Jackie Brown bathroom money scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3870, 138, '01:36:50', 'Troupe o microfoni visibili', 'Mentre Jackie cammina all''interno del Del Amo Fashion Center prima dello scambio, il riflesso della cinepresa e di parte della troupe è chiaramente visibile sulle vetrate scure dei negozi che Jackie oltrepassa sulla destra.', TRUE, '2026-11-02T10:06:24.467493', 'Jackie Brown mall reflection', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3871, 138, '01:48:15', 'Errori di scena / Posizione', 'Dopo che Louis spara a Melanie nel parcheggio, la macchia di sangue che appare sul finestrino laterale del furgone cambia forma e densità: vista dall''interno appare come pochi schizzi, mentre dall''esterno è una macchia molto più ampia e compatta.', TRUE, '2026-11-02T10:06:24.467493', 'Jackie Brown Louis shoots Melanie blood', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4216, 320, '01:42:30', 'Errori storici o fattuali', 'Il film mescola liberamente elementi di diverse civiltà e periodi mesoamericani (come l''uso di sacrifici massicci tipici degli Aztechi associati alla fine della civiltà Maya classica), sebbene storicamente le due culture avessero usanze, cronologie e contesti differenti.', TRUE, '2026-11-02T14:49:51.927251', 'Apocalypto historical inaccuracies maya aztecs', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4217, 320, '01:10:15', 'Errori di scena / Posizione', 'Quando Zampa di Giaguaro si ferisce durante la fuga e si nasconde nel fango, la quantità e la distribuzione del fango sul suo corpo e sul viso variano sensibilmente tra un''inquadratura frontale e quella di profilo immediatamente successiva.', TRUE, '2026-11-02T14:49:51.927251', 'Apocalypto mud scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4237, 328, '00:15:00', 'Errori di scena / Posizione', 'Quando Ray si trova in cucina e apre il frigorifero, la posizione degli alimenti e delle bottiglie cambia drasticamente tra un''inquadratura e l''altra nei tagli di montaggio.', TRUE, '2026-11-02T14:50:24.138675', 'War of the Worlds 2005 kitchen scene goofs', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4238, 328, '00:32:00', 'Errori di scena / Posizione', 'Durante la fuga in minivan, i danni subiti dal veicolo (vetri rotti e ammaccature) variano visibilmente da un''inquadratura all''altra mentre attraversano le strade caotiche.', TRUE, '2026-11-02T14:50:24.138675', 'War of the Worlds 2005 van scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4239, 328, '00:45:00', 'Troupe o microfoni visibili', 'Nella sequenza in cui la folla si accanisce contro il minivan, in un riflesso sullo specchietto retrovisore e sulla carrozzeria è brevemente visibile l''ombra di un operatore con attrezzatura.', TRUE, '2026-11-02T14:50:24.138675', 'War of the Worlds 2005 crew reflection visible', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4240, 328, '01:02:00', 'Errori di scena / Posizione', 'I vestiti della figlia Rachel (Dakota Fanning) cambiano livello di polvere e macchie di fango tra le scene immediatamente prima e dopo l''attacco del treno in fiamme.', TRUE, '2026-11-02T14:50:24.138675', 'War of the Worlds 2005 train scene continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4241, 328, '01:18:00', 'Errori storici o fattuali', 'Un EMP (impulso elettromagnetico) disattiva tutte le auto moderne con centralina elettronica, ma la videocamera che Justin Chatwin usa all''inizio continua a funzionare o vengono riaccesi dispositivi che dovrebbero essere permanentemente fritti.', TRUE, '2026-11-02T14:50:24.138675', 'War of the Worlds 2005 EMP logic error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4246, 330, '00:15:20', 'Errori di scena / Posizione', 'Durante la sparatoria nel diner, Tom Stall afferra uno dei criminali e usa una bottiglia di ketchup per colpirlo; la quantità e la posizione della salsa sul bancone e sui vestiti variano visibilmente tra un''inquadratura e l''altra nei tagli successivi.', TRUE, '2026-11-02T14:50:33.412673', 'A History of Violence diner scene fight continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4247, 330, '00:42:10', 'Errori di scena / Posizione', 'Nella scena in cui Carl Fogarty affronta Tom al bar del motel, il bicchiere di bevanda davanti a Fogarty è pieno a metà in un''inquadratura, quasi vuoto nella successiva e di nuovo pieno nel controcampo.', TRUE, '2026-11-02T14:50:33.412673', 'A History of Violence Carl Fogarty bar scene continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4248, 330, '01:12:45', 'Errori di scena / Posizione', 'Durante la colluttazione finale nella villa di Richie Stall, le ferite sul volto di Viggo Mortensen cambiano leggermente di intensità e posizione del sangue tra le diverse angolazioni della macchina da presa.', TRUE, '2026-11-02T14:50:33.412673', 'A History of Violence final fight house scene continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(373, 69, '01:52:00', 'Errori storici o fattuali', 'Il film mostra re Filippo II di Francia che guida personalmente un massiccio sbarco sulle coste inglesi prima della firma della Magna Carta (1215). Storicamente, Filippo II non invase mai l''Inghilterra in quel modo; fu suo figlio, il principe Luigi (futuro Luigi VIII), a sbarcare nel Kent nel 1216 su invito dei baroni ribelli inglesi, ben dopo la firma del celebre documento.', TRUE, '2026-09-15T18:23:52.268275', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL);
INSERT INTO public.errori ("id", "film_id", "minuto", "categoria", "descrizione", "approvato", "creato_il", "youtube_query", "conferme", "contestazioni", "inserito_da", "provenienza", "screenshot_url") VALUES
(374, 67, '00:24:40', 'Errori di scena / Posizione', 'Durante il duello sul tronco sospeso tra Robin Hood e Little John, quest''ultimo cade nel torrente sottostante. Nelle inquadrature immediatamente successive, mentre i due stringono amicizia, i vestiti e i capelli di Little John appaiono bagnati in modo del tutto incoerente: in alcuni tagli sono completamente inzuppati, mentre in altri sono quasi asciutti, specialmente sulle spalle e sul petto.', TRUE, '2026-09-15T18:28:25.278334', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(375, 67, '00:35:10', 'Anacronismi', 'Quando viene mostrata la cintura di castità di Lady Marian, si può notare chiaramente che è dotata di una moderna serratura a combinazione e presenta il logo della nota marca sportiva ''Everlast'' impresso sul metallo. Sebbene il film sia una parodia deliberata, questo costituisce un evidente anacronismo tecnologico e commerciale rispetto al XII secolo.', TRUE, '2026-09-15T18:28:25.362101', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(376, 67, '00:42:15', 'Anacronismi', 'Prima del combattimento contro gli scagnozzi dello Sceriffo di Rottingham, Ahchoo si ferma per gonfiare le sue scarpe da ginnastica, che sono delle evidenti ''Reebok Pump'' nere e bianche, un modello di calzatura sportiva introdotto sul mercato solo alla fine degli anni ''80.', TRUE, '2026-09-15T18:28:25.462177', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(703, 63, '00:18:45', 'Errori di scena / Posizione', 'Durante il torneo iniziale di giostra, la lancia del Conte di Huntingdon cambia impugnatura e orientamento tra la ripresa a campo largo e il primo piano immediatamente successivo prima dell''impatto.', TRUE, '2026-09-25T19:09:14.246576', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(3872, 142, '00:00:00', 'Errori di scena / Posizione', 'Quando il capo Brody si trova sulla spiaggia e guarda verso il mare, il suo orologio al polso scompare e riappare improvvisamente tra un''inquadratura e l''altra.', TRUE, '2026-11-02T10:06:53.662657', 'Jaws 2 watch continuity error Brody', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3873, 142, '00:00:00', 'Errori di scena / Posizione', 'Durante la scena in cui la barca della polizia traina il relitto verso la riva, la corda di traino cambia spessore e tipo di nodo in modo evidente tra i campi lunghi e i primi piani.', TRUE, '2026-11-02T10:06:53.662657', 'Jaws 2 tow rope continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4219, 321, '01:05:40', 'Troupe o microfoni visibili', 'Durante la scena dell''inseguimento ad alta velocità con la Dodge Charger, in un breve controcampo sui finestrini laterali dell''auto di Stuntman Mike è possibile intravedere il riflesso della telecamera e parte dell''equipaggiamento della troupe.', TRUE, '2026-11-02T14:49:57.038615', 'Death Proof car chase reflection camera crew', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4220, 321, '01:22:15', 'Errori di scena / Posizione', 'I danni subiti dalla Dodge Challenger delle ragazze durante il secondo scontro con Stuntman Mike variano visibilmente di gravità (ammaccature e vetri rotti) tra un''inquadratura frontale e quella laterale.', TRUE, '2026-11-02T14:49:57.038615', 'Death Proof Challenger crash continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4500, 24, '01:22:50', 'Audio / Doppiaggio / Sync', 'Il movimento delle labbra di uno degli attori secondari non coincide minimamente con la battuta pronunciata in italiano nella versione doppiata.', TRUE, '2026-11-02T15:32:06.26652', 'I sette gladiatori dubbing mistake sync', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4559, 303, '00:15:30', 'Errori di scena / Posizione', 'Durante la scena in cui la famiglia Patel discute prima della partenza, la posizione delle tazze da tè sul tavolo cambia visivamente tra un''inquadratura ravvicinata e quella grandangolare.', TRUE, '2026-11-02T15:34:23.431003', 'Life of Pi continuity error table', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(377, 67, '00:52:05', 'Errori di scena / Posizione', 'Nella tana della strega Latrina, mentre quest''ultima sta preparando una pozione per lo Sceriffo di Rottingham, la disposizione degli oggetti sul tavolo da lavoro cambia continuamente tra un''inquadratura e l''altra. In particolare, un teschio e un''ampolla di vetro blu si spostano da destra a sinistra senza che nessuno li tocchi.', TRUE, '2026-09-15T18:28:25.563859', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(378, 67, '01:18:30', 'Errori di scena / Posizione', 'Durante la celebre gara di tiro con l''arco, quando Robin scocca la freccia che ne fende in due un''altra già conficcata nel bersaglio, la posizione dei frammenti di legno cambia drasticamente. Nel primo piano ravvicinato la freccia è spaccata perfettamente a metà in senso longitudinale, mentre nell''inquadratura successiva a campo largo i pezzi di legno sono disposti in modo diverso e l''angolazione d''impatto sul bersaglio è mutata.', TRUE, '2026-09-15T18:28:25.665096', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(659, 129, '00:28:15', 'Errori di scena / Posizione', 'Durante la celebre scena in cui il giovane Noodles spia Deborah che danza nel retrobottega, la disposizione dei sacchi di farina e degli oggetti sugli scaffali cambia visibilmente tra le inquadrature strette e quelle larghe. Inoltre, la quantità di polvere di farina sul viso e sui capelli di Deborah varia inspiegabilmente da un''inquadratura all''altra.', TRUE, '2026-09-19T19:44:18.773942', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(379, 67, '01:22:10', 'Troupe o microfoni visibili', 'Durante la caotica scena del tentativo di impiccagione di Robin Hood, quando la folla inizia a ribellarsi e a combattere contro le guardie dello Sceriffo, sul lato sinistro dello schermo, parzialmente coperto da una finta colonna del castello, è possibile scorgere per un paio di fotogrammi un operatore della troupe cinematografica con indosso una maglietta scura moderna e un cappellino da baseball.', TRUE, '2026-09-15T18:28:25.766337', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(380, 67, '01:31:15', 'Errori storici o fattuali', 'All''arrivo di Re Riccardo, il sovrano indossa un''armatura a piastre completa e una corona con un design tipico del XV secolo. Storicamente, Riccardo Cuor di Leone visse alla fine del XII secolo (morì nel 1199), un''epoca in cui i cavalieri indossavano principalmente usberghi di maglia di ferro e non armature a piastre articolate, che si diffusero solo oltre due secoli dopo.', TRUE, '2026-09-15T18:28:25.864591', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(381, 66, '00:21:30', 'Errori storici o fattuali', 'Dopo essere sbarcati sulle coste meridionali dell''Inghilterra (nei pressi di Dover), Robin e Azeem si incamminano verso Nottingham affermando che saranno lì ''entro sera''. Tuttavia, durante il tragitto vengono mostrati mentre camminano lungo il Vallo di Adriano, che si trova a centinaia di chilometri più a nord, vicino al confine scozzese. È geograficamente impossibile passare di lì per andare da Dover a Nottingham, e ancor meno farlo a piedi in un solo giorno.', TRUE, '2026-09-15T18:33:00.354191', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(382, 66, '00:37:45', 'Anacronismi', 'Azeem mostra a Robin un cannocchiale tascabile per osservare i soldati dello Sceriffo in lontananza. Il film è ambientato nel 1194, durante la Terza Crociata, ma il cannocchiale non fu inventato prima dell''inizio del XVII secolo (intorno al 1608, ad opera di Hans Lippershey nei Paesi Bassi).', TRUE, '2026-09-15T18:33:00.431151', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(383, 66, '00:49:15', 'Errori di scena / Posizione', 'Durante il celebre scontro sul tronco d''albero tra Robin Hood e Little John, Robin cade ripetutamente nell''acqua profonda del fiume. Nelle inquadrature immediatamente successive, mentre i due ridono e fanno amicizia, i vestiti e i capelli di Robin appaiono completamente asciutti e in perfetto ordine, per poi tornare bagnati nel cambio di inquadratura successivo.', TRUE, '2026-09-15T18:33:00.507847', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(384, 66, '01:41:30', 'Anacronismi', 'Azeem utilizza la polvere da sparo per creare sofisticati ordigni esplosivi durante la preparazione della battaglia finale. Sebbene la polvere da sparo fosse già nota in Cina, il suo utilizzo militare sotto forma di bombe a mano ed esplosivi da lancio non era assolutamente diffuso né disponibile nell''Inghilterra del XII secolo.', TRUE, '2026-09-15T18:33:00.611397', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(385, 66, '02:01:40', 'Errori di scena / Posizione', 'Durante la cerimonia di matrimonio forzato tra Lady Marian e lo Sceriffo di Nottingham, la posizione del velo da sposa di Marian cambia continuamente tra i cambi di inquadratura. In alcuni primi piani il velo le copre parzialmente il viso, mentre nei campi medi è tirato completamente all''indietro, senza che nessuno lo abbia toccato.', TRUE, '2026-09-15T18:33:00.712559', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(386, 66, '02:05:10', 'Troupe o microfoni visibili', 'Durante la caotica scena dell''esecuzione pubblica in cui Robin e i suoi uomini intervengono per salvare i prigionieri dal patibolo, in diverse inquadrature rallentate dei saltatori e delle controfigure che si lanciano dalle mura del castello sono chiaramente visibili i cavi di sicurezza d''acciaio che sorreggono gli stuntman.', TRUE, '2026-09-15T18:33:00.81919', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(387, 66, '02:11:15', 'Errori di scena / Posizione', 'Nel duello finale tra Robin e lo Sceriffo di Nottingham, lo Sceriffo ferisce Robin alla mano e al braccio con la spada. Tuttavia, nelle inquadrature successive, la ferita scompare misteriosamente: non c''è traccia di sangue sulla manica o sulla pelle, e Robin continua a impugnare la spada e a combattere con incredibile vigore usando entrambe le mani senza mostrare alcun segno di dolore.', TRUE, '2026-09-15T18:33:00.91746', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(3874, 144, '01:25:00', 'Anacronismi', 'Nella scena della taverna, il gioco che i personaggi stanno facendo menziona ''Mata Hari'', ma il modo in cui viene utilizzato il gioco e alcune espressioni linguistiche presentano anacronismi rispetto all''epoca in cui è ambientato il film (1944).', TRUE, '2026-11-02T10:07:08.327943', 'Inglourious Basterds tavern scene card game goof', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3875, 144, '00:32:00', 'Errori di scena / Posizione', 'Durante il dialogo tra Shosanna e Joseph nel cinema riguardo alla proiezione del film, i fogli e i rulli di pellicola sul tavolo cambiano posizione tra le diverse inquadrature in primo piano e campo largo.', TRUE, '2026-11-02T10:07:08.327943', 'Inglourious Basterds Shosanna projection room scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3876, 144, '02:15:00', 'Errori di scena / Posizione', 'Nella sequenza finale del cinema in fiamme, la posizione delle bobine di pellicola infiammabili ammassate da Marcel sul pavimento varia visibilmente tra l''inquadratura in cui le dà fuoco e quella successiva.', TRUE, '2026-11-02T10:07:08.327943', 'Inglourious Basterds cinema fire scene Marcel continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3877, 147, '01:25:00', 'Errori di scena / Posizione', 'Durante la sequenza finale nella metropolitana di New York, quando Mick cerca di raggiungere Sue facendosi faticosamente strada tra la folla, la borsa che Sue tiene a tracolla cambia spalla in modo incongruente tra un''inquadratura e l''altra mentre i due si avvicinano.', TRUE, '2026-11-02T10:07:23.74666', 'Crocodile Dundee subway station scene ending', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4235, 326, '00:48:30', 'Errori di scena / Posizione', 'Nella sequenza in cui l''ispettore Uhl indaga nel laboratorio di Eisenheim, i fogli e gli strumenti di magia sulla scrivania cambiano visivamente disposizione e orientamento tra un''inquadratura in campo medio e il primo piano successivo.', TRUE, '2026-11-02T14:50:16.2583', 'The Illusionist 2006 continuity error desk scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4236, 326, '01:12:15', 'Errori storici o fattuali', 'La rappresentazione del sistema di polizia e dei metodi investigativi dell''Ispettore Generale Uhl sotto il Regno Austro-Ungarico riflette procedure e dinamiche più vicine ai thriller moderni che alle reali pratiche burocratiche e di polizia della Vienna d''inizio secolo.', TRUE, '2026-11-02T14:50:16.2583', 'The Illusionist 2006 police procedure historical error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(395, 82, '00:18:45', 'Errori di scena / Posizione', 'Alla clinica Shrublands, durante la violenta colluttazione tra James Bond e Lippe nel laboratorio, vari flaconi e provette sul bancone cambiano posizione tra le inquadrature prima ancora di essere urtati. Inoltre, le tracce di sangue sul volto di Lippe e la posizione delle schegge di vetro sul pavimento variano bruscamente nei raccordi di montaggio.', TRUE, '2026-09-15T19:26:19.839631', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(396, 82, '00:27:12', 'Troupe o microfoni visibili', 'Durante la sequenza in cui Fatima Blush provoca l''incidente d''auto mortale di Jack Petachi gettandogli una vipera nell''abitacolo, sul riflesso dei vetri e sulla fiancata metallica della vettura che sbanda si possono scorgere le luci del set e l''intelaiatura dell''attrezzatura per la cinepresa montata sul veicolo di ripresa.', TRUE, '2026-09-15T19:26:19.901087', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(397, 82, '00:46:18', 'Errori di scena / Posizione', 'Durante l''immersione subacquea alle Bahamas, quando Bond viene attaccato dallo squalo dopo essere stato intrappolato da Fatima, l''attrezzatura subacquea dell''agente 007 cambia configurazione: nei campi lunghi (interpretati dallo stuntman) le cinghie dell''imbragatura e il modello delle bombole differiscono visibilmente rispetto ai primi piani registrati con Sean Connery.', TRUE, '2026-09-15T19:26:19.996879', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(398, 82, '01:14:35', 'Errori di scena / Posizione', 'Durante l''inseguimento in moto nelle strade della Costa Azzurra, le calzature di Fatima Blush passano inspiegabilmente da eleganti scarpe con il tacco a stivali con suola piatta da motociclista durante le manovre più spericolate con la controfigura, per poi ritornare calzature coi tacchi alti non appena si ferma nel magazzino.', TRUE, '2026-09-15T19:26:20.092325', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(399, 82, '01:21:40', 'Errori di scena / Posizione', 'Nel corso della sfida al videogioco ''Domination'' tra Bond e Maximilian Largo al Casinò di Monte Carlo, lo stato della mappa olografica, i punteggi parziali e l''indicatore delle scosse elettriche mostrano valori incoerenti tra i controcampi sui due contendenti e le inquadrature fisse dello schermo di gioco.', TRUE, '2026-09-15T19:26:20.196922', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(400, 82, '01:45:12', 'Errori di scena / Posizione', 'Durante la rocambolesca fuga dalla fortezza di Palmyra, Bond e Domino si gettano con il cavallo da un alto bastione direttamente in mare. Il cavallo montato prima del salto presenta macchie e sfumature sul muso visibilmente diverse rispetto all''animale che nuota e riemerge dalle onde subito dopo l''impatto.', TRUE, '2026-09-15T19:26:20.297306', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(401, 82, '02:04:30', 'Errori storici o fattuali', 'Nello scontro finale subacqueo nella grotta delle ''Lacrime di Allah'', gli arpioni sparati dai fucili subacquei e dalle armi montate sui propulsori viaggiano a velocità supersonica con traiettorie perfettamente rettilinee su lunghe distanze, ignorando del tutto la resistenza fluidodinamica e la densità dell''acqua marina che frenerebbero drasticamente tali dardi entro pochi metri.', TRUE, '2026-09-15T19:26:20.398459', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(402, 84, '00:15:30', 'Anacronismi', 'Il velivolo da ricognizione tedesco Focke-Wulf Fw 189 ''Uhu'' che sorvola ripetutamente la zona è in realtà un aereo civile cecoslovacco Aero Ae-45 modificato per assomigliare al modello bellico. Le proporzioni della cabina di pilotaggio vetrata e la forma delle code gemelle rivelano la diversa natura del velivolo rispetto all''originale della Luftwaffe del 1943.', TRUE, '2026-09-15T20:53:33.12038', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(403, 84, '00:34:40', 'Troupe o microfoni visibili', 'Durante la drammatica sequenza del bombardamento d''artiglieria nella foresta, in cui i pini vengono spezzati dalle esplosioni, per una frazione di secondo sono visibili i cavi elettrici di innesco delle cariche pirotecniche che corrono lungo i tronchi degli alberi destinati a saltare in aria.', TRUE, '2026-09-15T20:53:33.256564', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(444, 89, '01:21:10', 'Errori di scena / Posizione', 'Mentre il cecchino ''Schoolboy'' fornisce copertura dall''alto con il suo fucile di precisione Barrett M82, i bossoli accumulati a terra accanto alla sua posizione cambiano disposizione e numero in maniera illogica tra i dettagli ravvicinati e le riprese più ampie.', TRUE, '2026-09-16T10:32:34.330245', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(404, 84, '00:42:15', 'Errori di scena / Posizione', 'Quando Flyora rientra nella sua casa ormai deserta e trova le bambole di pezza sul pavimento, la loro disposizione cambia nettamente tra l''inquadratura panoramica della stanza e il successivo primo piano dettagliato. Una delle bambole appare girata a pancia in giù, mentre prima era chiaramente rivolta verso l''alto.', TRUE, '2026-09-15T20:53:33.356493', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(405, 84, '00:52:15', 'Errori di scena / Posizione', 'Durante la faticosa traversata della palude, il fango sul viso e sui capelli di Glasha cambia continuamente consistenza, densità e posizione tra le inquadrature ravvicinate e i campi medi. In un fotogramma ha la guancia sinistra quasi pulita, mentre nel secondo successivo è completamente ricoperta di melma scura.', TRUE, '2026-09-15T20:53:33.506151', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(3878, 150, '00:00:00', 'Troupe o microfoni visibili', 'Durante una delle sequenze all''aperto su Arrakis, in un riflesso sugli occhiali protettivi o sui caschi dei personaggi, è possibile intravedere brevemente la sagoma di un membro della troupe con attrezzatura di illuminazione.', TRUE, '2026-11-02T10:08:07.082657', 'Dune crew reflection visible scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3879, 150, '00:00:00', 'Errori di scena / Posizione', 'Nella tenda in cui Jessica e Paul parlano prima di partire per Arrakis, la disposizione degli oggetti sul tavolo cambia leggermente di posizione tra un''inquadratura e l''altra.', TRUE, '2026-11-02T10:08:07.082657', 'Dune continuity error table tent', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4245, 329, '01:55:30', 'Troupe o microfoni visibili', 'In una delle inquadrature larghe della folla durante l''incontro finale per il titolo contro Max Baer, si intravede brevemente l''ombra di un microfono a boom sul bordo superiore dello schermo.', TRUE, '2026-11-02T14:50:28.471347', 'Cinderella Man boom mic visible error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4249, 331, '00:15:20', 'Errori di scena / Posizione', 'Durante la partita di tennis all''inizio del film, la posizione delle palline e il punteggio proclamato variano in modo incongruente tra un taglio e l''altro senza che sia passato un punto effettivo.', TRUE, '2026-11-02T14:50:37.02113', 'Match Point tennis match continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4250, 331, '00:42:10', 'Errori di scena / Posizione', 'Nella scena in cui Chris e Nola si incontrano alla galleria d''arte, la tazza di caffè tenuta da Nola cambia livello di riempimento e mano di presa tra le inquadrature in campo e controcampo.', TRUE, '2026-11-02T14:50:37.02113', 'Match Point art gallery scene continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4251, 331, '01:12:45', 'Troupe o microfoni visibili', 'In una delle inquadrature larghe all''esterno della villa di campagna, si intravede brevemente l''ombra di un microfono boom sul muro di mattoni della proprietà.', TRUE, '2026-11-02T14:50:37.02113', 'Match Point boom mic visible error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4252, 331, '01:25:30', 'Errori di scena / Posizione', 'Quando Chris entra nell''appartamento dell''anziana vicina per inscenare il furto, gli oggetti sulla scrivania cambiano disposizione da un''inquadratura all''altra prima di essere rotti.', TRUE, '2026-11-02T14:50:37.02113', 'Match Point murder scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(406, 84, '01:12:05', 'Errori storici o fattuali', 'Alcuni fucili Mosin-Nagant utilizzati dai partigiani bielorussi presentano cinghie di trasporto in tela e passanti metallici tipici delle versioni prodotte o modificate nel secondo dopoguerra (anni ''50), non conformi ai modelli standard in uso durante l''occupazione nazista del 1943.', TRUE, '2026-09-15T20:53:33.562939', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(407, 84, '01:42:10', 'Errori storici o fattuali', 'Molti dei camion utilizzati dalle truppe d''occupazione tedesche durante il massacro nel villaggio non sono veicoli d''epoca della Wehrmacht (come gli Opel Blitz), bensì camion sovietici del dopoguerra GAZ-63 e GAZ-51 camuffati. I mozzi delle ruote e la forma del telaio tradiscono la loro reale origine industriale degli anni ''50.', TRUE, '2026-09-15T20:53:33.678907', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(465, 86, '01:25:10', 'Troupe o microfoni visibili', 'Nelle battute finali all''interno della stazione di polizia, quando Rambo spara verso il soffitto per colpire lo sceriffo Teasle sul tetto, l''ombra del braccio del microfono boom si proietta chiaramente sulla parete di legno a sinistra dello schermo.', TRUE, '2026-09-16T10:45:07.709217', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(466, 86, '00:09:45', 'Errori di scena / Posizione', 'Durante la scena del tentativo di rasatura nella stazione di polizia, la quantità di schiuma da barba sul volto di Rambo varia vistosamente tra un cambio d''inquadratura e l''altro, e la posizione del taglio da rasoio sulla guancia cambia altezza prima che la lama lo tocchi.', TRUE, '2026-09-16T11:10:18.290089', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(467, 86, '00:14:40', 'Errori di scena / Posizione', 'Durante l''inseguimento in moto lungo il percorso ferrato, il pneumatico posteriore della Yamaha XT250 di Rambo cambia battistrada: passa da una gomma stradale a una da enduro tassellata per permettere allo stuntman di eseguire i salti in sicurezza.', TRUE, '2026-09-16T11:10:18.290089', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(468, 86, '00:28:15', 'Troupe o microfoni visibili', 'Quando il sergente Galt si sporge dall''elicottero per sparare a Rambo bloccato sulla parete rocciosa, nell''inquadratura dal basso verso l''alto si scorge chiaramente il cavo metallico di sicurezza dell''imbragatura dello stuntman fissato al telaio dell''aeromobile.', TRUE, '2026-09-16T11:10:18.290089', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(469, 86, '01:02:10', 'Errori storici o fattuali', 'Un ragazzo della Guardia Nazionale spara con un lanciarazzi M72 LAW contro l''ingresso della miniera. Un compagno si trova posizionato esattamente dietro il tubo di lancio: nella realtà la fiammata posteriore (backblast) dell''arma lo avrebbe ucciso o gravemente ustionato all''istante.', TRUE, '2026-09-16T11:10:18.290089', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(470, 86, '01:10:05', 'Troupe o microfoni visibili', 'Mentre Rambo guida il camion militare M35 sottratto alla Guardia Nazionale per fare ritorno in città, durante la curva a gomito prima del ponte è visibile il supporto tubolare metallico della cinepresa fissato sotto la fiancata del veicolo.', TRUE, '2026-09-16T11:10:18.290089', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(408, 84, '02:16:30', 'Errori di scena / Posizione', 'Nella celebre sequenza finale in cui Flyora spara ripetutamente al ritratto di Hitler immerso nella pozzanghera, il livello dell''acqua e la quantità di fango che copre il dipinto variano in modo non lineare tra i tagli di montaggio. In alcuni fotogrammi il ritratto è quasi totalmente visibile, mentre in altri è sommerso, prima ancora che i colpi ne alterino la posizione.', TRUE, '2026-09-15T20:53:33.767073', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(409, 84, '00:14:35', 'Anacronismi', 'Nel campo dei partigiani, tra i vari equipaggiamenti si possono notare alcuni zaini a sacco (''Veshmeshok'') nella versione da fanteria sovietica post-bellica (anni ''50/''60), riconoscibili dai passanti e dal tipo di fibbie metalliche, diversi dal modello semplificato utilizzato durante la seconda guerra mondiale.', TRUE, '2026-09-15T20:57:26.955057', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(410, 84, '00:38:12', 'Errori di scena / Posizione', 'Durante la celebre sequenza della pioggia nella foresta tra Flyora e Glasha, la disposizione del fango e delle foglie bagnate sul viso e sui capelli di Glasha cambia visibilmente tra i primi piani stretti e le inquadrature più larghe, rivelando molteplici ciak effettuati in momenti diversi.', TRUE, '2026-09-15T20:57:27.133981', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(411, 84, '01:12:45', 'Errori storici o fattuali', 'Il veicolo semicingolato tedesco utilizzato dalle truppe d''occupazione durante il rastrellamento è in realtà un OT-810 di fabbricazione cecoslovacca del dopoguerra, impiegato come sostituto del Sd.Kfz. 251. Si differenzia dall''originale tedesco per la forma del vano motore e la copertura superiore modificata.', TRUE, '2026-09-15T20:57:27.23419', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(412, 84, '00:48:22', 'Errori di scena / Posizione', 'Quando Flyora torna alla sua casa natale e trova la tavola ancora imbandita con il cibo abbandonato, la posizione delle mosche, delle ciotole e della bambola di pezza sul tavolo varia sensibilmente tra l''inquadratura soggettiva iniziale e il successivo piano sequenza in cui il ragazzo realizza la tragedia.', TRUE, '2026-09-15T20:57:27.434863', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(3880, 153, '00:03:00', 'Errori di scena / Posizione', 'Durante la festa di compleanno di Andy, quando la mamma distribuisce i regali, il numero e la disposizione delle scatole scartate sul pavimento cambiano visibilmente tra un''inquadratura e l''altra mentre Woody osserva dalla mensola.', TRUE, '2026-11-02T10:08:26.772488', 'Toy Story Andy birthday party presents scene error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3881, 153, '00:25:00', 'Errori di scena / Posizione', 'Nella stazione di servizio Dinoco, quando Woody si nasconde sotto la vettura e parla con Buzz, l''oggetto che Woody usa come clava (un attrezzo) sparisce e riappare tra le mani del cowboy a seconda dell''angolazione della telecamera.', TRUE, '2026-11-02T10:08:26.772488', 'Toy Story Gas Station scene Woody and Buzz error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3882, 153, '00:52:00', 'Errori di scena / Posizione', 'Nella camera di Sid, quando i giocattoli mutanti circondano Woody e Buzz, la posizione del secchiello della vernice aperto sul pavimento si sposta di oltre un metro verso sinistra tra l''inquadratura larga e il primo piano.', TRUE, '2026-11-02T10:08:26.772488', 'Toy Story Sid''s room mutant toys scene error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4253, 333, '00:25:12', 'Errori di scena / Posizione', 'Durante la conversazione in ufficio tra Frankie e Scrap, i fogli sulla scrivania cambiano posizione e orientamento tra un''inquadratura e l''altra, senza che nessuno li tocchi.', TRUE, '2026-11-02T14:50:45.464068', 'Million Dollar Baby office scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4254, 333, '01:12:45', 'Errori di scena / Posizione', 'Nel corso del combattimento decisivo per il titolo, il paradenti di Maggie scompare e riappare tra i primi piani e i campi medi durante gli scambi all''angolo.', TRUE, '2026-11-02T14:50:45.464068', 'Million Dollar Baby fight scene mouthpiece continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4255, 333, '01:45:20', 'Errori di scena / Posizione', 'Durante le scene in ospedale, la posizione delle lenzuola e dei tubi medicali collegati a Maggie varia visibilmente tra i cambi di inquadratura.', TRUE, '2026-11-02T14:50:45.464068', 'Million Dollar Baby hospital scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(413, 84, '00:31:15', 'Troupe o microfoni visibili', 'Durante l''improvviso e devastante bombardamento d''artiglieria nella foresta, in un''inquadratura dal basso che segue la caduta di un grosso pino, nell''angolo inferiore sinistro dello schermo è visibile per una frazione di secondo parte della barriera protettiva in plexiglass utilizzata per proteggere l''operatore di macchina dai detriti delle cariche pirotecniche.', TRUE, '2026-09-15T20:57:27.477643', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(414, 84, '02:12:05', 'Errori di scena / Posizione', 'Nella drammatica scena in cui Flyora viene costretto a posare per una foto con una pistola puntata alla tempia, la quantità di fango sul lato sinistro del suo volto cambia drasticamente: nella scena dinamica ha il viso quasi completamente coperto di terra bagnata, mentre nello scatto fotografico finale (mostrato come fermo immagine) la tempia è molto più pulita per rendere visibile l''espressione terrorizzata.', TRUE, '2026-09-15T20:57:27.546485', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(415, 84, '01:02:10', 'Anacronismi', 'I volantini di propaganda tedesca che vengono mostrati mentre cadono dal cielo presentano caratteri tipografici cirillici con glifi e spaziature tipiche delle macchine da stampa sovietiche degli anni ''70 e ''80, incongruenti con i caratteri d''epoca utilizzati dalle stamperie mobili della Wehrmacht o del Ministero della Propaganda nel 1943.', TRUE, '2026-09-15T20:57:27.750578', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(4256, 333, '01:25:00', 'Errori di scena / Posizione', 'Nel tragico momento in cui Maggie cade all''angolo subendo il colpo scorretto dopo il suono della campanella, il modo in cui batte contro lo sgabello e la posizione delle sue braccia cambiano nettamente tra l''inquadratura larga e il primo piano successivo.', TRUE, '2026-11-02T14:50:45.464068', 'Million Dollar Baby Maggie fall injury scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(417, 85, '00:34:20', 'Errori storici o fattuali', 'Durante il volo a bordo dello shuttle Aries verso la Stazione Spaziale, il Dr. Heywood Floyd beve cibo liquido con una cannuccia da un contenitore aspirante. Quando smette di aspirare, si nota il liquido scendere di nuovo verso il basso all''interno della cannuccia. In condizioni di microgravità nello spazio, il liquido non tornerebbe indietro verso il recipiente senza una forza di gravità che lo tiri verso il basso.', TRUE, '2026-09-16T10:00:41.199914', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(418, 85, '00:54:10', 'Errori di scena / Posizione', 'Durante la visita al monolito TMA-1 nel cratere lunare Tycho, le ombre proiettate dagli astronauti e dalla struttura del monolito procedono in direzioni visibilmente divergenti. Sulla Luna l''unica sorgente di luce diretta è il Sole, quindi le ombre dovrebbero essere perfettamente parallele; la divergenza rivela l''uso di molteplici proiettori di luce sul set cinematografico.', TRUE, '2026-09-16T10:00:41.399046', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(419, 85, '01:17:45', 'Errori storici o fattuali', 'Durante la partita a scacchi tra Frank Poole e il computer HAL 9000, quest''ultimo comunica a voce le mosse dicendo ''Regina in Alfiere 3'' e annunciando un checkmate forzato in due mosse. Tuttavia, guardando la disposizione dei pezzi sulla scacchiera mostrata a schermo, la mossa reale della Regina corrisponde a Alfiere 6 e Poole avrebbe avuto una mossa difensiva per evitare il matto immediato.', TRUE, '2026-09-16T10:00:41.616172', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(420, 85, '01:43:50', 'Troupe o microfoni visibili', 'Quando il braccio del pod controllato da HAL recide il tubo dell''ossigeno di Frank Poole inviandolo alla deriva nello spazio, il corpo dell''astronauta oscilla in modo innaturale. Durante la rotazione della figura nello spazio, per pochi fotogrammi sono visibili i cavi di sospensione dell''imbracatura dello stuntman illuminati dai riflettori di scena.', TRUE, '2026-09-16T10:00:41.795099', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(421, 85, '01:57:15', 'Errori di scena / Posizione', 'Nella drammatica sequenza in cui Dave Bowman si espelle dal pod d''emergenza privo di casco per rientrare nella Discovery 1, l''orientamento della valvola manuale di pressurizzazione del portello di emergenza cambia posizione in modo incoerente tra il campo largo dell''esplosione e il primo piano di Bowman che afferra i comandi.', TRUE, '2026-09-16T10:00:41.998998', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(423, 85, '02:19:30', 'Errori di scena / Posizione', 'Nella sequenza finale all''interno della stanza in stile neoclassico/vittoriano, il Dave Bowman anziano fa cadere involontariamente un bicchiere di vetro dalla tavola imbandita, frantumandolo al suolo. Nel campo lungo si vede il bicchiere rompersi a ridosso delle gambe del tavolo, ma nel dettaglio inquadrato subito dopo i cocci e la macchia di liquido si trovano a notevole distanza, vicino alla sedia.', TRUE, '2026-09-16T10:00:42.204629', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(424, 85, '00:08:45', 'Errori di scena / Posizione', 'Nella sequenza ''L''alba dell''uomo'', durante l''attacco del leopardo agli ominidi, negli occhi dell''animale si possono notare due distinti riflessi puntiformi proiettati dai proiettori di scena del set, tradendo la presenza di luci artificiali invece della sola luce solare naturale.', TRUE, '2026-09-16T10:21:59.98746', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(425, 85, '00:34:12', 'Troupe o microfoni visibili', 'Nella scena a bordo della navetta Orion in cui la hostess si muove a gravità zero per recuperare la penna fluttuante di Floyd, per un istante è visibile il dischetto di nastro biadesivo trasparente utilizzato dalla troupe per fissare la penna alle dita del guanto dell''attrice.', TRUE, '2026-09-16T10:21:59.98746', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(3883, 154, '00:03:15', 'Errori di scena / Posizione', 'Nel prologo iniziale del videogioco di Buzz Lightyear, quando Zurg distrugge la base, la posizione dei detriti e dei pannelli di controllo esplosi cambia drasticamente tra l''inquadratura larga e i primi piani.', TRUE, '2026-11-02T10:08:36.154322', 'Toy Story 2 video game opening scene goof', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3884, 154, '00:15:40', 'Errori di scena / Posizione', 'Nella camera di Andy, quando i giocattoli guardano la televisione per la televendita di Al''s Toy Barn, la tazza da tè di Mrs. Potato Head sul tavolino scompare e riappare tra un''inquadratura e l''altra.', TRUE, '2026-11-02T10:08:36.154322', 'Toy Story 2 Al''s Toy Barn commercial scene mistake', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3885, 154, '00:45:20', 'Errori di scena / Posizione', 'Nell''appartamento di Al, quando Woody guarda la TV e vede il vecchio show ''Woody''s Roundup'', i fogli di carta sparsi sulla scrivania vicino al televisore cambiano disposizione e numero a seconda dell''angolazione della telecamera.', TRUE, '2026-11-02T10:08:36.154322', 'Toy Story 2 Woody''s Roundup TV show scene goof', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3886, 154, '01:02:10', 'Errori di scena / Posizione', 'Nel corridoio dell''ascensore nel palazzo di Al, quando i giocattoli di Andy salgono sul termosifone per guardare fuori dal buco della serratura, la posizione di Slinky Dog rispetto agli altri giocattoli muta leggermente senza che ci sia un movimento visibile.', TRUE, '2026-11-02T10:08:36.154322', 'Toy Story 2 apartment hallway scene mistake', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4257, 333, '00:45:00', 'Errori di scena / Posizione', 'Durante una delle sessioni di allenamento di Maggie con i sacchi pesanti, la quantità di sudore sulla sua fronte e sui capelli varia visibilmente da un''inquadratura all''altra nel corso dello stesso esercizio continuo.', TRUE, '2026-11-02T14:50:45.464068', 'Million Dollar Baby training bag scene continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4277, 338, '00:15:20', 'Anacronismi', 'Durante la scena in cui Frank Abagnale Jr. si spaccia per un copilota della Pan Am nel 1963, si vede sullo sfondo un modello di aeroporto o dettagli di velivoli non coerenti con quel periodo specifico, oppure veicoli di servizio aeroportuale di anni successivi.', TRUE, '2026-11-02T14:51:08.319683', 'Catch Me If You Can Pan Am airport scene error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(426, 85, '00:52:30', 'Errori di scena / Posizione', 'Durante la discesa degli astronauti nella fossa dello scavo lunare verso il monolito TMA-1, le ombre proiettate dalle tute sul terreno divergono in varie direzioni anziché essere perfettamente parallele, rivelando l''uso di molteplici punti luce da studio invece dell''unica sorgente solare.', TRUE, '2026-09-16T10:21:59.98746', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(427, 85, '01:18:05', 'Errori storici o fattuali', 'Durante l''intervista della BBC trasmessa a bordo della Discovery One, il segnale video e le risposte tra la Terra e l''astronave (in rotta verso Giove) avvengono in tempo reale senza alcun ritardo di trasmissione, ignorando le leggi della fisica che richiederebbero decine di minuti per coprire tale distanza spaziale.', TRUE, '2026-09-16T10:21:59.98746', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(428, 85, '01:24:40', 'Troupe o microfoni visibili', 'Mentre Frank Poole fa allenamento correndo all''interno della centrifuga rotante, nella parte superiore dell''inquadratura ad ampio campo è possibile scorgere per un momento l''ombra del supporto del rig della telecamera, ancorato al centro del tamburo girevole.', TRUE, '2026-09-16T10:21:59.98746', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(429, 85, '02:02:15', 'Errori di scena / Posizione', 'Nella drammatica sequenza in cui Dave Bowman rientra dall''airlock d''emergenza senza casco, l''orientamento delle leve manuali sul pannello della porta e la posizione delle targhette indicatrici cambiano tra il totale dell''esplosione e il primo piano in cui aziona i comandi.', TRUE, '2026-09-16T10:21:59.98746', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(430, 85, '02:09:50', 'Anacronismi', 'Nella stanza in stile neoclassico in cui si ritrova Bowman al termine del viaggio attraverso il wormhole, il grande orologio a pendolo presenta cifre romane disposte con un orientamento errato e un movimento delle lancette a scatto continuo tipico dei meccanismi al quarzo moderni, incongruo con un arredo d''epoca o con la manifattura settecentesca.', TRUE, '2026-09-16T10:21:59.98746', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(431, 90, '00:07:45', 'Errori di scena / Posizione', 'Mentre John Rambo addestra i cavalli nel ranch, la posizione della corda sulla recinzione cambia tra i vari piani sequenza: prima è avvolta in modo disordinato sulla trave, mentre nell''inquadratura successiva appare perfettamente arrotolata.', TRUE, '2026-09-16T10:29:42.0926', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(434, 90, '00:52:15', 'Anacronismi', 'Nella scena in cui Rambo controlla le mappe e i sistemi di sorveglianza per pianificare la sua vendetta, viene mostrata un''interfaccia digitale con icone e font grafici anacronistici, basati su mockup operativi futuri non ancora disponibili all''epoca dell''ambientazione.', TRUE, '2026-09-16T10:29:42.0926', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(435, 90, '01:04:30', 'Troupe o microfoni visibili', 'Durante l''infiltrazione notturna di Rambo nella casa di Victor Martinez, nella parte superiore dello schermo, mentre si muove lungo il corridoio d''ingresso, è visibile l''ombra del microfono a giraffa proiettata sulla parete in alto.', TRUE, '2026-09-16T10:29:42.0926', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(69, 30, '00:24:15', 'Continuity', 'Durante il teso confronto all''interno del saloon, la posizione della bandana di Bob cambia di lato e di allacciatura tra i primi piani e i campi lunghi.', TRUE, '2026-09-13T15:08:13.351775', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(511, 103, '00:52:10', 'Errori storici o fattuali', 'La collocazione geografica di Fort William Henry nel film è errata. Viene mostrato adagiato ai piedi di imponenti e ripide montagne rocciose (le Blue Ridge Mountains della Carolina del Nord, dove il film è stato effettivamente girato). Nella realtà storica, il forte sorgeva sulle sponde pianeggianti e boscose del Lago George, nello stato di New York, un paesaggio collinare molto meno aspro.', TRUE, '2026-09-16T13:02:08.462231', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(436, 90, '01:16:20', 'Errori storici o fattuali', 'Durante la sequenza dell''imboscata nei tunnel sotto il ranch, le cariche artigianali al C4 preparate da Rambo detonano con effetti e tempi di propagazione incompatibili con i sistemi di innesco a filo e cavo elettrico mostrati nel montaggio.', TRUE, '2026-09-16T10:29:42.0926', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(437, 90, '01:23:45', 'Errori di scena / Posizione', 'Nel sanguinoso scontro finale con Hugo Martinez contro la parete del fienile, la quantità di sangue sul mantello del coltello e sulle mani di Rambo varia drasticamente tra il primo piano del colpo decisivo e l''inquadratura successiva a figura intera.', TRUE, '2026-09-16T10:29:42.0926', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(438, 89, '00:14:25', 'Errori di scena / Posizione', 'Durante la scena in cui i missionari tentano di convincere Rambo ad accompagnarli lungo il fiume, il posizionamento del cappello di Michael e il livello di umidità sui capelli di Rambo cambiano visibilmente tra un''inquadratura e l''altra durante il dialogo.', TRUE, '2026-09-16T10:32:34.330245', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(439, 89, '00:23:40', 'Errori di scena / Posizione', 'Quando i pirati abbordano la barca di Rambo e quest''ultimo reagisce estraendo la pistola, la ferita da arma da fuoco sul collo del capo dei pirati cambia dimensione e quantità di sangue visibile tra il primo piano e la successiva inquadratura ad angolo largo mentre cade in acqua.', TRUE, '2026-09-16T10:32:34.330245', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(440, 89, '00:41:10', 'Errori storici o fattuali', 'Rambo trova nella giungla un ordigno inesploso risalente alla Seconda Guerra Mondiale. Le bombe di quel tipo inutilizzate per oltre sessant''anni in un clima tropicale ad alta umidità avrebbero subito un deterioramento dei componenti chimici della spoletta tale da renderle del tutto inerti o estremamente instabili al minimo tocco, rendendo irrealistico il funzionamento perfetto della trappola improvvisata.', TRUE, '2026-09-16T10:32:34.330245', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(441, 89, '00:58:15', 'Troupe o microfoni visibili', 'Durante la fuga nel bosco, nell''esplosione che investe i soldati birmani inseguitori, per un istante è chiaramente visibile il cavo di sicurezza di acciaio agganciato alla schiena dello stuntman per scaraventarlo all''indietro.', TRUE, '2026-09-16T10:32:34.330245', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL);
